512	              </span>
513	            </label>
514	          </>
515	        )}
516	
517	        {/* Nguồn số liệu áp dụng cho CẢ HAI kiểu — check hằng ngày là loại dễ tự động nhất. */}
518	        <label className="flex flex-col gap-1 text-sm font-medium">
