'use client';

import { useEffect, useState, type RefObject } from 'react';
import {
  KPI_ALLOCATION_MODES,
  KPI_CRITERIA_KINDS,
  KPI_MEASURE_TYPES,
  KPI_SCORING_METHODS,
  KPI_SCORING_SHAPES,
  KPI_SOURCE_TYPES,
  type KpiAggregation,
  type KpiAllocationMode,
  type KpiCriteriaKind,
  type KpiDirection,
  type KpiMeasureType,
  type KpiScoringConfig,
  type KpiScoringMethod,
  type KpiScoringShape,
  type KpiSourceType,
} from '@ics/shared';
import { SlideOver } from '@/components/shared/slide-over';
import { AppSelect } from '@/components/shared/app-select';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { errorMessage } from '../api/kpi-api';
import {
  KPI_ALLOCATION_MODE_LABELS,
  KPI_CRITERIA_KIND_HINTS,
  KPI_CRITERIA_KIND_LABELS,
  KPI_MEASURE_TYPE_LABELS,
  KPI_SCORING_METHOD_LABELS,
  KPI_SCORING_SHAPE_LABELS,
  KPI_SOURCE_TYPE_LABELS,
  type KpiCriteria,
} from '../model/kpi.types';
import {
  EMPTY_CONFIG_DRAFT,
  KpiScoringConfigFields,
  configToDraft,
  draftToConfig,
  validateDraft,
  type ConfigDraft,
} from './kpi-scoring-config-fields';

/**
 * Đơn vị đo hay dùng — chọn nhanh thay vì gõ tay, để cùng một phép đo không bị
 * ghi thành "triệu VNĐ" / "Triệu VNĐ" / "trVNĐ" ở ba chỉ tiêu khác nhau.
 */
const UNIT_PRESETS = ['triệu VNĐ', '%', 'Đơn hàng', 'Khách hàng', 'Ngày'] as const;

/** Giá trị sentinel cho lựa chọn "Khác" — không phải đơn vị thật. */
const UNIT_OTHER = '__other__';

export type CriteriaFormValues = {
  name: string;
  description: string;
  csf: string;
  unit: string;
  sourceType: KpiSourceType;
  /** Cách đo — `PASS_FAIL` ẩn hết mục tiêu/đơn vị/cách chấm/cách gộp/phân bổ. */
  kind: KpiCriteriaKind;
  scoringShape: KpiScoringShape;
  scoringMethod: KpiScoringMethod;
  measureType: KpiMeasureType;
  allocationMode: KpiAllocationMode;
  isBlocking: boolean;
  /**
   * Cấu hình chấm khai NGAY Ở ĐÂY và dùng chung cho mọi kỳ.
   * Tắt ⇒ mỗi kế hoạch KPI tự thiết lập cấu hình của kỳ đó.
   */
  sharedConfig: boolean;
  config: ConfigDraft;
  /** Chỉ có khi form được mở kèm ô chọn mục tiêu. */
  objectiveId?: string;
};

const EMPTY: CriteriaFormValues = {
  name: '',
  description: '',
  csf: '',
  unit: '',
  sourceType: 'MANUAL',
  kind: 'MEASURED',
  scoringShape: 'UP',
  scoringMethod: 'CONTINUOUS',
  measureType: 'ADDITIVE',
  allocationMode: 'DIVIDE',
  isBlocking: false,
  sharedConfig: false,
  config: EMPTY_CONFIG_DRAFT,
};

function toValues(criteria: KpiCriteria | null): CriteriaFormValues {
  if (!criteria) return EMPTY;
  return {
    name: criteria.name,
    description: criteria.description ?? '',
    csf: criteria.csf ?? '',
    unit: criteria.unit ?? '',
    sourceType: criteria.sourceType,
    kind: criteria.kind,
    scoringShape: criteria.scoringShape,
    scoringMethod: criteria.scoringMethod,
    measureType: criteria.measureType,
    allocationMode: criteria.allocationMode,
    isBlocking: criteria.isBlocking,
    // Có cấu hình lưu ở định nghĩa ⇒ đó chính là "dùng chung".
    sharedConfig: Boolean(criteria.scoringConfig),
    config: configToDraft(criteria.scoringConfig),
  };
}

/** Chiều & cách gộp cũ vẫn còn trong DB — suy ra từ mô hình mới để tương thích. */
const DIRECTION_OF_SHAPE: Record<KpiScoringShape, KpiDirection> = {
  UP: 'INCREASE',
  DOWN: 'DECREASE',
  RANGE: 'INCREASE',
};
const AGGREGATION_OF_MEASURE: Record<KpiMeasureType, KpiAggregation> = {
  ADDITIVE: 'SUM',
  SEMI_ADDITIVE: 'LAST',
  RATIO: 'AVG',
};

/**
 * Cấu hình gửi kèm ĐỊNH NGHĨA — chỉ khi người dùng bật "dùng chung cho mọi kỳ".
 * Tắt ⇒ `undefined`, và mỗi kế hoạch KPI sẽ tự khai cấu hình của kỳ đó.
 */
function buildConfig(values: CriteriaFormValues): KpiScoringConfig | undefined {
  if (values.kind === 'PASS_FAIL' || !values.sharedConfig) return undefined;
  return draftToConfig(values.scoringShape, values.scoringMethod, values.config);
}

/** Đổi giá trị form thành payload API — dùng chung cho mọi nơi tạo/sửa chỉ tiêu. */
export function toCriteriaPayload(values: CriteriaFormValues) {
  /*
    Đạt/không đạt có hình dạng cố định. Gửi thẳng giá trị đã chuẩn hoá thay vì
    bỏ trống: backend cũng chuẩn hoá y hệt, nên hai bên khớp nhau và payload chỉ
    có MỘT shape (union hai shape làm kiểu trả về không khớp contract).

    Riêng `unit` phải BỎ TRỐNG — contract từ chối chỉ tiêu đạt/không đạt mà có
    đơn vị, vì đó là mâu thuẫn chứ không phải thiếu sót.
  */
  const isPassFail = values.kind === 'PASS_FAIL';

  return {
    name: values.name,
    description: values.description || undefined,
    csf: values.csf || undefined,
    // Nguồn số liệu áp dụng cho CẢ HAI kiểu: check hằng ngày là ứng viên số một
    // cho tự động hoá, không ai muốn tick tay 20 checkbox mỗi tháng.
    sourceType: values.sourceType,
    isBlocking: values.isBlocking,
    isCombined: false,
    kind: values.kind,
    unit: isPassFail ? undefined : values.unit,
    // `direction`/`aggregation` là cột cũ, suy ra từ mô hình mới cho tương thích.
    direction: isPassFail ? ('INCREASE' as const) : DIRECTION_OF_SHAPE[values.scoringShape],
    aggregation: isPassFail ? ('AVG' as const) : AGGREGATION_OF_MEASURE[values.measureType],
    allocationMode: isPassFail ? ('INHERIT' as const) : values.allocationMode,
    scoringShape: isPassFail ? ('UP' as const) : values.scoringShape,
    scoringMethod: isPassFail ? ('CONTINUOUS' as const) : values.scoringMethod,
    measureType: isPassFail ? ('RATIO' as const) : values.measureType,
    scoringConfig: buildConfig(values),
  };
}

/**
 * Form tạo/sửa ĐỊNH NGHĨA một chỉ tiêu (KPI).
 *
 * KHÔNG có trọng số và KHÔNG có target: hai con số đó thuộc về từng kỳ, nhập khi
 * đưa KPI vào kế hoạch KPI (`KpiDeptMetricForm`).
 *
 * Cách chấm khai theo hai trục trực giao: HÌNH DẠNG (càng cao/thấp/khoảng/nhị
 * phân) × CÁCH HIỆN (công thức liên tục / bảng khoảng).
 */
export function KpiCriteriaForm({
  open,
  criteria,
  triggerRef,
  objectives,
  stacked = false,
  onClose,
  onSubmit,
}: {
  open: boolean;
  criteria: KpiCriteria | null;
  triggerRef: RefObject<HTMLButtonElement>;
  objectives?: Array<{ id: string; label: string }>;
  stacked?: boolean;
  onClose: () => void;
  onSubmit: (values: CriteriaFormValues) => Promise<void>;
}) {
  const [values, setValues] = useState<CriteriaFormValues>(EMPTY);
  /**
   * Ô chọn đơn vị: giữ riêng khỏi `values.unit` vì "Khác" không phải một đơn vị.
   * `UNIT_OTHER` ⇒ hiện ô nhập tay bên cạnh, giá trị thật vẫn nằm ở `values.unit`.
   */
  const [unitChoice, setUnitChoice] = useState<string>('');
  const [objectiveId, setObjectiveId] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const needObjective = objectives !== undefined;

  useEffect(() => {
    if (!open) return;
    const next = toValues(criteria);
    setValues(next);
    // Đơn vị đã lưu nằm ngoài danh sách gợi ý ⇒ mở sẵn ô nhập tay.
    setUnitChoice(
      next.unit === ''
        ? ''
        : (UNIT_PRESETS as readonly string[]).includes(next.unit)
          ? next.unit
          : UNIT_OTHER,
    );
    setObjectiveId('');
    setError(null);
    setSubmitting(false);
  }, [open, criteria]);

  const set = <K extends keyof CriteriaFormValues>(key: K, value: CriteriaFormValues[K]) =>
    setValues((current) => ({ ...current, [key]: value }));

  const method = values.scoringMethod;
  /** Đạt/không đạt: không mục tiêu, không đơn vị, không cách chấm/gộp/phân bổ. */
  const isPassFail = values.kind === 'PASS_FAIL';

  /** Chỉ kiểm khi người dùng chọn khai cấu hình dùng chung ở đây. */
  function validateConfig(): string | null {
    if (isPassFail || !values.sharedConfig) return null;
    return validateDraft(values.scoringShape, method, values.config);
  }

  async function handleSubmit() {
    if (needObjective && !objectiveId) {
      setError('Vui lòng chọn mục tiêu chứa chỉ tiêu này.');
      return;
    }
    if (!values.name.trim()) {
      setError('Vui lòng nhập tên chỉ tiêu.');
      return;
    }
    if (!isPassFail && !values.unit.trim()) {
      setError('Vui lòng nhập đơn vị đo.');
      return;
    }
    const configError = validateConfig();
    if (configError) {
      setError(configError);
      return;
    }

    setSubmitting(true);
    setError(null);
    try {
      await onSubmit({
        ...values,
        name: values.name.trim(),
        unit: values.unit.trim(),
        ...(needObjective ? { objectiveId } : {}),
      });
      onClose();
    } catch (submitError) {
      setError(errorMessage(submitError, 'Không lưu được chỉ tiêu'));
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <SlideOver
      open={open}
      onClose={onClose}
      triggerRef={triggerRef}
      stacked={stacked}
      title={criteria ? 'Sửa chỉ tiêu' : 'Tạo chỉ tiêu mới'}
      footer={
        <div className="flex justify-end gap-2 px-4 py-3 sm:px-5">
          <Button type="button" variant="outline" onClick={onClose}>
            Hủy
          </Button>
          <Button type="button" onClick={handleSubmit} disabled={submitting}>
            {submitting ? 'Đang lưu…' : 'Lưu'}
          </Button>
        </div>
      }
    >
      <div className="space-y-4 px-4 py-5 sm:px-5">
        {objectives && (
          <label className="flex flex-col gap-1 text-sm font-medium">
            <span>
              Thuộc mục tiêu <span className="text-destructive">*</span>
            </span>
            <AppSelect
              aria-label="Chọn mục tiêu chứa chỉ tiêu"
              value={objectiveId}
              onValueChange={setObjectiveId}
              placeholder={objectives.length ? 'Chọn mục tiêu' : 'Phòng ban chưa có mục tiêu nào'}
              disabled={!objectives.length}
              options={objectives.map((objective) => ({
                value: objective.id,
                label: objective.label,
              }))}
            />
            <span className="text-xs font-normal text-muted-foreground">
              Chỉ tiêu luôn thuộc một mục tiêu sẵn có. Muốn thêm mục tiêu mới thì vào tab “Mục tiêu
              và chỉ tiêu”.
            </span>
          </label>
        )}

        <label className="flex flex-col gap-1 text-sm font-medium">
          <span>
            Tên chỉ tiêu <span className="text-destructive">*</span>
          </span>
          <Input
            value={values.name}
            onChange={(event) => set('name', event.target.value)}
            placeholder="Ví dụ: Doanh thu"
          />
          <span className="text-xs font-normal text-muted-foreground">
            Chỉ đặt tên phép đo, KHÔNG kèm con số — “Doanh thu”, không phải “Doanh thu đạt 50
            triệu”. Con số là của từng kỳ, nhập ở kế hoạch KPI.
          </span>
        </label>

        {/*
          Trục CAO NHẤT — đặt ngay dưới tên vì nó quyết định phần còn lại của form
          hiện những gì. Đổi lựa chọn này là đổi hẳn tập thuộc tính của chỉ tiêu.
        */}
        <label className="flex flex-col gap-1 text-sm font-medium">
          <span>Cách đo chỉ tiêu</span>
          <AppSelect
            aria-label="Chọn cách đo chỉ tiêu"
            value={values.kind}
            onValueChange={(value) => set('kind', value as KpiCriteriaKind)}
            options={KPI_CRITERIA_KINDS.map((kind) => ({
              value: kind,
              label: KPI_CRITERIA_KIND_LABELS[kind],
            }))}
          />
          <span className="text-xs font-normal text-muted-foreground">
            {KPI_CRITERIA_KIND_HINTS[values.kind]}
          </span>
        </label>

        <label className="flex flex-col gap-1 text-sm font-medium">
          <span>Yếu tố thành công (CSF)</span>
          <Input
            value={values.csf}
            onChange={(event) => set('csf', event.target.value)}
            placeholder="Chỉ tiêu này phục vụ yếu tố thành công nào?"
          />
        </label>

        <label className="flex flex-col gap-1 text-sm font-medium">
          <span>Mô tả</span>
          <Input
            value={values.description}
            onChange={(event) => set('description', event.target.value)}
          />
        </label>

        {/*
          Từ đây tới hết "Cách phân bổ" chỉ có nghĩa với chỉ tiêu ĐO BẰNG CON SỐ.
          Đạt/không đạt: không đơn vị, không cách chấm, gộp luôn là tỷ lệ số lần
          đạt, và luôn giao nguyên cho từng người — backend tự chuẩn hoá.
        */}
        {isPassFail ? (
          <p className="rounded-md border bg-muted/40 px-3 py-2 text-xs text-muted-foreground">
            Chỉ tiêu đạt/không đạt không có mục tiêu số hay đơn vị đo. Điểm được tính bằng tỷ lệ số
            lần đạt trên số lần kiểm, và luôn giao nguyên cho từng người.
          </p>
        ) : (
          <>
            <label className="flex flex-col gap-1 text-sm font-medium">
              <span>
                Đơn vị đo <span className="text-destructive">*</span>
              </span>
              <div className="flex items-center gap-2">
                <AppSelect
                  aria-label="Chọn đơn vị đo"
                  className="flex-1"
                  value={unitChoice}
                  onValueChange={(value) => {
                    setUnitChoice(value);
                    // Chọn "Khác" thì xoá trắng để người dùng gõ; chọn sẵn thì lấy luôn.
                    set('unit', value === UNIT_OTHER ? '' : value);
                  }}
                  placeholder="Chọn đơn vị đo"
                  options={[
                    ...UNIT_PRESETS.map((preset) => ({ value: preset, label: preset })),
                    { value: UNIT_OTHER, label: 'Khác…' },
                  ]}
                />
                {unitChoice === UNIT_OTHER && (
                  <Input
                    aria-label="Nhập đơn vị đo"
                    className="flex-1"
                    value={values.unit}
                    onChange={(event) => set('unit', event.target.value)}
                    placeholder="Nhập đơn vị đo"
                  />
                )}
              </div>
              <span className="text-xs font-normal text-muted-foreground">
                Đây cũng là đơn vị của mục tiêu và của các khoảng trong bảng chấm.
              </span>
            </label>

            {/* ── Cách chấm điểm: hai trục trực giao ─────────────────── */}
            <div className="space-y-3 rounded-lg border bg-muted/30 p-3">
              <p className="text-sm font-semibold">Cách chấm điểm</p>

              <label className="flex flex-col gap-1 text-sm font-medium">
                <span>Kiểu chấm</span>
                <AppSelect
                  aria-label="Chọn kiểu chấm"
                  value={values.scoringShape}
                  onValueChange={(value) => set('scoringShape', value as KpiScoringShape)}
                  options={KPI_SCORING_SHAPES.map((shape) => ({
                    value: shape,
                    label: KPI_SCORING_SHAPE_LABELS[shape],
                  }))}
                />
              </label>

              <label className="flex flex-col gap-1 text-sm font-medium">
                <span>Cách hiện thực</span>
                <AppSelect
                  aria-label="Chọn cách hiện thực"
                  value={values.scoringMethod}
                  onValueChange={(value) => set('scoringMethod', value as KpiScoringMethod)}
                  options={KPI_SCORING_METHODS.map((method) => ({
                    value: method,
                    label: KPI_SCORING_METHOD_LABELS[method],
                  }))}
                />
                <span className="text-xs font-normal text-muted-foreground">
                  Công thức liên tục: đạt bao nhiêu % mục tiêu thì được bấy nhiêu. Bảng khoảng: chia
                  thành các mức, dùng khi quan hệ không tuyến tính.
                </span>
              </label>

              <div className="space-y-3">
                {/*
                Cấu hình chấm mặc định thuộc về TỪNG KỲ (mỗi kế hoạch tự khai):
                phần lớn tham số mang ĐƠN VỊ của phép đo (khoảng, min/max) nên là
                con số của kỳ, còn sàn/trần thì là chính sách siết/nới theo kỳ.
                Chỉ bật ô này khi thang cố định qua mọi kỳ (tỷ lệ lỗi, uptime).
              */}
                <label className="flex items-start gap-2 text-sm font-medium">
                  <input
                    type="checkbox"
                    checked={values.sharedConfig}
                    onChange={(event) => set('sharedConfig', event.target.checked)}
                    className="mt-0.5 size-4 rounded border-field-border"
                  />
                  <span className="flex flex-col gap-0.5">
                    <span>Thiết lập cấu hình chấm cho chỉ tiêu chung</span>
                    <span className="text-xs font-normal text-muted-foreground">
                      {values.sharedConfig
                        ? 'Mọi kế hoạch KPI dùng chung cấu hình dưới đây.'
                        : 'Mỗi kế hoạch KPI sẽ tự thiết lập khi thêm chỉ tiêu này.'}
                    </span>
                  </span>
                </label>

                {values.sharedConfig && (
                  <KpiScoringConfigFields
                    shape={values.scoringShape}
                    method={method}
                    unit={values.unit}
                    draft={values.config}
                    onChange={(config) => set('config', config)}
                  />
                )}
              </div>
            </div>

            <label className="flex flex-col gap-1 text-sm font-medium">
              <span>Cách tổng hợp số liệu</span>
              <AppSelect
                aria-label="Chọn cách tổng hợp số liệu"
                value={values.measureType}
                onValueChange={(value) => set('measureType', value as KpiMeasureType)}
                options={KPI_MEASURE_TYPES.map((type) => ({
                  value: type,
                  label: KPI_MEASURE_TYPE_LABELS[type],
                }))}
              />
              <span className="text-xs font-normal text-muted-foreground">
                Quyết định cách gộp số liệu theo thời gian và giữa nhiều người. Tỷ lệ không cộng dồn
                được.
              </span>
            </label>

            <label className="flex flex-col gap-1 text-sm font-medium">
              <span>Cách phân bổ cho cá nhân</span>
              <AppSelect
                aria-label="Chọn cách phân bổ"
                value={values.allocationMode}
                onValueChange={(value) => set('allocationMode', value as KpiAllocationMode)}
                options={KPI_ALLOCATION_MODES.map((mode) => ({
                  value: mode,
                  label: KPI_ALLOCATION_MODE_LABELS[mode],
                }))}
              />
              <span className="text-xs font-normal text-muted-foreground">
                Chỉ tiêu dạng tỷ lệ (%) nên chọn “Giao nguyên” vì không chia nhỏ được.
              </span>
            </label>
          </>
        )}

        {/* Nguồn số liệu áp dụng cho CẢ HAI kiểu — check hằng ngày là loại dễ tự động nhất. */}
        <label className="flex flex-col gap-1 text-sm font-medium">
          <span>Nguồn số liệu</span>
          <AppSelect
            aria-label="Chọn nguồn số liệu"
            value={values.sourceType}
            onValueChange={(value) => set('sourceType', value as KpiSourceType)}
            options={KPI_SOURCE_TYPES.map((source) => ({
              value: source,
              label: KPI_SOURCE_TYPE_LABELS[source],
            }))}
          />
        </label>

        <label className="flex items-center gap-2 text-sm font-medium">
          <input
            type="checkbox"
            checked={values.isBlocking}
            onChange={(event) => set('isBlocking', event.target.checked)}
            className="size-4 rounded border-field-border"
          />
          <span>Chỉ tiêu bắt buộc (chặn)</span>
        </label>

        {error && (
          <p
            className="rounded-md border border-destructive/30 bg-destructive-subtle px-3 py-2 text-sm text-destructive"
            role="alert"
          >
            {error}
          </p>
        )}
      </div>
    </SlideOver>
  );
}

