1	import { calendarLateDays } from '@ics/shared';
2	import type { PrismaService } from '../common/prisma.service';
3	
4	/**
5	 * Danh mục nguồn dữ liệu KPI — nơi duy nhất định nghĩa "số thực tế của chỉ tiêu lấy từ đâu".
6	 *
7	 * Mỗi nguồn tự chịu trách nhiệm LỌC THEO KỲ KPI. Trước đây các nguồn cộng dồn toàn bộ lịch sử
8	 * (dù mô tả ghi "trong kỳ KPI"), nên điểm KPI tháng nào cũng giống nhau và tăng vô hạn theo
9	 * thời gian — sai về nghiệp vụ. Giờ mọi nguồn đều nhận `period` và chỉ tính trong khoảng đó.
10	 *
11	 * Thêm nguồn mới: khai một phần tử vào KPI_DATA_SOURCES là xong — không phải sửa chỗ chấm điểm.
12	 */
13	
14	export interface KpiPeriod {
15	  /** Đầu kỳ, tính cả mốc này. */
16	  start: Date;
17	  /** Cuối kỳ, tính cả mốc này. */
18	  end: Date;
19	}
20	
21	/**
22	 * Bối cảnh khi lấy số thực tế.
23	 *
24	 * `ownerUserId` rất quan trọng: KPI là của TỪNG NGƯỜI, nên chỉ tiêu "doanh thu" của nhân viên A
25	 * phải là doanh thu do A phụ trách, không phải doanh thu toàn công ty. Khi không truyền
26	 * (vd xem trước lúc soạn chỉ tiêu) thì lấy số của cả tenant.
27	 */
28	export interface KpiResolveContext {
29	  period: KpiPeriod;
30	  ownerUserId?: string | null;
31	  /**
32	   * Giới hạn theo MỘT NHÓM người phụ trách — dùng khi trang chủ hiển thị số của nhóm / phòng ban /
33	   * chi nhánh mà người xem được phép đọc. Có `ownerUserId` thì `ownerUserId` thắng (KPI cá nhân).
34	   *
35	   * Mảng RỖNG có nghĩa "không ai trong phạm vi" và phải cho ra 0. Đây là lý do tồn tại của
36	   * `ownerIdFilter` bên dưới: nếu để mảng rỗng rơi vào nhánh "không lọc gì" thì một trưởng nhóm
37	   * chưa có thành viên sẽ nhìn thấy số của TOÀN BỘ công ty — lộ dữ liệu, không phải hiển thị sai.
38	   */
39	  ownerUserIds?: readonly string[] | null;
40	}
41	
42	type ScopedPrisma = PrismaService['scoped'];
43	
44	export interface KpiDataSourceDef {
45	  id: string;
46	  name: string;
47	  description: string;
48	  defaultValue: string;
49	  defaultUnit: string;
50	  /** Lấy số thực tế của nguồn này trong kỳ (và theo người phụ trách nếu có). */
51	  resolve: (prisma: ScopedPrisma, context: KpiResolveContext) => Promise<number>;
52	}
53	
54	function toNumber(value: unknown): number {
55	  if (value === null || value === undefined) return 0;
56	  const parsed = Number.parseFloat(String(value));
57	  return Number.isFinite(parsed) ? parsed : 0;
58	}
59	
60	/** Khoảng thời gian dạng Prisma filter cho một cột ngày. */
61	function inPeriod(period: KpiPeriod) {
62	  return { gte: period.start, lte: period.end };
63	}
64	
65	/**
66	 * Bộ lọc cho một cột kiểu `ownerId`. Trả `undefined` = không giới hạn (cả tenant), dùng cho scope
67	 * ALL và cho lúc xem trước chỉ tiêu. Tách riêng để các nguồn lọc qua quan hệ (`opportunity: {...}`)
68	 * dùng chung một luật với `byOwner`.
69	 */
70	function ownerIdFilter(context: KpiResolveContext): string | { in: string[] } | undefined {
71	  if (context.ownerUserId) return context.ownerUserId;
72	  if (context.ownerUserIds) return { in: [...context.ownerUserIds] };
73	  return undefined;
74	}
75	
76	/** Điều kiện lọc theo người phụ trách; rỗng khi tính cho cả tenant. */
77	function byOwner(context: KpiResolveContext) {
78	  const ownerId = ownerIdFilter(context);
79	  return ownerId ? { ownerId } : {};
80	}
81	
82	/** Số giờ giữa hai mốc thời gian. */
83	function hoursBetween(from: Date, to: Date): number {
84	  return (to.getTime() - from.getTime()) / (60 * 60 * 1000);
85	}
86	
87	/** Số phút giữa hai mốc thời gian. */
88	function minutesBetween(from: Date, to: Date): number {
89	  return (to.getTime() - from.getTime()) / (60 * 1000);
90	}
91	
92	/** Điều kiện lọc ticket cơ bản: chưa xoá, thuộc người phụ trách nếu có. */
93	function ticketBase(context: KpiResolveContext) {
94	  return { deletedAt: null, ...byOwner(context) };
95	}
96	
97	/** Id các cơ hội đã chuyển sang trạng thái THẮNG trong kỳ (theo lịch sử chuyển giai đoạn). */
98	async function wonOpportunityIdsInPeriod(
99	  prisma: ScopedPrisma,
100	  context: KpiResolveContext,
101	): Promise<string[]> {
102	  const ownerId = ownerIdFilter(context);
103	  const histories = await prisma.opportunityStageHistory.findMany({
104	    where: {
105	      toStage: 'THANG',
106	      changedAt: inPeriod(context.period),
107	      ...(ownerId ? { opportunity: { ownerId } } : {}),
108	    },
109	    select: { opportunityId: true },
110	    distinct: ['opportunityId'],
111	  });
112	  return histories.map((row) => row.opportunityId);
113	}
114	
115	export const KPI_DATA_SOURCES: KpiDataSourceDef[] = [
116	  {
117	    id: 'sales.closed_revenue',
118	    name: 'Doanh thu đã chốt',
119	    description:
120	      'Tổng giá trị cơ hội chuyển sang THẮNG trong kỳ, cộng giá trị hợp đồng hoàn thành ký trong kỳ.',
121	    defaultValue: '0.00',
122	    defaultUnit: 'VNĐ',
123	    async resolve(prisma, context) {
124	      const wonIds = await wonOpportunityIdsInPeriod(prisma, context);
125	      const [opportunities, contracts] = await Promise.all([
126	        wonIds.length
127	          ? prisma.opportunity.aggregate({
128	              where: { id: { in: wonIds } },
129	              _sum: { amount: true },
130	            })
131	          : Promise.resolve({ _sum: { amount: null } }),
132	        prisma.contract.aggregate({
133	          where: {
134	            status: 'COMPLETED',
135	            signDate: inPeriod(context.period),
136	            ...byOwner(context),
137	          },
138	          _sum: { contractValue: true },
139	        }),
140	      ]);
141	      return toNumber(opportunities._sum.amount) + toNumber(contracts._sum.contractValue);
142	    },
143	  },
144	  {
145	    id: 'sales.closed_deals',
146	    name: 'Số thương vụ đã chốt',
147	    description: 'Số cơ hội chuyển sang THẮNG trong kỳ, cộng số hợp đồng hoàn thành ký trong kỳ.',
148	    defaultValue: '0.00',
149	    defaultUnit: 'Thương vụ',
150	    async resolve(prisma, context) {
151	      const [wonIds, contracts] = await Promise.all([
152	        wonOpportunityIdsInPeriod(prisma, context),
153	        prisma.contract.count({
154	          where: {
155	            status: 'COMPLETED',
156	            signDate: inPeriod(context.period),
157	            ...byOwner(context),
158	          },
159	        }),
160	      ]);
161	      return wonIds.length + contracts;
162	    },
163	  },
164	  {
165	    id: 'sales.conversion_rate',
166	    name: 'Tỷ lệ chuyển đổi cơ hội',
167	    description:
168	      'Trong số cơ hội tạo mới trong kỳ, bao nhiêu phần trăm đã chuyển sang THẮNG (tính theo %).',
169	    defaultValue: '0.00',
170	    defaultUnit: '%',
171	    async resolve(prisma, context) {
172	      const base = { createdAt: inPeriod(context.period), ...byOwner(context) };
173	      const [total, won] = await Promise.all([
174	        prisma.opportunity.count({ where: base }),
175	        prisma.opportunity.count({ where: { ...base, stage: 'THANG' } }),
176	      ]);
177	      if (total === 0) return 0;
178	      return Math.round((won / total) * 10_000) / 100;
179	    },
180	  },
181	  {
182	    id: 'sales.overdue_debt_count',
183	    name: 'Số khoản công nợ quá hạn',
184	    description:
185	      'Số kỳ thanh toán của đơn hàng và hợp đồng chưa thu mà đã quá hạn tính đến cuối kỳ KPI. ' +
186	      'Dùng cho chỉ tiêu trừ điểm công nợ.',
187	    defaultValue: '0.00',
188	    defaultUnit: 'Khoản',
189	    async resolve(prisma, context) {
190	      const overdue = { isPaid: false, dueDate: { lt: context.period.end }, deletedAt: null };
191	      const ownerId = ownerIdFilter(context);
192	      const [orderPayments, contractPayments] = await Promise.all([
193	        prisma.salesOrderPayment.count({
194	          where: { ...overdue, ...(ownerId ? { order: { ownerId } } : {}) },
195	        }),
196	        prisma.contractPayment.count({
197	          where: { ...overdue, ...(ownerId ? { contract: { ownerId } } : {}) },
198	        }),
199	      ]);
200	      return orderPayments + contractPayments;
201	    },
202	  },
203	  {
204	    id: 'sales.activity_count',
205	    name: 'Số hoạt động bán hàng',
206	    description: 'Số hoạt động (gọi, gặp, email, ghi chú) phát sinh trong kỳ KPI.',
207	    defaultValue: '0.00',
208	    defaultUnit: 'Hoạt động',
209	    async resolve(prisma, context) {
210	      return prisma.activity.count({
211	        where: { occurredAt: inPeriod(context.period), deletedAt: null, ...byOwner(context) },
212	      });
213	    },
214	  },
215	  {
216	    id: 'support.sla_on_time_rate',
217	    name: 'Tỷ lệ ticket đúng hạn SLA',
218	    description:
219	      'Trong số ticket tạo trong kỳ, bao nhiêu % được xử lý xong trước hạn SLA (theo %). ' +
220	      'Ticket chưa xử lý xong hoặc xử lý sau hạn đều tính là trễ.',
221	    defaultValue: '0.00',
222	    defaultUnit: '%',
223	    async resolve(prisma, context) {
224	      const tickets = await prisma.ticket.findMany({
225	        where: { ...ticketBase(context), createdAt: inPeriod(context.period) },
226	        select: { slaDueAt: true, resolvedAt: true },
227	      });
228	      if (!tickets.length) return 0;
229	      const onTime = tickets.filter(
230	        (ticket) =>
231	          ticket.resolvedAt !== null &&
232	          (ticket.slaDueAt === null || ticket.resolvedAt <= ticket.slaDueAt),
233	      ).length;
234	      return Math.round((onTime / tickets.length) * 10_000) / 100;
235	    },
236	  },
237	  {
238	    id: 'support.avg_resolution_hours',
239	    name: 'Thời gian xử lý ticket trung bình (giờ)',
240	    description:
241	      'Số giờ trung bình từ lúc tạo ticket đến lúc xử lý xong, tính trên các ticket xử lý xong ' +
242	      'trong kỳ. Chỉ tiêu này càng thấp càng tốt (dùng hướng DECREASE).',
243	    defaultValue: '0.00',
244	    defaultUnit: 'Giờ',
245	    async resolve(prisma, context) {
246	      const tickets = await prisma.ticket.findMany({
247	        where: {
248	          ...ticketBase(context),
249	          resolvedAt: inPeriod(context.period),
250	        },
251	        select: { createdAt: true, resolvedAt: true },
252	      });
253	      const durations = tickets
254	        .filter((ticket) => ticket.resolvedAt !== null)
255	        .map((ticket) => hoursBetween(ticket.createdAt, ticket.resolvedAt as Date));
256	      if (!durations.length) return 0;
257	      const total = durations.reduce((sum, hours) => sum + hours, 0);
258	      return Math.round((total / durations.length) * 100) / 100;
259	    },
260	  },
261	  {
262	    id: 'support.incident_count',
