434	  {
435	    id: 'finance.compliance_issue_count',
436	    name: 'Số vấn đề tuân thủ',
437	    description: 'Số vi phạm tuân thủ phát hiện trong kỳ. Dùng cho chỉ tiêu trừ điểm tuân thủ.',
438	    defaultValue: '0.00',
