452	    id: 'marketing.qualified_leads',
453	    name: 'Lead đủ điều kiện',
454	    description: 'Số lead đủ điều kiện được ghi nhận trong kỳ KPI.',
455	    defaultValue: '0.00',
456	    defaultUnit: 'Lead',
457	    async resolve(prisma, context) {
458	      return prisma.campaignRecipient.count({
459	        where: { status: 'COMPLETED', completedAt: inPeriod(context.period) },
460	      });
461	    },
