464	    id: 'customer.new_customers',
465	    name: 'Khách hàng mới',
466	    description: 'Số khách hàng mới được tạo trong kỳ KPI.',
467	    defaultValue: '0.00',
468	    defaultUnit: 'Khách hàng',
469	    async resolve(prisma, context) {
470	      return prisma.customer.count({
