481	    async resolve(prisma, context) {
482	      const assigneeId = ownerIdFilter(context);
483	      return prisma.task.count({
484	        where: {
485	          status: 'COMPLETED',
486	          completedAt: inPeriod(context.period),
487	          deletedAt: null,
488	          ...(assigneeId ? { assigneeId } : {}),
489	        },
490	      });
491	    },
492	  },
