import { calendarLateDays } from '@ics/shared';
import type { PrismaService } from '../common/prisma.service';

/**
 * Danh mục nguồn dữ liệu KPI — nơi duy nhất định nghĩa "số thực tế của chỉ tiêu lấy từ đâu".
 *
 * Mỗi nguồn tự chịu trách nhiệm LỌC THEO KỲ KPI. Trước đây các nguồn cộng dồn toàn bộ lịch sử
 * (dù mô tả ghi "trong kỳ KPI"), nên điểm KPI tháng nào cũng giống nhau và tăng vô hạn theo
 * thời gian — sai về nghiệp vụ. Giờ mọi nguồn đều nhận `period` và chỉ tính trong khoảng đó.
 *
 * Thêm nguồn mới: khai một phần tử vào KPI_DATA_SOURCES là xong — không phải sửa chỗ chấm điểm.
 */

export interface KpiPeriod {
  /** Đầu kỳ, tính cả mốc này. */
  start: Date;
  /** Cuối kỳ, tính cả mốc này. */
  end: Date;
}

/**
 * Bối cảnh khi lấy số thực tế.
 *
 * `ownerUserId` rất quan trọng: KPI là của TỪNG NGƯỜI, nên chỉ tiêu "doanh thu" của nhân viên A
 * phải là doanh thu do A phụ trách, không phải doanh thu toàn công ty. Khi không truyền
 * (vd xem trước lúc soạn chỉ tiêu) thì lấy số của cả tenant.
 */
export interface KpiResolveContext {
  period: KpiPeriod;
  ownerUserId?: string | null;
  /**
   * Giới hạn theo MỘT NHÓM người phụ trách — dùng khi trang chủ hiển thị số của nhóm / phòng ban /
   * chi nhánh mà người xem được phép đọc. Có `ownerUserId` thì `ownerUserId` thắng (KPI cá nhân).
   *
   * Mảng RỖNG có nghĩa "không ai trong phạm vi" và phải cho ra 0. Đây là lý do tồn tại của
   * `ownerIdFilter` bên dưới: nếu để mảng rỗng rơi vào nhánh "không lọc gì" thì một trưởng nhóm
   * chưa có thành viên sẽ nhìn thấy số của TOÀN BỘ công ty — lộ dữ liệu, không phải hiển thị sai.
   */
  ownerUserIds?: readonly string[] | null;
}

type ScopedPrisma = PrismaService['scoped'];

export interface KpiDataSourceDef {
  id: string;
  name: string;
  description: string;
  defaultValue: string;
  defaultUnit: string;
  /** Lấy số thực tế của nguồn này trong kỳ (và theo người phụ trách nếu có). */
  resolve: (prisma: ScopedPrisma, context: KpiResolveContext) => Promise<number>;
}

function toNumber(value: unknown): number {
  if (value === null || value === undefined) return 0;
  const parsed = Number.parseFloat(String(value));
  return Number.isFinite(parsed) ? parsed : 0;
}

/** Khoảng thời gian dạng Prisma filter cho một cột ngày. */
function inPeriod(period: KpiPeriod) {
  return { gte: period.start, lte: period.end };
}

/**
 * Bộ lọc cho một cột kiểu `ownerId`. Trả `undefined` = không giới hạn (cả tenant), dùng cho scope
 * ALL và cho lúc xem trước chỉ tiêu. Tách riêng để các nguồn lọc qua quan hệ (`opportunity: {...}`)
 * dùng chung một luật với `byOwner`.
 */
function ownerIdFilter(context: KpiResolveContext): string | { in: string[] } | undefined {
  if (context.ownerUserId) return context.ownerUserId;
  if (context.ownerUserIds) return { in: [...context.ownerUserIds] };
  return undefined;
}

/** Điều kiện lọc theo người phụ trách; rỗng khi tính cho cả tenant. */
function byOwner(context: KpiResolveContext) {
  const ownerId = ownerIdFilter(context);
  return ownerId ? { ownerId } : {};
}

/** Số giờ giữa hai mốc thời gian. */
function hoursBetween(from: Date, to: Date): number {
  return (to.getTime() - from.getTime()) / (60 * 60 * 1000);
}

/** Số phút giữa hai mốc thời gian. */
function minutesBetween(from: Date, to: Date): number {
  return (to.getTime() - from.getTime()) / (60 * 1000);
}

/** Điều kiện lọc ticket cơ bản: chưa xoá, thuộc người phụ trách nếu có. */
function ticketBase(context: KpiResolveContext) {
  return { deletedAt: null, ...byOwner(context) };
}

/** Id các cơ hội đã chuyển sang trạng thái THẮNG trong kỳ (theo lịch sử chuyển giai đoạn). */
async function wonOpportunityIdsInPeriod(
  prisma: ScopedPrisma,
  context: KpiResolveContext,
): Promise<string[]> {
  const ownerId = ownerIdFilter(context);
  const histories = await prisma.opportunityStageHistory.findMany({
    where: {
      toStage: 'THANG',
      changedAt: inPeriod(context.period),
      ...(ownerId ? { opportunity: { ownerId } } : {}),
    },
    select: { opportunityId: true },
    distinct: ['opportunityId'],
  });
  return histories.map((row) => row.opportunityId);
}

export const KPI_DATA_SOURCES: KpiDataSourceDef[] = [
  {
    id: 'sales.closed_revenue',
    name: 'Doanh thu đã chốt',
    description:
      'Tổng giá trị cơ hội chuyển sang THẮNG trong kỳ, cộng giá trị hợp đồng hoàn thành ký trong kỳ.',
    defaultValue: '0.00',
    defaultUnit: 'VNĐ',
    async resolve(prisma, context) {
      const wonIds = await wonOpportunityIdsInPeriod(prisma, context);
      const [opportunities, contracts] = await Promise.all([
        wonIds.length
          ? prisma.opportunity.aggregate({
              where: { id: { in: wonIds } },
              _sum: { amount: true },
            })
          : Promise.resolve({ _sum: { amount: null } }),
        prisma.contract.aggregate({
          where: {
            status: 'COMPLETED',
            signDate: inPeriod(context.period),
            ...byOwner(context),
          },
          _sum: { contractValue: true },
        }),
      ]);
      return toNumber(opportunities._sum.amount) + toNumber(contracts._sum.contractValue);
    },
  },
  {
    id: 'sales.closed_deals',
    name: 'Số thương vụ đã chốt',
    description: 'Số cơ hội chuyển sang THẮNG trong kỳ, cộng số hợp đồng hoàn thành ký trong kỳ.',
    defaultValue: '0.00',
    defaultUnit: 'Thương vụ',
    async resolve(prisma, context) {
      const [wonIds, contracts] = await Promise.all([
        wonOpportunityIdsInPeriod(prisma, context),
        prisma.contract.count({
          where: {
            status: 'COMPLETED',
            signDate: inPeriod(context.period),
            ...byOwner(context),
          },
        }),
      ]);
      return wonIds.length + contracts;
    },
  },
  {
    id: 'sales.conversion_rate',
    name: 'Tỷ lệ chuyển đổi cơ hội',
    description:
      'Trong số cơ hội tạo mới trong kỳ, bao nhiêu phần trăm đã chuyển sang THẮNG (tính theo %).',
    defaultValue: '0.00',
    defaultUnit: '%',
    async resolve(prisma, context) {
      const base = { createdAt: inPeriod(context.period), ...byOwner(context) };
      const [total, won] = await Promise.all([
        prisma.opportunity.count({ where: base }),
        prisma.opportunity.count({ where: { ...base, stage: 'THANG' } }),
      ]);
      if (total === 0) return 0;
      return Math.round((won / total) * 10_000) / 100;
    },
  },
  {
    id: 'sales.overdue_debt_count',
    name: 'Số khoản công nợ quá hạn',
    description:
      'Số kỳ thanh toán của đơn hàng và hợp đồng chưa thu mà đã quá hạn tính đến cuối kỳ KPI. ' +
      'Dùng cho chỉ tiêu trừ điểm công nợ.',
    defaultValue: '0.00',
    defaultUnit: 'Khoản',
    async resolve(prisma, context) {
      const overdue = { isPaid: false, dueDate: { lt: context.period.end }, deletedAt: null };
      const ownerId = ownerIdFilter(context);
      const [orderPayments, contractPayments] = await Promise.all([
        prisma.salesOrderPayment.count({
          where: { ...overdue, ...(ownerId ? { order: { ownerId } } : {}) },
        }),
        prisma.contractPayment.count({
          where: { ...overdue, ...(ownerId ? { contract: { ownerId } } : {}) },
        }),
      ]);
      return orderPayments + contractPayments;
    },
  },
  {
    id: 'sales.activity_count',
    name: 'Số hoạt động bán hàng',
    description: 'Số hoạt động (gọi, gặp, email, ghi chú) phát sinh trong kỳ KPI.',
    defaultValue: '0.00',
    defaultUnit: 'Hoạt động',
    async resolve(prisma, context) {
      return prisma.activity.count({
        where: { occurredAt: inPeriod(context.period), deletedAt: null, ...byOwner(context) },
      });
    },
  },
  {
    id: 'support.sla_on_time_rate',
    name: 'Tỷ lệ ticket đúng hạn SLA',
    description:
      'Trong số ticket tạo trong kỳ, bao nhiêu % được xử lý xong trước hạn SLA (theo %). ' +
      'Ticket chưa xử lý xong hoặc xử lý sau hạn đều tính là trễ.',
    defaultValue: '0.00',
    defaultUnit: '%',
    async resolve(prisma, context) {
      const tickets = await prisma.ticket.findMany({
        where: { ...ticketBase(context), createdAt: inPeriod(context.period) },
        select: { slaDueAt: true, resolvedAt: true },
      });
      if (!tickets.length) return 0;
      const onTime = tickets.filter(
        (ticket) =>
          ticket.resolvedAt !== null &&
          (ticket.slaDueAt === null || ticket.resolvedAt <= ticket.slaDueAt),
      ).length;
      return Math.round((onTime / tickets.length) * 10_000) / 100;
    },
  },
  {
    id: 'support.avg_resolution_hours',
    name: 'Thời gian xử lý ticket trung bình (giờ)',
    description:
      'Số giờ trung bình từ lúc tạo ticket đến lúc xử lý xong, tính trên các ticket xử lý xong ' +
      'trong kỳ. Chỉ tiêu này càng thấp càng tốt (dùng hướng DECREASE).',
    defaultValue: '0.00',
    defaultUnit: 'Giờ',
    async resolve(prisma, context) {
      const tickets = await prisma.ticket.findMany({
        where: {
          ...ticketBase(context),
          resolvedAt: inPeriod(context.period),
        },
        select: { createdAt: true, resolvedAt: true },
      });
      const durations = tickets
        .filter((ticket) => ticket.resolvedAt !== null)
        .map((ticket) => hoursBetween(ticket.createdAt, ticket.resolvedAt as Date));
      if (!durations.length) return 0;
      const total = durations.reduce((sum, hours) => sum + hours, 0);
      return Math.round((total / durations.length) * 100) / 100;
    },
  },
  {
    id: 'support.incident_count',
    name: 'Số sự cố',
    description: 'Số ticket loại SỰ CỐ phát sinh trong kỳ. Dùng cho chỉ tiêu trừ điểm sự cố.',
    defaultValue: '0.00',
    defaultUnit: 'Sự cố',
    async resolve(prisma, context) {
      return prisma.ticket.count({
        where: { ...ticketBase(context), type: 'INCIDENT', createdAt: inPeriod(context.period) },
      });
    },
  },
  {
    id: 'support.avg_first_response_minutes',
    name: 'Thời gian phản hồi đầu tiên (phút)',
    description:
      'Số phút trung bình từ lúc tạo ticket đến lần phản hồi đầu tiên cho khách, tính trên ' +
      'ticket tạo trong kỳ đã được phản hồi. Càng thấp càng tốt (dùng hướng DECREASE).',
    defaultValue: '0.00',
    defaultUnit: 'Phút',
    async resolve(prisma, context) {
      const tickets = await prisma.ticket.findMany({
        where: {
          ...ticketBase(context),
          createdAt: inPeriod(context.period),
          firstRespondedAt: { not: null },
        },
        select: { createdAt: true, firstRespondedAt: true },
      });
      const durations = tickets
        .filter((ticket) => ticket.firstRespondedAt !== null)
        .map((ticket) => minutesBetween(ticket.createdAt, ticket.firstRespondedAt as Date));
      if (!durations.length) return 0;
      const total = durations.reduce((sum, minutes) => sum + minutes, 0);
      return Math.round((total / durations.length) * 100) / 100;
    },
  },
  {
    id: 'support.resolved_within_sla_rate',
    name: 'Tỷ lệ giải quyết đúng SLA',
    description:
      'Trong số ticket ĐÃ giải quyết trong kỳ, bao nhiêu % đúng hạn SLA (theo %). ' +
      'Khác với chỉ tiêu SLA đúng hạn ở chỗ mẫu số chỉ gồm ticket đã giải quyết.',
    defaultValue: '0.00',
    defaultUnit: '%',
    async resolve(prisma, context) {
      const tickets = await prisma.ticket.findMany({
        where: { ...ticketBase(context), resolvedAt: inPeriod(context.period) },
        select: { slaDueAt: true, resolvedAt: true },
      });
      if (!tickets.length) return 0;
      const withinSla = tickets.filter(
        (ticket) =>
          ticket.resolvedAt !== null &&
          (ticket.slaDueAt === null || ticket.resolvedAt <= ticket.slaDueAt),
      ).length;
      return Math.round((withinSla / tickets.length) * 10_000) / 100;
    },
  },
  {
    id: 'support.avg_csat',
    name: 'Điểm hài lòng khách hàng (CSAT)',
    description:
      'Điểm CSAT trung bình (thang 1..5) của các ticket tạo trong kỳ mà khách đã đánh giá.',
    defaultValue: '0.00',
    defaultUnit: 'Điểm',
    async resolve(prisma, context) {
      const result = await prisma.ticket.aggregate({
        where: {
          ...ticketBase(context),
          createdAt: inPeriod(context.period),
          csatScore: { not: null },
        },
        _avg: { csatScore: true },
      });
      return Math.round(toNumber(result._avg.csatScore) * 100) / 100;
    },
  },
  {
    id: 'support.complaint_count',
    name: 'Số khiếu nại',
    description:
      'Số ticket loại KHIẾU NẠI phát sinh trong kỳ. Dùng cho chỉ tiêu trừ điểm khiếu nại.',
    defaultValue: '0.00',
    defaultUnit: 'Khiếu nại',
    async resolve(prisma, context) {
      return prisma.ticket.count({
        where: { ...ticketBase(context), type: 'COMPLAINT', createdAt: inPeriod(context.period) },
      });
    },
  },
  {
    id: 'operation.completed_processes',
    name: 'Số quy trình hoàn thành',
    description:
      'Số phiếu quy trình (RequestTicket) được duyệt xong trong kỳ. Lọc theo người đề nghị.',
    defaultValue: '0.00',
    defaultUnit: 'Quy trình',
    async resolve(prisma, context) {
      const requesterUserId = ownerIdFilter(context);
      return prisma.requestTicket.count({
        where: {
          deletedAt: null,
          status: 'APPROVED',
          resolvedAt: inPeriod(context.period),
          ...(requesterUserId ? { requesterUserId } : {}),
        },
      });
    },
  },
  {
    id: 'finance.late_days',
    name: 'Tổng số ngày trễ hạn (Tài chính)',
    description:
      'Tổng số ngày trễ của các công việc tài chính có hạn trong kỳ. Việc chưa xong thì tính ' +
      'tới hiện tại. Dùng cho chỉ tiêu trừ điểm đúng hạn.',
    defaultValue: '0.00',
    defaultUnit: 'Ngày',
    async resolve(prisma, context) {
      const tasks = await prisma.financeTask.findMany({
        where: {
          deletedAt: null,
          status: { not: 'CANCELLED' },
          dueDate: inPeriod(context.period),
          ...byOwner(context),
        },
        select: { dueDate: true, completedAt: true },
      });
      const now = new Date();
      return tasks.reduce(
        (sum, task) => sum + calendarLateDays(task.dueDate, task.completedAt, now),
        0,
      );
    },
  },
  {
    id: 'finance.error_count',
    name: 'Số lỗi tài chính',
    description: 'Số lỗi phát hiện trong kỳ. Dùng cho chỉ tiêu trừ điểm độ chính xác.',
    defaultValue: '0.00',
    defaultUnit: 'Lỗi',
    async resolve(prisma, context) {
      return prisma.financeIssue.count({
        where: {
          deletedAt: null,
          type: 'ERROR',
          detectedAt: inPeriod(context.period),
          ...byOwner(context),
        },
      });
    },
  },
  {
    id: 'finance.reconciled_amount',
    name: 'Số tiền đã đối soát',
    description:
      'Tổng số tiền đã đối soát xong của các công việc đối soát có hạn trong kỳ. ' +
      'So với mục tiêu trong kế hoạch KPI để ra điểm.',
    defaultValue: '0.00',
    defaultUnit: 'VNĐ',
    async resolve(prisma, context) {
      const result = await prisma.financeTask.aggregate({
        where: {
          deletedAt: null,
          type: 'RECONCILIATION',
          dueDate: inPeriod(context.period),
          ...byOwner(context),
        },
        _sum: { reconciledAmount: true },
      });
      return toNumber(result._sum.reconciledAmount);
    },
  },
  {
    id: 'finance.compliance_issue_count',
    name: 'Số vấn đề tuân thủ',
    description: 'Số vi phạm tuân thủ phát hiện trong kỳ. Dùng cho chỉ tiêu trừ điểm tuân thủ.',
    defaultValue: '0.00',
    defaultUnit: 'Vấn đề',
    async resolve(prisma, context) {
      return prisma.financeIssue.count({
        where: {
          deletedAt: null,
          type: 'COMPLIANCE',
          detectedAt: inPeriod(context.period),
          ...byOwner(context),
        },
      });
    },
  },
  {
    id: 'marketing.qualified_leads',
    name: 'Lead đủ điều kiện',
    description: 'Số lead đủ điều kiện được ghi nhận trong kỳ KPI.',
    defaultValue: '0.00',
    defaultUnit: 'Lead',
    async resolve(prisma, context) {
      return prisma.campaignRecipient.count({
        where: { status: 'COMPLETED', completedAt: inPeriod(context.period) },
      });
    },
  },
  {
    id: 'customer.new_customers',
    name: 'Khách hàng mới',
    description: 'Số khách hàng mới được tạo trong kỳ KPI.',
    defaultValue: '0.00',
    defaultUnit: 'Khách hàng',
    async resolve(prisma, context) {
      return prisma.customer.count({
        where: { createdAt: inPeriod(context.period), deletedAt: null, ...byOwner(context) },
      });
    },
  },
  {
    id: 'tasks.completed',
    name: 'Công việc hoàn thành',
    description: 'Số công việc được đánh dấu hoàn thành trong kỳ KPI.',
    defaultValue: '0.00',
    defaultUnit: 'Việc',
    async resolve(prisma, context) {
      const assigneeId = ownerIdFilter(context);
      return prisma.task.count({
        where: {
          status: 'COMPLETED',
          completedAt: inPeriod(context.period),
          deletedAt: null,
          ...(assigneeId ? { assigneeId } : {}),
        },
      });
    },
  },
];

export function findKpiDataSource(id: string): KpiDataSourceDef | undefined {
  return KPI_DATA_SOURCES.find((source) => source.id === id);
}

/** Kỳ KPI theo tháng/năm: từ 00:00:00 ngày 1 đến 23:59:59.999 ngày cuối tháng. */
export function monthPeriod(periodMonth: number, periodYear: number): KpiPeriod {
  return {
    start: new Date(periodYear, periodMonth - 1, 1, 0, 0, 0, 0),
    end: new Date(periodYear, periodMonth, 0, 23, 59, 59, 999),
  };
}

