/**
 * TRỤC THỜI GIAN của KPI — chia một kỳ (1 năm) thành các kỳ con.
 *
 * Toàn bộ phép toán lịch nằm ở đây và dùng chung backend ↔ frontend: backend cần
 * để sinh slot và gộp số, frontend cần để vẽ selector và dải ô. Hai bên tự tính
 * lấy là kiểu bug lệch một ô mà không ai phát hiện.
 *
 * Hàm thuần, không phụ thuộc Zod. Mọi mốc thời gian tính bằng UTC — dùng giờ địa
 * phương thì cùng một `slotIndex` cho ra hai ngày khác nhau ở hai múi giờ.
 *
 * ── Ba khái niệm ────────────────────────────────────────────
 *   cadence   Nhịp chia của MỘT chỉ tiêu (mỗi chỉ tiêu tự chọn).
 *   slotIndex Thứ tự 0-based trong nhịp đó (quý 3 ⇒ 2, tháng 8 ⇒ 7).
 *   slotKey   Khoá tự mô tả, duy nhất trong kế hoạch: `2026-Q3`, `2026-08`.
 */

export const KPI_CADENCES = ['PERIOD', 'QUARTER', 'MONTH', 'WEEK', 'DAY'] as const;
export type KpiCadence = (typeof KPI_CADENCES)[number];

/**
 * Nhãn của nhịp khi CHỌN. "Cả kỳ (không chia)" chứ không phải "Năm": người dùng
 * chọn cách chia, và lựa chọn này nghĩa là *không* chia.
 */
export const KPI_CADENCE_LABELS: Record<KpiCadence, string> = {
  PERIOD: 'Cả kỳ (không chia)',
  QUARTER: 'Theo quý',
  MONTH: 'Theo tháng',
  WEEK: 'Theo tuần',
  DAY: 'Theo ngày',
};

/**
 * Nhãn ngắn dùng cho selector "độ mịn đang xem".
 *
 * `PERIOD` ở đây là "Năm" chứ không phải "Cả kỳ": trong bộ chọn nó đứng cạnh
 * Quý/Tháng/Tuần nên phải cùng một loại đơn vị thời gian. Còn khi CHỌN CÁCH CHIA
 * (`KPI_CADENCE_LABELS`) thì nó mang nghĩa "không chia" — hai ngữ cảnh khác nhau.
 */
export const KPI_CADENCE_SHORT_LABELS: Record<KpiCadence, string> = {
  PERIOD: 'Năm',
  QUARTER: 'Quý',
  MONTH: 'Tháng',
  WEEK: 'Tuần',
  DAY: 'Ngày',
};

/**
 * Các cửa sổ NGƯỜI XEM chọn được — hẹp hơn `KPI_CADENCES`.
 *
 * Khác với `cadence` của chỉ tiêu (nhịp GHI NHẬN), đây là nhịp ĐỌC. Không có
 * "Ngày": xem từng ngày thì quá mủn để đọc ra xu hướng và ô chọn kỳ thành danh
 * sách 365 mục — chỉ tiêu vẫn tick theo ngày, xem ở mức Tuần là thấy đủ.
 *
 * Nằm ở shared vì backend chấm SẴN điểm tổng hợp cho đúng những cửa sổ này; hai
 * bên lệch một mức là frontend chọn được một kỳ mà không có điểm nào khớp.
 */
export const KPI_VIEW_CADENCES = ['PERIOD', 'QUARTER', 'MONTH', 'WEEK'] as const;

/** Độ mịn tăng dần — so hai nhịp xem cái nào chia nhỏ hơn. */
export const KPI_CADENCE_RANK: Record<KpiCadence, number> = {
  PERIOD: 0,
  QUARTER: 1,
  MONTH: 2,
  WEEK: 3,
  DAY: 4,
};

/**
 * Tuần thứ 52 GỘP NỐT 1–2 ngày lẻ cuối năm.
 *
 * Cố ý không dùng tuần ISO: tuần ISO tràn sang năm trước/sau, mà một kỳ KPI là
 * một năm dương lịch — có ô nằm ngoài kỳ là vô nghĩa. Đổi lại, tuần cuối dài 8–9
 * ngày; đó là cái giá rẻ hơn nhiều so với một tuần "thuộc hai kỳ".
 */
const WEEKS_PER_YEAR = 52;

export function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function daysInYear(year: number): number {
  return isLeapYear(year) ? 366 : 365;
}

/** Số kỳ con của một nhịp trong một năm. */
export function slotCount(cadence: KpiCadence, year: number): number {
  switch (cadence) {
    case 'PERIOD':
      return 1;
    case 'QUARTER':
      return 4;
    case 'MONTH':
      return 12;
    case 'WEEK':
      return WEEKS_PER_YEAR;
    case 'DAY':
      return daysInYear(year);
  }
}

const pad2 = (value: number) => String(value).padStart(2, '0');

/** Ngày thứ `dayOfYear` (1-based) của năm, tính theo UTC. */
function dateOfYear(year: number, dayOfYear: number): Date {
  return new Date(Date.UTC(year, 0, dayOfYear));
}

/** Ngày thứ mấy trong năm (1-based) của một mốc thời gian. */
function dayOfYearOf(date: Date): number {
  const startOfYear = Date.UTC(date.getUTCFullYear(), 0, 1);
  return (
    Math.floor(
      (Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) - startOfYear) /
        86_400_000,
    ) + 1
  );
}

export type SlotRange = { startAt: Date; endAt: Date };

/** Khoảng thời gian [đầu, cuối] của một kỳ con. `endAt` là mili-giây cuối cùng. */
export function slotRange(cadence: KpiCadence, year: number, slotIndex: number): SlotRange {
  const endOfDay = (date: Date) => new Date(date.getTime() + 86_400_000 - 1);

  switch (cadence) {
    case 'PERIOD':
      return {
        startAt: new Date(Date.UTC(year, 0, 1)),
        endAt: endOfDay(new Date(Date.UTC(year, 11, 31))),
      };
    case 'QUARTER':
      return {
        startAt: new Date(Date.UTC(year, slotIndex * 3, 1)),
        // Ngày 0 của tháng kế tiếp = ngày cuối tháng hiện tại.
        endAt: endOfDay(new Date(Date.UTC(year, slotIndex * 3 + 3, 0))),
      };
    case 'MONTH':
      return {
        startAt: new Date(Date.UTC(year, slotIndex, 1)),
        endAt: endOfDay(new Date(Date.UTC(year, slotIndex + 1, 0))),
      };
    case 'WEEK': {
      const startDay = slotIndex * 7 + 1;
      const endDay = slotIndex === WEEKS_PER_YEAR - 1 ? daysInYear(year) : startDay + 6;
      return { startAt: dateOfYear(year, startDay), endAt: endOfDay(dateOfYear(year, endDay)) };
    }
    case 'DAY': {
      const day = dateOfYear(year, slotIndex + 1);
      return { startAt: day, endAt: endOfDay(day) };
    }
  }
}

/** Khoá tự mô tả, duy nhất trong một kế hoạch (một kế hoạch = một năm). */
export function slotKey(cadence: KpiCadence, year: number, slotIndex: number): string {
  switch (cadence) {
    case 'PERIOD':
      return String(year);
    case 'QUARTER':
      return `${year}-Q${slotIndex + 1}`;
    case 'MONTH':
      return `${year}-${pad2(slotIndex + 1)}`;
    case 'WEEK':
      return `${year}-W${pad2(slotIndex + 1)}`;
    case 'DAY': {
      const { startAt } = slotRange('DAY', year, slotIndex);
      return `${year}-${pad2(startAt.getUTCMonth() + 1)}-${pad2(startAt.getUTCDate())}`;
    }
  }
}

/** Nhãn đầy đủ, dùng ở selector và tiêu đề. */
export function slotLabel(cadence: KpiCadence, year: number, slotIndex: number): string {
  switch (cadence) {
    case 'PERIOD':
      return 'Cả kỳ';
    case 'QUARTER':
      return `Quý ${slotIndex + 1}`;
    case 'MONTH':
      return `Tháng ${slotIndex + 1}`;
    case 'WEEK':
      return `Tuần ${slotIndex + 1}`;
    case 'DAY': {
      const { startAt } = slotRange('DAY', year, slotIndex);
      return `${pad2(startAt.getUTCDate())}/${pad2(startAt.getUTCMonth() + 1)}`;
    }
  }
}

/**
 * Nhãn ngắn cho tiêu đề cột của dải ô.
 *
 * Tháng dùng `T7`, tuần dùng `W31` — KHÔNG cùng chữ `T`, vì khi một chỉ tiêu theo
 * tháng và một chỉ tiêu theo tuần nằm cạnh nhau thì `T7` và `T7` là hai thứ khác
 * hẳn nhau.
 */
export function slotShortLabel(cadence: KpiCadence, year: number, slotIndex: number): string {
  switch (cadence) {
    case 'PERIOD':
      return 'Cả kỳ';
    case 'QUARTER':
      return `Q${slotIndex + 1}`;
    case 'MONTH':
      return `T${slotIndex + 1}`;
    case 'WEEK':
      return `W${slotIndex + 1}`;
    case 'DAY':
      return slotLabel('DAY', year, slotIndex);
  }
}

/**
 * Nhãn của một DÃY kỳ con liền nhau: "Tuần 1–13", "Tháng 7–9".
 *
 * Dùng khi một cửa sổ ôm nhiều kỳ con. Liệt kê từng cái ("Tuần 1 · Tuần 2 · …")
 * vừa dài vừa phải cắt bằng dấu ba chấm, mà cắt xong thì người đọc mất luôn
 * thông tin quan trọng nhất là dãy đó KẾT THÚC ở đâu.
 *
 * `slotIndexesWithin` luôn trả về một dãy liền nhau nên chỉ cần hai đầu mút.
 */
export function slotSpanLabel(
  cadence: KpiCadence,
  year: number,
  fromIndex: number,
  toIndex: number,
): string {
  if (fromIndex === toIndex) return slotLabel(cadence, year, fromIndex);
  switch (cadence) {
    case 'PERIOD':
      return 'Cả kỳ';
    case 'QUARTER':
      return `Quý ${fromIndex + 1}–${toIndex + 1}`;
    case 'MONTH':
      return `Tháng ${fromIndex + 1}–${toIndex + 1}`;
    case 'WEEK':
      return `Tuần ${fromIndex + 1}–${toIndex + 1}`;
    case 'DAY':
      // Ngày đã có nhãn dd/MM nên ghép hai đầu là đọc được ngay.
      return `${slotLabel('DAY', year, fromIndex)}–${slotLabel('DAY', year, toIndex)}`;
  }
}

/** Mô tả khoảng ("T7–T9", "01/08–31/08") — hiện kèm nhãn khi nhịp khác nhau. */
export function slotRangeLabel(cadence: KpiCadence, year: number, slotIndex: number): string {
  if (cadence === 'PERIOD') return `01/01–31/12/${year}`;
  const { startAt, endAt } = slotRange(cadence, year, slotIndex);
  if (cadence === 'MONTH') return `${pad2(startAt.getUTCMonth() + 1)}/${year}`;
  const fmt = (date: Date) => `${pad2(date.getUTCDate())}/${pad2(date.getUTCMonth() + 1)}`;
  return `${fmt(startAt)}–${fmt(endAt)}`;
}

/**
 * Kỳ con chứa một mốc thời gian. `null` khi mốc đó nằm ngoài năm của kế hoạch.
 */
export function slotIndexAt(cadence: KpiCadence, year: number, at: Date): number | null {
  if (at.getUTCFullYear() !== year) return null;
  switch (cadence) {
    case 'PERIOD':
      return 0;
    case 'QUARTER':
      return Math.floor(at.getUTCMonth() / 3);
    case 'MONTH':
      return at.getUTCMonth();
    case 'WEEK':
      return Math.min(WEEKS_PER_YEAR - 1, Math.floor((dayOfYearOf(at) - 1) / 7));
    case 'DAY':
      return dayOfYearOf(at) - 1;
  }
}

/**
 * Kỳ con mặc định khi mở màn hình.
 *
 * Kỳ đang chạy ⇒ kỳ con chứa hôm nay. Kỳ đã qua ⇒ kỳ con cuối (nơi có số liệu
 * gần nhất). Kỳ tương lai ⇒ kỳ con đầu.
 */
export function defaultSlotIndex(cadence: KpiCadence, year: number, now: Date): number {
  const current = slotIndexAt(cadence, year, now);
  if (current !== null) return current;
  return now.getUTCFullYear() > year ? slotCount(cadence, year) - 1 : 0;
}

/**
 * Các kỳ con của `cadence` GIAO với một cửa sổ thời gian.
 *
 * Đây là phép duy nhất dùng để ghép hai nhịp khác nhau — không dùng phép chia
 * số học "quý = 3 tháng", vì tuần thì không lồng khít vào tháng. Giao khoảng
 * đúng cho mọi cặp nhịp, kể cả tuần nằm vắt qua hai tháng.
 */
export function slotIndexesWithin(cadence: KpiCadence, year: number, window: SlotRange): number[] {
  const result: number[] = [];
  const total = slotCount(cadence, year);
  for (let index = 0; index < total; index += 1) {
    const range = slotRange(cadence, year, index);
    if (
      range.startAt.getTime() <= window.endAt.getTime() &&
      range.endAt.getTime() >= window.startAt.getTime()
    ) {
      result.push(index);
    }
  }
  return result;
}

// ─────────────────────────────────────────────────────────────
// Nhịp nào hợp lệ với loại chỉ tiêu nào
// ─────────────────────────────────────────────────────────────

/**
 * Nhịp cho phép theo CÁCH ĐO.
 *
 * Đạt/không đạt mở tới tuần/ngày — đó chính là loại cần keep-check thường xuyên
 * ("nộp báo cáo đúng hạn mỗi ngày"), và điểm của nó là Σđạt/Σlần nên chia mịn
 * bao nhiêu cũng vẫn đúng.
 *
 * Chỉ tiêu đo bằng số dừng ở THÁNG: chia doanh thu xuống từng ngày là con số
 * không ai lập được kế hoạch, và một năm sẽ có 365 ô mục tiêu phải khai tay.
 */
export function allowedCadences(input: { kind: 'MEASURED' | 'PASS_FAIL' }): readonly KpiCadence[] {
  return input.kind === 'PASS_FAIL' ? KPI_CADENCES : (['PERIOD', 'QUARTER', 'MONTH'] as const);
}

/**
 * Loại này có phải khai LƯỚI MỐC (% cho từng kỳ con) không?
 *
 * Chỉ ADDITIVE và SEMI_ADDITIVE mới chia được mục tiêu theo thời gian:
 *   · ADDITIVE      — chia phần, Σ các kỳ con = mục tiêu cả kỳ
 *   · SEMI_ADDITIVE — lộ trình, MỐC CUỐI = mục tiêu cả kỳ
 *
 * RATIO thì mục tiêu LẶP LẠI ở mọi kỳ con ("tỷ lệ hài lòng ≥ 90% mỗi tháng") nên
 * không có gì để chia; đạt/không đạt cũng vậy. Hai loại đó vẫn chọn nhịp — để
 * THU SỐ theo kỳ con — chỉ là không có lưới mốc.
 */
export function requiresSlotTargets(input: {
  kind: 'MEASURED' | 'PASS_FAIL';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  cadence: KpiCadence;
}): boolean {
  if (input.cadence === 'PERIOD') return false;
  if (input.kind === 'PASS_FAIL') return false;
  return input.measureType === 'ADDITIVE' || input.measureType === 'SEMI_ADDITIVE';
}

export type KpiSlotTarget = { slotIndex: number; percent: number };

/**
 * Kiểm lưới mốc hợp lệ. Trả thông báo tiếng Việt hoặc `null`.
 *
 * Một chân lý duy nhất cho contract (Zod), service và form — ba nơi lệch luật là
 * kiểu bug người dùng lưu được ở màn này nhưng bị 409 ở màn kia.
 */
export function validateSlotTargets(input: {
  kind: 'MEASURED' | 'PASS_FAIL';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  cadence: KpiCadence;
  periodYear: number;
  targets: readonly KpiSlotTarget[] | undefined;
}): string | null {
  if (!requiresSlotTargets(input)) return null;

  const targets = input.targets ?? [];
  if (!targets.length) return 'Cần chia mục tiêu cho từng kỳ con';

  const total = slotCount(input.cadence, input.periodYear);
  const seen = new Set<number>();
  for (const target of targets) {
    if (!Number.isInteger(target.slotIndex) || target.slotIndex < 0 || target.slotIndex >= total)
      return 'Có kỳ con không thuộc kỳ này';
    if (seen.has(target.slotIndex)) return 'Mỗi kỳ con chỉ được khai một lần';
    seen.add(target.slotIndex);
  }

  if (input.measureType === 'ADDITIVE') {
    // Dung sai 0.01 như tỷ trọng: 33.33+33.33+33.34 phải được coi là đủ 100%.
    const sum = targets.reduce((acc, target) => acc + target.percent, 0);
    if (Math.abs(sum - 100) >= 0.01)
      return `Tổng các kỳ con đang là ${Math.round(sum * 100) / 100}%, phải bằng 100%`;
    return null;
  }

  // SEMI_ADDITIVE — lộ trình: chỉ số CUỐI KỲ mới là thứ được chấm, nên mốc ở kỳ
  // con cuối cùng phải chính là mục tiêu cả kỳ. Các mốc giữa là chặng đường.
  const last = targets.find((target) => target.slotIndex === total - 1);
  if (!last) return 'Lộ trình phải có mốc ở kỳ con cuối cùng';
  if (Math.abs(last.percent - 100) >= 0.01) return 'Mốc của kỳ con cuối cùng phải bằng 100%';
  return null;
}

