import { Body, Controller, Delete, Get, Param, Patch, Post, Query } from '@nestjs/common';
import {
  PERMISSIONS,
  kpiCriteriaCreateSchema,
  kpiCriteriaUpdateSchema,
  kpiObjectiveCreateSchema,
  kpiObjectiveQuerySchema,
  kpiObjectiveUpdateSchema,
  type KpiCriteriaCreateInput,
  type KpiCriteriaUpdateInput,
  type KpiObjectiveCreateInput,
  type KpiObjectiveQuery,
  type KpiObjectiveUpdateInput,
} from '@ics/shared';
import type { AuthenticatedUser } from '../auth/auth.types';
import { CurrentPrincipal } from '../common/current-principal.decorator';
import { CurrentUser } from '../common/current-user.decorator';
import { RequirePermission } from '../common/require-permission.decorator';
import { ZodValidationPipe } from '../common/zod-validation.pipe';
import type { RbacPrincipal } from '../rbac/rbac.service';
import { KpiObjectiveService } from './kpi-objective.service';

/**
 * Thư viện mục tiêu & chỉ tiêu là việc NỘI BỘ PHÒNG BAN.
 *
 * Mọi route ghi chỉ đặt guard ở mức KPI_READ, còn quyền thật do service quyết
 * định theo phòng ban của người gọi: chỉ quản lý phòng đó sửa được phòng mình.
 * KPI admin chỉ đọc ở đây (quyền ghi duy nhất của admin là tỷ trọng công ty).
 */
@Controller('kpi/objectives')
export class KpiObjectiveController {
  constructor(private readonly service: KpiObjectiveService) {}

  /** Khai báo TRƯỚC `:id` để không bị route param bắt mất. */
  @Get('context')
  @RequirePermission(PERMISSIONS.KPI_READ)
  context(@CurrentPrincipal() principal: RbacPrincipal | undefined) {
    return this.service.context(principal);
  }

  @Get()
  @RequirePermission(PERMISSIONS.KPI_READ)
  list(
    @Query(new ZodValidationPipe(kpiObjectiveQuerySchema)) query: KpiObjectiveQuery,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
  ) {
    return this.service.list(query, principal);
  }

  @Get(':id')
  @RequirePermission(PERMISSIONS.KPI_READ)
  getById(@Param('id') id: string, @CurrentPrincipal() principal: RbacPrincipal | undefined) {
    return this.service.getById(id, principal);
  }

  @Post()
  @RequirePermission(PERMISSIONS.KPI_READ)
  create(
    @Body(new ZodValidationPipe(kpiObjectiveCreateSchema)) body: KpiObjectiveCreateInput,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    return this.service.create(body, principal, user.userId);
  }

  @Patch(':id')
  @RequirePermission(PERMISSIONS.KPI_READ)
  update(
    @Param('id') id: string,
    @Body(new ZodValidationPipe(kpiObjectiveUpdateSchema)) body: KpiObjectiveUpdateInput,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    return this.service.update(id, body, principal, user.userId);
  }

  @Delete(':id')
  @RequirePermission(PERMISSIONS.KPI_READ)
  remove(
    @Param('id') id: string,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    return this.service.remove(id, principal, user.userId);
  }

  @Post(':id/criteria')
  @RequirePermission(PERMISSIONS.KPI_READ)
  addCriteria(
    @Param('id') id: string,
    @Body(new ZodValidationPipe(kpiCriteriaCreateSchema)) body: KpiCriteriaCreateInput,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
  ) {
    return this.service.addCriteria(id, body, principal);
  }

  @Patch(':id/criteria/:criteriaId')
  @RequirePermission(PERMISSIONS.KPI_READ)
  updateCriteria(
    @Param('id') id: string,
    @Param('criteriaId') criteriaId: string,
    @Body(new ZodValidationPipe(kpiCriteriaUpdateSchema)) body: KpiCriteriaUpdateInput,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
  ) {
    return this.service.updateCriteria(id, criteriaId, body, principal);
  }

  @Delete(':id/criteria/:criteriaId')
  @RequirePermission(PERMISSIONS.KPI_READ)
  removeCriteria(
    @Param('id') id: string,
    @Param('criteriaId') criteriaId: string,
    @CurrentPrincipal() principal: RbacPrincipal | undefined,
  ) {
    return this.service.removeCriteria(id, criteriaId, principal);
  }
}

