import { Module } from '@nestjs/common';
import { KpiAllocationController } from './kpi-allocation.controller';
import { KpiAllocationService } from './kpi-allocation.service';
import { KpiAspectWeightController } from './kpi-aspect-weight.controller';
import { KpiAspectWeightService } from './kpi-aspect-weight.service';
import { KpiObjectiveController } from './kpi-objective.controller';
import { KpiObjectiveService } from './kpi-objective.service';
import { KpiPlanController } from './kpi-plan.controller';
import { KpiPlanService } from './kpi-plan.service';

/**
 * Module KPI theo khung BSC.
 *
 * Đã có:
 *   - Tỷ trọng 4 trụ cột: cấp công ty (KPI admin) + cấp phòng ban (quản lý)
 *   - Thư viện Key Objective → CSF → chỉ tiêu (KPI)
 *   - Luồng A: kế hoạch KPI phòng ban + chỉ tiêu cấp phòng (có target, target theo tháng)
 *     + vòng đời nháp → ban hành → chốt kỳ (không có bước phê duyệt)
 *   - Luồng B: phân bổ chỉ tiêu phòng ban cho cá nhân (chia phần / giao nguyên)
 *
 * Logic thuần tách riêng, có spec: `kpi-scoring.ts` (công thức chấm điểm — nguồn
 * DUY NHẤT, frontend không tính lại) và `kpi-workflow.ts` (quy tắc chuyển trạng thái).
 *
 * Chưa làm: nhập kết quả thực tế theo tháng, kế hoạch KPI cá nhân, dashboard.
 */
@Module({
  controllers: [
    KpiAspectWeightController,
    KpiObjectiveController,
    KpiPlanController,
    KpiAllocationController,
  ],
  providers: [KpiAspectWeightService, KpiObjectiveService, KpiPlanService, KpiAllocationService],
})
export class KpiModule {}

