 */
async readDetail(id: string, principal: RbacPrincipal | undefined): Promise<PlanDetailView> {
  await this.requirePlan(id, principal, 'read');
  return this.getDetail(id, principal);
}

/**
 * Dựng view chi tiết.
 *
 * `principal` dùng để tính các cờ theo NGƯỜI ĐANG XEM (sửa được gì, dòng nào là
 * của mình, nhập kết quả ở đâu). Bỏ trống thì mọi cờ về false — an toàn mặc định.
 */
async getDetail(id: string, principal?: RbacPrincipal | undefined): Promise<PlanDetailView> {
  const plan = await this.prisma.scoped.kpiPlan.findUnique({
    where: { id },
    select: {
      id: true,
      departmentId: true,
      periodYear: true,
      name: true,
      description: true,
      status: true,
      department: { select: { name: true } },
    },
  });
  if (!plan) throw new NotFoundException('Không tìm thấy kế hoạch KPI');

  // ── Cờ theo người đang xem ──────────────────────────────
  // `canWrite` là quyền sửa nội dung phòng ban đó (admin luôn false), tách khỏi
  // `isEditable` là điều kiện theo trạng thái. Nhân hai cái mới ra quyền thật.
  const canWrite = canWriteDepartment(principal, plan.departmentId);
  const editable = isEditable(plan.status);
  const canEditContent = canWrite && editable;
  const canAdjustWeights = canWrite && isAdjustable(plan.status);
  const canEnterActualsNow = acceptsActuals(plan.status);
  const viewerEmployeeId = principal?.employeeId ?? null;

  // Ban hành / chốt kỳ là việc của quản lý phòng; mở lại kỳ đã chốt là của admin.
  const availableStatusActions = KPI_PLAN_STATUSES.filter((to) => {
    if (!isValidStatusTransition(plan.status, to)) return false;
    return requiresAdmin(plan.status, to) ? isKpiAdmin(principal) : canWrite;
  });

  const [metrics, aspectWeightRows, slots] = await Promise.all([
    this.prisma.scoped.kpiPlanMetric.findMany({
      where: { planId: id },
      orderBy: [{ aspect: 'asc' }, { createdAt: 'asc' }],
      select: {
        id: true,
        level: true,
        parentMetricId: true,
        planTargetId: true,
        criteriaId: true,
        objectiveId: true,
        aspect: true,
        csf: true,
        name: true,
        unit: true,
        targetValue: true,
        allocationPercent: true,
        actualValue: true,
        weight: true,
        direction: true,
        allocationMode: true,
        aggregation: true,
        isBlocking: true,
        kind: true,
        scoringShape: true,
        scoringMethod: true,
        measureType: true,
        cadence: true,
        scoringConfig: true,
        thresholdValue: true,
        stretchValue: true,
        planTarget: {
          select: {
            employeeId: true,
            employeeNameSnapshot: true,
            positionNameSnapshot: true,
          },
        },
      },
    }),
    this.prisma.scoped.kpiAspectWeight.findMany({
      where: {
        scope: 'DEPARTMENT',
        departmentId: plan.departmentId,
        periodYear: plan.periodYear,
      },
      select: { aspect: true, weight: true },
    }),
    this.prisma.scoped.kpiPlanSlot.findMany({
      where: { planId: id },
      orderBy: { slotIndex: 'asc' },
      select: {
        slotIndex: true,
        metricSlots: {
          select: { planMetricId: true, targetPercent: true, actualValue: true },
        },
      },
    }),
  ]);

  const aspectWeightByAspect = new Map(
    aspectWeightRows.map((row) => [row.aspect, toNumber(row.weight)]),
  );
  /*
    Ô kỳ con theo từng chỉ tiêu.

    `slotIndex` một mình là đủ để định danh: mỗi chỉ tiêu chỉ có MỘT nhịp, nên
    trong phạm vi một chỉ tiêu không có hai lưới chồng nhau. Nhịp nào thì đọc
    từ `metric.cadence` của chính dòng đó.
  */
  type RawSlot = { targetPercent: number | null; actualValue: number | null };
  const slotsByMetric = new Map<string, Map<number, RawSlot>>();
  for (const slot of slots) {
    for (const metricSlot of slot.metricSlots) {
      const bucket = slotsByMetric.get(metricSlot.planMetricId) ?? new Map<number, RawSlot>();
      bucket.set(slot.slotIndex, {
        targetPercent: toNullableNumber(metricSlot.targetPercent),
        actualValue: toNullableNumber(metricSlot.actualValue),
      });
      slotsByMetric.set(metricSlot.planMetricId, bucket);
    }
  }
  /** Chỉ số kỳ con có dữ liệu của một dòng, xếp tăng dần. */
  const slotIndexesOf = (metricId: string) =>
    [...(slotsByMetric.get(metricId)?.keys() ?? [])].sort((a, b) => a - b);

  // Tên mục tiêu: `KpiPlanMetric` chỉ giữ `objectiveId` (không có quan hệ tới
  // `KpiTemplate`), nên nạp tên bằng MỘT truy vấn theo tập id thay vì join.
  const objectiveIds = [
    ...new Set(metrics.map((metric) => metric.objectiveId).filter((id): id is string => !!id)),
  ];
  const objectiveRows = objectiveIds.length
    ? await this.prisma.scoped.kpiTemplate.findMany({
        where: { id: { in: objectiveIds } },
        select: { id: true, title: true },
      })
    : [];
  const objectiveTitleById = new Map(objectiveRows.map((row) => [row.id, row.title]));

  const deptMetrics = metrics.filter((metric) => metric.level === 'DEPARTMENT');
  const childrenByParent = new Map<string, typeof metrics>();
  for (const metric of metrics) {
    if (metric.level !== 'INDIVIDUAL' || !metric.parentMetricId) continue;
    const list = childrenByParent.get(metric.parentMetricId) ?? [];
    list.push(metric);
    childrenByParent.set(metric.parentMetricId, list);
  }

  const aspects: PlanAspectView[] = KPI_ASPECTS.map((aspect) => {
    const rows = deptMetrics.filter((metric) => metric.aspect === aspect);
    const aspectWeight = aspectWeightByAspect.get(aspect) ?? 0;

    const views: DeptMetricView[] = rows.map((metric) => {
      const children = childrenByParent.get(metric.id) ?? [];
      const mode = metric.allocationMode ?? 'DIVIDE';
      const targetValue = toNumber(metric.targetValue);
      const isPassFail = metric.kind === 'PASS_FAIL';
      const hasSlots = metric.cadence !== 'PERIOD';

      /** Chấm MỘT con số — dùng lại y hệt cho cả kỳ lẫn từng kỳ con. */
      const scoreOne = (
        row: (typeof metrics)[number],
        actual: number | null,
        target: number,
      ): number | null =>
        row.kind === 'PASS_FAIL'
          ? scorePassFail(actual, target)
          : scoreMetric({
              actual,
              target,
              shape: row.scoringShape,
              method: row.scoringMethod,
              config: row.scoringConfig as KpiScoringConfig | null,
              threshold: toNullableNumber(row.thresholdValue),
              stretch: toNullableNumber(row.stretchValue),
              aspect,
            });

      /*
        Kết quả của phòng ban được GỘP TỪ phần đã giao, không đọc thẳng cột
        `actualValue`: `updateActual` chặn cứng việc nhập ở cấp phòng ban, nên
        cột đó luôn null và thanh tiến trình của phòng luôn trống dù nhân viên
        đã nhập.

        Chưa giao cho ai thì mới dùng lại giá trị đang lưu — chừa đường cho
