 *
 * Đây là thao tác duy nhất trong module làm được KHI KẾ HOẠCH ĐANG ÁP DỤNG —
 * ngược lại với sửa cấu hình (chỉ khi còn nháp). Vì vậy nó không dùng
 * `assertEditable` mà dùng `acceptsActuals`.
 *
 * Ai được nhập: CHỈ QUẢN LÝ PHÒNG BAN đó.
 *   - dòng CÁ NHÂN  → quản lý phòng nhập cho từng người
 *   - dòng PHÒNG BAN → không ai, kết quả gộp từ phần đã giao
 *   - nhân viên      → chỉ xem kết quả của mình, không tự nhập
 *   - KPI admin      → không, admin chỉ theo dõi
 *
 * Trước đây chính nhân viên tự nhập. Đổi theo yêu cầu nghiệp vụ: quản lý là
 * người ghi nhận và chịu trách nhiệm về số liệu. Vết vẫn đầy đủ nhờ
 * `KpiMetricActualHistory` ghi `enteredBy` + thời điểm mỗi lần nhập.
 */
async updateActual(
  planId: string,
  input: KpiActualEntryInput,
  principal: RbacPrincipal | undefined,
  actorId: string,
): Promise<PlanDetailView> {
  return this.updateActuals(planId, [input], principal, actorId);
}

/**
 * Nhập NHIỀU ô kết quả trong một lần gọi.
 *
 * Bắt buộc phải có khi chỉ tiêu chia kỳ con: quản lý sửa cả một dải tuần rồi
 * bấm Lưu một lần. Gửi từng ô thì mỗi lần lại dựng lại toàn bộ view chi tiết
 * kế hoạch — vừa chậm vừa nhấp nháy, và có thể ghi được nửa dải rồi lỗi.
 *
 * KIỂM TOÀN BỘ TRƯỚC KHI GHI: một ô sai thì không ô nào được ghi. Ghi dở dang
 * là trạng thái không ai gỡ được vì người dùng không biết ô nào đã vào.
 */
async updateActuals(
  planId: string,
  entries: readonly KpiActualEntryInput[],
  principal: RbacPrincipal | undefined,
  actorId: string,
): Promise<PlanDetailView> {
  const plan = await this.requirePlan(planId, principal, 'read');

  // Chỉ quản lý phòng đó ghi nhận số liệu. `canWrite` cũng loại admin — admin
  // chỉ theo dõi, nhất quán với toàn bộ module.
  assertCanWriteDepartment(principal, plan.departmentId);

  if (!acceptsActuals(plan.status)) {
    throw new ConflictException(
      'Chỉ nhập được kết quả thực tế khi kế hoạch KPI đang áp dụng (đã ban hành, chưa chốt)',
    );
  }

  const metricIds = [...new Set(entries.map((entry) => entry.metricId))];
  const metrics = await this.prisma.scoped.kpiPlanMetric.findMany({
    where: { id: { in: metricIds }, planId },
    select: { id: true, level: true, kind: true, cadence: true, measureType: true },
  });
  const metricById = new Map(metrics.map((metric) => [metric.id, metric]));

  for (const entry of entries) {
    const metric = metricById.get(entry.metricId);
    if (!metric) throw new NotFoundException('Không tìm thấy chỉ tiêu trong kế hoạch KPI');

    // Cấp phòng ban vẫn không nhập tay: số của phòng là tổng hợp từ phần đã giao.
    if (metric.level === 'DEPARTMENT') {
