        'Không nhập kết quả trực tiếp ở cấp phòng ban — kết quả đến từ phần đã giao cho từng người',
      );
    }

    const value = entry.actualValue ?? null;

    // Đạt/không đạt chỉ nhận 0 hoặc 1 (số lần đạt trên một lần kiểm). Chặn ở đây
    // vì contract không biết `kind` — nó chỉ thấy `metricId`.
    if (metric.kind === 'PASS_FAIL' && value !== null && value !== 0 && value !== 1) {
      throw new ConflictException('Chỉ tiêu đạt/không đạt chỉ nhận giá trị đạt hoặc không đạt');
    }

    // `cadence` lấy từ CHÍNH dòng chỉ tiêu, không tin `slotIndex` của FE: nếu
    // không, gửi index của một nhịp khác là ghi số vào đúng ô sai khoảng thời gian.
    if (metric.cadence === 'PERIOD') {
      if (entry.slotIndex !== undefined) {
        throw new ConflictException(
          'Chỉ tiêu này không chia kỳ con — chỉ nhập kết quả cho cả kỳ',
        );
      }
    } else {
      if (entry.slotIndex === undefined) {
        throw new ConflictException('Chỉ tiêu này chia theo kỳ con — cần chọn kỳ con để nhập');
      }
      if (entry.slotIndex >= slotCount(metric.cadence, plan.periodYear)) {
        throw new ConflictException('Kỳ con không thuộc kỳ này');
      }
    }
  }

  await this.prisma.$transaction(async (tx) => {
    const tenantId = this.tenantId();
    const touchedSlotMetrics = new Set<string>();

    for (const entry of entries) {
      const metric = metricById.get(entry.metricId)!;
      const value = entry.actualValue ?? null;
      const decimal = value === null ? null : new Prisma.Decimal(value);

      if (metric.cadence === 'PERIOD') {
        await tx.kpiPlanMetric.update({
          where: { id: metric.id },
          data: { actualValue: decimal },
        });
        // Xoá số (về null) thì không ghi lịch sử — `value` của history là NOT NULL.
        if (decimal !== null) {
          await tx.kpiMetricActualHistory.create({
            data: {
              tenantId,
              metricId: metric.id,
              value: decimal,
              enteredBy: actorId,
              note: entry.note ?? null,
            },
          });
        }
        continue;
      }

      const planSlotId = await this.ensurePlanSlot(
        tx,
        plan,
        metric.cadence,
        entry.slotIndex as number,
      );
      const existing = await tx.kpiPlanMetricSlot.findFirst({
        where: { tenantId, planSlotId, planMetricId: metric.id },
        select: { id: true },
      });
      const metricSlotId = existing
        ? existing.id
        : (
            await tx.kpiPlanMetricSlot.create({
              data: { tenantId, planSlotId, planMetricId: metric.id, actualValue: decimal },
              select: { id: true },
            })
          ).id;
      if (existing) {
        await tx.kpiPlanMetricSlot.update({
          where: { id: metricSlotId },
          data: { actualValue: decimal },
        });
      }

      if (decimal !== null) {
        await tx.kpiPlanMetricSlotActualHistory.create({
          data: {
            tenantId,
            metricSlotId,
            value: decimal,
            enteredBy: actorId,
            note: entry.note ?? null,
          },
        });
      }

      touchedSlotMetrics.add(metric.id);
    }

    // Gộp lại con số CẢ KỲ sau khi mọi ô đã vào — làm một lần cho mỗi chỉ tiêu
    // thay vì mỗi ô, và làm sau cùng để không gộp trên trạng thái dở dang.
    for (const metricId of touchedSlotMetrics) {
      await this.recomputeFromSlots(tx, metricById.get(metricId)!);
    }
  });

  await this.audit.record({
    action: 'kpi.actual.update',
    entity: 'KpiPlanMetric',
    entityId: entries[0].metricId,
    after: {
      entries: entries.map((entry) => ({
        metricId: entry.metricId,
        slotIndex: entry.slotIndex ?? null,
        actualValue: entry.actualValue ?? null,
        note: entry.note ?? null,
      })),
    },
  });

  return this.getDetail(planId, principal);
}

