    và bắt từng kỳ tự khai. Kỳ khai thì GHI ĐÈ NGUYÊN KHỐI; không khai thì kế thừa.

    Ghi đè nguyên khối chứ không merge từng field: các tham số của một cách chấm
    đi cùng nhau (min/max/tolerance là một bộ), trộn nửa cũ nửa mới sẽ ra cấu hình
    không ai chủ ý tạo.

    Cách chấm cần cấu hình mà cả hai nơi đều trống là không chấm được — chặn ngay
    tại đây thay vì để chỉ tiêu nằm im rồi trả `percent: null` mà không ai hiểu vì sao.
  */
  const isPassFail = criteria.kind === 'PASS_FAIL';

  /*
    Đạt/không đạt không có mục tiêu số. Lưu `targetValue = 1` mang nghĩa "MỘT
    LẦN KIỂM" — cùng thang với `actualValue` (số lần đạt), nên khi có kỳ con chỉ
    cần nâng lên N là công thức tỷ lệ chạy tiếp, không phải đổi gì.
  */
  const targetValue = isPassFail ? 1 : input.targetValue;
  if (targetValue === undefined) {
    throw new ConflictException('Vui lòng nhập mục tiêu của phòng ban cho kỳ này');
  }

  const definitionConfig = (criteria.scoringConfig ?? null) as KpiScoringConfig | null;
  const scoringConfig: KpiScoringConfig | null = isPassFail
    ? null
    : (input.scoringConfig ?? definitionConfig);

  if (!isPassFail) {
    const configError = validateScoringConfig({
      shape: criteria.scoringShape,
      method: criteria.scoringMethod,
      config: scoringConfig,
    });
    if (configError) throw new ConflictException(configError);
  }

  // Nhịp kỳ con + lưới mốc: kiểm bằng đúng luật dùng chung với contract và UI.
  const cadence = this.resolveCadence(input.cadence ?? 'PERIOD', criteria.kind);
  this.assertSlotTargets({
    kind: criteria.kind,
    measureType: criteria.measureType,
    cadence,
    periodYear: plan.periodYear,
    slotTargets: input.slotTargets,
  });

  try {
    await this.prisma.$transaction(async (tx) => {
      const metric = await tx.kpiPlanMetric.create({
        data: {
          tenantId: this.tenantId(),
          planId,
          level: 'DEPARTMENT',
          parentMetricId: null,
          planTargetId: null,
          criteriaId: criteria.id,
          sourceCriteriaId: criteria.id,
          objectiveId: criteria.templateId,
          aspect: criteria.template.aspect,
          csf: criteria.csf,
          name: criteria.name,
          description: criteria.description,
          targetValue: new Prisma.Decimal(targetValue),
          actualValue: null,
          unit: criteria.unit,
          weight: new Prisma.Decimal(input.weight),
          direction: criteria.direction,
          allocationMode: criteria.allocationMode,
          aggregation: criteria.aggregation,
          isBlocking: criteria.isBlocking,
          // Snapshot mô hình chấm điểm: đóng băng cùng lý do với target/weight.
          kind: criteria.kind,
          scoringShape: criteria.scoringShape,
          scoringMethod: criteria.scoringMethod,
          measureType: criteria.measureType,
          cadence,
          scoringConfig: (scoringConfig ?? Prisma.JsonNull) as Prisma.InputJsonValue,
          status: 'DRAFT',
        },
        select: { id: true },
      });

      if (input.slotTargets?.length) {
        await this.writeSlotTargets(tx, plan, metric.id, cadence, input.slotTargets);
      }
    });
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === 'P2002') {
      throw new ConflictException('Chỉ tiêu này đã có trong kế hoạch KPI');
    }
    throw error;
  }

  const view = await this.getDetail(planId, principal);
  await this.audit.record({
    action: 'kpi.plan.metric.add',
    entity: 'KpiPlanMetric',
    entityId: planId,
    after: view,
  });
  return view;
}

async updateDeptMetric(
  planId: string,
  metricId: string,
  input: KpiDeptMetricUpdateInput,
  principal: RbacPrincipal | undefined,
): Promise<PlanDetailView> {
  const plan = await this.requirePlan(planId, principal);
  this.assertAdjustable(plan.status);
  const current = await this.requireDeptMetric(planId, metricId);

  /*
    HAI MỨC QUYỀN SỬA, không phải một.

    Đang áp dụng vẫn ĐIỀU CHỈNH được trọng số và lưới mốc — đó là việc điều
    hành bình thường (quý 1 hụt thì dồn sang quý sau). Nhưng mục tiêu của kỳ,
    nhịp chia và cách chấm thì khoá từ lúc ban hành: sửa được ba thứ đó sau khi
    kỳ đã chạy là sửa lại thước đo cho vừa kết quả.

