1920	   *
1921	   * `KpiPlanSlot` dùng chung cho MỌI chỉ tiêu cùng nhịp trong kế hoạch — hai chỉ
1922	   * tiêu cùng theo tháng thì dùng chung 12 dòng, không nhân đôi.
1923	   */
1924	  private async ensurePlanSlot(
1925	    tx: Prisma.TransactionClient,
1926	    plan: { id: string; periodYear: number },
1927	    cadence: KpiCadence,
1928	    slotIndex: number,
1929	  ): Promise<string> {
1930	    const tenantId = this.tenantId();
1931	    const key = slotKey(cadence, plan.periodYear, slotIndex);
1932	
1933	    const existing = await tx.kpiPlanSlot.findFirst({
1934	      where: { tenantId, planId: plan.id, slotKey: key },
1935	      select: { id: true },
1936	    });
1937	    if (existing) return existing.id;
1938	
1939	    const range = slotRange(cadence, plan.periodYear, slotIndex);
1940	    const created = await tx.kpiPlanSlot.create({
1941	      data: {
1942	        tenantId,
1943	        planId: plan.id,
1944	        cadence,
1945	        slotKey: key,
1946	        slotIndex,
1947	        slotStartAt: range.startAt,
1948	        slotEndAt: range.endAt,
1949	      },
1950	      select: { id: true },
1951	    });
1952	    return created.id;
1953	  }
1954	
1955	  /**
1956	   * Ghi lưới mốc của dòng PHÒNG BAN — thay nguyên khối.
1957	   *
1958	   * Lưu `targetPercent`, không lưu số tuyệt đối: đổi mục tiêu cả kỳ thì các mốc
1959	   * tự giãn theo. Đây đúng là cách `allocationPercent` hoạt động khi giao cho cá
1960	   * nhân, và cùng một lý do.
1961	   */
1962	  private async writeSlotTargets(
1963	    tx: Prisma.TransactionClient,
1964	    plan: { id: string; periodYear: number },
1965	    metricId: string,
1966	    cadence: KpiCadence,
1967	    slotTargets: readonly KpiSlotTargetInput[],
1968	  ): Promise<void> {
1969	    const tenantId = this.tenantId();
1970	
1971	    await tx.kpiPlanMetricSlot.deleteMany({ where: { tenantId, planMetricId: metricId } });
1972	
1973	    for (const target of slotTargets) {
1974	      const planSlotId = await this.ensurePlanSlot(tx, plan, cadence, target.slotIndex);
1975	      await tx.kpiPlanMetricSlot.create({
1976	        data: {
1977	          tenantId,
1978	          planSlotId,
1979	          planMetricId: metricId,
1980	          targetPercent: new Prisma.Decimal(target.percent),
1981	          targetValue: null,
1982	          actualValue: null,
1983	        },
1984	      });
1985	    }
1986	  }
1987	
1988	  /**
1989	   * Dựng lại con số CẢ KỲ của một dòng từ các ô kỳ con của nó.
1990	   *
1991	   * Đây là mấu chốt khiến phần còn lại của module không phải biết gì về kỳ con:
1992	   * sau khi gộp, `KpiPlanMetric.actualValue` vẫn là "kết quả cả kỳ" như cũ, nên
1993	   * chấm điểm, gộp lên phòng ban và điểm tổng chạy nguyên vẹn.
1994	   *
1995	   * Cũng chính là nguyên tắc "gộp trước, chấm sau": chỉ có MỘT lần chấm, ở cấp kỳ.
1996	   */
1997	  private async recomputeFromSlots(
1998	    tx: Prisma.TransactionClient,
1999	    metric: { id: string; kind: 'MEASURED' | 'PASS_FAIL'; measureType: KpiMeasureType },
2000	  ): Promise<void> {
2001	    const rows = await tx.kpiPlanMetricSlot.findMany({
2002	      where: { tenantId: this.tenantId(), planMetricId: metric.id },
2003	      select: { actualValue: true, planSlot: { select: { slotIndex: true } } },
2004	    });
2005	    const slots: SlotValue[] = rows.map((row) => ({
2006	      slotIndex: row.planSlot.slotIndex,
2007	      value: toNullableNumber(row.actualValue),
2008	    }));
2009	
2010	    if (metric.kind === 'PASS_FAIL') {
2011	      /*
2012	        Đạt/không đạt: `actualValue` = số lần đạt, `targetValue` = số LẦN KIỂM.
2013	        Cả hai cùng thang nên `scorePassFail` không phải đổi gì — đúng ý đồ đặt
2014	        `targetValue = 1` ("một lần kiểm") lúc thêm chỉ tiêu, giờ chỉ nâng lên N.
2015	
2016	        Chưa ghi nhận lần nào ⇒ trả về trạng thái ban đầu (null / 1) thay vì 0/0,
2017	        để chỉ tiêu bị coi là "chưa đánh giá được" chứ không phải "trượt".
2018	      */
2019	      const { passes, checks } = aggregatePassFailSlots(slots);
2020	      await tx.kpiPlanMetric.update({
2021	        where: { id: metric.id },
2022	        data: {
2023	          actualValue: checks === 0 ? null : new Prisma.Decimal(passes),
2024	          targetValue: new Prisma.Decimal(checks === 0 ? 1 : checks),
2025	        },
2026	      });
2027	      return;
2028	    }
2029	
2030	    const aggregated = aggregateSlotActual(slots, metric.measureType);
2031	    await tx.kpiPlanMetric.update({
2032	      where: { id: metric.id },
2033	      data: { actualValue: aggregated === null ? null : new Prisma.Decimal(aggregated) },
2034	    });
2035	  }
