import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { Prisma, PrismaClient } from '@prisma/client';
import { DomainError } from './errors/domain-error';
import {
  createSafeRefreshTokenRepository,
  type SafeRefreshTokenCreateArgs,
  type SafeRefreshTokenOperations,
} from './persistence/refresh-token.repository';
import { tenantExtension } from './prisma-tenant.extension';
import { TenantContextService } from './tenant-context.service';

function extendTenantClient(client: PrismaClient, tenantContext: TenantContextService) {
  return client.$extends(tenantExtension(tenantContext));
}

export type TenantExtendedClient = ReturnType<typeof extendTenantClient>;

@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit, OnModuleDestroy {
  readonly scoped: ReturnType<PrismaService['buildScopedClient']>;
  readonly refreshTokens: ReturnType<PrismaService['buildRefreshTokenFacade']>;

  constructor(private readonly tenantContext: TenantContextService) {
    super();
    const extended = extendTenantClient(this, tenantContext);
    this.scoped = this.buildScopedClient(extended);
    this.refreshTokens = this.buildRefreshTokenFacade();
  }

  private buildScopedClient(extended: TenantExtendedClient) {
    const refreshToken = {
      create: (args: SafeRefreshTokenCreateArgs) =>
        this.$transaction((tx) =>
          createSafeRefreshTokenRepository(
            this.refreshTokenOperations(tx),
            this.tenantContext.getTenantId(),
          ).create(args),
        ),
      updateMany: (args: Parameters<SafeRefreshTokenOperations['updateMany']>[0]) => {
        if (!this.tenantContext.getTenantId()) {
          throw new DomainError({ code: 'PERMISSION_DENIED' });
        }
        return extended.refreshToken.updateMany(args);
      },
    };

    return Object.freeze({
      $transaction: extended.$transaction.bind(extended),
      tenant: extended.tenant,
      organization: extended.organization,
      user: extended.user,
      notification: extended.notification,
      productUpdateRead: extended.productUpdateRead,
      refreshToken,
      passwordResetToken: extended.passwordResetToken,
      accountInvitationToken: extended.accountInvitationToken,
      branch: extended.branch,
      team: extended.team,
      department: extended.department,
      position: extended.position,
      employee: extended.employee,
      employeeDependent: extended.employeeDependent,
      employeeSequence: extended.employeeSequence,
      permission: extended.permission,
      role: extended.role,
      rolePermission: extended.rolePermission,
      userRole: extended.userRole,
      requestProcess: extended.requestProcess,
      requestProcessStep: extended.requestProcessStep,
      requestTicket: extended.requestTicket,
      requestApproval: extended.requestApproval,
      requestApprovalCandidate: extended.requestApprovalCandidate,
      requestSequence: extended.requestSequence,
      salaryAdvance: extended.salaryAdvance,
      attendanceRecord: extended.attendanceRecord,
      branchNetwork: extended.branchNetwork,
      kpiTemplate: extended.kpiTemplate,
      kpiTemplateCriteria: extended.kpiTemplateCriteria,
      kpiPlan: extended.kpiPlan,
      kpiAspectWeight: extended.kpiAspectWeight,
      kpiDepartmentManager: extended.kpiDepartmentManager,
      kpiPlanTarget: extended.kpiPlanTarget,
      kpiPlanMetric: extended.kpiPlanMetric,
      kpiMetricActualHistory: extended.kpiMetricActualHistory,
      kpiMetricStatusHistory: extended.kpiMetricStatusHistory,
      kpiPlanSlot: extended.kpiPlanSlot,
      kpiPlanMetricSlot: extended.kpiPlanMetricSlot,
      kpiPlanMetricSlotActualHistory: extended.kpiPlanMetricSlotActualHistory,
      customer: extended.customer,
      customerStatusHistory: extended.customerStatusHistory,
      customerScoreHistory: extended.customerScoreHistory,
      leadScoringRule: extended.leadScoringRule,
      leadScoringSettings: extended.leadScoringSettings,
      company: extended.company,
      contact: extended.contact,
      address: extended.address,
      activity: extended.activity,
      ticket: extended.ticket,
      ticketSequence: extended.ticketSequence,
      financeTask: extended.financeTask,
      financeIssue: extended.financeIssue,
      financeTaskSequence: extended.financeTaskSequence,
      auditLog: extended.auditLog,
      customerSource: extended.customerSource,
      customerGroup: extended.customerGroup,
      customerTag: extended.customerTag,
      customerTagAssignment: extended.customerTagAssignment,
      customerRelationship: extended.customerRelationship,
      customFieldDefinition: extended.customFieldDefinition,
      opportunity: extended.opportunity,
      opportunityStageHistory: extended.opportunityStageHistory,
      importJob: extended.importJob,
      productCategory: extended.productCategory,
      productUnit: extended.productUnit,
      product: extended.product,
      pricePolicy: extended.pricePolicy,
      pricePolicyItem: extended.pricePolicyItem,
      quote: extended.quote,
      quoteItem: extended.quoteItem,
      salesOrder: extended.salesOrder,
      salesOrderItem: extended.salesOrderItem,
      salesOrderPayment: extended.salesOrderPayment,
      contract: extended.contract,
      contractItem: extended.contractItem,
      contractPayment: extended.contractPayment,
      campaign: extended.campaign,
      marketingAutomation: extended.marketingAutomation,
      marketingAutomationLog: extended.marketingAutomationLog,
      marketingAutomationExecution: extended.marketingAutomationExecution,
      campaignStage: extended.campaignStage,
      campaignRecipient: extended.campaignRecipient,
      campaignActivity: extended.campaignActivity,
      emailTemplate: extended.emailTemplate,
      emailCampaign: extended.emailCampaign,
      emailMessage: extended.emailMessage,
      emailSuppression: extended.emailSuppression,
      campaignParticipant: extended.campaignParticipant,
      campaignFailureReason: extended.campaignFailureReason,
      optinForm: extended.optinForm,
      optinFormSubmission: extended.optinFormSubmission,
      sequence: extended.sequence,
      documentSequence: extended.documentSequence,
      project: extended.project,
      projectMember: extended.projectMember,
      projectPhase: extended.projectPhase,
      workflow: extended.workflow,
      workflowColumn: extended.workflowColumn,
      workflowTemplateCategory: extended.workflowTemplateCategory,
      workflowTemplate: extended.workflowTemplate,
      workflowTemplatePhase: extended.workflowTemplatePhase,
      workflowTemplateItem: extended.workflowTemplateItem,
      workflowTemplateShare: extended.workflowTemplateShare,
      task: extended.task,
      taskComment: extended.taskComment,
      taskAttachment: extended.taskAttachment,
      taskCollaborator: extended.taskCollaborator,
      taskTag: extended.taskTag,
      taskTagRelation: extended.taskTagRelation,
      workspaceActivity: extended.workspaceActivity,
      idempotencyRecord: extended.idempotencyRecord,
    });
  }

  private buildRefreshTokenFacade() {
    return Object.freeze({
      createForTenant: (tenantId: string, args: SafeRefreshTokenCreateArgs) =>
        this.$transaction((tx) =>
          createSafeRefreshTokenRepository(this.refreshTokenOperations(tx), tenantId).create(args),
        ),
      rotateForTenant: (
        tenantId: string,
        currentTokenId: string,
        args: SafeRefreshTokenCreateArgs,
      ) =>
        this.$transaction(async (tx) => {
          const revoked = await tx.refreshToken.updateMany({
            where: { id: currentTokenId, tenantId, revokedAt: null },
            data: { revokedAt: new Date() },
          });
          if (revoked.count !== 1) throw new DomainError({ code: 'RESOURCE_NOT_FOUND' });
          await createSafeRefreshTokenRepository(this.refreshTokenOperations(tx), tenantId).create(
            args,
          );
        }),
    });
  }

  private refreshTokenOperations(tx: Prisma.TransactionClient): SafeRefreshTokenOperations {
    return {
      findActiveUser: async (userId, tenantId) =>
        (await tx.user.findFirst({
          where: { id: userId, tenantId, deletedAt: null },
          select: { id: true },
        })) !== null,
      create: (data) => tx.refreshToken.create({ data }),
      updateMany: (args) => tx.refreshToken.updateMany(args),
    };
  }

  async onModuleInit(): Promise<void> {
    await this.$connect();
  }

  async onModuleDestroy(): Promise<void> {
    await this.$disconnect();
  }
}

