 * CÔNG THỨC KPI — ghép các nguồn số liệu thô thành một con số.
 *
 * Ranh giới với `sourceType = EXISTING`:
 *   · Nguồn   = MỘT phép đo. Được tính trong từng dòng dữ liệu (số ngày trễ, số
 *               giờ xử lý) nhưng KHÔNG ghép hai phép đo độc lập.
 *   · Công thức = ghép nhiều phép đo.
 *
 * Vì tham số của công thức là NGUỒN chứ không phải chỉ tiêu khác, ở đây không có
 * đồ thị phụ thuộc: không vòng lặp, không phải sắp thứ tự tính, không cần mã định
 * danh riêng cho chỉ tiêu. Đó là lý do chọn cách này thay vì cho tham chiếu chéo.
 *
 * TUYỆT ĐỐI KHÔNG dùng `eval`/`Function`: chuỗi này do người dùng nhập và được
 * chạy ở server, dùng eval là mở đường thực thi mã tuỳ ý.
 *
 * Hàm thuần, không phụ thuộc Zod — dùng chung backend (tính) ↔ frontend (kiểm khi
 * nhập). Hai bên kiểm khác nhau là kiểu bug lưu được ở form nhưng 409 ở server.
 */

/** Chặn công thức dài bất thường — vừa khó đọc vừa là bề mặt tấn công vô ích. */
export const KPI_FORMULA_MAX_LENGTH = 500;

/** Chặn lồng ngoặc quá sâu để parser đệ quy không thể làm tràn ngăn xếp. */
const MAX_DEPTH = 20;

/**
 * Cú pháp tham chiếu nguồn: `[sales.closed_revenue]`.
 *
 * Dùng ngoặc vuông chứ không để trần: id nguồn có dấu chấm (`sales.closed_deals`)
 * nên nếu để trần thì không phân biệt được đâu là hết tên, đâu là toán tử.
 */
const REFERENCE_PATTERN = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/;

type Node =
  | { type: 'number'; value: number }
  | { type: 'ref'; id: string }
  | { type: 'unary'; operator: '-'; operand: Node }
  | { type: 'binary'; operator: '+' | '-' | '*' | '/'; left: Node; right: Node };

type Token =
  | { type: 'number'; value: number; at: number }
  | { type: 'ref'; id: string; at: number }
  | { type: 'operator'; value: '+' | '-' | '*' | '/'; at: number }
  | { type: 'paren'; value: '(' | ')'; at: number };

/** Lỗi cú pháp mang thông điệp tiếng Việt — ném ra rồi bắt lại ở biên public. */
class FormulaError extends Error {}

// ─────────────────────────────────────────────────────────────
// Tách token
// ─────────────────────────────────────────────────────────────

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let index = 0;

  while (index < source.length) {
    const char = source[index];

    if (char === ' ' || char === '\t' || char === '\n' || char === '\r') {
      index += 1;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({ type: 'paren', value: char, at: index });
      index += 1;
      continue;
    }

    if (char === '+' || char === '-' || char === '*' || char === '/') {
      tokens.push({ type: 'operator', value: char, at: index });
      index += 1;
      continue;
    }

    if (char === '[') {
      const end = source.indexOf(']', index);
      if (end === -1) throw new FormulaError('Thiếu dấu `]` đóng tham chiếu nguồn');
      const id = source.slice(index + 1, end).trim();
      if (!id) throw new FormulaError('Tham chiếu nguồn đang để trống');
      if (!REFERENCE_PATTERN.test(id)) {
        throw new FormulaError(`Mã nguồn không hợp lệ: \`${id}\``);
      }
      tokens.push({ type: 'ref', id, at: index });
      index = end + 1;
      continue;
    }

    if (char >= '0' && char <= '9') {
      let end = index;
      let seenDot = false;
      while (end < source.length) {
        const digit = source[end];
        if (digit >= '0' && digit <= '9') {
          end += 1;
          continue;
        }
        // Chỉ chấp nhận MỘT dấu chấm: "1.2.3" là lỗi gõ, không phải số.
        if (digit === '.' && !seenDot) {
          seenDot = true;
          end += 1;
          continue;
        }
        break;
      }
      const text = source.slice(index, end);
      const value = Number.parseFloat(text);
      if (!Number.isFinite(value)) throw new FormulaError(`Số không hợp lệ: \`${text}\``);
      tokens.push({ type: 'number', value, at: index });
      index = end;
      continue;
    }

    throw new FormulaError(`Ký tự không dùng được trong công thức: \`${char}\``);
  }

  return tokens;
}

// ─────────────────────────────────────────────────────────────
// Phân tích cú pháp — đệ quy xuống, nhân/chia ưu tiên hơn cộng/trừ
// ─────────────────────────────────────────────────────────────

function parseTokens(tokens: Token[]): Node {
  let position = 0;

  const peek = (): Token | undefined => tokens[position];

  function parseExpression(depth: number): Node {
    let left = parseTerm(depth);
    for (;;) {
      const token = peek();
      if (token?.type !== 'operator' || (token.value !== '+' && token.value !== '-')) return left;
      position += 1;
      left = { type: 'binary', operator: token.value, left, right: parseTerm(depth) };
    }
  }

  function parseTerm(depth: number): Node {
    let left = parseFactor(depth);
    for (;;) {
      const token = peek();
      if (token?.type !== 'operator' || (token.value !== '*' && token.value !== '/')) return left;
      position += 1;
      left = { type: 'binary', operator: token.value, left, right: parseFactor(depth) };
    }
  }

  function parseFactor(depth: number): Node {
    if (depth > MAX_DEPTH) throw new FormulaError('Công thức lồng ngoặc quá sâu');

    const token = peek();
    if (!token) throw new FormulaError('Công thức kết thúc giữa chừng');

    // Dấu âm đứng đầu: `-5`, `-[x]`, `-(a + b)`.
    if (token.type === 'operator' && token.value === '-') {
      position += 1;
      return { type: 'unary', operator: '-', operand: parseFactor(depth + 1) };
    }

    if (token.type === 'number') {
      position += 1;
      return { type: 'number', value: token.value };
    }

    if (token.type === 'ref') {
      position += 1;
      return { type: 'ref', id: token.id };
    }

    if (token.type === 'paren' && token.value === '(') {
      position += 1;
      const inner = parseExpression(depth + 1);
      const closing = peek();
      if (closing?.type !== 'paren' || closing.value !== ')') {
        throw new FormulaError('Thiếu dấu `)` đóng ngoặc');
      }
      position += 1;
      return inner;
    }

    if (token.type === 'paren') throw new FormulaError('Thừa dấu `)`');
    throw new FormulaError('Thiếu toán hạng — có hai toán tử đứng liền nhau');
  }

  const node = parseExpression(0);
  if (position < tokens.length) {
    const rest = tokens[position];
    if (rest.type === 'paren' && rest.value === ')') throw new FormulaError('Thừa dấu `)`');
    throw new FormulaError('Thiếu toán tử giữa hai giá trị');
  }
  return node;
}

// ─────────────────────────────────────────────────────────────
// Biên public
// ─────────────────────────────────────────────────────────────

export type KpiFormulaAst = Node;

export type KpiFormulaParseResult =
  | { ok: true; ast: KpiFormulaAst; refs: string[] }
  | { ok: false; error: string };

/**
 * Phân tích công thức. `refs` là danh sách mã nguồn đã khử trùng lặp — chính là
 * tập nguồn cần truy vấn, nên nơi gọi không phải tự dò lại chuỗi.
 */
export function parseKpiFormula(source: string): KpiFormulaParseResult {
  const text = source.trim();
  if (!text) return { ok: false, error: 'Vui lòng nhập công thức' };
  if (text.length > KPI_FORMULA_MAX_LENGTH) {
    return { ok: false, error: `Công thức tối đa ${KPI_FORMULA_MAX_LENGTH} ký tự` };
  }

  try {
    const ast = parseTokens(tokenize(text));
    const refs: string[] = [];
    collectRefs(ast, refs);
    if (!refs.length) {
      // Công thức toàn hằng số cho ra cùng một con số ở mọi kỳ, mọi người — gần
      // như chắc chắn là gõ nhầm chứ không phải ý đồ.
      return { ok: false, error: 'Công thức phải dùng ít nhất một nguồn số liệu' };
    }
    return { ok: true, ast, refs };
  } catch (error) {
    if (error instanceof FormulaError) return { ok: false, error: error.message };
    throw error;
  }
}

function collectRefs(node: Node, out: string[]): void {
  switch (node.type) {
    case 'ref':
      if (!out.includes(node.id)) out.push(node.id);
      return;
    case 'unary':
      collectRefs(node.operand, out);
      return;
    case 'binary':
      collectRefs(node.left, out);
      collectRefs(node.right, out);
      return;
    default:
      return;
  }
}

/**
 * Kiểm công thức hợp lệ VÀ mọi nguồn nó dùng đều có thật. Trả thông báo tiếng
 * Việt hoặc `null` — cùng khuôn với `validateSlotTargets`/`validateScoreBands`.
 */
export function validateKpiFormula(source: string, knownSourceIds: readonly string[]): string | null {
  const parsed = parseKpiFormula(source);
  if (!parsed.ok) return parsed.error;

  const unknown = parsed.refs.filter((ref) => !knownSourceIds.includes(ref));
  if (unknown.length) return `Không có nguồn số liệu: ${unknown.join(', ')}`;
  return null;
}

/**
 * Tính công thức trên một bộ giá trị nguồn.
 *
 * Trả `null` khi CHƯA ĐÁNH GIÁ ĐƯỢC, và mọi phép có toán hạng `null` đều lan
 * `null` ra ngoài. Đây là điều kiện sống còn: ép về 0 nghĩa là một chỉ tiêu chưa
 * có số bị chấm 0 điểm, trong khi cả module đã thống nhất "thiếu số thì loại khỏi
 * phép tính điểm, không phải trượt".
 *
 * Chia cho 0 cũng trả `null` chứ không phải Infinity — "chưa có mẫu số" là chưa
 * đo được, ví dụ tỷ lệ chuyển đổi khi trong kỳ chưa có cơ hội nào.
 */
export function evaluateKpiFormula(
  ast: KpiFormulaAst,
  values: Readonly<Record<string, number | null | undefined>>,
): number | null {
  switch (ast.type) {
    case 'number':
      return ast.value;

    case 'ref': {
      const value = values[ast.id];
      return value === null || value === undefined || !Number.isFinite(value) ? null : value;
    }

    case 'unary': {
      const operand = evaluateKpiFormula(ast.operand, values);
      return operand === null ? null : -operand;
    }

    case 'binary': {
      const left = evaluateKpiFormula(ast.left, values);
      if (left === null) return null;
      const right = evaluateKpiFormula(ast.right, values);
      if (right === null) return null;

      switch (ast.operator) {
        case '+':
          return left + right;
        case '-':
          return left - right;
        case '*':
          return left * right;
        case '/':
          return right === 0 ? null : left / right;
      }
    }
  }
}

/** Tiện dụng: phân tích rồi tính trong một bước. Trả `null` nếu công thức hỏng. */
export function runKpiFormula(
  source: string,
  values: Readonly<Record<string, number | null | undefined>>,
): number | null {
  const parsed = parseKpiFormula(source);
  return parsed.ok ? evaluateKpiFormula(parsed.ast, values) : null;
}

