 * Tính công thức trên một bộ giá trị nguồn.
 *
 * Trả `null` khi CHƯA ĐÁNH GIÁ ĐƯỢC, và mọi phép có toán hạng `null` đều lan
 * `null` ra ngoài. Đây là điều kiện sống còn: ép về 0 nghĩa là một chỉ tiêu chưa
 * có số bị chấm 0 điểm, trong khi cả module đã thống nhất "thiếu số thì loại khỏi
 * phép tính điểm, không phải trượt".
 *
 * Chia cho 0 cũng trả `null` chứ không phải Infinity — "chưa có mẫu số" là chưa
 * đo được, ví dụ tỷ lệ chuyển đổi khi trong kỳ chưa có cơ hội nào.
 */
export function evaluateKpiFormula(
  ast: KpiFormulaAst,
  values: Readonly<Record<string, number | null | undefined>>,
): number | null {
  switch (ast.type) {
    case 'number':
      return ast.value;

    case 'ref': {
      const value = values[ast.id];
      return value === null || value === undefined || !Number.isFinite(value) ? null : value;
    }

    case 'unary': {
      const operand = evaluateKpiFormula(ast.operand, values);
      return operand === null ? null : -operand;
    }

    case 'binary': {
      const left = evaluateKpiFormula(ast.left, values);
      if (left === null) return null;
      const right = evaluateKpiFormula(ast.right, values);
      if (right === null) return null;

      switch (ast.operator) {
        case '+':
          return left + right;
        case '-':
          return left - right;
        case '*':
          return left * right;
        case '/':
          return right === 0 ? null : left / right;
      }
    }
  }
}

/** Tiện dụng: phân tích rồi tính trong một bước. Trả `null` nếu công thức hỏng. */
export function runKpiFormula(
  source: string,
  values: Readonly<Record<string, number | null | undefined>>,
): number | null {
  const parsed = parseKpiFormula(source);
  return parsed.ok ? evaluateKpiFormula(parsed.ast, values) : null;
}

