      'Số phút trung bình từ lúc tạo ticket đến lần phản hồi đầu tiên cho khách, tính trên ' +
      'ticket tạo trong kỳ đã được phản hồi. Càng thấp càng tốt (dùng hướng DECREASE).',
    kind: 'DERIVED',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày tạo ticket',
    ownerBasis: 'Người phụ trách ticket',
    defaultValue: '0.00',
    defaultUnit: 'Phút',
    async resolve(prisma, context) {
      const tickets = await prisma.ticket.findMany({
        where: {
          ...ticketBase(context),
          createdAt: inPeriod(context.period),
          firstRespondedAt: { not: null },
        },
        select: { createdAt: true, firstRespondedAt: true },
      });
      const durations = tickets
        .filter((ticket) => ticket.firstRespondedAt !== null)
        .map((ticket) => minutesBetween(ticket.createdAt, ticket.firstRespondedAt as Date));
      if (!durations.length) return 0;
      const total = durations.reduce((sum, minutes) => sum + minutes, 0);
      return Math.round((total / durations.length) * 100) / 100;
    },
  },
  {
    id: 'support.resolved_within_sla_rate',
    name: 'Tỷ lệ giải quyết đúng SLA',
    description:
      'Trong số ticket ĐÃ giải quyết trong kỳ, bao nhiêu % đúng hạn SLA (theo %). ' +
      'Khác với chỉ tiêu SLA đúng hạn ở chỗ mẫu số chỉ gồm ticket đã giải quyết.',
    kind: 'DERIVED',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày xử lý xong ticket',
    ownerBasis: 'Người phụ trách ticket',
    defaultValue: '0.00',
    defaultUnit: '%',
    async resolve(prisma, context) {
      const tickets = await prisma.ticket.findMany({
        where: { ...ticketBase(context), resolvedAt: inPeriod(context.period) },
        select: { slaDueAt: true, resolvedAt: true },
      });
      if (!tickets.length) return 0;
      const withinSla = tickets.filter(
        (ticket) =>
          ticket.resolvedAt !== null &&
          (ticket.slaDueAt === null || ticket.resolvedAt <= ticket.slaDueAt),
      ).length;
      return Math.round((withinSla / tickets.length) * 10_000) / 100;
    },
  },
  {
    id: 'support.avg_csat',
    name: 'Điểm hài lòng khách hàng (CSAT)',
    description:
      'Điểm CSAT trung bình (thang 1..5) của các ticket tạo trong kỳ mà khách đã đánh giá.',
    kind: 'DERIVED',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày tạo ticket',
    ownerBasis: 'Người phụ trách ticket',
    defaultValue: '0.00',
    defaultUnit: 'Điểm',
    async resolve(prisma, context) {
      const result = await prisma.ticket.aggregate({
        where: {
          ...ticketBase(context),
          createdAt: inPeriod(context.period),
          csatScore: { not: null },
        },
        _avg: { csatScore: true },
      });
      return Math.round(toNumber(result._avg.csatScore) * 100) / 100;
    },
  },

  // ── Vận hành & tài chính ────────────────────────────────────────────────────
  {
    id: 'operation.completed_processes',
    name: 'Số quy trình hoàn thành',
    description:
      'Số phiếu quy trình (RequestTicket) được duyệt xong trong kỳ. Lọc theo người đề nghị.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày phiếu được duyệt xong',
    ownerBasis: 'Người đề nghị',
    defaultValue: '0.00',
    defaultUnit: 'Quy trình',
    async resolve(prisma, context) {
      const requesterUserId = ownerIdFilter(context);
      return prisma.requestTicket.count({
        where: {
          deletedAt: null,
          status: 'APPROVED',
          resolvedAt: inPeriod(context.period),
          ...(requesterUserId ? { requesterUserId } : {}),
        },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.requestTicket.groupBy({
        by: ['requesterUserId'],
        where: {
          deletedAt: null,
          status: 'APPROVED',
          resolvedAt: inPeriod(context.period),
          requesterUserId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.requesterUserId,
        (row) => row._count._all,
      );
    },
  },
  {
    id: 'finance.late_days',
    name: 'Tổng số ngày trễ hạn (Tài chính)',
    description:
      'Tổng số ngày trễ của các công việc tài chính có hạn trong kỳ. Việc chưa xong thì tính ' +
      'tới hiện tại. Dùng cho chỉ tiêu trừ điểm đúng hạn.',
    // Vẫn là RAW: có tính toán, nhưng tính trong TỪNG DÒNG rồi cộng lại — một phép đo duy nhất,
    // không phải ghép hai phép đo độc lập.
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Hạn hoàn thành công việc',
    ownerBasis: 'Người phụ trách công việc',
    defaultValue: '0.00',
    defaultUnit: 'Ngày',
    async resolve(prisma, context) {
      const tasks = await prisma.financeTask.findMany({
        where: {
          deletedAt: null,
          status: { not: 'CANCELLED' },
          dueDate: inPeriod(context.period),
          ...byOwner(context),
        },
        select: { dueDate: true, completedAt: true },
      });
      const now = new Date();
      return tasks.reduce(
        (sum, task) => sum + calendarLateDays(task.dueDate, task.completedAt, now),
        0,
      );
    },
    async resolveByOwner(prisma, context) {
      const tasks = await prisma.financeTask.findMany({
        where: {
          deletedAt: null,
          status: { not: 'CANCELLED' },
          dueDate: inPeriod(context.period),
          ownerId: { in: [...context.ownerUserIds] },
        },
        select: { ownerId: true, dueDate: true, completedAt: true },
      });
      const now = new Date();
      return ownerMap(
        tasks,
        (task) => task.ownerId,
        (task) => calendarLateDays(task.dueDate, task.completedAt, now),
      );
    },
  },
  {
    id: 'finance.error_count',
    name: 'Số lỗi tài chính',
    description: 'Số lỗi phát hiện trong kỳ. Dùng cho chỉ tiêu trừ điểm độ chính xác.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày phát hiện lỗi',
    ownerBasis: 'Người phụ trách',
    defaultValue: '0.00',
    defaultUnit: 'Lỗi',
    async resolve(prisma, context) {
      return prisma.financeIssue.count({
        where: {
          deletedAt: null,
          type: 'ERROR',
          detectedAt: inPeriod(context.period),
          ...byOwner(context),
        },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.financeIssue.groupBy({
        by: ['ownerId'],
        where: {
          deletedAt: null,
          type: 'ERROR',
          detectedAt: inPeriod(context.period),
          ownerId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.ownerId,
        (row) => row._count._all,
      );
    },
  },
  {
    id: 'finance.reconciled_amount',
    name: 'Số tiền đã đối soát',
    description:
      'Tổng số tiền đã đối soát xong của các công việc đối soát có hạn trong kỳ. ' +
      'So với mục tiêu trong kế hoạch KPI để ra điểm.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Hạn hoàn thành công việc đối soát',
    ownerBasis: 'Người phụ trách công việc',
    defaultValue: '0.00',
    defaultUnit: 'VNĐ',
    async resolve(prisma, context) {
      const result = await prisma.financeTask.aggregate({
        where: {
          deletedAt: null,
          type: 'RECONCILIATION',
          dueDate: inPeriod(context.period),
          ...byOwner(context),
        },
        _sum: { reconciledAmount: true },
      });
      return toNumber(result._sum.reconciledAmount);
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.financeTask.groupBy({
        by: ['ownerId'],
        where: {
          deletedAt: null,
          type: 'RECONCILIATION',
          dueDate: inPeriod(context.period),
          ownerId: { in: [...context.ownerUserIds] },
        },
        _sum: { reconciledAmount: true },
      });
      return ownerMap(
        rows,
        (row) => row.ownerId,
        (row) => toNumber(row._sum.reconciledAmount),
      );
    },
  },
  {
    id: 'finance.compliance_issue_count',
    name: 'Số vấn đề tuân thủ',
    description: 'Số vi phạm tuân thủ phát hiện trong kỳ. Dùng cho chỉ tiêu trừ điểm tuân thủ.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày phát hiện vi phạm',
    ownerBasis: 'Người phụ trách',
    defaultValue: '0.00',
    defaultUnit: 'Vấn đề',
    async resolve(prisma, context) {
      return prisma.financeIssue.count({
        where: {
          deletedAt: null,
          type: 'COMPLIANCE',
          detectedAt: inPeriod(context.period),
          ...byOwner(context),
        },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.financeIssue.groupBy({
        by: ['ownerId'],
        where: {
          deletedAt: null,
          type: 'COMPLIANCE',
          detectedAt: inPeriod(context.period),
          ownerId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.ownerId,
        (row) => row._count._all,
      );
    },
  },

  // ── Marketing & khách hàng ──────────────────────────────────────────────────
  {
    id: 'marketing.qualified_leads',
    name: 'Lead đủ điều kiện',
    description:
      'Số lead đủ điều kiện được ghi nhận trong kỳ KPI. KHÔNG tách được theo người phụ trách — ' +
      'chỉ dùng cho chỉ tiêu cấp phòng ban.',
    kind: 'RAW',
    // Bảng `campaignRecipient` không có cột người phụ trách. Nếu để nguồn này chạy cho chỉ tiêu
    // cá nhân thì cả phòng cùng nhận con số của toàn công ty — sai mà nhìn vào không thấy sai.
    ownerScope: 'TENANT_ONLY',
    periodBasis: 'Ngày lead hoàn tất chiến dịch',
    ownerBasis: 'Không có — số của toàn công ty',
    defaultValue: '0.00',
    defaultUnit: 'Lead',
    async resolve(prisma, context) {
      return prisma.campaignRecipient.count({
        where: { status: 'COMPLETED', completedAt: inPeriod(context.period) },
      });
    },
  },
  {
    id: 'customer.new_customers',
    name: 'Khách hàng mới',
    description: 'Số khách hàng mới được tạo trong kỳ KPI.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày tạo khách hàng',
    ownerBasis: 'Người phụ trách khách hàng',
    defaultValue: '0.00',
    defaultUnit: 'Khách hàng',
    async resolve(prisma, context) {
      return prisma.customer.count({
        where: { createdAt: inPeriod(context.period), deletedAt: null, ...byOwner(context) },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.customer.groupBy({
        by: ['ownerId'],
        where: {
          createdAt: inPeriod(context.period),
          deletedAt: null,
          ownerId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.ownerId,
        (row) => row._count._all,
      );
    },
  },

  // ── Công việc ───────────────────────────────────────────────────────────────
  {
    id: 'tasks.assigned_total',
    name: 'Số công việc được giao',
    description:
      'Tổng số công việc được tạo và giao cho người đó trong kỳ. Đây là "tổng số việc" theo NGÀY ' +
      'GIAO — muốn đếm theo hạn thì dùng "Số công việc đến hạn".',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày tạo công việc',
    ownerBasis: 'Người được giao việc',
    defaultValue: '0.00',
    defaultUnit: 'Việc',
    async resolve(prisma, context) {
      const assigneeId = ownerIdFilter(context);
      return prisma.task.count({
        where: {
          createdAt: inPeriod(context.period),
          deletedAt: null,
          ...(assigneeId ? { assigneeId } : {}),
        },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.task.groupBy({
        by: ['assigneeId'],
        where: {
          createdAt: inPeriod(context.period),
          deletedAt: null,
          assigneeId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.assigneeId,
        (row) => row._count._all,
      );
    },
  },
  {
    id: 'tasks.due_total',
    name: 'Số công việc đến hạn',
    description:
      'Số công việc có HẠN rơi vào trong kỳ. Là mẫu số tự nhiên của tỷ lệ hoàn thành đúng hạn: ' +
      'ghép với "Số công việc hoàn thành" bằng công thức.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Hạn hoàn thành công việc',
    ownerBasis: 'Người được giao việc',
    defaultValue: '0.00',
    defaultUnit: 'Việc',
    async resolve(prisma, context) {
      const assigneeId = ownerIdFilter(context);
      return prisma.task.count({
        where: {
          dueDate: inPeriod(context.period),
          deletedAt: null,
          ...(assigneeId ? { assigneeId } : {}),
        },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.task.groupBy({
        by: ['assigneeId'],
        where: {
          dueDate: inPeriod(context.period),
          deletedAt: null,
          assigneeId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.assigneeId,
        (row) => row._count._all,
      );
    },
  },
  {
    id: 'tasks.completed',
    name: 'Số công việc hoàn thành',
    description: 'Số công việc được đánh dấu hoàn thành trong kỳ KPI.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày hoàn thành công việc',
    ownerBasis: 'Người được giao việc',
    defaultValue: '0.00',
    defaultUnit: 'Việc',
    async resolve(prisma, context) {
      const assigneeId = ownerIdFilter(context);
      return prisma.task.count({
        where: {
          status: 'COMPLETED',
          completedAt: inPeriod(context.period),
          deletedAt: null,
          ...(assigneeId ? { assigneeId } : {}),
        },
      });
    },
    async resolveByOwner(prisma, context) {
      const rows = await prisma.task.groupBy({
        by: ['assigneeId'],
        where: {
          status: 'COMPLETED',
          completedAt: inPeriod(context.period),
          deletedAt: null,
          assigneeId: { in: [...context.ownerUserIds] },
        },
        _count: { _all: true },
      });
      return ownerMap(
        rows,
        (row) => row.assigneeId,
        (row) => row._count._all,
      );
    },
  },
];

/** Làm tròn 2 chữ số — dùng nội bộ cho các nguồn cộng dồn thời lượng. */
function roundTwo(value: number): number {
  return Math.round(value * 100) / 100;
}

const SOURCE_BY_ID = new Map(KPI_DATA_SOURCES.map((source) => [source.id, source]));

export function findKpiDataSource(id: string): KpiDataSourceDef | undefined {
  return SOURCE_BY_ID.get(id);
}

/**
 * Nguồn dùng được làm chỉ tiêu KPI — chỉ RAW.
 *
 * DERIVED bị loại vì không gộp nhiều kỳ con lên cả năm được (xem chú thích đầu file).
 */
export function kpiSelectableDataSources(): KpiDataSourceDef[] {
  return KPI_DATA_SOURCES.filter((source) => source.kind === 'RAW');
}

/** Mã của các nguồn dùng được cho KPI — để kiểm tham chiếu trong công thức. */
export function kpiSelectableDataSourceIds(): string[] {
  return kpiSelectableDataSources().map((source) => source.id);
}

/** Kỳ KPI theo tháng/năm: từ 00:00:00 ngày 1 đến 23:59:59.999 ngày cuối tháng. */
export function monthPeriod(periodMonth: number, periodYear: number): KpiPeriod {
  return {
    start: new Date(periodYear, periodMonth - 1, 1, 0, 0, 0, 0),
    end: new Date(periodYear, periodMonth, 0, 23, 59, 59, 999),
  };
}

