  // ── Bán hàng ────────────────────────────────────────────────────────────────
  {
    id: 'sales.closed_revenue',
    name: 'Doanh thu đã chốt',
    description:
      'Tổng giá trị cơ hội chuyển sang THẮNG trong kỳ, cộng giá trị hợp đồng hoàn thành ký trong kỳ.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày cơ hội chuyển sang THẮNG / ngày ký hợp đồng',
    ownerBasis: 'Người phụ trách cơ hội / hợp đồng',
    defaultValue: '0.00',
    defaultUnit: 'VNĐ',
    async resolve(prisma, context) {
      const wonIds = await wonOpportunityIdsInPeriod(prisma, context);
      const [opportunities, contracts] = await Promise.all([
        wonIds.length
          ? prisma.opportunity.aggregate({
              where: { id: { in: wonIds } },
              _sum: { amount: true },
            })
          : Promise.resolve({ _sum: { amount: null } }),
        prisma.contract.aggregate({
          where: {
            status: 'COMPLETED',
            signDate: inPeriod(context.period),
            ...byOwner(context),
          },
          _sum: { contractValue: true },
        }),
      ]);
      return toNumber(opportunities._sum.amount) + toNumber(contracts._sum.contractValue);
    },
    async resolveByOwner(prisma, context) {
      const [won, contracts] = await Promise.all([
        wonOpportunitiesByOwner(prisma, context),
        prisma.contract.groupBy({
          by: ['ownerId'],
          where: {
            status: 'COMPLETED',
            signDate: inPeriod(context.period),
            ownerId: { in: [...context.ownerUserIds] },
          },
          _sum: { contractValue: true },
        }),
      ]);

      const result = ownerMap(
        won,
        (row) => row.ownerId,
        (row) => row.amount,
      );
      for (const row of contracts) {
        const value = toNumber(row._sum.contractValue);
        result.set(row.ownerId, (result.get(row.ownerId) ?? 0) + value);
      }
      return result;
    },
  },
  {
    id: 'sales.closed_deals',
    name: 'Số thương vụ đã chốt',
    description: 'Số cơ hội chuyển sang THẮNG trong kỳ, cộng số hợp đồng hoàn thành ký trong kỳ.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày cơ hội chuyển sang THẮNG / ngày ký hợp đồng',
    ownerBasis: 'Người phụ trách cơ hội / hợp đồng',
    defaultValue: '0.00',
    defaultUnit: 'Thương vụ',
    async resolve(prisma, context) {
      const [wonIds, contracts] = await Promise.all([
        wonOpportunityIdsInPeriod(prisma, context),
        prisma.contract.count({
          where: {
            status: 'COMPLETED',
            signDate: inPeriod(context.period),
            ...byOwner(context),
          },
