    // Đã ghép hai phép đo ⇒ không gộp nhiều kỳ con lên cả năm được. Làm chỉ tiêu KPI thì dùng
    // công thức `[sales.opportunities_won] / [sales.opportunities_created] * 100`.
    kind: 'DERIVED',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày tạo cơ hội (mẫu số)',
    ownerBasis: 'Người phụ trách cơ hội',
    defaultValue: '0.00',
    defaultUnit: '%',
    async resolve(prisma, context) {
      const base = { createdAt: inPeriod(context.period), ...byOwner(context) };
