      if (total === 0) return 0;
      return Math.round((won / total) * 10_000) / 100;
    },
  },
  {
    id: 'sales.overdue_debt_count',
    name: 'Số khoản công nợ quá hạn',
    description:
      'Số kỳ thanh toán của đơn hàng và hợp đồng chưa thu mà đã quá hạn tính đến cuối kỳ KPI. ' +
      'Dùng cho chỉ tiêu trừ điểm công nợ.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Hạn thanh toán trước thời điểm cuối kỳ',
    ownerBasis: 'Người phụ trách đơn hàng / hợp đồng',
    defaultValue: '0.00',
    defaultUnit: 'Khoản',
    async resolve(prisma, context) {
      const overdue = { isPaid: false, dueDate: { lt: context.period.end }, deletedAt: null };
      const ownerId = ownerIdFilter(context);
      const [orderPayments, contractPayments] = await Promise.all([
        prisma.salesOrderPayment.count({
          where: { ...overdue, ...(ownerId ? { order: { ownerId } } : {}) },
