    },
    async resolveByOwner(prisma, context) {
      const overdue = { isPaid: false, dueDate: { lt: context.period.end }, deletedAt: null };
      const owners = { in: [...context.ownerUserIds] };
      const [orderPayments, contractPayments] = await Promise.all([
        prisma.salesOrderPayment.findMany({
          where: { ...overdue, order: { ownerId: owners } },
          select: { order: { select: { ownerId: true } } },
        }),
        prisma.contractPayment.findMany({
          where: { ...overdue, contract: { ownerId: owners } },
          select: { contract: { select: { ownerId: true } } },
        }),
      ]);

      const result = ownerMap(
        orderPayments,
        (row) => row.order.ownerId,
        () => 1,
      );
      for (const row of contractPayments) {
        const owner = row.contract.ownerId;
        result.set(owner, (result.get(owner) ?? 0) + 1);
      }
      return result;
    },
  },
  {
    id: 'sales.activity_count',
    name: 'Số hoạt động bán hàng',
    description: 'Số hoạt động (gọi, gặp, email, ghi chú) phát sinh trong kỳ KPI.',
    kind: 'RAW',
    ownerScope: 'PER_OWNER',
    periodBasis: 'Ngày diễn ra hoạt động',
    ownerBasis: 'Người thực hiện hoạt động',
    defaultValue: '0.00',
    defaultUnit: 'Hoạt động',
    async resolve(prisma, context) {
