import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import {
  evaluateKpiFormula,
  parseKpiFormula,
  slotCount,
  slotKey,
  slotRange,
  type KpiCadence,
} from '@ics/shared';
import { PrismaService } from '../common/prisma.service';
import { TenantContextService } from '../common/tenant-context.service';
import { findKpiDataSource, type KpiPeriod } from './kpi-data-sources';

/**
 * Điền SỐ THỰC TẾ cho các chỉ tiêu lấy dữ liệu tự động.
 *
 * ── HAI CHẾ ĐỘ, RANH GIỚI LÀ KỲ CON ĐÃ KẾT THÚC CHƯA ──────────────────────────
 *
 *   Kỳ con ĐANG CHẠY   Tính lại mỗi lần đọc, KHÔNG ghi DB. Người ta mở trang KPI
 *                      chính là để hỏi "giờ tôi được bao nhiêu rồi" — bắt bấm nút
 *                      "Đồng bộ" hay chờ cron đêm đều trả lời sai câu hỏi đó.
 *
 *   Kỳ con ĐÃ XONG     Lượt đọc đầu tiên sau khi hết hạn ân hạn sẽ tính MỘT LẦN
 *                      rồi ghi xuống kèm `autoSyncedAt`. Từ đó con số đứng yên
 *                      vĩnh viễn.
 *
 * Vì sao phải đóng băng: không đóng thì số của quá khứ vẫn đổi. Tháng 8 có người
 * sửa lại một cơ hội của quý 1 là điểm KPI quý 1 — đã duyệt lương — tự đổi theo,
 * và không có gì để giải thích với nhân viên. Đây cũng là lý do `KpiPlanStatus`
 * có trạng thái đã chốt: kỳ chốt rồi thì bất biến.
 *
 * Cách này không cần cron và không cần nút bấm: ai mở trang đầu tiên sau khi kỳ
 * con kết thúc thì chính lượt đọc đó chốt số.
 */

/**
 * Ân hạn trước khi đóng băng một kỳ con đã hết.
 *
 * Hợp đồng ký 28/6 rất hay được nhập liệu ngày 3/7. Đóng băng ngay 00:00 ngày đầu
 * kỳ sau là chốt mất phần doanh thu chưa kịp vào sổ.
 */
const FREEZE_GRACE_DAYS = 5;

/**
 * Trần số lượt TÍNH MỚI trong một lần đọc.
 *
 * Chỉ tiêu đạt/không đạt được phép chia theo NGÀY, nên một kế hoạch bỏ quên nửa
 * năm có thể cần đóng băng hàng trăm ô cùng lúc — đủ để một request treo. Chặn
 * lại ở đây; phần còn lại được đóng băng dần ở các lượt đọc sau, cũ trước mới
 * sau. Không mất dữ liệu, chỉ là chốt chậm vài lượt.
 */
const MAX_RESOLVES_PER_READ = 90;

/** Một ô kết quả do nguồn tự động điền. */
export interface AutoSlotValue {
  /** Chỉ tiêu không chia kỳ con dùng khoá 0 — đại diện cho "cả kỳ". */
  slotIndex: number;
  value: number | null;
  /** Đã chốt (đọc từ DB hoặc vừa ghi trong lượt này) hay đang tính sống. */
  frozen: boolean;
}

/** Chỉ tiêu cần phân giải — đúng những trường cần, không kéo cả dòng. */
export interface AutoMetricInput {
  id: string;
  level: 'DEPARTMENT' | 'INDIVIDUAL';
  kind: 'MEASURED' | 'PASS_FAIL';
  cadence: KpiCadence;
  sourceType: 'MANUAL' | 'EXISTING' | 'FORMULA';
  dataSourceId: string | null;
  formula: string | null;
  /** Mốc đóng băng của con số CẢ KỲ (chỉ dùng khi `cadence = PERIOD`). */
  autoSyncedAt: Date | null;
  /** Giá trị cả kỳ đang lưu — dùng lại khi đã đóng băng. */
  actualValue: number | null;
  /** Người của dòng cá nhân. `null` ở dòng phòng ban. */
  ownerUserId: string | null;
  /** Dòng phòng ban đã giao cho ai chưa — đã giao thì số của phòng là gộp từ con. */
  hasChildren: boolean;
}

/** Ô kỳ con đang lưu trong DB, để biết ô nào đã chốt. */
export interface ExistingSlot {
  slotIndex: number;
  actualValue: number | null;
  autoSyncedAt: Date | null;
}

export interface ResolvePlanInput {
  plan: { id: string; periodYear: number };
  metrics: readonly AutoMetricInput[];
  /** metricId → các ô kỳ con đang có trong DB. */
  existingSlots: ReadonlyMap<string, readonly ExistingSlot[]>;
  /** Danh sách người của phòng — dùng cho dòng phòng ban chưa giao cho ai. */
  departmentUserIds: readonly string[];
  now: Date;
}

/** Một lượt truy vấn gộp: một nguồn × một khoảng thời gian × một tập người. */
interface BatchJob {
  sourceId: string;
  period: KpiPeriod;
  owners: Set<string>;
  /** Có dòng nào cần số KHÔNG lọc theo người (nguồn không tách được theo người). */
  needsTenantWide: boolean;
}

@Injectable()
export class KpiMetricSourceService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly tenant: TenantContextService,
  ) {}

  /**
   * Phân giải toàn bộ chỉ tiêu tự động của một kế hoạch.
   *
   * Trả `metricId → các ô đã điền`. Chỉ tiêu nhập tay không xuất hiện trong kết quả.
   */
  async resolveForPlan(input: ResolvePlanInput): Promise<Map<string, AutoSlotValue[]>> {
    const targets = this.collectTargets(input);
    if (!targets.length) return new Map();

    const jobs = this.planBatchJobs(targets);
    const readings = await this.runBatchJobs(jobs);
    const result = this.composeValues(targets, readings);

    await this.freeze(input.plan, targets, result);
    return result;
  }

  // ─────────────────────────────────────────────────────────────
  // 1. Xác định phải tính những ô nào
  // ─────────────────────────────────────────────────────────────

  /** Một ô cụ thể cần tính (hoặc đã có sẵn vì đã chốt). */
  private collectTargets(input: ResolvePlanInput): ResolveTarget[] {
    const targets: ResolveTarget[] = [];
    let budget = MAX_RESOLVES_PER_READ;

    for (const metric of input.metrics) {
      const sources = this.sourcesOf(metric);
      if (!sources) continue;

      /*
        Dòng phòng ban ĐÃ GIAO cho cá nhân thì không tự lấy số: kết quả của phòng
        được gộp từ phần đã giao (`rollUpAllocatedActual`). Tự lấy thêm ở đây là
        có hai nguồn sự thật trên cùng một dòng, và chúng sẽ lệch nhau.
      */
      if (metric.level === 'DEPARTMENT' && metric.hasChildren) continue;

      const owners =
        metric.level === 'INDIVIDUAL'
          ? metric.ownerUserId
            ? [metric.ownerUserId]
            : null // Nhân viên chưa có tài khoản ⇒ không tra được, để trống.
          : [...input.departmentUserIds];
      if (owners === null) continue;

      /*
        Nguồn không tách được theo người (vd lead từ chiến dịch) chỉ dùng được ở
        cấp phòng ban. Gán cho cá nhân thì cả 12 người cùng nhận số toàn công ty —
        sai mà nhìn vào không thấy sai, nên thà để trống.
      */
      const tenantWideOnly = sources.some(
        (source) => findKpiDataSource(source)?.ownerScope === 'TENANT_ONLY',
      );
      if (tenantWideOnly && metric.level === 'INDIVIDUAL') continue;

      for (const slot of this.slotsToResolve(metric, input)) {
        if (slot.reuse !== undefined) {
          targets.push({ metric, sources, owners, tenantWideOnly, ...slot });
          continue;
        }
        if (budget <= 0) break;
        budget -= 1;
        targets.push({ metric, sources, owners, tenantWideOnly, ...slot });
      }
    }

    return targets;
  }

  /** Mã các nguồn một chỉ tiêu cần. `null` = chỉ tiêu này không lấy tự động. */
  private sourcesOf(metric: AutoMetricInput): string[] | null {
    if (metric.sourceType === 'EXISTING') {
      return metric.dataSourceId ? [metric.dataSourceId] : null;
    }
    if (metric.sourceType === 'FORMULA') {
      if (!metric.formula) return null;
      const parsed = parseKpiFormula(metric.formula);
      return parsed.ok ? parsed.refs : null;
    }
    return null;
  }

  /**
   * Những ô của một chỉ tiêu cần xử lý trong lượt này.
   *
   * Bỏ hẳn kỳ con CHƯA BẮT ĐẦU: chúng chắc chắn chưa có dữ liệu, và điền 0 vào đó
   * là biến "chưa tới kỳ" thành "làm được 0" — chấm điểm sẽ thành trượt.
   */
  private slotsToResolve(metric: AutoMetricInput, input: ResolvePlanInput): SlotPlan[] {
    const { periodYear } = input.plan;
    const now = input.now;

    if (metric.cadence === 'PERIOD') {
      const range = slotRange('PERIOD', periodYear, 0);
      if (range.startAt > now) return [];
      if (metric.autoSyncedAt) {
        return [{ slotIndex: 0, period: toPeriod(range), reuse: metric.actualValue, freeze: false }];
      }
      return [
        {
          slotIndex: 0,
          period: toPeriod(range),
          freeze: this.pastGrace(range.endAt, now),
        },
      ];
    }

    const stored = new Map(
      (input.existingSlots.get(metric.id) ?? []).map((slot) => [slot.slotIndex, slot]),
    );
    const total = slotCount(metric.cadence, periodYear);
    const plans: SlotPlan[] = [];

    for (let index = 0; index < total; index += 1) {
      const range = slotRange(metric.cadence, periodYear, index);
      if (range.startAt > now) break; // Các kỳ sau còn xa hơn nữa — dừng luôn.

      const existing = stored.get(index);
      if (existing?.autoSyncedAt) {
        plans.push({
          slotIndex: index,
          period: toPeriod(range),
          reuse: existing.actualValue,
          freeze: false,
        });
        continue;
      }
      plans.push({
        slotIndex: index,
        period: toPeriod(range),
        freeze: this.pastGrace(range.endAt, now),
      });
    }

    return plans;
  }

  /** Kỳ con đã kết thúc và qua luôn hạn ân hạn nhập liệu muộn chưa. */
  private pastGrace(endAt: Date, now: Date): boolean {
    return now.getTime() > endAt.getTime() + FREEZE_GRACE_DAYS * 86_400_000;
  }

  // ─────────────────────────────────────────────────────────────
  // 2. Gộp lô rồi truy vấn
  // ─────────────────────────────────────────────────────────────

  /**
   * Gộp mọi ô cần tính thành các lượt truy vấn theo (nguồn × khoảng thời gian).
   *
   * Đây là chỗ quyết định hiệu năng. Một kế hoạch 12 người × 3 chỉ tiêu tự động,
   * nếu hỏi từng người thì là 36 lượt × ~2 truy vấn cho MỘT lần mở trang. Gộp lại
   * còn đúng một truy vấn cho mỗi (nguồn, kỳ) nhờ `resolveByOwner` dùng `groupBy`.
   */
  private planBatchJobs(targets: readonly ResolveTarget[]): Map<string, BatchJob> {
    const jobs = new Map<string, BatchJob>();

    for (const target of targets) {
      if (target.reuse !== undefined) continue; // Đã chốt, không phải hỏi lại.

      for (const sourceId of target.sources) {
        const key = `${sourceId}|${target.period.start.getTime()}|${target.period.end.getTime()}`;
        const job = jobs.get(key) ?? {
          sourceId,
          period: target.period,
          owners: new Set<string>(),
          needsTenantWide: false,
        };
        if (target.tenantWideOnly) job.needsTenantWide = true;
        else for (const owner of target.owners) job.owners.add(owner);
        jobs.set(key, job);
      }
    }

    return jobs;
  }

  /** Chạy các lượt gộp. Khoá kết quả trùng với khoá của `planBatchJobs`. */
  private async runBatchJobs(jobs: Map<string, BatchJob>): Promise<Map<string, SourceReading>> {
    const entries = await Promise.all(
      [...jobs].map(async ([key, job]) => [key, await this.runBatchJob(job)] as const),
    );
    return new Map(entries);
  }

  private async runBatchJob(job: BatchJob): Promise<SourceReading> {
    const source = findKpiDataSource(job.sourceId);
    // Nguồn đã bị gỡ khỏi danh mục (đổi mã, bỏ tính năng) — để `null` là "chưa
    // đánh giá được" thay vì 0, vì 0 sẽ bị chấm thành trượt.
    if (!source) return { byOwner: new Map(), tenantWide: null, missing: true };

    const tenantWide = job.needsTenantWide
      ? await source.resolve(this.prisma.scoped, { period: job.period })
      : null;

    if (!job.owners.size) return { byOwner: new Map(), tenantWide, missing: false };

    const owners = [...job.owners];
    if (source.resolveByOwner) {
      const byOwner = await source.resolveByOwner(this.prisma.scoped, {
        period: job.period,
        ownerUserIds: owners,
      });
      return { byOwner, tenantWide, missing: false };
    }

    /*
      Nguồn chưa có bản gộp lô ⇒ hỏi từng người. Đúng nhưng tốn; chỉ nên rơi vào
      đây với nguồn ít dùng. Thêm `resolveByOwner` cho nguồn nào bị dùng nhiều.
    */
    const byOwner = new Map<string, number>();
    for (const owner of owners) {
      byOwner.set(
        owner,
        await source.resolve(this.prisma.scoped, { period: job.period, ownerUserId: owner }),
      );
    }
    return { byOwner, tenantWide, missing: false };
  }

  // ─────────────────────────────────────────────────────────────
  // 3. Ghép thành con số của từng ô
  // ─────────────────────────────────────────────────────────────

  private composeValues(
    targets: readonly ResolveTarget[],
    readings: ReadonlyMap<string, SourceReading>,
  ): Map<string, AutoSlotValue[]> {
    const result = new Map<string, AutoSlotValue[]>();

    for (const target of targets) {
      const bucket = result.get(target.metric.id) ?? [];

      if (target.reuse !== undefined) {
        bucket.push({ slotIndex: target.slotIndex, value: target.reuse, frozen: true });
        result.set(target.metric.id, bucket);
        continue;
      }

      const value = this.valueOf(target, readings);
      bucket.push({ slotIndex: target.slotIndex, value, frozen: target.freeze && value !== null });
      result.set(target.metric.id, bucket);
    }

    return result;
  }

  private valueOf(
    target: ResolveTarget,
    readings: ReadonlyMap<string, SourceReading>,
  ): number | null {
    /** Số của MỘT nguồn cho đúng phạm vi người của dòng này. */
    const readOne = (sourceId: string): number | null => {
      const key = `${sourceId}|${target.period.start.getTime()}|${target.period.end.getTime()}`;
      const reading = readings.get(key);
      if (!reading || reading.missing) return null;
      if (target.tenantWideOnly) return reading.tenantWide;

      /*
        Cộng số của những người trong phạm vi. Dòng cá nhân chỉ có một người; dòng
        phòng ban chưa giao cho ai thì cộng cả phòng.

        Vắng mặt trong bảng = 0, KHÔNG phải `null`: nguồn RAW đều là đếm/cộng nên
        "không có dòng nào" đúng nghĩa là 0. Cần phân biệt "chưa có gì để đo" thì
        dùng công thức có mẫu số — 0/0 mới ra `null`.
      */
      let total = 0;
      for (const owner of target.owners) total += reading.byOwner.get(owner) ?? 0;
      return total;
    };

    const raw = this.rawValueOf(target, readOne);
    if (raw === null) return null;

    /*
      Đạt/không đạt: nguồn trả về một con số đếm, quy về 1 lần đạt / 0 lần đạt.
      Đây đúng là loại đáng tự động hoá nhất — "có nộp báo cáo hôm nay không" thì
      đếm được, và không ai muốn tick tay 20 ô mỗi tháng.
    */
    if (target.metric.kind === 'PASS_FAIL') return raw > 0 ? 1 : 0;

    return roundFour(raw);
  }

  private rawValueOf(
    target: ResolveTarget,
    readOne: (sourceId: string) => number | null,
  ): number | null {
    if (target.metric.sourceType === 'EXISTING') {
      return readOne(target.sources[0]);
    }

    /*
      Công thức được tính LẠI TỪ CÁC NGUỒN THÔ ở từng ô, không bao giờ gộp kết quả
      của các ô lại. Đây là luật sống còn của tỷ lệ: quý 1 thắng 10/40 = 25%, quý 2
      thắng 30/60 = 50%, cả năm là 40/100 = 40% chứ KHÔNG phải trung bình 37.5%.
      Vì mỗi ô đều tính từ tử số và mẫu số của chính khoảng thời gian đó nên kết
      quả đúng ở mọi mức gộp.
    */
    const parsed = parseKpiFormula(target.metric.formula ?? '');
    if (!parsed.ok) return null;

    const values: Record<string, number | null> = {};
    for (const ref of parsed.refs) values[ref] = readOne(ref);
    return evaluateKpiFormula(parsed.ast, values);
  }

  // ─────────────────────────────────────────────────────────────
  // 4. Đóng băng
  // ─────────────────────────────────────────────────────────────

  /**
   * Ghi xuống DB những ô đã qua hạn ân hạn, kèm mốc `autoSyncedAt` và một dòng
   * lịch sử mang `enteredBy = 'SYSTEM'`.
   *
   * Có vết là bắt buộc: nếu sau này ai đó sửa đè con số máy lấy, phải đọc được
   * "SYSTEM ghi 280tr → người B sửa thành 265tr" chứ không phải chỉ thấy 265tr.
   */
  private async freeze(
    plan: { id: string; periodYear: number },
    targets: readonly ResolveTarget[],
    values: ReadonlyMap<string, AutoSlotValue[]>,
  ): Promise<void> {
    const pending = targets.filter((target) => target.freeze && target.reuse === undefined);
    if (!pending.length) return;

    const valueAt = (metricId: string, slotIndex: number): number | null =>
      values.get(metricId)?.find((slot) => slot.slotIndex === slotIndex)?.value ?? null;

    const writable = pending
      .map((target) => ({ target, value: valueAt(target.metric.id, target.slotIndex) }))
      // Chưa tính ra số thì chưa chốt — chốt một ô `null` là khoá vĩnh viễn một ô
      // rỗng, trong khi lần đọc sau có thể đã có dữ liệu.
      .filter((row): row is { target: ResolveTarget; value: number } => row.value !== null);
    if (!writable.length) return;

    const tenantId = this.tenantId();
    const now = new Date();

    await this.prisma.$transaction(async (tx) => {
      for (const { target, value } of writable) {
        const decimal = new Prisma.Decimal(value);

        if (target.metric.cadence === 'PERIOD') {
          await tx.kpiPlanMetric.update({
            where: { id: target.metric.id },
            data: { actualValue: decimal, autoSyncedAt: now },
          });
          await tx.kpiMetricActualHistory.create({
            data: {
              tenantId,
              metricId: target.metric.id,
              value: decimal,
              enteredBy: SYSTEM_ACTOR,
              note: this.freezeNote(target),
            },
          });
          continue;
        }

        const planSlotId = await this.ensurePlanSlot(
          tx,
          plan,
          target.metric.cadence,
          target.slotIndex,
        );
        const existing = await tx.kpiPlanMetricSlot.findFirst({
          where: { tenantId, planSlotId, planMetricId: target.metric.id },
          select: { id: true },
        });
        const metricSlotId = existing
          ? existing.id
          : (
              await tx.kpiPlanMetricSlot.create({
                data: { tenantId, planSlotId, planMetricId: target.metric.id },
                select: { id: true },
              })
            ).id;

        await tx.kpiPlanMetricSlot.update({
          where: { id: metricSlotId },
          data: { actualValue: decimal, autoSyncedAt: now },
        });
        await tx.kpiPlanMetricSlotActualHistory.create({
          data: {
            tenantId,
            metricSlotId,
            value: decimal,
            enteredBy: SYSTEM_ACTOR,
            note: this.freezeNote(target),
          },
        });
      }
    });
  }

  /** Ghi rõ số đến từ đâu — người đọc lịch sử không phải tra mã nguồn. */
  private freezeNote(target: ResolveTarget): string {
    if (target.metric.sourceType === 'FORMULA') {
      return `Tự động chốt theo công thức: ${target.metric.formula ?? ''}`.trim();
    }
    const source = findKpiDataSource(target.sources[0]);
    return `Tự động chốt từ nguồn: ${source?.name ?? target.sources[0]}`;
  }

  /**
   * Dòng kỳ con dùng chung cho mọi chỉ tiêu cùng nhịp trong kế hoạch — giống hệt
   * `KpiPlanService.ensurePlanSlot`. Hai nơi cùng ghi vào một bảng nên phải cùng
   * một cách sinh `slotKey`, nếu không sẽ có hai dòng cho cùng một khoảng.
   */
  private async ensurePlanSlot(
    tx: Prisma.TransactionClient,
    plan: { id: string; periodYear: number },
    cadence: KpiCadence,
    slotIndex: number,
  ): Promise<string> {
    const tenantId = this.tenantId();
    const key = slotKey(cadence, plan.periodYear, slotIndex);

    const existing = await tx.kpiPlanSlot.findFirst({
      where: { tenantId, planId: plan.id, slotKey: key },
      select: { id: true },
    });
    if (existing) return existing.id;

    const range = slotRange(cadence, plan.periodYear, slotIndex);
    const created = await tx.kpiPlanSlot.create({
      data: {
        tenantId,
        planId: plan.id,
        cadence,
        slotKey: key,
        slotIndex,
        slotStartAt: range.startAt,
        slotEndAt: range.endAt,
      },
      select: { id: true },
    });
    return created.id;
  }

  private tenantId(): string {
    const tenantId = this.tenant.getTenantId();
    if (!tenantId) throw new Error('Tenant context is required');
    return tenantId;
  }
}

/** Người ghi của các dòng lịch sử do hệ thống tạo. */
export const SYSTEM_ACTOR = 'SYSTEM';

interface SlotPlan {
  slotIndex: number;
  period: KpiPeriod;
  /** Đã chốt từ trước ⇒ dùng lại số đang lưu, không truy vấn lại. */
  reuse?: number | null;
  /** Ô này đã qua hạn ân hạn ⇒ ghi xuống DB sau khi tính. */
  freeze: boolean;
}

interface ResolveTarget extends SlotPlan {
  metric: AutoMetricInput;
  sources: string[];
  owners: string[];
  tenantWideOnly: boolean;
}

interface SourceReading {
  byOwner: ReadonlyMap<string, number>;
  tenantWide: number | null;
  /** Nguồn không còn trong danh mục. */
  missing: boolean;
}

function toPeriod(range: { startAt: Date; endAt: Date }): KpiPeriod {
  return { start: range.startAt, end: range.endAt };
}

/** Cột lưu là `Decimal(18,4)` — làm tròn đúng độ chính xác của kho. */
function roundFour(value: number): number {
  return Math.round(value * 10_000) / 10_000;
}

