// ── KPI (chỉ tiêu) ──────────────────────────────────────────

/**
 * ĐỊNH NGHĨA phép đo, tái dùng được qua nhiều kỳ — KHÔNG chứa con số của kỳ nào.
 *
 * Cố ý không có `weight` và không có target mặc định: cả hai đều chỉ có nghĩa
 * trong phạm vi MỘT kỳ. Trọng số phải xét theo cả tập KPI cùng trụ của kỳ đó
 * (tổng = 100%), nên một giá trị đặt sẵn ở đây gần như luôn sai; còn target thì
 * mỗi kỳ mỗi khác. Hai con số đó nhập ở kế hoạch KPI — xem `kpiDeptMetricCreateSchema`.
 *
 * Hệ quả về cách đặt tên: tên KPI phải là "Doanh thu", KHÔNG phải "Doanh thu đạt
 * 50 triệu" — có số trong tên là hết tái dùng được.
 */
export const kpiCriteriaCreateSchema = z
  .object({
    name: nonEmpty.max(200),
    description: optionalText(4000),
    csf: optionalText(500),
    sourceType: z.enum(KPI_SOURCE_TYPES).default('MANUAL'),
    dataSourceId: optionalId,
    formula: optionalText(4000),
    direction: z.enum(KPI_DIRECTIONS),
    allocationMode: z.enum(KPI_ALLOCATION_MODES).default('DIVIDE'),
    aggregation: z.enum(KPI_AGGREGATIONS).default('SUM'),
    isCombined: z.boolean().default(false),
    isBlocking: z.boolean().default(false),
    /// Cách đo — trục cao nhất. `PASS_FAIL` làm mọi trường bên dưới mất ý nghĩa.
    kind: z.enum(KPI_CRITERIA_KINDS).default('MEASURED'),
    /**
     * Mô hình chấm điểm — CHỈ có nghĩa với `kind = MEASURED`.
     * Để `optional` (KHÔNG default) nên bỏ trống thì DB tự điền `@default`.
     */
    scoringShape: z.enum(KPI_SCORING_SHAPES).optional(),
    scoringMethod: z.enum(KPI_SCORING_METHODS).optional(),
    measureType: z.enum(KPI_MEASURE_TYPES).optional(),
    scoringConfig: kpiScoringConfigSchema.optional(),
    /**
     * Đơn vị đo. BẮT BUỘC với `MEASURED`, phải BỎ TRỐNG với `PASS_FAIL` —
     * đạt/không đạt không đo bằng đơn vị nào cả (xem `superRefine` bên dưới).
     */
    unit: optionalText(80),
    /**
     * Bỏ trống ⇒ server tự đặt vào cuối danh sách.
     * KHÔNG dùng `.default(0)`: khi có default, giá trị luôn là 0 nên nhánh
     * tự-tính-thứ-tự ở service không bao giờ chạy, mọi chỉ tiêu mới đều sortOrder = 0.
     */
    sortOrder: z.coerce.number().int().min(0).optional(),
  })
  .strict()
  .superRefine((value, ctx) => {
    // Đạt/không đạt: không đơn vị, không cấu hình chấm. Service còn dọn thêm
    // (measureType/allocationMode) nhưng chặn ngay ở contract để lỗi hiện sớm.
    if (value.kind === 'PASS_FAIL') {
      if (value.unit)
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['unit'],
          message: 'Chỉ tiêu đạt/không đạt không có đơn vị đo',
        });
      return;
    }

    if (!value.unit)
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['unit'],
        message: 'Vui lòng nhập đơn vị đo',
      });

    /*
      Cấu hình chấm ở ĐÂY là TUỲ CHỌN và mang nghĩa "dùng chung cho mọi kỳ".
      Không khai ⇒ mỗi kế hoạch KPI phải tự khai cấu hình của kỳ đó (bắt buộc ở
      `kpiDeptMetricCreateSchema`). Đó là lý do không ép cấu hình ở tầng định nghĩa
      — phần lớn tham số mang đơn vị của phép đo (khoảng, min/max), mà con số thì
      thuộc về kỳ.

      Có khai thì phải hợp lệ với đúng loại đang chọn.
    */
    if (!value.scoringConfig) return;
    const error = validateScoringConfig({
      shape: value.scoringShape ?? 'UP',
      method: value.scoringMethod ?? 'CONTINUOUS',
      config: value.scoringConfig,
    });
    if (error)
      ctx.addIssue({ code: z.ZodIssueCode.custom, path: ['scoringConfig'], message: error });
  });

// `.superRefine` trả ZodEffects nên KHÔNG còn `.partial()`; update schema dựng
// lại từ object gốc (tách ra biến riêng ở trên sẽ gọn hơn, nhưng giữ tối thiểu
// thay đổi: build partial từ chính object bên trong hiệu ứng là không được, nên
// khai lại các field optional cho update).
export const kpiCriteriaUpdateSchema = z
  .object({
    name: nonEmpty.max(200).optional(),
    description: optionalText(4000),
    csf: optionalText(500),
    sourceType: z.enum(KPI_SOURCE_TYPES).optional(),
    dataSourceId: optionalId,
    formula: optionalText(4000),
    direction: z.enum(KPI_DIRECTIONS).optional(),
    allocationMode: z.enum(KPI_ALLOCATION_MODES).optional(),
    aggregation: z.enum(KPI_AGGREGATIONS).optional(),
    isCombined: z.boolean().optional(),
    isBlocking: z.boolean().optional(),
    kind: z.enum(KPI_CRITERIA_KINDS).optional(),
    scoringShape: z.enum(KPI_SCORING_SHAPES).optional(),
    scoringMethod: z.enum(KPI_SCORING_METHODS).optional(),
    measureType: z.enum(KPI_MEASURE_TYPES).optional(),
    scoringConfig: kpiScoringConfigSchema.optional(),
    unit: nonEmpty.max(80).optional(),
    sortOrder: z.coerce.number().int().min(0).optional(),
  })
  .strict()
  .refine((value) => Object.keys(value).length > 0, 'Cần ít nhất một trường cập nhật');

