import { z } from 'zod';
import { KPI_CADENCES } from '../kpi-cadence.js';

// ─────────────────────────────────────────────────────────────
// KPI theo khung BSC (Thẻ điểm cân bằng)
//
// Cấu trúc: Trụ cột (Aspect) → Key Objective → CSF → KPI phòng ban
//           → phân bổ cho cá nhân → chu kỳ tháng
//
// Lưu ý: mọi công thức chấm điểm nằm ở backend (`kpi-scoring.ts`).
// Frontend chỉ hiển thị `percent`/`score` do API trả về, không tự tính lại.
// ─────────────────────────────────────────────────────────────

const nonEmpty = z.string().trim().min(1);
const optionalText = (max: number) =>
  z.preprocess(
    (value) => (value === '' || value === null ? undefined : value),
    z.string().trim().max(max).optional(),
  );
const optionalId = optionalText(120);
const optionalNumber = z.preprocess(
  (value) => (value === '' || value === null || value === undefined ? undefined : value),
  z.coerce.number().finite().optional(),
);
const optionalNullableNumber = z.preprocess((value) => {
  if (value === '' || value === undefined) return undefined;
  if (value === null) return null;
  return value;
}, z.coerce.number().finite().nullable().optional());
const periodYear = z.coerce.number().int().min(2000).max(9999);
const percentWeight = z.coerce.number().min(0).max(100);

// ── Enum dùng chung (mirror của Prisma enum) ────────────────

export const KPI_ASPECTS = ['FINANCE', 'CUSTOMER', 'PROCESS', 'PEOPLE'] as const;
export const KPI_WEIGHT_SCOPES = ['COMPANY', 'DEPARTMENT'] as const;
export const KPI_METRIC_LEVELS = ['DEPARTMENT', 'INDIVIDUAL'] as const;
export const KPI_ALLOCATION_MODES = ['DIVIDE', 'INHERIT'] as const;
export const KPI_AGGREGATIONS = ['SUM', 'AVG', 'LAST'] as const;
export const KPI_SOURCE_TYPES = ['EXISTING', 'MANUAL', 'FORMULA'] as const;
export const KPI_DIRECTIONS = ['INCREASE', 'DECREASE'] as const;
/// CÁCH ĐO chỉ tiêu — trục cao nhất, quyết định có mục tiêu số hay không.
/// `MEASURED` dùng tiếp shape/method/config bên dưới; `PASS_FAIL` bỏ qua hết.
export const KPI_CRITERIA_KINDS = ['MEASURED', 'PASS_FAIL'] as const;
/// Hình dạng quan hệ giá trị–điểm. CHỈ có nghĩa với `kind = MEASURED`.
/// Trực giao với `KPI_SCORING_METHODS`.
export const KPI_SCORING_SHAPES = ['UP', 'DOWN', 'RANGE'] as const;
/// Cách hiện thực đường chấm: công thức liên tục hay bảng band rời rạc.
export const KPI_SCORING_METHODS = ['CONTINUOUS', 'DISCRETE'] as const;
