export function validateScoringConfig(input: {
  shape: KpiScoringShape;
  method: KpiScoringMethod;
  config: KpiScoringConfig | null | undefined;
}): string | null {
  const { shape, method, config } = input;

  if (method === 'DISCRETE') {
    if (!config?.bands?.length) return 'Cách chấm theo bảng khoảng cần khai các khoảng';
    return validateScoreBands(config.bands);
  }

  if (shape === 'RANGE') {
    const { min, max } = config ?? {};
    if (min == null || max == null)
      return 'Kiểu khoảng tối ưu cần khai giá trị nhỏ nhất và lớn nhất';
    if (min > max) return 'Giá trị nhỏ nhất phải ≤ giá trị lớn nhất';
    return null;
  }

  // UP/DOWN liên tục: sàn/trần đều tuỳ chọn, chỉ chặn giá trị vô lý.
  if (config?.floorPctOfTarget != null && config.floorPctOfTarget >= 100)
    return 'Sàn phải nhỏ hơn 100% của mục tiêu';
  return null;
}

// ── KPI (chỉ tiêu) ──────────────────────────────────────────

