/**
 * Kiểm NGUỒN SỐ LIỆU khai có khớp với loại nguồn đang chọn không.
 *
 * Ba lựa chọn nguồn phải ràng buộc chặt, nếu không sẽ lưu được những dòng vô
 * nghĩa kiểu `sourceType = FORMULA` mà `formula` rỗng — chỉ tiêu đó khoá ô nhập
 * tay xong không bao giờ có số, và người dùng không hiểu vì sao.
 *
 * `knownSourceIds` bỏ trống ⇒ chỉ kiểm HÌNH DẠNG. Danh mục nguồn nằm ở backend
 * (mỗi nguồn là một truy vấn Prisma) nên contract không tự kiểm được mã có thật
 * hay không; service backend truyền danh mục vào để kiểm nốt, còn form frontend
 * truyền danh sách lấy từ API để báo lỗi sớm.
 */
export function validateKpiSourceBinding(input: {
  sourceType: KpiSourceType;
  dataSourceId?: string | null;
  formula?: string | null;
  knownSourceIds?: readonly string[];
}): string | null {
  const { sourceType, knownSourceIds } = input;
  const dataSourceId = input.dataSourceId?.trim() || null;
  const formula = input.formula?.trim() || null;

  if (sourceType === 'MANUAL') {
    // Không chặn: dọn sạch là việc của nơi ghi. Chặn ở đây thì đổi từ tự động về
    // nhập tay sẽ báo lỗi vì hai trường cũ vẫn còn trong payload.
    return null;
  }

  if (sourceType === 'EXISTING') {
    if (!dataSourceId) return 'Vui lòng chọn nguồn dữ liệu của hệ thống';
    if (formula) return 'Nguồn lấy tự động không dùng công thức';
    if (knownSourceIds && !knownSourceIds.includes(dataSourceId)) {
      return `Không có nguồn dữ liệu: ${dataSourceId}`;
    }
    return null;
  }

  if (!formula) return 'Vui lòng nhập công thức';
  if (dataSourceId) return 'Chỉ tiêu tính bằng công thức không chọn nguồn đơn lẻ';
  return knownSourceIds
    ? validateKpiFormula(formula, knownSourceIds)
    : (parseKpiFormula(formula).ok ? null : parseKpiFormula(formula).error ?? 'Công thức không hợp lệ');
}

// ── KPI (chỉ tiêu) ──────────────────────────────────────────

