450	  /** Trả về phòng ban của người dùng để dùng tiếp cho `toView`. */
451	  private assertCanManage(
452	    objectiveDepartmentId: string | null,
453	    principal: RbacPrincipal | undefined,
454	  ): string {
455	    const departmentId = this.requireOwnedDepartmentId(principal);
456	    if (objectiveDepartmentId !== departmentId) {
457	      throw new ForbiddenException('Bạn chỉ sửa được mục tiêu của phòng ban mình');
458	    }
459	    return departmentId;
460	  }
461	
462	  private assertCanRead(
463	    objectiveDepartmentId: string | null,
464	    principal: RbacPrincipal | undefined,
465	  ): void {
466	    if (this.isKpiAdmin(principal)) return;
467	    // departmentId = null là mục tiêu dùng chung, không thuộc phòng nào → ai cũng xem được.
468	    if (objectiveDepartmentId === null) return;
469	    if (objectiveDepartmentId !== (principal?.departmentId ?? null)) {
470	      throw new ForbiddenException('Bạn chỉ xem được mục tiêu của phòng ban mình');
471	    }
472	  }
473	
474	  /** Admin thấy tất cả; các vai khác chỉ thấy phòng mình + mục tiêu dùng chung. */
475	  private visibilityWhere(principal: RbacPrincipal | undefined): Prisma.KpiTemplateWhereInput {
476	    if (this.isKpiAdmin(principal)) return {};
477	    const departmentId = principal?.departmentId ?? null;
478	    return departmentId
479	      ? { OR: [{ departmentId }, { departmentId: null }] }
480	      : { departmentId: null };
481	  }
