private requireOwnedDepartmentId(principal: RbacPrincipal | undefined): string {
  const departmentId = this.resolveOwnedDepartmentId(principal);
  if (!departmentId) {
    throw new ForbiddenException(
      'Chỉ quản lý phòng ban được tạo/sửa mục tiêu KPI của phòng mình',
    );
  }
  return departmentId;
}

/** Trả về phòng ban của người dùng để dùng tiếp cho `toView`. */
private assertCanManage(
  objectiveDepartmentId: string | null,
  principal: RbacPrincipal | undefined,
): string {
  const departmentId = this.requireOwnedDepartmentId(principal);
  if (objectiveDepartmentId !== departmentId) {
    throw new ForbiddenException('Bạn chỉ sửa được mục tiêu của phòng ban mình');
  }
  return departmentId;
}

private assertCanRead(
  objectiveDepartmentId: string | null,
  principal: RbacPrincipal | undefined,
): void {
  if (this.isKpiAdmin(principal)) return;
  // departmentId = null là mục tiêu dùng chung, không thuộc phòng nào → ai cũng xem được.
  if (objectiveDepartmentId === null) return;
  if (objectiveDepartmentId !== (principal?.departmentId ?? null)) {
    throw new ForbiddenException('Bạn chỉ xem được mục tiêu của phòng ban mình');
  }
}

/** Admin thấy tất cả; các vai khác chỉ thấy phòng mình + mục tiêu dùng chung. */
private visibilityWhere(principal: RbacPrincipal | undefined): Prisma.KpiTemplateWhereInput {
  if (this.isKpiAdmin(principal)) return {};
  const departmentId = principal?.departmentId ?? null;
  return departmentId
    ? { OR: [{ departmentId }, { departmentId: null }] }
    : { departmentId: null };
}

private isKpiAdmin(principal: RbacPrincipal | undefined): boolean {
  return principal?.permissions.has(PERMISSIONS.KPI_ADMIN) === true;
}

private toCriteriaData(
  tenantId: string,
  templateId: string,
  input: KpiCriteriaCreateInput,
  sortOrder: number,
) {
  /*
    Chỉ tiêu ĐẠT/KHÔNG ĐẠT có hình dạng cố định, không để người dùng chọn:
      · không đơn vị đo
      · gộp theo tỷ lệ (số lần đạt / số lần kiểm) — không phải cộng dồn
      · giao nguyên cho từng người (không chia phần được một giá trị boolean)
      · không có cấu hình chấm
    Chuẩn hoá ngay tại đây thay vì tin vào FE: API là biên, không phải form.
  */
  if (input.kind === 'PASS_FAIL') {
    return {
      tenantId,
      templateId,
      name: input.name,
      description: input.description ?? null,
      csf: input.csf ?? null,
      // Nguồn số liệu GIỮ LẠI: check hằng ngày là ứng viên số một cho tự động hoá.
      sourceType: input.sourceType,
      dataSourceId: input.dataSourceId ?? null,
      formula: input.formula ?? null,
      direction: 'INCREASE' as const,
      allocationMode: 'INHERIT' as const,
      aggregation: 'AVG' as const,
      isCombined: false,
      isBlocking: input.isBlocking,
      kind: input.kind,
      scoringShape: 'UP' as const,
      scoringMethod: 'CONTINUOUS' as const,
      measureType: 'RATIO' as const,
      scoringConfig: Prisma.JsonNull,
      unit: null,
      sortOrder,
    };
  }

  return {
    tenantId,
    templateId,
    name: input.name,
    description: input.description ?? null,
    csf: input.csf ?? null,
    sourceType: input.sourceType,
    dataSourceId: input.dataSourceId ?? null,
    formula: input.formula ?? null,
    direction: input.direction,
    allocationMode: input.allocationMode,
    aggregation: input.aggregation,
    isCombined: input.isCombined,
    isBlocking: input.isBlocking,
    kind: input.kind,
    // Bỏ trống ⇒ để cột DB tự điền @default (UP/CONTINUOUS/ADDITIVE).
    scoringShape: input.scoringShape,
    scoringMethod: input.scoringMethod,
    measureType: input.measureType,
    scoringConfig:
      input.scoringConfig === undefined
        ? Prisma.JsonNull
        : (input.scoringConfig as Prisma.InputJsonValue),
    unit: input.unit,
    sortOrder,
  };
}

