async addCriteria(
  objectiveId: string,
  input: KpiCriteriaCreateInput,
  principal: RbacPrincipal | undefined,
): Promise<KpiObjectiveView> {
  const objective = await this.requireObjective(objectiveId);
  const departmentId = this.assertCanManage(objective.departmentId, principal);
  const nextSortOrder =
    input.sortOrder ??
    objective.criteria.reduce((max, row) => Math.max(max, row.sortOrder + 1), 0);

  await this.prisma.scoped.kpiTemplateCriteria.create({
    data: this.toCriteriaData(this.tenantId(), objectiveId, input, nextSortOrder),
  });

  const after = this.toView(await this.requireObjective(objectiveId), departmentId);
  await this.audit.record({
    action: 'kpi.criteria.create',
    entity: 'KpiTemplateCriteria',
    entityId: objectiveId,
    after,
  });
  return after;
}

