import { Controller, Get } from '@nestjs/common';
import { PERMISSIONS } from '@ics/shared';
import { RequirePermission } from '../common/require-permission.decorator';
import { kpiSelectableDataSources, type KpiOwnerScope } from './kpi-data-sources';

/** Một nguồn dữ liệu, phần hiện ra cho người khai chỉ tiêu. */
export type KpiDataSourceView = {
  id: string;
  name: string;
  description: string;
  unit: string;
  /** Cột ngày quyết định bản ghi thuộc kỳ nào. */
  periodBasis: string;
  /** Cột xác định "của ai". */
  ownerBasis: string;
  ownerScope: KpiOwnerScope;
};

/**
 * Danh mục nguồn dữ liệu để chọn khi khai chỉ tiêu.
 *
 * CHỈ trả nguồn RAW. Nguồn DERIVED (tỷ lệ/trung bình dựng sẵn) vẫn tồn tại cho
 * trang chủ nhưng không được làm chỉ tiêu KPI: chúng không gộp nhiều kỳ con lên
 * cả năm được — xem chú thích đầu `kpi-data-sources.ts`.
 *
 * Không đụng DB nên không có service riêng: đây là hằng số của mã nguồn, và một
 * lớp service chỉ để `return` lại danh sách là tầng thừa.
 */
@Controller('kpi/data-sources')
export class KpiDataSourceController {
  @Get()
  @RequirePermission(PERMISSIONS.KPI_READ)
  list(): KpiDataSourceView[] {
    return kpiSelectableDataSources().map((source) => ({
      id: source.id,
      name: source.name,
      description: source.description,
      unit: source.defaultUnit,
      periodBasis: source.periodBasis,
      ownerBasis: source.ownerBasis,
      ownerScope: source.ownerScope,
    }));
  }
}

