export type MetricSlotView = {
  slotIndex: number;
  /** % của mục tiêu cả kỳ — chỉ dòng PHÒNG BAN của loại có lưới mốc. */
  targetPercent: number | null;
  /** Mục tiêu của kỳ con, đã quy ra đơn vị đo. */
  targetValue: number | null;
  actualValue: number | null;
  /** Backend chấm sẵn ở cấp kỳ con — frontend không tính lại. */
  percent: number | null;
};

/**
 * Kết quả ĐÃ GỘP của một cửa sổ thời gian thô hơn nhịp của chỉ tiêu.
 *
 * Cho phép người xem chọn "theo Quý" mà vẫn thấy con số thật của quý đó dù chỉ
 * tiêu chia theo tuần. Chỉ sinh cho nhịp THÔ HƠN nhịp của chỉ tiêu; nhịp bằng
 * hoặc mịn hơn đã có ở `slots`.
 */
export type MetricRollupView = {
  cadence: KpiCadence;
  slotIndex: number;
  targetValue: number | null;
  actualValue: number | null;
  percent: number | null;
};

export type AllocationItemView = {
  id: string;
  employeeId: string;
  employeeName: string;
  positionName: string;
  targetValue: number;
  /** Phần trăm của mục tiêu phòng ban — nguồn sự thật của phân bổ (chế độ DIVIDE). */
  allocationPercent: number | null;
  actualValue: number | null;
  percent: number | null;
  /** Phần này giao cho CHÍNH người đang xem — UI làm nổi bật và đẩy lên đầu. */
  isMine: boolean;
  /** Người đang xem có được nhập kết quả cho dòng này không. */
  canEnterActual: boolean;
  /** Kết quả theo kỳ con của riêng người này — rỗng khi chỉ tiêu không chia kỳ. */
  slots: MetricSlotView[];
  /** Kết quả đã gộp theo từng cửa sổ thô hơn — xem `MetricRollupView`. */
  rollups: MetricRollupView[];
};

export type DeptMetricView = {
  id: string;
  criteriaId: string | null;
  objectiveId: string | null;
  /** Tên mục tiêu chứa chỉ tiêu này — UI hiện thành badge. */
  objectiveTitle: string | null;
  csf: string | null;
  name: string;
  /** NULL với chỉ tiêu đạt/không đạt — loại đó không có đơn vị đo. */
  unit: string | null;
  targetValue: number;
  actualValue: number | null;
  weight: number;
  direction: 'INCREASE' | 'DECREASE';
  allocationMode: 'DIVIDE' | 'INHERIT';
  aggregation: 'SUM' | 'AVG' | 'LAST';
  isBlocking: boolean;
  /** Cách đo: có mục tiêu số hay chỉ đạt/không đạt. */
  kind: 'MEASURED' | 'PASS_FAIL';
  /** Mô hình chấm điểm (snapshot) — chỉ có nghĩa với MEASURED. */
  scoringShape: 'UP' | 'DOWN' | 'RANGE';
  scoringMethod: 'CONTINUOUS' | 'DISCRETE';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  /** Nhịp chia kỳ con. `PERIOD` ⇒ không chia, `slots` rỗng. */
  cadence: KpiCadence;
  /** Cấu hình chấm CỦA KỲ (đã gộp bảng dùng chung + bảng riêng) — UI prefill khi sửa. */
  scoringConfig: KpiScoringConfig | null;
  /** Backend tính sẵn — frontend KHÔNG tính lại. */
  percent: number | null;
  allocation: ReturnType<typeof allocationSummary> & {
    items: AllocationItemView[];
    /** Tổng phần trăm đã giao — chưa đủ 100% chỉ là cảnh báo, không chặn gì. */
    allocatedPercent: number;
  };
  /**
   * Lưới kỳ con của PHÒNG BAN: mốc mục tiêu + kết quả đã gộp từ những người được
   * giao. Rỗng khi `cadence = PERIOD`.
   */
  slots: MetricSlotView[];
  /** Kết quả đã gộp theo từng cửa sổ thô hơn — xem `MetricRollupView`. */
  rollups: MetricRollupView[];
  /** Luôn false: số của phòng ban đến từ phần đã giao, không nhập tay. */
  canEnterActual: boolean;
};

export type PlanAspectView = {
  aspect: KpiAspect;
  aspectWeight: number;
  metrics: DeptMetricView[];
  totalCriteriaWeight: number;
  isWeightComplete: boolean;
};

/**
 * ĐIỂM TỔNG HỢP của một cửa sổ thời gian.
 *
 * Chấm sẵn cho MỌI cửa sổ người xem chọn được (`KPI_VIEW_CADENCES` × số kỳ), y
 * như `rollups` của từng chỉ tiêu. Lý do giống hệt: đổi kỳ xem là thao tác trong
 * tích tắc trên một màn hình chỉ tải một lần, nên con số phải có sẵn — gọi lại
 * backend mỗi lần bấm thì cái toggle "xem điểm" biến thành cái vòng quay.
 */
export type ScoreWindowView = ScoreWithCoverage & {
  cadence: KpiCadence;
  slotIndex: number;

