 * cần: ai (tài khoản của nhân viên), kỳ nào (nhịp của chính dòng đó), ô nào đã chốt.
 *
 * Trả về map RỖNG khi kế hoạch không có dòng tự động nào — đường đi thường gặp
 * nhất, và nó không tốn thêm một truy vấn nào.
 */
private async resolveAutoValues(
  plan: { id: string; periodYear: number; departmentId: string },
  metrics: ReadonlyArray<
    MetricSource & {
      id: string;
      level: 'DEPARTMENT' | 'INDIVIDUAL';
      kind: 'MEASURED' | 'PASS_FAIL';
      cadence: KpiCadence;
      parentMetricId: string | null;
      actualValue: Prisma.Decimal | null;
      autoSyncedAt: Date | null;
      planTarget: { employee: { userId: string | null } | null } | null;
    }
  >,
  slotsByMetric: ReadonlyMap<
    string,
    ReadonlyMap<number, { actualValue: number | null; autoFrozen?: boolean }>
  >,
) {
  const autoMetrics = metrics.filter((metric) => isAutoSourced(metric));
  if (!autoMetrics.length) return new Map<string, never[]>();

  const parentIds = new Set(
    metrics.map((metric) => metric.parentMetricId).filter((id): id is string => Boolean(id)),
  );

  /*
    Dòng phòng ban CHƯA giao cho ai vẫn cần số — và phạm vi của nó là cả phòng.
    Nạp một lần ở đây thay vì trong service phân giải: `Employee` là bảng của
    module nhân sự, giữ mọi truy vấn của kế hoạch ở cùng một chỗ dễ lần hơn.
  */
  const needsDepartmentScope = autoMetrics.some(
    (metric) => metric.level === 'DEPARTMENT' && !parentIds.has(metric.id),
  );
  const departmentUserIds = needsDepartmentScope
    ? (
        await this.prisma.scoped.employee.findMany({
          where: { departmentId: plan.departmentId, deletedAt: null, userId: { not: null } },
          select: { userId: true },
        })
      ).map((row) => row.userId as string)
    : [];

  const existingSlots = new Map(
    [...slotsByMetric].map(([metricId, bucket]) => [
      metricId,
      [...bucket].map(([slotIndex, slot]) => ({
        slotIndex,
        actualValue: slot.actualValue,
        // `slotsByMetric` lúc này mới chỉ chứa dữ liệu ĐỌC TỪ DB, nên `autoFrozen`
        // phản ánh đúng cột `autoSyncedAt` chứ chưa lẫn số vừa tính sống.
        autoSyncedAt: slot.autoFrozen ? new Date() : null,
      })),
    ]),
  );

  const inputs: AutoMetricInput[] = autoMetrics.map((metric) => ({
    id: metric.id,
    level: metric.level,
    kind: metric.kind,
    cadence: metric.cadence,
    sourceType: metric.sourceType,
    dataSourceId: metric.dataSourceId,
    formula: metric.formula,
    autoSyncedAt: metric.autoSyncedAt,
    actualValue: toNullableNumber(metric.actualValue),
    ownerUserId: metric.planTarget?.employee?.userId ?? null,
    hasChildren: parentIds.has(metric.id),
  }));

  return this.metricSource.resolveForPlan({
    plan,
    metrics: inputs,
    existingSlots,
    departmentUserIds,
    now: new Date(),
  });
}

