import type {
  KpiAllocationCreateInput,
  KpiAllocationUpdateInput,
  KpiAspectWeightUpsertInput,
  KpiCriteriaCreateInput,
  KpiCriteriaUpdateInput,
  KpiDeptMetricCreateInput,
  KpiDeptMetricUpdateInput,
  KpiObjectiveCreateInput,
  KpiObjectiveUpdateInput,
  KpiActualBulkUpdateInput,
  KpiActualEntryInput,
  KpiPlanCreateInput,
  KpiPlanStatusInput,
  KpiWeightScope,
} from '@ics/shared';
import { BffError, bffJson } from '@/lib/bff-json';
import type {
  KpiAspectWeightOverview,
  KpiAspectWeightSet,
  KpiObjective,
  KpiObjectiveContext,
  KpiPlanContext,
  KpiPlanDetail,
  KpiPlanListItem,
} from '../model/kpi.types';

/** Dùng `bffJson` dùng chung — không dựng wrapper HTTP riêng cho feature. */

// ── Tỷ trọng trụ cột ────────────────────────────────────────

export function getAspectWeights(query: {
  scope: KpiWeightScope;
  departmentId?: string | null;
  periodYear: number;
}) {
  const params = new URLSearchParams({
    scope: query.scope,
    periodYear: String(query.periodYear),
  });
  if (query.departmentId) params.set('departmentId', query.departmentId);
  return bffJson<KpiAspectWeightSet>(`/kpi/aspect-weights?${params.toString()}`);
}

/** Dữ liệu dashboard: tỷ trọng công ty + phòng ban được xem + quyền sửa. */
export function getAspectWeightOverview(periodYear?: number) {
  const search = periodYear ? `?periodYear=${periodYear}` : '';
  return bffJson<KpiAspectWeightOverview>(`/kpi/aspect-weights/overview${search}`);
}

export const saveAspectWeights = (body: KpiAspectWeightUpsertInput) =>
  bffJson<KpiAspectWeightSet>('/kpi/aspect-weights', {
    method: 'PUT',
    body: JSON.stringify(body),
  });

// ── Mục tiêu (Key Objective) & chỉ tiêu (KPI) ───────────────

/** Quyền của người dùng trên thư viện mục tiêu — dùng để hiện/ẩn nút tạo. */
export const getObjectiveContext = () => bffJson<KpiObjectiveContext>('/kpi/objectives/context');

export function listObjectives(
  query: { query?: string; aspect?: string; departmentId?: string } = {},
) {
  const params = new URLSearchParams();
  if (query.query) params.set('query', query.query);
  if (query.aspect) params.set('aspect', query.aspect);
  if (query.departmentId) params.set('departmentId', query.departmentId);
  const search = params.toString();
  return bffJson<KpiObjective[]>(`/kpi/objectives${search ? `?${search}` : ''}`);
}

export const getObjective = (id: string) =>
  bffJson<KpiObjective>(`/kpi/objectives/${encodeURIComponent(id)}`);

export const createObjective = (body: KpiObjectiveCreateInput) =>
  bffJson<KpiObjective>('/kpi/objectives', { method: 'POST', body: JSON.stringify(body) });

export const updateObjective = (id: string, body: KpiObjectiveUpdateInput) =>
  bffJson<KpiObjective>(`/kpi/objectives/${encodeURIComponent(id)}`, {
    method: 'PATCH',
    body: JSON.stringify(body),
  });

export const deleteObjective = (id: string) =>
  bffJson<void>(`/kpi/objectives/${encodeURIComponent(id)}`, { method: 'DELETE' });

export const addCriteria = (objectiveId: string, body: KpiCriteriaCreateInput) =>
  bffJson<KpiObjective>(`/kpi/objectives/${encodeURIComponent(objectiveId)}/criteria`, {
    method: 'POST',
    body: JSON.stringify(body),
  });

export const updateCriteria = (
  objectiveId: string,
  criteriaId: string,
  body: KpiCriteriaUpdateInput,
) =>
  bffJson<KpiObjective>(
    `/kpi/objectives/${encodeURIComponent(objectiveId)}/criteria/${encodeURIComponent(criteriaId)}`,
    { method: 'PATCH', body: JSON.stringify(body) },
  );

export const deleteCriteria = (objectiveId: string, criteriaId: string) =>
  bffJson<KpiObjective>(
    `/kpi/objectives/${encodeURIComponent(objectiveId)}/criteria/${encodeURIComponent(criteriaId)}`,
    { method: 'DELETE' },
  );

// ── Phân loại lỗi (dùng `code`/`status` của BffError, không so khớp chuỗi) ──

export const isForbidden = (error: unknown): error is BffError =>
  error instanceof BffError && error.status === 403;

/** 409 = đang được dùng trong kế hoạch KPI nên không xoá được. */
export const isConflict = (error: unknown): error is BffError =>
  error instanceof BffError && error.status === 409;

export const errorMessage = (error: unknown, fallback: string): string =>
  error instanceof Error && error.message ? error.message : fallback;

// ── Kế hoạch KPI phòng ban (Luồng A) ────────────────────────────

/** Quyền trên danh sách kế hoạch — dùng để hiện/ẩn nút lập kế hoạch. */
export const getPlanContext = () => bffJson<KpiPlanContext>('/kpi/plans/context');

export function listPlans(
  query: { departmentId?: string; periodYear?: number; status?: string } = {},
) {
  const params = new URLSearchParams();
  if (query.departmentId) params.set('departmentId', query.departmentId);
  if (query.periodYear) params.set('periodYear', String(query.periodYear));
  if (query.status) params.set('status', query.status);
  const search = params.toString();
  return bffJson<KpiPlanListItem[]>(`/kpi/plans${search ? `?${search}` : ''}`);
}

export const getPlan = (id: string) =>
  bffJson<KpiPlanDetail>(`/kpi/plans/${encodeURIComponent(id)}`);

export const createPlan = (body: KpiPlanCreateInput) =>
  bffJson<KpiPlanDetail>('/kpi/plans', { method: 'POST', body: JSON.stringify(body) });

export const deletePlan = (id: string) =>
  bffJson<void>(`/kpi/plans/${encodeURIComponent(id)}`, { method: 'DELETE' });

