export const changePlanStatus = (id: string, body: KpiPlanStatusInput) =>
  bffJson<KpiPlanDetail>(`/kpi/plans/${encodeURIComponent(id)}/status`, {
    method: 'POST',
    body: JSON.stringify(body),
  });

export const addDeptMetric = (planId: string, body: KpiDeptMetricCreateInput) =>
  bffJson<KpiPlanDetail>(`/kpi/plans/${encodeURIComponent(planId)}/metrics`, {
    method: 'POST',
    body: JSON.stringify(body),
  });

export const updateDeptMetric = (
  planId: string,
