) =>
  bffJson<KpiPlanDetail>(
    `/kpi/plans/${encodeURIComponent(planId)}/metrics/${encodeURIComponent(metricId)}`,
    { method: 'PATCH', body: JSON.stringify(body) },
  );

/** Nhập kết quả thực tế cho một chỉ tiêu (cấp phòng ban hoặc phần đã giao). */
export const updateActual = (planId: string, body: KpiActualEntryInput) =>
  bffJson<KpiPlanDetail>(`/kpi/plans/${encodeURIComponent(planId)}/actuals`, {
    method: 'PATCH',
    body: JSON.stringify(body),
