  bffJson<KpiPlanDetail>(`/kpi/plans/${encodeURIComponent(planId)}/actuals/bulk`, {
    method: 'PATCH',
    body: JSON.stringify(body),
  });

export const removeDeptMetric = (planId: string, metricId: string) =>
  bffJson<KpiPlanDetail>(
    `/kpi/plans/${encodeURIComponent(planId)}/metrics/${encodeURIComponent(metricId)}`,
    { method: 'DELETE' },
  );

// ── Phân bổ cho cá nhân (Luồng B) ───────────────────────────

export const allocateMetric = (body: KpiAllocationCreateInput) =>
  bffJson<KpiPlanDetail>('/kpi/allocations', {
    method: 'POST',
    body: JSON.stringify(body),
  });

export const updateAllocation = (id: string, body: KpiAllocationUpdateInput) =>
  bffJson<KpiPlanDetail>(`/kpi/allocations/${encodeURIComponent(id)}`, {
    method: 'PATCH',
    body: JSON.stringify(body),
  });

