'use client';

import { Plus, Trash2 } from 'lucide-react';
import type { KpiScoreBand } from '@ics/shared';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

/**
 * Một dòng của bảng khoảng, giữ dạng CHUỖI để nhập liệu mượt (cho phép ô trống
 * = vô cực). Quy đổi sang số chỉ xảy ra lúc submit.
 */
export type BandRow = { from: string; to: string; score: string };

export const EMPTY_BAND: BandRow = { from: '', to: '', score: '' };

/**
 * Khởi đầu bằng MỘT khoảng phủ toàn bộ (hợp lệ ngay), người dùng bấm "Thêm
 * khoảng" để dựng thang.
 *
 * Không đặt sẵn mốc số: cận là giá trị thô cùng đơn vị với mục tiêu, mà lúc dựng
 * form thì chưa biết mục tiêu lẫn đơn vị — đặt bừa 80/100 là gợi ý sai.
 */
export const DEFAULT_BANDS: BandRow[] = [{ from: '', to: '', score: '100' }];

const parseNum = (value: string): number | null => {
  const trimmed = value.trim();
  if (trimmed === '') return null;
  const parsed = Number(trimmed);
  return Number.isFinite(parsed) ? parsed : null;
};

/** Đổi các dòng đang nhập thành payload API. Ô trống ⇒ `null` = mở vô cực. */
export function toBandPayload(rows: BandRow[]): KpiScoreBand[] {
  return rows.map((row) => ({
    from: parseNum(row.from),
    to: parseNum(row.to),
    score: parseNum(row.score) ?? 0,
  }));
}

