const [objectiveId, setObjectiveId] = useState('');
const [submitting, setSubmitting] = useState(false);
const [error, setError] = useState<string | null>(null);
const [dataSources, setDataSources] = useState<KpiDataSource[]>([]);
const [sourcesLoading, setSourcesLoading] = useState(false);
const needObjective = objectives !== undefined;

/*
  Danh mục nguồn là hằng số của backend nên nạp MỘT LẦN rồi giữ lại: mở/đóng
  form nhiều lần trong một phiên không cần gọi lại. Nạp ngay khi mở (không đợi
  người dùng chọn "lấy tự động") để lúc họ chọn thì danh sách đã sẵn.
*/
useEffect(() => {
  if (!open || dataSources.length || sourcesLoading) return;
  let cancelled = false;
  setSourcesLoading(true);
  listKpiDataSources()
    .then((rows) => {
      if (!cancelled) setDataSources(rows);
    })
    // Nuốt lỗi ở đây là cố ý: form vẫn dùng được cho chỉ tiêu nhập tay, và
    // `KpiSourceFields` đã có thông báo riêng cho trường hợp danh mục rỗng.
    .catch(() => undefined)
    .finally(() => {
      if (!cancelled) setSourcesLoading(false);
    });
  return () => {
    cancelled = true;
  };
}, [open, dataSources.length, sourcesLoading]);

