import { describe, expect, it } from 'vitest';
import {
  evaluateKpiFormula,
  parseKpiFormula,
  runKpiFormula,
  validateKpiFormula,
} from './kpi-formula.js';

const SOURCES = ['sales.opportunities_won', 'sales.opportunities_created', 'tasks.completed'];

describe('parseKpiFormula', () => {
  it('trả về danh sách nguồn đã khử trùng lặp', () => {
    const parsed = parseKpiFormula(
      '[sales.opportunities_won] / [sales.opportunities_created] * 100',
    );
    expect(parsed.ok).toBe(true);
    if (!parsed.ok) return;
    expect(parsed.refs).toEqual(['sales.opportunities_won', 'sales.opportunities_created']);
  });

  it('không đếm hai lần khi một nguồn xuất hiện nhiều chỗ', () => {
    const parsed = parseKpiFormula('[tasks.completed] + [tasks.completed]');
    expect(parsed.ok && parsed.refs).toEqual(['tasks.completed']);
  });

  it('từ chối công thức toàn hằng số', () => {
    // Cho ra cùng một con số ở mọi kỳ, mọi người ⇒ gần như chắc chắn gõ nhầm.
    expect(parseKpiFormula('100 - 5')).toMatchObject({ ok: false });
  });

  it.each([
    ['[tasks.completed] +', 'thiếu toán hạng cuối'],
    ['[tasks.completed] * * 2', 'hai toán tử liền nhau'],
    ['([tasks.completed]', 'thiếu ngoặc đóng'],
    ['[tasks.completed])', 'thừa ngoặc đóng'],
    ['[tasks.completed', 'thiếu ngoặc vuông đóng'],
    ['[tasks.completed] [tasks.completed]', 'thiếu toán tử ở giữa'],
    ['[Tasks.Completed]', 'mã nguồn viết hoa'],
    ['[tasks.completed] & 2', 'ký tự lạ'],
  ])('từ chối %s (%s)', (source) => {
    expect(parseKpiFormula(source).ok).toBe(false);
  });

  it('KHÔNG thực thi mã — chuỗi JS hợp lệ vẫn bị từ chối', () => {
    // Nếu ở đâu đó lỡ dùng `eval` thì đây là chỗ nó lộ ra.
    expect(parseKpiFormula('process.exit(1)').ok).toBe(false);
    expect(parseKpiFormula('(() => 1)()').ok).toBe(false);
  });
});

describe('validateKpiFormula', () => {
  it('báo tên nguồn không có trong danh mục', () => {
    expect(validateKpiFormula('[sales.khong_co_that] * 2', SOURCES)).toContain(
      'sales.khong_co_that',
    );
  });

  it('chấp nhận công thức chỉ dùng nguồn có thật', () => {
    expect(validateKpiFormula('[tasks.completed] * 2', SOURCES)).toBeNull();
  });
});

describe('evaluateKpiFormula', () => {
  const run = (source: string, values: Record<string, number | null>) =>
    runKpiFormula(source, values);

  it('tính đúng thứ tự ưu tiên và ngoặc', () => {
    expect(run('[tasks.completed] + 2 * 3', { 'tasks.completed': 1 })).toBe(7);
    expect(run('([tasks.completed] + 2) * 3', { 'tasks.completed': 1 })).toBe(9);
  });

  it('hiểu dấu âm đứng đầu', () => {
    expect(run('-[tasks.completed]', { 'tasks.completed': 4 })).toBe(-4);
    expect(run('100 - 5 * [tasks.completed]', { 'tasks.completed': 3 })).toBe(85);
  });

  it('THIẾU SỐ thì trả null, không phải 0', () => {
    // Ép về 0 nghĩa là chỉ tiêu chưa có số bị chấm 0 điểm — cả module thống nhất
    // "chưa có số thì loại khỏi phép tính điểm", không phải trượt.
    expect(run('[tasks.completed] * 2', { 'tasks.completed': null })).toBeNull();
    expect(run('[tasks.completed] * 2', {})).toBeNull();
  });

  it('CHIA CHO 0 trả null', () => {
    // Tỷ lệ chuyển đổi khi trong kỳ chưa có cơ hội nào là "chưa đo được".
    const values = { 'sales.opportunities_won': 0, 'sales.opportunities_created': 0 };
    expect(run('[sales.opportunities_won] / [sales.opportunities_created] * 100', values)).toBeNull();
  });

  it('tính tỷ lệ đúng ở từng mức gộp, không trung bình các kỳ con', () => {
    /*
      Đây là lý do tỷ lệ phải là công thức trên hai nguồn thô thay vì một nguồn
      trả sẵn %. Q1 thắng 10/40 = 25%, Q2 thắng 30/60 = 50%. Trung bình hai quý ra
      37.5% — SAI. Số đúng của cả năm là 40/100 = 40%, và chỉ ra được khi tính lại
      từ tử số và mẫu số của cả năm.
    */
    const formula = '[sales.opportunities_won] / [sales.opportunities_created] * 100';
    const q1 = run(formula, {
      'sales.opportunities_won': 10,
      'sales.opportunities_created': 40,
    });
    const q2 = run(formula, {
      'sales.opportunities_won': 30,
      'sales.opportunities_created': 60,
    });
    const year = run(formula, {
      'sales.opportunities_won': 40,
      'sales.opportunities_created': 100,
    });

    expect(q1).toBe(25);
    expect(q2).toBe(50);
    expect(year).toBe(40);
    expect(year).not.toBe(((q1 as number) + (q2 as number)) / 2);
  });

  it('dùng lại được AST đã phân tích cho nhiều bộ giá trị', () => {
    const parsed = parseKpiFormula('[tasks.completed] * 2');
    expect(parsed.ok).toBe(true);
    if (!parsed.ok) return;
    expect(evaluateKpiFormula(parsed.ast, { 'tasks.completed': 3 })).toBe(6);
    expect(evaluateKpiFormula(parsed.ast, { 'tasks.completed': 5 })).toBe(10);
  });
});

