/** Kết quả cả kỳ của một dòng — ưu tiên số tự động, sau đó mới tới cột đã lưu. */
const actualValueOf = (metric: { id: string; actualValue: Prisma.Decimal | null }) =>
  autoPeriodValue.has(metric.id)
    ? (autoPeriodValue.get(metric.id) ?? null)
    : toNullableNumber(metric.actualValue);

