/*
  Danh mục nguồn là hằng số của backend nên nạp MỘT LẦN rồi giữ lại: mở/đóng
  form nhiều lần trong một phiên không cần gọi lại. Nạp ngay khi mở (không đợi
  người dùng chọn "lấy tự động") để lúc họ chọn thì danh sách đã sẵn.

  Cờ "đã gọi" phải là REF chứ không phải state, và deps chỉ có `open`.
  Để `sourcesLoading` vào deps thì effect tự huỷ chính nó: bật cờ loading ⇒
  deps đổi ⇒ cleanup chạy ⇒ lượt sau bị guard chặn ⇒ response về thì không còn
  ai nhận. Request vẫn thành công trên Network nhưng màn hình kẹt ở "Đang tải…".
*/
useEffect(() => {
  if (!open || sourcesRequested.current) return;
  sourcesRequested.current = true;
  setSourcesLoading(true);
  listKpiDataSources()
    .then(setDataSources)
    // Nuốt lỗi là cố ý: form vẫn dùng được cho chỉ tiêu nhập tay, và
    // `KpiSourceFields` đã có thông báo riêng cho trường hợp danh mục rỗng.
    // Mở cờ ra để lần mở form sau còn thử lại được.
    .catch(() => {
      sourcesRequested.current = false;
    })
    .finally(() => setSourcesLoading(false));
}, [open]);

