1	import { describe, expect, it } from 'vitest';
2	import {
3	  evaluateKpiFormula,
4	  parseKpiFormula,
5	  runKpiFormula,
6	  validateKpiFormula,
7	} from './kpi-formula.js';
8	
9	const SOURCES = ['sales.opportunities_won', 'sales.opportunities_created', 'tasks.completed'];
10	
11	describe('parseKpiFormula', () => {
12	  it('trả về danh sách nguồn đã khử trùng lặp', () => {
13	    const parsed = parseKpiFormula(
14	      '[sales.opportunities_won] / [sales.opportunities_created] * 100',
15	    );
16	    expect(parsed.ok).toBe(true);
17	    if (!parsed.ok) return;
18	    expect(parsed.refs).toEqual(['sales.opportunities_won', 'sales.opportunities_created']);
19	  });
20	
21	  it('không đếm hai lần khi một nguồn xuất hiện nhiều chỗ', () => {
22	    const parsed = parseKpiFormula('[tasks.completed] + [tasks.completed]');
23	    expect(parsed.ok && parsed.refs).toEqual(['tasks.completed']);
24	  });
25	
26	  it('từ chối công thức toàn hằng số', () => {
27	    // Cho ra cùng một con số ở mọi kỳ, mọi người ⇒ gần như chắc chắn gõ nhầm.
28	    expect(parseKpiFormula('100 - 5')).toMatchObject({ ok: false });
29	  });
30	
31	  it.each([
32	    ['[tasks.completed] +', 'thiếu toán hạng cuối'],
33	    ['[tasks.completed] * * 2', 'hai toán tử liền nhau'],
34	    ['([tasks.completed]', 'thiếu ngoặc đóng'],
35	    ['[tasks.completed])', 'thừa ngoặc đóng'],
36	    ['[tasks.completed', 'thiếu ngoặc vuông đóng'],
37	    ['[tasks.completed] [tasks.completed]', 'thiếu toán tử ở giữa'],
38	    ['[Tasks.Completed]', 'mã nguồn viết hoa'],
39	    ['[tasks.completed] & 2', 'ký tự lạ'],
40	  ])('từ chối %s (%s)', (source) => {
41	    expect(parseKpiFormula(source).ok).toBe(false);
42	  });
43	
44	  it('KHÔNG thực thi mã — chuỗi JS hợp lệ vẫn bị từ chối', () => {
45	    // Nếu ở đâu đó lỡ dùng `eval` thì đây là chỗ nó lộ ra.
46	    expect(parseKpiFormula('process.exit(1)').ok).toBe(false);
47	    expect(parseKpiFormula('(() => 1)()').ok).toBe(false);
48	  });
49	});
50	
51	describe('validateKpiFormula', () => {
52	  it('báo tên nguồn không có trong danh mục', () => {
53	    expect(validateKpiFormula('[sales.khong_co_that] * 2', SOURCES)).toContain(
54	      'sales.khong_co_that',
55	    );
56	  });
57	
58	  it('chấp nhận công thức chỉ dùng nguồn có thật', () => {
59	    expect(validateKpiFormula('[tasks.completed] * 2', SOURCES)).toBeNull();
60	  });
61	});
62	
63	describe('evaluateKpiFormula', () => {
64	  const run = (source: string, values: Record<string, number | null>) =>
65	    runKpiFormula(source, values);
66	
67	  it('tính đúng thứ tự ưu tiên và ngoặc', () => {
68	    expect(run('[tasks.completed] + 2 * 3', { 'tasks.completed': 1 })).toBe(7);
69	    expect(run('([tasks.completed] + 2) * 3', { 'tasks.completed': 1 })).toBe(9);
70	  });
71	
72	  it('hiểu dấu âm đứng đầu', () => {
73	    expect(run('-[tasks.completed]', { 'tasks.completed': 4 })).toBe(-4);
74	    expect(run('100 - 5 * [tasks.completed]', { 'tasks.completed': 3 })).toBe(85);
75	  });
76	
77	  it('THIẾU SỐ thì trả null, không phải 0', () => {
78	    // Ép về 0 nghĩa là chỉ tiêu chưa có số bị chấm 0 điểm — cả module thống nhất
79	    // "chưa có số thì loại khỏi phép tính điểm", không phải trượt.
80	    expect(run('[tasks.completed] * 2', { 'tasks.completed': null })).toBeNull();
81	    expect(run('[tasks.completed] * 2', {})).toBeNull();
82	  });
83	
84	  it('CHIA CHO 0 trả null', () => {
85	    // Tỷ lệ chuyển đổi khi trong kỳ chưa có cơ hội nào là "chưa đo được".
86	    const values = { 'sales.opportunities_won': 0, 'sales.opportunities_created': 0 };
87	    expect(
88	      run('[sales.opportunities_won] / [sales.opportunities_created] * 100', values),
89	    ).toBeNull();
90	  });
91	
92	  it('tính tỷ lệ đúng ở từng mức gộp, không trung bình các kỳ con', () => {
93	    /*
94	      Đây là lý do tỷ lệ phải là công thức trên hai nguồn thô thay vì một nguồn
95	      trả sẵn %. Q1 thắng 10/40 = 25%, Q2 thắng 30/60 = 50%. Trung bình hai quý ra
96	      37.5% — SAI. Số đúng của cả năm là 40/100 = 40%, và chỉ ra được khi tính lại
97	      từ tử số và mẫu số của cả năm.
98	    */
99	    const formula = '[sales.opportunities_won] / [sales.opportunities_created] * 100';
100	    const q1 = run(formula, {
101	      'sales.opportunities_won': 10,
102	      'sales.opportunities_created': 40,
103	    });
104	    const q2 = run(formula, {
105	      'sales.opportunities_won': 30,
106	      'sales.opportunities_created': 60,
107	    });
108	    const year = run(formula, {
109	      'sales.opportunities_won': 40,
110	      'sales.opportunities_created': 100,
111	    });
112	
113	    expect(q1).toBe(25);
114	    expect(q2).toBe(50);
115	    expect(year).toBe(40);
116	    expect(year).not.toBe(((q1 as number) + (q2 as number)) / 2);
117	  });
118	
119	  it('dùng lại được AST đã phân tích cho nhiều bộ giá trị', () => {
120	    const parsed = parseKpiFormula('[tasks.completed] * 2');
121	    expect(parsed.ok).toBe(true);
122	    if (!parsed.ok) return;
123	    expect(evaluateKpiFormula(parsed.ast, { 'tasks.completed': 3 })).toBe(6);
124	    expect(evaluateKpiFormula(parsed.ast, { 'tasks.completed': 5 })).toBe(10);
125	  });
126	});

1	import { Injectable } from '@nestjs/common';
2	import { Prisma } from '@prisma/client';
3	import {
4	  evaluateKpiFormula,
5	  parseKpiFormula,
6	  slotCount,
7	  slotKey,
8	  slotRange,
9	  type KpiCadence,
10	} from '@ics/shared';
11	import { PrismaService } from '../common/prisma.service';
12	import { TenantContextService } from '../common/tenant-context.service';
13	import { findKpiDataSource, type KpiPeriod } from './kpi-data-sources';
14	
15	/**
16	 * Điền SỐ THỰC TẾ cho các chỉ tiêu lấy dữ liệu tự động.
17	 *
18	 * ── HAI CHẾ ĐỘ, RANH GIỚI LÀ KỲ CON ĐÃ KẾT THÚC CHƯA ──────────────────────────
19	 *
20	 *   Kỳ con ĐANG CHẠY   Tính lại mỗi lần đọc, KHÔNG ghi DB. Người ta mở trang KPI
21	 *                      chính là để hỏi "giờ tôi được bao nhiêu rồi" — bắt bấm nút
22	 *                      "Đồng bộ" hay chờ cron đêm đều trả lời sai câu hỏi đó.
23	 *
24	 *   Kỳ con ĐÃ XONG     Lượt đọc đầu tiên sau khi hết hạn ân hạn sẽ tính MỘT LẦN
25	 *                      rồi ghi xuống kèm `autoSyncedAt`. Từ đó con số đứng yên
26	 *                      vĩnh viễn.
27	 *
28	 * Vì sao phải đóng băng: không đóng thì số của quá khứ vẫn đổi. Tháng 8 có người
29	 * sửa lại một cơ hội của quý 1 là điểm KPI quý 1 — đã duyệt lương — tự đổi theo,
30	 * và không có gì để giải thích với nhân viên. Đây cũng là lý do `KpiPlanStatus`
31	 * có trạng thái đã chốt: kỳ chốt rồi thì bất biến.
32	 *
33	 * Cách này không cần cron và không cần nút bấm: ai mở trang đầu tiên sau khi kỳ
34	 * con kết thúc thì chính lượt đọc đó chốt số.
35	 */
36	
37	/**
38	 * Ân hạn trước khi đóng băng một kỳ con đã hết.
39	 *
40	 * Hợp đồng ký 28/6 rất hay được nhập liệu ngày 3/7. Đóng băng ngay 00:00 ngày đầu
41	 * kỳ sau là chốt mất phần doanh thu chưa kịp vào sổ.
42	 */
43	const FREEZE_GRACE_DAYS = 5;
44	
45	/**
46	 * Trần số lượt TÍNH MỚI trong một lần đọc.
47	 *
48	 * Chỉ tiêu đạt/không đạt được phép chia theo NGÀY, nên một kế hoạch bỏ quên nửa
49	 * năm có thể cần đóng băng hàng trăm ô cùng lúc — đủ để một request treo. Chặn
50	 * lại ở đây; phần còn lại được đóng băng dần ở các lượt đọc sau, cũ trước mới
51	 * sau. Không mất dữ liệu, chỉ là chốt chậm vài lượt.
52	 */
53	const MAX_RESOLVES_PER_READ = 90;
54	
55	/** Một ô kết quả do nguồn tự động điền. */
56	export interface AutoSlotValue {
57	  /** Chỉ tiêu không chia kỳ con dùng khoá 0 — đại diện cho "cả kỳ". */
58	  slotIndex: number;
59	  value: number | null;
60	  /** Đã chốt (đọc từ DB hoặc vừa ghi trong lượt này) hay đang tính sống. */
61	  frozen: boolean;
62	}
63	
64	/** Chỉ tiêu cần phân giải — đúng những trường cần, không kéo cả dòng. */
65	export interface AutoMetricInput {
66	  id: string;
67	  level: 'DEPARTMENT' | 'INDIVIDUAL';
68	  kind: 'MEASURED' | 'PASS_FAIL';
69	  cadence: KpiCadence;
70	  sourceType: 'MANUAL' | 'EXISTING' | 'FORMULA';
71	  dataSourceId: string | null;
72	  formula: string | null;
73	  /** Mốc đóng băng của con số CẢ KỲ (chỉ dùng khi `cadence = PERIOD`). */
74	  autoSyncedAt: Date | null;
75	  /** Giá trị cả kỳ đang lưu — dùng lại khi đã đóng băng. */
76	  actualValue: number | null;
77	  /** Người của dòng cá nhân. `null` ở dòng phòng ban. */
78	  ownerUserId: string | null;
79	  /** Dòng phòng ban đã giao cho ai chưa — đã giao thì số của phòng là gộp từ con. */
80	  hasChildren: boolean;
81	}
82	
83	/** Ô kỳ con đang lưu trong DB, để biết ô nào đã chốt. */
84	export interface ExistingSlot {
85	  slotIndex: number;
86	  actualValue: number | null;
87	  autoSyncedAt: Date | null;
88	}
89	
90	export interface ResolvePlanInput {
91	  plan: { id: string; periodYear: number };
92	  metrics: readonly AutoMetricInput[];
93	  /** metricId → các ô kỳ con đang có trong DB. */
94	  existingSlots: ReadonlyMap<string, readonly ExistingSlot[]>;
95	  /** Danh sách người của phòng — dùng cho dòng phòng ban chưa giao cho ai. */
96	  departmentUserIds: readonly string[];
97	  now: Date;
98	}
99	
100	/** Một lượt truy vấn gộp: một nguồn × một khoảng thời gian × một tập người. */
101	interface BatchJob {
102	  sourceId: string;
103	  period: KpiPeriod;
104	  owners: Set<string>;
105	  /** Có dòng nào cần số KHÔNG lọc theo người (nguồn không tách được theo người). */
106	  needsTenantWide: boolean;
107	}
108	
109	@Injectable()
110	export class KpiMetricSourceService {
111	  constructor(
112	    private readonly prisma: PrismaService,
113	    private readonly tenant: TenantContextService,
114	  ) {}
115	
116	  /**
117	   * Phân giải toàn bộ chỉ tiêu tự động của một kế hoạch.
118	   *
119	   * Trả `metricId → các ô đã điền`. Chỉ tiêu nhập tay không xuất hiện trong kết quả.
120	   */
121	  async resolveForPlan(input: ResolvePlanInput): Promise<Map<string, AutoSlotValue[]>> {
122	    const targets = this.collectTargets(input);
123	    if (!targets.length) return new Map();
124	
125	    const jobs = this.planBatchJobs(targets);
126	    const readings = await this.runBatchJobs(jobs);
127	    const result = this.composeValues(targets, readings);
128	
129	    await this.freeze(input.plan, targets, result);
130	    return result;
131	  }
132	
133	  // ─────────────────────────────────────────────────────────────
134	  // 1. Xác định phải tính những ô nào
135	  // ─────────────────────────────────────────────────────────────
136	
137	  /** Một ô cụ thể cần tính (hoặc đã có sẵn vì đã chốt). */
138	  private collectTargets(input: ResolvePlanInput): ResolveTarget[] {
139	    const targets: ResolveTarget[] = [];
140	    let budget = MAX_RESOLVES_PER_READ;
141	
142	    for (const metric of input.metrics) {
143	      const sources = this.sourcesOf(metric);
144	      if (!sources) continue;
145	
146	      /*
147	        Dòng phòng ban ĐÃ GIAO cho cá nhân thì không tự lấy số: kết quả của phòng
148	        được gộp từ phần đã giao (`rollUpAllocatedActual`). Tự lấy thêm ở đây là
149	        có hai nguồn sự thật trên cùng một dòng, và chúng sẽ lệch nhau.
150	      */
151	      if (metric.level === 'DEPARTMENT' && metric.hasChildren) continue;
152	
153	      const owners =
154	        metric.level === 'INDIVIDUAL'
