import { PrismaService } from './src/common/prisma.service';
import { KPI_DATA_SOURCES } from './src/kpi/kpi-data-sources';
import { PrismaClient } from '@prisma/client';

async function main() {
  const raw = new PrismaClient();
  const tenant = (await raw.tenant.findFirst({ select: { id: true } }))!;
  const users = await raw.user.findMany({ where: { deletedAt: null }, select: { id: true } });
  await raw.$disconnect();

  const ctx = { getTenantId: () => tenant.id } as never;
  const prisma = new PrismaService(ctx);
  const owners = users.map((u) => u.id);
  console.log(`tenant=${tenant.id} users=${owners.length}`);

  const periods = [
    { label: '2026 cả năm', start: new Date(Date.UTC(2026, 0, 1)), end: new Date(Date.UTC(2026, 11, 31, 23, 59, 59, 999)) },
    { label: '2026-08', start: new Date(Date.UTC(2026, 7, 1)), end: new Date(Date.UTC(2026, 7, 31, 23, 59, 59, 999)) },
  ];

  let problems = 0;
  for (const period of periods) {
    console.log(`\n===== KỲ ${period.label} =====`);
    for (const src of KPI_DATA_SOURCES) {
      if (!src.resolveByOwner) {
        console.log(`  [không có batch] ${src.id}`);
        continue;
      }
      const byOwner = await src.resolveByOwner(prisma.scoped, { period, ownerUserIds: owners });
      const mismatches: string[] = [];
      let nonZero = 0;
      for (const owner of owners) {
        const batch = byOwner.get(owner) ?? 0;
        const single = await src.resolve(prisma.scoped, { period, ownerUserId: owner });
        if (Math.abs(batch - single) > 0.011) mismatches.push(`${owner.slice(-6)}: batch=${batch} single=${single}`);
        if (batch !== 0 || single !== 0) nonZero += 1;
      }
      const tag = mismatches.length ? '!! LỆCH' : 'ok';
      if (mismatches.length) problems += 1;
      console.log(`  ${tag} ${src.id} (${nonZero} người có số) ${mismatches.slice(0, 4).join(' | ')}`);
    }
  }
  console.log(`\n==== TỔNG SỐ NGUỒN LỆCH: ${problems} ====`);
  await prisma.$disconnect();
}
main();
EOF
