import { Prisma, PrismaClient } from '@prisma/client';
import * as argon2 from 'argon2';
import {
  PERMISSION_CODES,
  SYSTEM_ROLE_PERMISSIONS,
  SYSTEM_ROLE_SCOPES,
  SystemRole,
} from '@ics/shared';
import { seedDemo } from './seed-demo';

/*
 * KHỞI TẠO — chỉ những gì một tenant THẬT cũng cần: quyền, vai trò hệ thống, tài khoản admin, quy
 * trình mặc định, cơ cấu tổ chức tối thiểu, thông tin công ty in trên chứng từ. Không một khách
 * hàng, cơ hội, đơn hàng hay tài khoản nhân viên bịa nào.
 *
 * Dữ liệu minh hoạ nằm ở `seed-demo.ts` và CHỈ chạy khi được gọi tên:
 *
 *     pnpm --filter @ics/backend prisma:seed        # khởi tạo, an toàn ở mọi môi trường
 *     pnpm --filter @ics/backend prisma:seed:demo   # khởi tạo + dữ liệu minh hoạ (chỉ máy dev)
 *
 * Trước đây hai phần dùng chung một lệnh, nên ai cần tài khoản đăng nhập trên môi trường thật đều
 * nhận kèm sổ khách hàng giả — xem khối comment đầu `seed-demo.ts` để biết dấu vết còn lại trong
 * repo và lý do việc đó không phải giả thuyết.
 */

const prisma = new PrismaClient();

const ADMIN_EMAIL = process.env.SEED_ADMIN_EMAIL ?? 'admin@demo.local';
const ADMIN_PASSWORD = process.env.SEED_ADMIN_PASSWORD ?? 'Admin@12345';

/*
 * Cờ bật dữ liệu minh hoạ. Đọc từ tham số dòng lệnh, KHÔNG chỉ từ biến môi trường: cú pháp
 * `SEED_DEMO=true pnpm ...` không chạy trên PowerShell, mà đây là shell mặc định của người đang phát
 * triển repo này. Vẫn nhận biến môi trường cho CI/script.
 */
const WITH_DEMO = process.argv.includes('--demo') || process.env.SEED_DEMO === 'true';

async function main() {
  for (const code of PERMISSION_CODES) {
    await prisma.permission.upsert({
      where: { code },
      update: { module: code.split('.')[0] },
      create: { code, module: code.split('.')[0] },
    });
  }

  const tenant = await prisma.tenant.upsert({
    where: { slug: 'demo' },
    update: {},
    create: { name: 'Demo Tenant', slug: 'demo' },
  });

  await prisma.organization.upsert({
    where: { id: `${tenant.id}-root` },
    update: {},
    create: { id: `${tenant.id}-root`, tenantId: tenant.id, name: 'Demo Organization' },
  });

  const permissions = await prisma.permission.findMany();
  const permissionIds = new Map(permissions.map((permission) => [permission.code, permission.id]));
  const roleIds = new Map<string, string>();
  for (const code of Object.values(SystemRole)) {
    const role = await prisma.role.upsert({
      where: { tenantId_code: { tenantId: tenant.id, code } },
      update: { name: code, isSystem: true, dataScope: SYSTEM_ROLE_SCOPES[code] },
      create: {
        tenantId: tenant.id,
        code,
        name: code,
        isSystem: true,
        dataScope: SYSTEM_ROLE_SCOPES[code],
      },
    });
    roleIds.set(code, role.id);
    await prisma.rolePermission.deleteMany({
      where: {
        roleId: role.id,
        permission: { code: { notIn: SYSTEM_ROLE_PERMISSIONS[code] } },
      },
    });
    for (const permissionCode of SYSTEM_ROLE_PERMISSIONS[code]) {
      const permissionId = permissionIds.get(permissionCode);
      if (!permissionId) throw new Error(`Permission not seeded: ${permissionCode}`);
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId: role.id, permissionId } },
        update: {},
        create: { roleId: role.id, permissionId },
      });
    }
  }
  // Chỉ dọn role HỆ THỐNG lạc mã. `isSystem: true` trong filter là bắt buộc — bỏ nó đi thì
  // seed xoá luôn nhóm quyền admin tự tạo ở màn Cài đặt → Phân quyền.
  await prisma.role.updateMany({
    where: {
      tenantId: tenant.id,
      isSystem: true,
      code: { notIn: Object.values(SystemRole) },
      deletedAt: null,
    },
    data: { deletedAt: new Date() },
  });

  // Admin đăng nhập được: idempotent theo email, luôn reset password hash để dev login ổn định.
  const passwordHash = await argon2.hash(ADMIN_PASSWORD, { type: argon2.argon2id });
  const admin = await prisma.user.upsert({
    where: { email: ADMIN_EMAIL },
    update: { passwordHash, status: 'ACTIVE', deletedAt: null },
    create: {
      tenantId: tenant.id,
      email: ADMIN_EMAIL,
      passwordHash,
      fullName: 'Demo Admin',
    },
  });
  const adminRoleId = roleIds.get(SystemRole.ADMIN);
  if (!adminRoleId) throw new Error('ADMIN role not seeded');
  await prisma.userRole.upsert({
    where: { userId_roleId: { userId: admin.id, roleId: adminRoleId } },
    update: { dataScope: SYSTEM_ROLE_SCOPES.ADMIN, deletedAt: null },
    create: {
      tenantId: tenant.id,
      userId: admin.id,
      roleId: adminRoleId,
      dataScope: SYSTEM_ROLE_SCOPES.ADMIN,
    },
  });

  // Lead Scoring (Fit + Intent) không seed — bảng điểm chuẩn viết cứng trong
  // packages/shared/src/lead-scoring-standard.ts, tenant tự thêm rule tùy biến qua UI nếu cần.

  // Quy trình mặc định của module Công việc (không gắn dự án cụ thể) — thiếu dòng này thì màn
  // Kanban đứng lỗi WORKFLOW_DEFAULT_MISSING với bất kỳ ai chưa từng mở một dự án. Cấu trúc 3 cột
  // mirror đúng quy trình mặc định mà `createProject` dựng cho một dự án mới.
  const moduleWorkflowId = `${tenant.id}-workflow-module-default`;
  await prisma.workflow.upsert({
    where: { id: moduleWorkflowId },
    update: { deletedAt: null },
    create: {
      id: moduleWorkflowId,
      tenantId: tenant.id,
      projectId: null,
      name: 'Quy trình mặc định',
      normalizedName: 'quy trình mặc định',
      isModuleDefault: true,
      createdBy: admin.id,
      updatedBy: admin.id,
    },
  });

  const moduleWorkflowColumns = [
    {
      suffix: 'new',
      name: 'Mới',
      status: 'NEW' as const,
      isDone: false,
      color: '#64748B',
      sortOrder: 1024,
    },
    {
      suffix: 'in-progress',
      name: 'Đang thực hiện',
      status: 'IN_PROGRESS' as const,
      isDone: false,
      color: '#F59E0B',
      sortOrder: 2048,
    },
    {
