      id: `${salaryAdvanceProcessId}-step-1`,
      tenantId: tenant.id,
      processId: salaryAdvanceProcessId,
      sequence: 1,
      name: 'Quản lý duyệt',
      approverType: 'USER',
      approverUserId: admin.id,
    },
  });

