   *
   * Migration `20260813180000_company_profile` khởi tạo hàng này từ `Tenant.name`, mà tenant demo
   * tên "Demo Tenant" — nên bản PDF đầu tiên in ra chữ đó ở góc trên. Ở đây đặt lại tên thật.
   *
   * CHỈ ghi đè khi hàng chưa có hoặc còn nguyên tên mặc định: người dùng đã vào Cài đặt → Thông tin
   * công ty sửa rồi thì chạy lại seed KHÔNG được xoá công sức đó (đúng lỗi mà sản phẩm/hợp đồng mẫu
   * từng mắc).
   *
   * MST và số tài khoản CỐ Ý để trống, không điền số giả: đây là chứng từ gửi cho khách hàng, in
   * nhầm một số tài khoản không có thật là khách chuyển tiền đi đâu không ai biết. Phần in tự bỏ
   * qua dòng trống, nên để trống trông vẫn gọn. Điền nốt ở Cài đặt → Thông tin công ty.
   */
  const companyProfile = {
    name: 'Công ty Cổ phần An ninh mạng Quốc tế',
    // Chỗ giữ chỗ viết rõ là "chưa cập nhật" chứ KHÔNG bịa địa chỉ/điện thoại trông như thật: chứng
    // từ này gửi thẳng cho khách, một dòng giả mà trông thật thì không ai phát hiện ra để sửa.
    address: '(Chưa cập nhật địa chỉ)',
    phone: '(Chưa cập nhật điện thoại)',
    email: '(Chưa cập nhật email)',
    representativeName: '(Chưa cập nhật người đại diện)',
    footerNote: 'Cảm ơn Quý khách đã tin tưởng sử dụng dịch vụ của chúng tôi.',
  };
  const existingProfile = await prisma.companyProfile.findUnique({
    where: { tenantId: tenant.id },
    select: { name: true },
  });
  if (!existingProfile || existingProfile.name === 'Demo Tenant') {
    await prisma.companyProfile.upsert({
      where: { tenantId: tenant.id },
      update: companyProfile,
      create: { tenantId: tenant.id, ...companyProfile },
    });
  }

  const demoSummary = WITH_DEMO
    ? await seedDemo(prisma, {
        tenantId: tenant.id,
        adminUserId: admin.id,
        branchId: branch.id,
        hrDepartmentId: department.id,
        moduleWorkflowId,
        moduleColumnIds,
      })
    : 'KHÔNG seed dữ liệu minh hoạ (thêm --demo nếu muốn).';

  console.log(
    `Seeded ${PERMISSION_CODES.length} permissions, ${Object.values(SystemRole).length} roles, ` +
      `tenant "${tenant.slug}", admin "${ADMIN_EMAIL}", ` +
      `1 quy trình mặc định module Công việc, 1 quy trình tạm ứng lương, ` +
      `cơ cấu tổ chức tối thiểu + hồ sơ nhân viên cho admin.\n${demoSummary}`,
  );
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());

import { Prisma, PrismaClient } from '@prisma/client';
import { seedDemoMarketing } from './seed-demo-marketing';
import { seedDemoSales } from './seed-demo-sales';
import { seedKpi } from './seed-kpi';
import { seedOrg } from './seed-org';
import { isoDay } from '../src/reports/report-period';

/*
 * DỮ LIỆU MINH HOẠ — KHÔNG BAO GIỜ CHẠY TRÊN MÔI TRƯỜNG THẬT.
 *
 * Khối này từng nằm chung trong `seed.ts`, tức là dùng chung một lệnh với phần khởi tạo bắt buộc
 * (quyền, vai trò, tài khoản admin). Ai đó chỉ muốn có tài khoản đăng nhập trên môi trường thật thì
 * buộc phải nhận kèm cả sổ khách hàng bịa. Dấu vết còn lại trong repo: commit 359f6fb
 * "thông tin công ty mặc định trên chứng từ in không còn là Demo Tenant" — chứng từ gửi khách in ra
 * chữ "Demo Tenant" thì bộ seed này đã chạy ở nơi có người dùng thật.
 *
 * Hậu quả không chỉ là con số xấu trên báo cáo: `seedOrg` tạo ba tài khoản đăng nhập được
 * (`huong.le@demo.local`, `anh.tran@demo.local`, `lan.nguyen@demo.local`) với mật khẩu dùng chung
 * viết cứng, và ĐẶT LẠI hash mật khẩu mỗi lần chạy — đổi mật khẩu cũng không giữ được.
 *
 * Vì vậy `prisma db seed` chỉ chạy phần khởi tạo. Muốn có dữ liệu minh hoạ:
 *
 *     pnpm --filter @ics/backend prisma:seed:demo
 *
 * Dọn dữ liệu minh hoạ đã lỡ ghi vào một DB: `demo-data-purge.sql` (đếm trước bằng
 * `demo-data-report.sql`). Là file SQL chứ không phải lệnh pnpm, vì việc này cần đọc kết quả chạy
 * thử rồi mới quyết định commit — không phải thứ nên gói sau một lệnh bấm là chạy.
 */

/** Những gì phần khởi tạo trong `seed.ts` đã dựng sẵn và khối minh hoạ cần gắn vào. */
export interface DemoSeedContext {
  tenantId: string;
  adminUserId: string;
  branchId: string;
  hrDepartmentId: string;
  moduleWorkflowId: string;
  /** id cột Kanban của quy trình mặc định, tra theo `TaskStatus`. */
  moduleColumnIds: Map<string, string>;
}

export async function seedDemo(prisma: PrismaClient, ctx: DemoSeedContext): Promise<string> {
  const { tenantId, adminUserId, moduleWorkflowId, moduleColumnIds } = ctx;

  // Khách hàng demo (owner = admin) để UI có dữ liệu. Idempotent theo id cố định.
  const demoCustomers = [
    {
      suffix: 'cust-1',
      code: 'KH00001',
      type: 'INDIVIDUAL' as const,
      status: 'MOI' as const,
      name: 'Nguyễn Văn An',
      phone: '0901234567',
      email: 'an.nguyen@example.com',
    },
    {
      suffix: 'cust-2',
      code: 'KH00002',
      type: 'COMPANY' as const,
      status: 'DANG_CHAM_SOC' as const,
      name: 'Công ty TNHH ABC',
      phone: '02838123456',
      email: 'lienhe@abc.vn',
      taxCode: '0301234567',
    },
    {
      suffix: 'cust-3',
      code: 'KH00003',
      type: 'INDIVIDUAL' as const,
      status: 'NONG' as const,
      name: 'Trần Thị Bình',
      phone: '0912345678',
      email: 'binh.tran@example.com',
    },
  ];
  for (const c of demoCustomers) {
    await prisma.customer.upsert({
      where: { id: `${tenantId}-${c.suffix}` },
      update: { code: c.code, status: c.status, deletedAt: null },
      create: {
        id: `${tenantId}-${c.suffix}`,
        tenantId,
        code: c.code,
        type: c.type,
        status: c.status,
        name: c.name,
        phone: c.phone,
        email: c.email,
        phoneNormalized: c.phone.replace(/[^\d+]/g, ''),
        emailNormalized: c.email.toLowerCase(),
        taxCode: c.taxCode,
        ownerId: adminUserId,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }

  /*
   * Danh mục phân loại (nguồn / nhóm / tag / trường tùy biến).
   *
   * Đây là danh mục MINH HOẠ, không phải cấu hình mặc định của sản phẩm: "Khó tính",
   * "Gạch ốp lát", "Ngói" là của một nhà bán vật liệu, trong khi tenant thật ở đây là công ty an
   * ninh mạng. Tenant thật tự tạo danh mục của mình ở màn Cài đặt.
   */
  const sources = ['Facebook', 'Website', 'Giới thiệu'];
  const sourceIds = new Map<string, string>();
  for (const name of sources) {
    const row = await prisma.customerSource.upsert({
      where: { tenantId_name: { tenantId, name } },
      update: { deletedAt: null },
      create: { tenantId, name, createdBy: adminUserId, updatedBy: adminUserId },
    });
    sourceIds.set(name, row.id);
  }

  /*
   * Nhóm khách hàng = MỘT ĐỢT GOM KHÁCH, không phải bậc phân loại.
   *
   * Bản cũ seed "Khách lẻ / Đại lý / VIP" — đó là một trục phân loại thứ hai chạy song song với
   * nhóm gom theo đợt nhập Excel ("Khách xã Tân Phú", "Danh sách RAR"), nên cùng một cột "Nhóm
   * khách hàng" trên danh sách lại chứa hai loại giá trị khác nhau và không lọc ra được gì.
   * Chỉ còn một trục duy nhất: nhóm theo đợt gom, mặc định là `DEFAULT_IMPORT_GROUP_NAME`.
   */
  const groups = ['ICS', 'Khách hội thảo 2026'];
  const groupIds = new Map<string, string>();
  for (const name of groups) {
    const row = await prisma.customerGroup.upsert({
      where: { tenantId_name: { tenantId, name } },
      update: { deletedAt: null },
      create: { tenantId, name, createdBy: adminUserId, updatedBy: adminUserId },
    });
    groupIds.set(name, row.id);
  }

  const tags: { name: string; color: string }[] = [
    { name: 'Tiềm năng', color: '#0ea5e9' },
    { name: 'Ưu tiên', color: '#f59e0b' },
    { name: 'Khó tính', color: '#ef4444' },
  ];
  const tagIds = new Map<string, string>();
  for (const t of tags) {
    const row = await prisma.customerTag.upsert({
      where: { tenantId_name: { tenantId, name: t.name } },
      update: { color: t.color, deletedAt: null },
      create: {
        tenantId,
        name: t.name,
        color: t.color,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
    tagIds.set(t.name, row.id);
  }

  const customFields: {
    key: string;
    label: string;
    type: 'TEXT' | 'NUMBER' | 'DATE' | 'SELECT';
    options?: string[];
    sortOrder: number;
  }[] = [
    { key: 'nganh_nghe', label: 'Ngành nghề', type: 'TEXT', sortOrder: 1 },
    {
      key: 'khu_vuc',
      label: 'Khu vực',
      type: 'SELECT',
      options: ['Miền Bắc', 'Miền Trung', 'Miền Nam'],
      sortOrder: 2,
    },
    { key: 'ngay_hop_tac', label: 'Ngày hợp tác', type: 'DATE', sortOrder: 3 },
  ];
  for (const f of customFields) {
    await prisma.customFieldDefinition.upsert({
      where: { tenantId_key: { tenantId, key: f.key } },
      update: {
        label: f.label,
        type: f.type,
        options: f.options,
        sortOrder: f.sortOrder,
        deletedAt: null,
      },
      create: {
        tenantId,
        key: f.key,
        label: f.label,
        type: f.type,
        options: f.options,
        sortOrder: f.sortOrder,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }

  // Lead Scoring (Fit + Intent) không seed — bảng điểm chuẩn viết cứng trong
  // packages/shared/src/lead-scoring-standard.ts, tenant tự thêm rule tùy biến qua UI nếu cần.

  // Gán phân loại cho khách demo để UI có dữ liệu.
  await prisma.customer.update({
    where: { id: `${tenantId}-cust-2` },
    data: {
      groupId: groupIds.get('Khách hội thảo 2026'),
      sourceId: sourceIds.get('Website'),
      customFields: { nganh_nghe: 'Xây dựng', khu_vuc: 'Miền Nam' },
    },
  });
  await prisma.customer.update({
    where: { id: `${tenantId}-cust-3` },
    data: { groupId: groupIds.get('ICS'), sourceId: sourceIds.get('Giới thiệu') },
  });
  await prisma.customer.update({
    where: { id: `${tenantId}-cust-1` },
    data: { groupId: groupIds.get('ICS'), sourceId: sourceIds.get('Facebook') },
  });
  for (const [customerSuffix, tagName] of [
    ['cust-2', 'Tiềm năng'],
    ['cust-3', 'Ưu tiên'],
  ] as const) {
    const tagId = tagIds.get(tagName);
    if (!tagId) continue;
    await prisma.customerTagAssignment.upsert({
      where: { customerId_tagId: { customerId: `${tenantId}-${customerSuffix}`, tagId } },
      update: {},
      create: { tenantId, customerId: `${tenantId}-${customerSuffix}`, tagId },
    });
  }

  // Cơ hội mẫu gắn khách demo (owner = admin), idempotent theo id cố định.
  const demoOpportunities = [
    {
      suffix: 'opp-1',
      customerSuffix: 'cust-2',
      name: 'Cung cấp nội thất văn phòng ABC',
      amount: 150_000_000,
      stage: 'BAO_GIA' as const,
      days: 20,
    },
    {
      suffix: 'opp-2',
      customerSuffix: 'cust-3',
      name: 'Gói thi công nhà phố chị Bình',
      amount: 480_000_000,
      stage: 'THUONG_THAO' as const,
      days: 35,
    },
  ];
  for (const o of demoOpportunities) {
    await prisma.opportunity.upsert({
      where: { id: `${tenantId}-${o.suffix}` },
      update: { name: o.name, amount: o.amount, stage: o.stage, deletedAt: null },
      create: {
        id: `${tenantId}-${o.suffix}`,
        tenantId,
        customerId: `${tenantId}-${o.customerSuffix}`,
        name: o.name,
        amount: o.amount,
        stage: o.stage,
        expectedCloseDate: new Date(Date.now() + o.days * 24 * 60 * 60 * 1000),
        ownerId: adminUserId,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }

  // ── CRM-32: danh mục sản phẩm & dịch vụ (nhóm / đơn vị / sản phẩm mẫu) ──
  const productCategories = ['Gạch ốp lát', 'Keo & phụ kiện', 'Ngói', 'Dịch vụ thi công'];
  const productCategoryIds = new Map<string, string>();
  for (const name of productCategories) {
    const row = await prisma.productCategory.upsert({
      where: { tenantId_name: { tenantId, name } },
      update: { deletedAt: null },
      create: { tenantId, name, createdBy: adminUserId, updatedBy: adminUserId },
    });
    productCategoryIds.set(name, row.id);
  }

  const productUnits = ['Viên', 'Hộp', 'm2', 'Bao', 'Gói'];
  const productUnitIds = new Map<string, string>();
  for (const name of productUnits) {
    const row = await prisma.productUnit.upsert({
      where: { tenantId_name: { tenantId, name } },
      update: { deletedAt: null },
      create: { tenantId, name, createdBy: adminUserId, updatedBy: adminUserId },
    });
    productUnitIds.set(name, row.id);
  }

  const demoProducts = [
    {
      suffix: 'prod-1',
      code: '612M01A',
      name: 'Gạch 60x120 Vân gỗ xương cá chiếc lá',
      type: 'GOODS' as const,
      category: 'Gạch ốp lát',
      unit: 'm2',
      retailPrice: 385_000,
      wholesalePrice: 350_000,
      purchasePrice: 300_000,
      vatPercent: 10,
      stockQuantity: 240,
    },
    {
      suffix: 'prod-2',
      code: 'TT61222',
      name: 'Gạch 60x120 lá sen đậm',
      type: 'GOODS' as const,
      category: 'Gạch ốp lát',
      unit: 'm2',
      retailPrice: 420_000,
      wholesalePrice: 390_000,
      purchasePrice: 330_000,
      vatPercent: 10,
      stockQuantity: 120,
    },
    {
      suffix: 'prod-3',
      code: 'KEO2TP-E803',
      name: 'Keo 2 thành phần Wenimax E803',
      type: 'GOODS' as const,
      category: 'Keo & phụ kiện',
      unit: 'Bao',
      retailPrice: 95_000,
      wholesalePrice: 82_000,
      purchasePrice: 65_000,
      vatPercent: 8,
      stockQuantity: 500,
    },
    {
      suffix: 'prod-4',
      code: 'DV-THICONG',
      name: 'Dịch vụ thi công ốp lát (m2)',
      type: 'SERVICE' as const,
      category: 'Dịch vụ thi công',
      unit: 'm2',
      retailPrice: 120_000,
      wholesalePrice: 100_000,
      purchasePrice: 0,
      vatPercent: 0,
      stockQuantity: 0,
    },
  ];
  for (const p of demoProducts) {
    await prisma.product.upsert({
      where: { id: `${tenantId}-${p.suffix}` },
      update: {
        code: p.code,
        name: p.name,
        type: p.type,
        categoryId: productCategoryIds.get(p.category),
        unitId: productUnitIds.get(p.unit),
        retailPrice: p.retailPrice,
        wholesalePrice: p.wholesalePrice,
        purchasePrice: p.purchasePrice,
        vatPercent: p.vatPercent,
        stockQuantity: p.stockQuantity,
        // CỐ Ý không đặt `deletedAt: null`: sản phẩm mẫu có id cố định nên mỗi lần chạy seed lại
        // (nằm trong `pnpm dev:setup`) sẽ hồi sinh đúng những sản phẩm người dùng vừa xóa —
        // trông y như "mấy sản phẩm có sẵn không xóa được".
      },
      create: {
        id: `${tenantId}-${p.suffix}`,
        tenantId,
        code: p.code,
        name: p.name,
        type: p.type,
        categoryId: productCategoryIds.get(p.category),
        unitId: productUnitIds.get(p.unit),
        retailPrice: p.retailPrice,
        wholesalePrice: p.wholesalePrice,
        purchasePrice: p.purchasePrice,
        taxable: p.vatPercent > 0,
        vatPercent: p.vatPercent,
        stockQuantity: p.stockQuantity,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }

  // ── Dữ liệu mẫu cho trang chủ (dashboard): khách mới, cơ hội thắng, hợp đồng hoàn thành,
  // hoạt động, báo giá chờ duyệt, công nợ quá hạn, công việc trễ/đến hạn hôm nay. Idempotent theo
  // id cố định — mọi mốc ngày tính lại theo "now" mỗi lần seed chạy nên "quá hạn" luôn đúng.
  const demoDashboardCustomers = [
    {
      suffix: 'cust-4',
      code: 'KH00004',
      type: 'INDIVIDUAL' as const,
      status: 'MOI' as const,
      name: 'Lê Văn Cường',
      phone: '0934567890',
      email: 'cuong.le@example.com',
    },
    {
      suffix: 'cust-5',
      code: 'KH00005',
      type: 'COMPANY' as const,
      status: 'DANG_CHAM_SOC' as const,
      name: 'Công ty TNHH Minh Phát',
      phone: '02839988776',
      email: 'lienhe@minhphat.vn',
      taxCode: '0309876543',
    },
  ];
  for (const c of demoDashboardCustomers) {
    await prisma.customer.upsert({
      where: { id: `${tenantId}-${c.suffix}` },
      update: { code: c.code, status: c.status, deletedAt: null },
      create: {
        id: `${tenantId}-${c.suffix}`,
        tenantId,
        code: c.code,
        type: c.type,
        status: c.status,
        name: c.name,
        phone: c.phone,
        email: c.email,
        phoneNormalized: c.phone.replace(/[^\d+]/g, ''),
        emailNormalized: c.email.toLowerCase(),
        taxCode: c.taxCode,
        ownerId: adminUserId,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }

  // Hai cơ hội mới trong kỳ này: một THẮNG (nuôi doanh thu/thương vụ đã chốt + phễu), một đang
  // BÁO_GIÁ (nuôi tỷ lệ chuyển đổi và phễu). `createdAt` để mặc định `now()` — luôn rơi vào kỳ này.
  const demoRecentOpportunities = [
    {
      suffix: 'opp-3',
      customerSuffix: 'cust-1',
      name: 'Thi công sảnh khách sạn anh An',
      amount: 220_000_000,
      stage: 'THANG' as const,
      days: 0,
    },
    {
      suffix: 'opp-4',
      customerSuffix: 'cust-1',
      name: 'Ốp lát sân vườn anh An',
      amount: 90_000_000,
      stage: 'BAO_GIA' as const,
      days: 15,
    },
  ];
  for (const o of demoRecentOpportunities) {
    await prisma.opportunity.upsert({
      where: { id: `${tenantId}-${o.suffix}` },
      update: { name: o.name, amount: o.amount, stage: o.stage, deletedAt: null },
      create: {
        id: `${tenantId}-${o.suffix}`,
        tenantId,
        customerId: `${tenantId}-${o.customerSuffix}`,
        name: o.name,
        amount: o.amount,
        stage: o.stage,
        expectedCloseDate: new Date(Date.now() + o.days * 24 * 60 * 60 * 1000),
        ownerId: adminUserId,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }
  await prisma.opportunityStageHistory.upsert({
    where: { id: `${tenantId}-opp-3-won` },
    update: { toStage: 'THANG' },
    create: {
      id: `${tenantId}-opp-3-won`,
      tenantId,
      opportunityId: `${tenantId}-opp-3`,
      fromStage: 'THUONG_THAO',
      toStage: 'THANG',
    },
  });

  // Hai hợp đồng hoàn thành, ký trong kỳ này, để module Hợp đồng có dữ liệu mở màn. Chúng KHÔNG
  // nuôi con số nào trên trang chủ: doanh thu và công nợ đọc đơn hàng (xem khối `demoOrders` bên
  // dưới), hợp đồng chỉ còn là hồ sơ của thương vụ.
  const demoContracts = [
    {
      suffix: 'contract-1',
      code: 'HD-DEMO001',
      customerSuffix: 'cust-2',
      customerName: 'Công ty TNHH ABC',
      name: 'Hợp đồng cung cấp nội thất văn phòng ABC',
      value: 150_000_000,
    },
    {
      suffix: 'contract-2',
      code: 'HD-DEMO002',
      customerSuffix: 'cust-1',
      customerName: 'Nguyễn Văn An',
      name: 'Hợp đồng thi công sảnh khách sạn anh An',
      value: 220_000_000,
    },
  ];
  for (const ct of demoContracts) {
    const contract = await prisma.contract.upsert({
      where: { id: `${tenantId}-${ct.suffix}` },
      // Không hồi sinh hợp đồng đã xóa — cùng lý do với sản phẩm mẫu ở trên.
      update: { name: ct.name, status: 'COMPLETED', contractValue: ct.value },
      create: {
        id: `${tenantId}-${ct.suffix}`,
        tenantId,
        code: ct.code,
        name: ct.name,
        customerId: `${tenantId}-${ct.customerSuffix}`,
        customerName: ct.customerName,
        signDate: new Date(),
        effectiveDate: new Date(),
        expiryDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
        contractValue: ct.value,
        status: 'COMPLETED',
        ownerId: adminUserId,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });

    await prisma.contractItem.upsert({
      where: { id: `${contract.id}-item-1` },
      update: {},
      create: {
        id: `${contract.id}-item-1`,
        tenantId,
        contractId: contract.id,
        productId: `${tenantId}-prod-4`,
        productCode: 'DV-THICONG',
        productName: 'Dịch vụ thi công ốp lát (m2)',
        unitName: 'm2',
        quantity: 100,
        unitPrice: 120_000,
        lineTotal: ct.value,
      },
    });
  }
  await prisma.contractPayment.upsert({
    where: { id: `${tenantId}-contract-1-payment-1` },
    update: { isPaid: true },
    create: {
      id: `${tenantId}-contract-1-payment-1`,
      tenantId,
      contractId: `${tenantId}-contract-1`,
      name: 'Đợt 1 - Tạm ứng',
      amount: 75_000_000,
      dueDate: new Date(Date.now() - 10 * 24 * 60 * 60 * 1000),
      isPaid: true,
      paidAt: new Date(),
    },
  });
  await prisma.contractPayment.upsert({
    where: { id: `${tenantId}-contract-2-payment-1` },
    update: { isPaid: false, dueDate: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000) },
    create: {
      id: `${tenantId}-contract-2-payment-1`,
      tenantId,
      contractId: `${tenantId}-contract-2`,
      name: 'Đợt 2 - Thanh toán còn lại',
      amount: 110_000_000,
      dueDate: new Date(Date.now() - 3 * 24 * 60 * 60 * 1000),
      isPaid: false,
    },
  });

  /*
    Đơn hàng demo của admin. Vừa là dữ liệu mở màn — bộ seed gốc chạy một mình vẫn phải ra số khác 0
    trên trang chủ — vừa là chốt chặn cho ba điều kiện mà doanh thu và công nợ dựa vào:

      - Doanh thu đã chốt chỉ cộng đơn ĐÃ DUYỆT. Đơn nháp `DH-DEMO003` nằm đây để nếu điều kiện
        `status` rơi mất thì tổng nhảy thêm đúng 90tr — sai lệch nhìn thấy được, không âm thầm.
      - Công nợ chỉ tính trên đơn đã duyệt. Đơn ĐÃ HUỶ `DH-DEMO004` vẫn giữ nguyên lịch thu tiền quá
        hạn (đúng thực tế: huỷ đơn không xoá lịch đã lập), nên quên lọc `CANCELLED` là giao cho người
        dùng đi đòi 312tr không tồn tại.
      - `paidAmount` phải bằng tổng các đợt đã đánh dấu thu — bất biến của `SalesOrderService`. Sai ở
        đây thì cột "Còn nợ" của danh sách đơn và thẻ "Công nợ phải thu" nói hai con số khác nhau
        trên cùng một đơn.

    Dùng mã `DV-THICONG` (VAT 0%, 120.000đ/m²) cho mọi dòng nên tổng đơn tròn và cộng nhẩm được:
    doanh thu 150 + 216 = 366tr, còn nợ 108tr, đúng một đợt quá hạn cần đi đòi.
  */
  const ORDER_UNIT_PRICE = 120_000;
  const orderInstalments = [
    { name: 'Đợt 1 - Tạm ứng', percent: 50, dueInDays: 7 },
    { name: 'Đợt 2 - Thanh toán còn lại', percent: 50, dueInDays: 30 },
  ];
  const demoOrders = [
    {
      suffix: 'order-1',
      code: 'DH-DEMO001',
      customerSuffix: 'cust-2',
      customerName: 'Công ty TNHH ABC',
      quantity: 1250,
      status: 'APPROVED' as const,
      daysAgo: 40,
      /** Đợt nào đã thu, theo thứ tự `orderInstalments`. */
      paid: [true, true],
    },
    {
      suffix: 'order-2',
      code: 'DH-DEMO002',
      customerSuffix: 'cust-1',
      customerName: 'Nguyễn Văn An',
      quantity: 1800,
      status: 'APPROVED' as const,
      daysAgo: 40,
      // Đợt 2 đến hạn sau 30 ngày mà đơn đã đặt 40 ngày: quá hạn 10 ngày, nuôi ô "Đợt thu tiền quá
      // hạn" ở khối Cần bạn xử lý.
      paid: [true, false],
    },
    {
      suffix: 'order-3',
      code: 'DH-DEMO003',
      customerSuffix: 'cust-3',
      customerName: 'Trần Thị Bình',
      quantity: 750,
      status: 'DRAFT' as const,
      daysAgo: 5,
      paid: [false, false],
    },
    {
      suffix: 'order-4',
      code: 'DH-DEMO004',
      customerSuffix: 'cust-4',
      customerName: 'Lê Văn Cường',
      quantity: 2600,
      status: 'CANCELLED' as const,
      daysAgo: 40,
      paid: [false, false],
    },
  ];
  for (const o of demoOrders) {
    const orderId = `${tenantId}-${o.suffix}`;
    const orderDate = new Date(Date.now() - o.daysAgo * 24 * 60 * 60 * 1000);
    const grandTotal = o.quantity * ORDER_UNIT_PRICE;
    const approved = o.status === 'APPROVED';
    const amounts = orderInstalments.map((part, index) =>
      // Đợt cuối lấy phần còn lại để tổng các đợt luôn khớp tổng đơn từng đồng.
      index === orderInstalments.length - 1
        ? grandTotal - Math.round((grandTotal * orderInstalments[0].percent) / 100)
        : Math.round((grandTotal * part.percent) / 100),
    );
    const paidAmount = amounts.reduce((sum, amount, i) => sum + (o.paid[i] ? amount : 0), 0);

    const orderData = {
      code: o.code,
      customerId: `${tenantId}-${o.customerSuffix}`,
      customerName: o.customerName,
      orderDate,
      status: o.status,
      paymentStatus:
        paidAmount <= 0
          ? ('UNPAID' as const)
          : paidAmount >= grandTotal
            ? ('PAID' as const)
            : ('PARTIAL' as const),
      subtotal: grandTotal,
      vatAmount: 0,
      grandTotal,
      paidAmount,
      approvedBy: approved ? adminUserId : null,
      approvedAt: approved ? orderDate : null,
      ownerId: adminUserId,
      createdAt: orderDate,
    };
    await prisma.salesOrder.upsert({
      where: { id: orderId },
      update: { ...orderData, deletedAt: null, updatedBy: adminUserId },
      create: {
        id: orderId,
        tenantId,
        ...orderData,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });

    const itemData = {
      productId: `${tenantId}-prod-4`,
      productCode: 'DV-THICONG',
      productName: 'Dịch vụ thi công ốp lát (m2)',
      unitName: 'm2',
      quantity: o.quantity,
      unitPrice: ORDER_UNIT_PRICE,
      lineTotal: grandTotal,
    };
    await prisma.salesOrderItem.upsert({
      where: { id: `${orderId}-item-1` },
      update: { ...itemData, deletedAt: null },
      create: { id: `${orderId}-item-1`, tenantId, orderId, ...itemData },
    });

    /*
      Xoá sạch lần thu của đơn rồi dựng lại — seed là chủ sở hữu duy nhất của đơn này nên phải là
      nguồn duy nhất của sổ thu. Chỉ `upsert` theo id cố định là cộng dồn lên những lần thu mà
      migration `20260816090000` đã backfill (id `cuid()`): tiền tính hai lần, công nợ ra số âm.
    */
    await prisma.salesOrderReceipt.deleteMany({ where: { orderId } });

    for (const [index, part] of orderInstalments.entries()) {
      const dueDate = new Date(orderDate.getTime() + part.dueInDays * 24 * 60 * 60 * 1000);
      const paymentData = {
        name: part.name,
        percent: part.percent,
        amount: amounts[index],
        dueDate,
        isPaid: o.paid[index],
        paidAt: o.paid[index] ? dueDate : null,
        sortOrder: index,
      };
      await prisma.salesOrderPayment.upsert({
        where: { id: `${orderId}-payment-${index + 1}` },
        update: { ...paymentData, deletedAt: null },
        create: {
          id: `${orderId}-payment-${index + 1}`,
          tenantId,
          orderId,
          ...paymentData,
        },
      });

      /*
        Lần thu tương ứng. Chỉ số công nợ đọc `SalesOrderReceipt` chứ không đọc cờ `isPaid` của kỳ
        (xem `orderOutstandingAsOf` trong `src/kpi/kpi-data-sources.ts`), nên thiếu hàng này thì bộ
        demo báo còn nợ đúng bằng trọn giá trị đơn — lệch hẳn cột "Còn nợ" mà chính khối comment ở
        trên tự nhận là chốt chặn.
      */
      if (o.paid[index]) {
        await prisma.salesOrderReceipt.create({
          data: {
            id: `${orderId}-receipt-${index + 1}`,
            tenantId,
            orderId,
            amount: amounts[index],
            receivedAt: dueDate,
            createdBy: adminUserId,
          },
        });
      }
    }
  }

  // Bốn hoạt động CRM trong kỳ này (occurredAt/createdAt mặc định now()).
  const demoActivities = [
    {
      suffix: 'activity-1',
      customerSuffix: 'cust-1',
      type: 'CALL' as const,
      subject: 'Gọi điện tư vấn nhu cầu ốp lát',
    },
    {
      suffix: 'activity-2',
      customerSuffix: 'cust-2',
      type: 'MEETING' as const,
      subject: 'Họp báo giá nội thất văn phòng',
    },
    {
      suffix: 'activity-3',
      customerSuffix: 'cust-3',
      type: 'EMAIL' as const,
      subject: 'Gửi email báo giá thi công nhà phố',
    },
    {
      suffix: 'activity-4',
      customerSuffix: 'cust-4',
      type: 'NOTE' as const,
      subject: 'Ghi chú nhu cầu khách hàng mới',
    },
  ];
  for (const a of demoActivities) {
    await prisma.activity.upsert({
      where: { id: `${tenantId}-${a.suffix}` },
      update: { subject: a.subject, deletedAt: null },
      create: {
        id: `${tenantId}-${a.suffix}`,
        tenantId,
        customerId: `${tenantId}-${a.customerSuffix}`,
        type: a.type,
        subject: a.subject,
        ownerId: adminUserId,
        createdBy: adminUserId,
        updatedBy: adminUserId,
      },
    });
  }

  // Một báo giá chờ duyệt của admin (nuôi "Báo giá chờ duyệt" ở khối "Cần bạn xử lý").
  const pendingQuoteId = `${tenantId}-quote-demo-1`;
  await prisma.quote.upsert({
    where: { id: pendingQuoteId },
    update: { status: 'PENDING', deletedAt: null },
    create: {
      id: pendingQuoteId,
      tenantId,
      code: 'BG-DEMO001',
      customerId: `${tenantId}-cust-5`,
      customerName: 'Công ty TNHH Minh Phát',
      issueDate: new Date(),
      status: 'PENDING',
      ownerId: adminUserId,
      createdBy: adminUserId,
      updatedBy: adminUserId,
    },
  });
  await prisma.quoteItem.upsert({
    where: { id: `${pendingQuoteId}-item-1` },
    update: {},
    create: {
      id: `${pendingQuoteId}-item-1`,
      tenantId,
      quoteId: pendingQuoteId,
      productId: `${tenantId}-prod-1`,
      productCode: '612M01A',
      productName: 'Gạch 60x120 Vân gỗ xương cá chiếc lá',
      unitName: 'm2',
      quantity: 50,
      unitPrice: 385_000,
      lineTotal: 19_250_000,
    },
  });

  // Hai công việc của admin: một trễ hạn (hôm qua), một đến hạn hôm nay — nuôi khối
  // "Cần bạn xử lý". `dueDate` là cột DATE nên phải ghép nửa đêm UTC của đúng ngày lịch Bangkok,
  // không dùng trực tiếp instant hiện tại (lệch múi giờ sẽ rơi sang ngày khác).
  const demoTasks = [
    {
      suffix: 'task-demo-1',
      code: 'TSK-DEMO001',
      title: 'Gọi lại khách hàng Trần Thị Bình',
      status: 'NEW' as const,
      dueOffsetDays: -1,
      listOrder: 1024,
    },
    {
      suffix: 'task-demo-2',
      code: 'TSK-DEMO002',
      title: 'Gửi hợp đồng cho Công ty TNHH Minh Phát',
      status: 'IN_PROGRESS' as const,
      dueOffsetDays: 0,
      listOrder: 2048,
    },
  ];
