import { PrismaClient } from '@prisma/client';
import * as argon2 from 'argon2';
import { DEPARTMENT_ROLE_SEEDS, SYSTEM_ROLE_SCOPES, SystemRole } from '@ics/shared';

/**
 * Cơ cấu tổ chức mở rộng cho môi trường dev: phòng ban thứ hai, và mỗi phòng có
 * 1 trưởng phòng + 2 nhân viên, kèm tài khoản đăng nhập cho các vai cần thiết.
 *
 * Vì sao cần: module KPI phân quyền theo PHÒNG BAN (quản lý chỉ sửa được phòng
 * mình, admin chỉ đọc). Với một phòng ban duy nhất thì không thể kiểm được các
 * ràng buộc chéo phòng — mà đó lại là phần dễ sai nhất.
 *
 * Idempotent: id tiền định + upsert, và luôn reset `passwordHash` để đăng nhập
 * ở máy dev không bị lệch sau khi đổi biến môi trường.
 */

/** Mật khẩu dùng chung cho các tài khoản dev bên dưới. */
const DEV_PASSWORD = process.env.SEED_DEV_PASSWORD ?? 'Demo@12345';

type PersonSeed = {
  key: string;
  code: string;
  familyName: string;
  givenName: string;
  department: 'hr' | 'sales';
  position: string;
  jobTitle: string;
  /** Có tài khoản đăng nhập hay không, và với vai nào. */
  account?: { email: string; role: SystemRole };
};

const PEOPLE: PersonSeed[] = [
  {
    key: 'hr-head',
    code: 'EPL/2026/00002',
    familyName: 'Lê',
    givenName: 'Thị Hương',
    department: 'hr',
    position: 'hr-head',
    jobTitle: 'Trưởng phòng Hành chính - Nhân sự',
    account: { email: 'huong.le@demo.local', role: SystemRole.MANAGER },
  },
  {
    key: 'hr-staff-1',
    code: 'EPL/2026/00003',
    familyName: 'Phạm',
    givenName: 'Văn Dũng',
    department: 'hr',
    position: 'hr-staff',
    jobTitle: 'Chuyên viên nhân sự',
  },
  {
    key: 'hr-staff-2',
    code: 'EPL/2026/00004',
    familyName: 'Ngô',
    givenName: 'Thị Mai',
    department: 'hr',
    position: 'hr-staff',
    jobTitle: 'Chuyên viên hành chính',
  },
  {
    key: 'sales-head',
    code: 'EPL/2026/00005',
    familyName: 'Trần',
    givenName: 'Quốc Anh',
    department: 'sales',
    position: 'sales-head',
    jobTitle: 'Trưởng phòng Kinh doanh',
    account: { email: 'anh.tran@demo.local', role: SystemRole.MANAGER },
  },
  {
    key: 'sales-staff-1',
    code: 'EPL/2026/00006',
    familyName: 'Nguyễn',
    givenName: 'Thị Lan',
    department: 'sales',
    position: 'sales-staff',
    jobTitle: 'Nhân viên kinh doanh',
    account: { email: 'lan.nguyen@demo.local', role: SystemRole.EMPLOYEE },
  },
  {
    key: 'sales-staff-2',
    code: 'EPL/2026/00007',
    familyName: 'Vũ',
    givenName: 'Minh Khôi',
    department: 'sales',
    position: 'sales-staff',
    jobTitle: 'Nhân viên kinh doanh',
  },
];

/** Mã nhân viên cuối cùng đã dùng ở trên — đẩy bộ đếm để app không sinh mã trùng. */
const LAST_EMPLOYEE_SEQUENCE = 7;

export async function seedOrg(
  prisma: PrismaClient,
  context: { tenantId: string; branchId: string; hrDepartmentId: string },
): Promise<string> {
  const { tenantId, branchId, hrDepartmentId } = context;

  const salesDepartmentId = `${tenantId}-dept-sales`;
  await prisma.department.upsert({
    where: { id: salesDepartmentId },
    update: { name: 'Phòng Kinh doanh', deletedAt: null },
    create: {
      id: salesDepartmentId,
      tenantId,
      branchId,
      name: 'Phòng Kinh doanh',
      description: 'Phòng ban phụ trách bán hàng và phát triển khách hàng',
      // `isSales` cố ý để mặc định false: cờ đó nới phạm vi dữ liệu ở RbacService,
      // bật lên là đổi hành vi phân quyền — cần quyết định riêng, không seed ngầm.
      createdBy: 'SYSTEM',
      updatedBy: 'SYSTEM',
    },
  });

  /*
    Hai nhóm quyền gắn theo phòng ban, seed sẵn để làm LỰA CHỌN trong ô "Thiết lập quyền cho phòng ban".
    Migration 20260814090000_add_department_roles chỉ tạo chúng cho tenant đã có phòng ban bật cờ
    `isSales`/`isRecruitment` cũ — DB mới không có phòng nào bật cờ nên sẽ không có role nào để
    chọn. Cố ý CHỈ tạo role, KHÔNG nối vào phòng ban nào: nối là quyết định phân quyền, phải do
    người dùng bấm ở UI và đi qua audit + kiểm quyền `role.assign`.
  */
  for (const seed of DEPARTMENT_ROLE_SEEDS) {
    const role = await prisma.role.upsert({
      where: { tenantId_code: { tenantId, code: seed.code } },
      update: { name: seed.name, deletedAt: null },
      create: {
        tenantId,
        code: seed.code,
        name: seed.name,
        isSystem: false,
        dataScope: seed.dataScope ?? 'OWN',
      },
      select: { id: true },
    });
    const permissions = await prisma.permission.findMany({
      where: { code: { in: [...seed.permissions] } },
      select: { id: true },
    });
    await prisma.rolePermission.createMany({
      data: permissions.map(({ id }) => ({ roleId: role.id, permissionId: id })),
      skipDuplicates: true,
    });
  }

  const departmentIdByKey: Record<PersonSeed['department'], string> = {
    hr: hrDepartmentId,
    sales: salesDepartmentId,
  };

  /*
    Nhóm (Team) là ĐƯỜNG DUY NHẤT nối một khách hàng / cơ hội về phòng ban: bảng `customers` chỉ có
    `teamId`, không có `departmentId`. Không seed nhóm thì báo cáo "Phòng ban & Nhân viên" chỉ hiện
    đúng một dòng "Chưa phân công" cho toàn bộ dữ liệu — trông như báo cáo hỏng.
  */
  const teamIdByDepartment: Record<PersonSeed['department'], string> = {
