    { key: 'sales' as const, name: 'Nhóm Kinh doanh 1' },
  ];
  for (const team of teams) {
    const id = teamIdByDepartment[team.key];
    const departmentId = departmentIdByKey[team.key];
    await prisma.team.upsert({
      where: { id },
      update: { name: team.name, branchId, departmentId, deletedAt: null, updatedBy: 'SYSTEM' },
      create: {
        id,
        tenantId,
        branchId,
        departmentId,
        name: team.name,
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
    });
  }

  const positions = [
    { key: 'hr-head', department: 'hr', name: 'Trưởng phòng Hành chính - Nhân sự' },
    { key: 'hr-staff', department: 'hr', name: 'Nhân viên Hành chính - Nhân sự' },
    { key: 'sales-head', department: 'sales', name: 'Trưởng phòng Kinh doanh' },
    { key: 'sales-staff', department: 'sales', name: 'Nhân viên Kinh doanh' },
  ] as const;

  for (const position of positions) {
    const id = `${tenantId}-pos-${position.key}`;
    const departmentId = departmentIdByKey[position.department];
    await prisma.position.upsert({
      where: { id },
      update: { name: position.name, departmentId, deletedAt: null },
      create: {
        id,
        tenantId,
        departmentId,
        name: position.name,
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
    });
  }

  const roles = await prisma.role.findMany({
    where: { tenantId },
    select: { id: true, code: true },
  });
  const roleIdByCode = new Map(roles.map((role) => [role.code, role.id]));
  const passwordHash = await argon2.hash(DEV_PASSWORD, { type: argon2.argon2id });

  let accountCount = 0;

  for (const person of PEOPLE) {
    const employeeId = `${tenantId}-emp-${person.key}`;
    const fullName = `${person.familyName} ${person.givenName}`;
    const employeeData = {
      tenantId,
      employeeCode: person.code,
      fullName,
      familyName: person.familyName,
      givenName: person.givenName,
      branchId,
      departmentId: departmentIdByKey[person.department],
      teamId: teamIdByDepartment[person.department],
      positionId: `${tenantId}-pos-${person.position}`,
      jobTitle: person.jobTitle,
      startDate: new Date(Date.UTC(2026, 0, 1)),
      status: 'WORKING' as const,
      workEmail: person.account?.email ?? null,
    };

    // Mã nhân viên là unique theo tenant, nhưng seed upsert theo `id`: một hồ sơ tạo tay trong DB
