    // Tạo tài khoản ACTIVE kèm passwordHash để đăng nhập được ngay, bỏ qua luồng
    // gửi email mời (SMTP ở dev là placeholder).
    const user = await prisma.user.upsert({
      where: { email: person.account.email },
      update: {
        passwordHash,
        status: 'ACTIVE',
        deletedAt: null,
        fullName,
        branchId,
        teamId: teamIdByDepartment[person.department],
        updatedBy: 'SYSTEM',
      },
      create: {
        tenantId,
        email: person.account.email,
        passwordHash,
        fullName,
        status: 'ACTIVE',
        branchId,
        teamId: teamIdByDepartment[person.department],
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
