    if (!roleId) throw new Error(`Không tìm thấy role ${person.account.role}`);
    await prisma.userRole.upsert({
      where: { userId_roleId: { userId: user.id, roleId } },
      update: { dataScope: SYSTEM_ROLE_SCOPES[person.account.role], deletedAt: null },
      create: {
        tenantId,
        userId: user.id,
        roleId,
        dataScope: SYSTEM_ROLE_SCOPES[person.account.role],
      },
    });

    // Nối hồ sơ nhân sự ↔ tài khoản: RbacService lấy `departmentId` của principal
    // qua đường này, nên thiếu bước này là phân quyền theo phòng ban hỏng.
    await prisma.employee.update({
      where: { id: employeeId },
      data: { userId: user.id, updatedBy: 'SYSTEM' },
    });
    accountCount += 1;
  }

  await prisma.employeeSequence.upsert({
    where: { tenantId_year: { tenantId, year: 2026 } },
    update: { lastValue: LAST_EMPLOYEE_SEQUENCE },
    create: { tenantId, year: 2026, lastValue: LAST_EMPLOYEE_SEQUENCE },
  });

  const emails = PEOPLE.filter((person) => person.account)
    .map((person) => `${person.account!.email} (${person.account!.role})`)
    .join(', ');

  return (
    `Tổ chức dev: 2 phòng ban, ${teams.length} nhóm, ${positions.length} vị trí, ` +
    `${PEOPLE.length} nhân sự, ` +
    `${accountCount} tài khoản [${emails}] — mật khẩu chung "${DEV_PASSWORD}"`
  );
}

