import { Prisma, PrismaClient } from '@prisma/client';
import { validateScoringConfig, type KpiScoringConfig } from '@ics/shared';

/**
 * Seed dữ liệu KPI theo khung BSC — **CHỈ THƯ VIỆN ĐỊNH NGHĨA**.
 *
 * Nguyên tắc chia tầng, điểm dễ hiểu sai nhất của module:
 *
 *   - `KpiTemplate` + `KpiTemplateCriteria` = **ĐỊNH NGHĨA** ("Mục tiêu" và
 *     "Chỉ tiêu" trên giao diện), dùng lại qua nhiều kỳ. Chứa: đo cái gì, đơn vị,
 *     chấm thế nào, gộp thế nào, chia cho người thế nào.
 *     KHÔNG có trọng số, KHÔNG có mục tiêu số. Tên chỉ tiêu vì vậy là
 *     "Doanh thu", tuyệt đối không phải "Doanh thu đạt 500 triệu".
 *
 *   - `KpiPlan` + `KpiPlanMetric` = **CON SỐ CỦA MỘT KỲ**: mục tiêu + trọng số
 *     trong trụ + nhịp chia kỳ con. Seed này **KHÔNG tạo kế hoạch nào** — người
 *     dùng tự tạo để tự chọn kỳ, tập chỉ tiêu và trọng số.
 *
 * Mục tiêu thuộc PHÒNG BAN, không dùng chung: theo phân quyền hiện tại chỉ quản
 * lý phòng mới tạo/sửa được mục tiêu của phòng mình, admin chỉ đọc.
 *
 * Tỷ trọng trụ cột VẪN được seed: nó là cấu hình của phòng ban (màn Tỷ trọng),
 * không phải kế hoạch. Thiếu nó thì kế hoạch vừa tạo không ban hành được và mọi
 * điểm tổng đều bằng `null`.
 */

type Aspect = 'FINANCE' | 'CUSTOMER' | 'PROCESS' | 'PEOPLE';
type AspectWeightSet = Record<Aspect, number>;

const YEAR_CURRENT = 2026;
const YEAR_NEXT = 2027;

/** Tỷ trọng trụ cột cấp công ty — đổi giữa hai kỳ để thấy nó gắn với từng kỳ. */
const COMPANY_ASPECT_WEIGHTS: Record<number, AspectWeightSet> = {
  [YEAR_CURRENT]: { FINANCE: 50, CUSTOMER: 25, PROCESS: 10, PEOPLE: 15 },
  [YEAR_NEXT]: { FINANCE: 40, CUSTOMER: 30, PROCESS: 20, PEOPLE: 10 },
};

/** Tỷ trọng cấp phòng ban, luân phiên theo thứ tự phòng để hai phòng khác nhau. */
const DEPARTMENT_ASPECT_WEIGHTS: AspectWeightSet[][] = [
  [
    { FINANCE: 40, CUSTOMER: 30, PROCESS: 20, PEOPLE: 10 },
    { FINANCE: 25, CUSTOMER: 25, PROCESS: 25, PEOPLE: 25 },
  ],
  [
    { FINANCE: 55, CUSTOMER: 25, PROCESS: 10, PEOPLE: 10 },
    { FINANCE: 35, CUSTOMER: 35, PROCESS: 20, PEOPLE: 10 },
  ],
];

/**
 * Cột `direction` và `aggregation` là DI SẢN, suy ra từ mô hình chấm mới.
 *
 * Bản sao đúng nguyên của `DIRECTION_OF_SHAPE` / `AGGREGATION_OF_MEASURE` trong
 * `kpi-criteria-form.tsx`, để chỉ tiêu do seed tạo không phân biệt được với chỉ
 * tiêu người dùng tự nhập.
 */
const DIRECTION_OF_SHAPE = {
  UP: 'INCREASE',
  DOWN: 'DECREASE',
  // Khoảng tối ưu không "tăng" cũng không "giảm"; cột cũ buộc phải có một giá trị.
  RANGE: 'INCREASE',
} as const;

const AGGREGATION_OF_MEASURE = {
  ADDITIVE: 'SUM',
  SEMI_ADDITIVE: 'LAST',
  RATIO: 'AVG',
} as const;

type MeasuredBlueprint = {
  key: string;
  name: string;
  description: string;
  csf: string;
  kind?: 'MEASURED';
  unit: string;
  scoringShape: 'UP' | 'DOWN' | 'RANGE';
  scoringMethod: 'CONTINUOUS' | 'DISCRETE';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  allocationMode: 'DIVIDE' | 'INHERIT';
  /**
   * Cấu hình dùng chung cho MỌI kỳ. Chỉ khai khi thang đo cố định qua các năm
   * (tỷ lệ %, số ngày tồn) — cận của bảng khoảng và min/max mang ĐƠN VỊ của phép
   * đo, nên nếu mỗi kỳ một thang thì phải để trống và khai ở từng kế hoạch.
   */
  scoringConfig?: KpiScoringConfig;
  isBlocking?: boolean;
};

type PassFailBlueprint = {
  key: string;
  name: string;
  description: string;
  csf: string;
  kind: 'PASS_FAIL';
  isBlocking?: boolean;
};

type CriteriaBlueprint = MeasuredBlueprint | PassFailBlueprint;

type ObjectiveBlueprint = {
  key: string;
  aspect: Aspect;
  title: string;
  description: string;
  criteria: CriteriaBlueprint[];
};

/**
 * Thư viện mục tiêu + chỉ tiêu, nhân bản cho từng phòng ban.
 *
 * Chọn có chủ đích để PHỦ KÍN mọi trục của mô hình chấm, và mỗi tổ hợp đều gắn
 * với một phép đo mà tổ hợp đó thật sự đúng — không phải bịa ra cho đủ:
 *
 *   kind          MEASURED (15) · PASS_FAIL (2)
 *   scoringShape  UP (8) · DOWN (6) · RANGE (2)
 *   scoringMethod CONTINUOUS (12) · DISCRETE (3)
 *   measureType   ADDITIVE (4) · SEMI_ADDITIVE (4) · RATIO (9)
 *   allocation    DIVIDE (4) · INHERIT (13)
 *   config        sàn · trần · sàn+trần · bảng khoảng · min/max/dung sai · không có
 *
 * Hai ràng buộc bản chất được tôn trọng xuyên suốt (đây là lý do DIVIDE chỉ đi
 * với ADDITIVE):
 *   · chỉ đại lượng CỘNG DỒN mới chia phần cho từng người được — chia đôi một tỷ
 *     lệ phần trăm hay một mức tồn kho là vô nghĩa;
