const ASPECTS: Aspect[] = ['FINANCE', 'CUSTOMER', 'PROCESS', 'PEOPLE'];

function isPassFail(criteria: CriteriaBlueprint): criteria is PassFailBlueprint {
  return criteria.kind === 'PASS_FAIL';
}

/**
 * Dữ liệu ghi vào `kpi_template_criteria`.
 *
 * Chuẩn hoá PASS_FAIL đúng như `KpiObjectiveService.toCriteriaData`: không đơn
 * vị, gộp theo tỷ lệ, giao nguyên, không cấu hình chấm. Lệch khỏi bản đó là seed
 * tạo ra loại dữ liệu mà API không bao giờ tạo được.
 */
function toCriteriaRow(criteria: CriteriaBlueprint, sortOrder: number) {
  const common = {
    name: criteria.name,
    description: criteria.description,
    csf: criteria.csf,
    sourceType: 'MANUAL' as const,
    dataSourceId: null,
    formula: null,
    isCombined: false,
    isBlocking: criteria.isBlocking ?? false,
    sortOrder,
  };

  if (isPassFail(criteria)) {
    return {
      ...common,
      direction: 'INCREASE' as const,
      allocationMode: 'INHERIT' as const,
      aggregation: 'AVG' as const,
      kind: 'PASS_FAIL' as const,
      scoringShape: 'UP' as const,
      scoringMethod: 'CONTINUOUS' as const,
      measureType: 'RATIO' as const,
      scoringConfig: Prisma.JsonNull,
      unit: null,
    };
  }

  return {
    ...common,
    direction: DIRECTION_OF_SHAPE[criteria.scoringShape],
    allocationMode: criteria.allocationMode,
    aggregation: AGGREGATION_OF_MEASURE[criteria.measureType],
    kind: 'MEASURED' as const,
    scoringShape: criteria.scoringShape,
    scoringMethod: criteria.scoringMethod,
    measureType: criteria.measureType,
    scoringConfig: criteria.scoringConfig
      ? (criteria.scoringConfig as Prisma.InputJsonValue)
      : Prisma.JsonNull,
    unit: criteria.unit,
  };
}

/**
 * Bắt lỗi cấu hình NGAY LÚC SEED, bằng chính hàm mà contract và UI dùng.
 *
 * Bảng khoảng hở một đoạn hoặc `min > max` sẽ không nổ lúc ghi (cột là JSON tự
 * do) mà nổ lúc chấm điểm — khi đó lỗi hiện ra dưới dạng "điểm bằng null" ở một
 * màn hình cách xa đây, gần như không lần ngược được.
 */
function assertBlueprintConfigs(): void {
  for (const objective of OBJECTIVE_LIBRARY) {
    for (const criteria of objective.criteria) {
      if (isPassFail(criteria)) continue;
      const error = validateScoringConfig({
        shape: criteria.scoringShape,
        method: criteria.scoringMethod,
        config: criteria.scoringConfig ?? null,
      });
      if (error) {
        throw new Error(`Seed KPI — cấu hình chấm của "${criteria.name}" không hợp lệ: ${error}`);
      }
    }
  }
}

/**
 * Ghi một bộ tỷ trọng trụ cột.
 *
 * Compound unique có `departmentId` nullable nên KHÔNG dùng được trong `where`
 * của upsert (giới hạn Prisma) ⇒ upsert theo id tiền định.
 */
async function upsertAspectWeights(
  prisma: PrismaClient,
  tenantId: string,
  scope: 'COMPANY' | 'DEPARTMENT',
  departmentId: string | null,
  periodYear: number,
  weights: AspectWeightSet,
): Promise<void> {
  for (const aspect of ASPECTS) {
    const id = `${tenantId}-kpi-aspect-${scope === 'COMPANY' ? 'company' : departmentId}-${aspect}-${periodYear}`;
    const weight = new Prisma.Decimal(weights[aspect]);
    await prisma.kpiAspectWeight.upsert({
      where: { id },
      update: { weight, updatedBy: 'SYSTEM' },
      create: {
        id,
        tenantId,
        scope,
        departmentId,
        aspect,
        periodYear,
        weight,
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
    });
  }
}

export async function seedKpi(prisma: PrismaClient, tenantId: string): Promise<string> {
  assertBlueprintConfigs();

  const departments = await prisma.department.findMany({
    where: { tenantId, deletedAt: null },
    orderBy: { name: 'asc' },
    select: { id: true, name: true },
  });
  if (departments.length === 0) return 'KPI: bỏ qua (chưa có phòng ban nào)';

  for (const year of [YEAR_CURRENT, YEAR_NEXT]) {
    await upsertAspectWeights(
      prisma,
      tenantId,
      'COMPANY',
      null,
      year,
      COMPANY_ASPECT_WEIGHTS[year],
    );
  }

  let objectiveCount = 0;
  let criteriaCount = 0;
  let removedPlans = 0;
  let retiredCriteria = 0;

  for (const [index, department] of departments.entries()) {
    const weightPair = DEPARTMENT_ASPECT_WEIGHTS[index % DEPARTMENT_ASPECT_WEIGHTS.length];
    await upsertAspectWeights(
      prisma,
      tenantId,
      'DEPARTMENT',
      department.id,
      YEAR_CURRENT,
      weightPair[0],
    );
    await upsertAspectWeights(
      prisma,
      tenantId,
      'DEPARTMENT',
      department.id,
      YEAR_NEXT,
      weightPair[1],
    );

    const objectiveIds: string[] = [];
    const criteriaIds: string[] = [];

    for (const blueprint of OBJECTIVE_LIBRARY) {
      const objectiveId = `${department.id}-kpi-obj-${blueprint.key}`;
      objectiveIds.push(objectiveId);
      await prisma.kpiTemplate.upsert({
        where: { id: objectiveId },
        update: {
          aspect: blueprint.aspect,
          departmentId: department.id,
          title: blueprint.title,
          description: blueprint.description,
          updatedBy: 'SYSTEM',
          deletedAt: null,
        },
        create: {
          id: objectiveId,
          tenantId,
          aspect: blueprint.aspect,
          departmentId: department.id,
          title: blueprint.title,
          description: blueprint.description,
          createdBy: 'SYSTEM',
          updatedBy: 'SYSTEM',
        },
      });
      objectiveCount += 1;

      for (const [sortOrder, criteria] of blueprint.criteria.entries()) {
        const criteriaId = `${department.id}-kpi-crit-${criteria.key}`;
        criteriaIds.push(criteriaId);
        const data = toCriteriaRow(criteria, sortOrder);
        await prisma.kpiTemplateCriteria.upsert({
          where: { id: criteriaId },
          update: { ...data, templateId: objectiveId, deletedAt: null },
          create: { id: criteriaId, tenantId, templateId: objectiveId, ...data },
        });
        criteriaCount += 1;
      }
    }

    /*
      Dọn phần thư viện do SEED tạo ra ở lần chạy trước mà nay không còn trong
      danh sách trên (đổi khoá, bỏ bớt chỉ tiêu).

      XOÁ MỀM chứ không xoá cứng: một chỉ tiêu có thể đã được đưa vào kế hoạch
      của người dùng, mà `KpiPlanMetric.criteria` là `onDelete: Restrict` —
      xoá cứng sẽ nổ FK và làm hỏng cả lượt seed. Lọc theo tiền tố id nên chỉ
      chạm vào hàng do seed sinh, không đụng chỉ tiêu người dùng tự tạo.
    */
    const retired = await prisma.kpiTemplateCriteria.updateMany({
      where: {
        tenantId,
        id: { startsWith: `${department.id}-kpi-crit-`, notIn: criteriaIds },
        deletedAt: null,
      },
      data: { deletedAt: new Date() },
    });
    retiredCriteria += retired.count;

    await prisma.kpiTemplate.updateMany({
      where: {
        tenantId,
        id: { startsWith: `${department.id}-kpi-obj-`, notIn: objectiveIds },
        deletedAt: null,
      },
      data: { deletedAt: new Date() },
    });

    /*
      Seed KHÔNG tạo kế hoạch KPI nữa — người dùng tự tạo để tự chọn kỳ, tập chỉ
      tiêu, trọng số và nhịp chia.

      Phải xoá cả những kế hoạch mà bản seed CŨ đã tạo, nếu không chúng nằm lại
      trong DB và "seed không tạo kế hoạch nào" là sai ngay sau lần chạy đầu.
      Chỉ nhắm đúng id do seed cũ sinh ra (`<dept>-kpi-plan-<năm>`); kế hoạch
      người dùng tự tạo mang cuid nên không khớp tiền tố này. Xoá cứng an toàn:
      mọi bảng con (chỉ tiêu, lưới kỳ, lịch sử nhập) đều `onDelete: Cascade`.
    */
    const removed = await prisma.kpiPlan.deleteMany({
      where: { tenantId, id: { startsWith: `${department.id}-kpi-plan-` } },
    });
    removedPlans += removed.count;
  }

  const perDepartment = OBJECTIVE_LIBRARY.length;
  const criteriaPerDepartment = OBJECTIVE_LIBRARY.reduce(
    (sum, objective) => sum + objective.criteria.length,
    0,
  );

  return (
    `KPI: ${departments.length} phòng ban × (${perDepartment} mục tiêu, ` +
    `${criteriaPerDepartment} chỉ tiêu) = ${objectiveCount} + ${criteriaCount} bản ghi; ` +
    `tỷ trọng trụ cột kỳ ${YEAR_CURRENT} + ${YEAR_NEXT}; ` +
    `KHÔNG tạo kế hoạch KPI (đã gỡ ${removedPlans} kế hoạch do seed cũ tạo, ` +
    `ngừng dùng ${retiredCriteria} chỉ tiêu cũ)`
  );
}

