import { calendarLateDays } from '@ics/shared';
import type { PrismaService } from '../common/prisma.service';

/**
 * Danh mục nguồn dữ liệu KPI — nơi duy nhất định nghĩa "số thực tế của chỉ tiêu lấy từ đâu".
 *
 * Mỗi nguồn tự chịu trách nhiệm LỌC THEO KỲ KPI. Trước đây các nguồn cộng dồn toàn bộ lịch sử
 * (dù mô tả ghi "trong kỳ KPI"), nên điểm KPI tháng nào cũng giống nhau và tăng vô hạn theo
 * thời gian — sai về nghiệp vụ. Giờ mọi nguồn đều nhận `period` và chỉ tính trong khoảng đó.
 *
 * Thêm nguồn mới: khai một phần tử vào KPI_DATA_SOURCES là xong — không phải sửa chỗ chấm điểm.
 *
 * ── HAI LOẠI NGUỒN ──────────────────────────────────────────────────────────────────────
 *
 *   RAW      MỘT phép đo. Được phép tính toán trong TỪNG DÒNG dữ liệu (số ngày trễ của một
 *            công việc, số giờ xử lý một ticket) và được phép gom từ nhiều bảng cùng nói về
 *            một thứ (doanh thu = cơ hội thắng + hợp đồng ký). Dùng làm chỉ tiêu KPI.
 *
 *   DERIVED  Đã GHÉP HAI phép đo độc lập thành tỷ lệ/trung bình. CHỈ dùng cho trang chủ.
 *
 * Vì sao DERIVED bị cấm làm chỉ tiêu KPI: KPI gộp nhiều kỳ con lên cả năm, mà tỷ lệ thì không
 * gộp được. Quý 1 thắng 10/40, quý 2 thắng 30/60 ⇒ cả năm là 40/100 = 40%, KHÔNG phải trung
 * bình của 25% và 50% = 37.5%. Muốn đúng thì tử số và mẫu số phải là hai nguồn RAW riêng, rồi
 * `sourceType = FORMULA` chia lại ở TỪNG cấp gộp. Trang chủ chỉ hiển thị một kỳ, không gộp,
 * nên nhận sẵn tỷ lệ là hoàn toàn đúng — đó là lý do hai bên có luật khác nhau.
 */

export interface KpiPeriod {
  /** Đầu kỳ, tính cả mốc này. */
  start: Date;
  /** Cuối kỳ, tính cả mốc này. */
  end: Date;
}

/**
 * Bối cảnh khi lấy số thực tế.
 *
 * `ownerUserId` rất quan trọng: KPI là của TỪNG NGƯỜI, nên chỉ tiêu "doanh thu" của nhân viên A
 * phải là doanh thu do A phụ trách, không phải doanh thu toàn công ty. Khi không truyền
 * (vd xem trước lúc soạn chỉ tiêu) thì lấy số của cả tenant.
 */
export interface KpiResolveContext {
  period: KpiPeriod;
  ownerUserId?: string | null;
  /**
   * Giới hạn theo MỘT NHÓM người phụ trách — dùng khi trang chủ hiển thị số của nhóm / phòng ban /
   * chi nhánh mà người xem được phép đọc. Có `ownerUserId` thì `ownerUserId` thắng (KPI cá nhân).
   *
   * Mảng RỖNG có nghĩa "không ai trong phạm vi" và phải cho ra 0. Đây là lý do tồn tại của
   * `ownerIdFilter` bên dưới: nếu để mảng rỗng rơi vào nhánh "không lọc gì" thì một trưởng nhóm
   * chưa có thành viên sẽ nhìn thấy số của TOÀN BỘ công ty — lộ dữ liệu, không phải hiển thị sai.
   */
  ownerUserIds?: readonly string[] | null;
}

/**
 * Bối cảnh lấy số theo LÔ: một kỳ, nhiều người, tách riêng số của từng người.
 *
 * Đây là thứ khiến KPI tự động dùng được trong thực tế. Một kế hoạch phòng ban có 12 nhân viên
 * × 3 chỉ tiêu tự động; gọi `resolve` từng người là 36 lượt × ~2 truy vấn = ~72 truy vấn cho một
 * lần mở trang. `resolveByOwner` gom lại còn ĐÚNG MỘT truy vấn cho mỗi nguồn.
 */
export interface KpiBatchContext {
  period: KpiPeriod;
  /** Danh sách người cần lấy số. Rỗng ⇒ không truy vấn gì cả. */
  ownerUserIds: readonly string[];
}

type ScopedPrisma = PrismaService['scoped'];

/** RAW dùng được cho KPI; DERIVED đã ghép sẵn nên chỉ hợp với trang chủ. */
export type KpiDataSourceKind = 'RAW' | 'DERIVED';

/**
 * Nguồn có tách được theo người không.
 *
 * `TENANT_ONLY` là nguồn KHÔNG có cột người phụ trách (vd lead từ chiến dịch marketing). Giao
 * một chỉ tiêu như vậy cho cá nhân thì cả 12 người cùng nhận số của toàn công ty — sai và rất
 * khó phát hiện, nên nơi phân giải phải từ chối thay vì điền bừa.
 */
export type KpiOwnerScope = 'PER_OWNER' | 'TENANT_ONLY';

export interface KpiDataSourceDef {
  id: string;
  name: string;
  description: string;
  kind: KpiDataSourceKind;
  ownerScope: KpiOwnerScope;
  /**
   * Cột ngày quyết định một bản ghi THUỘC KỲ NÀO, viết cho người dùng đọc.
   *
   * Bắt buộc phải hiện ra lúc chọn nguồn: "số công việc trong tháng 8" có ít nhất ba nghĩa
   * (giao trong tháng 8 / đến hạn trong tháng 8 / hoàn thành trong tháng 8) và ba con số đó
   * khác hẳn nhau. Để người khai tự đoán là mở đường cho tranh cãi lúc chốt lương.
   */
  periodBasis: string;
  /** Cột xác định "của ai", viết cho người dùng đọc. */
  ownerBasis: string;
  defaultValue: string;
  defaultUnit: string;
  /** Lấy số thực tế của nguồn này trong kỳ (và theo người phụ trách nếu có). */
  resolve: (prisma: ScopedPrisma, context: KpiResolveContext) => Promise<number>;
  /**
   * Bản gộp lô: số của TỪNG người trong một lần truy vấn.
   *
   * Người không có dòng dữ liệu nào thì VẮNG MẶT trong Map, và nơi gọi hiểu là 0 — đúng với
   * mọi nguồn RAW vì chúng đều là đếm/cộng ("không bán được đơn nào" = 0 thật). Các số trung
   * bình/tỷ lệ không đi đường này: chúng là DERIVED, và bản KPI của chúng được ghép bằng công
   * thức từ tử/mẫu, nên 0/0 ra `null` = "chưa đánh giá được" thay vì 0 điểm oan.
   */
  resolveByOwner?: (prisma: ScopedPrisma, context: KpiBatchContext) => Promise<Map<string, number>>;
}

function toNumber(value: unknown): number {
  if (value === null || value === undefined) return 0;
  const parsed = Number.parseFloat(String(value));
  return Number.isFinite(parsed) ? parsed : 0;
}

/** Khoảng thời gian dạng Prisma filter cho một cột ngày. */
function inPeriod(period: KpiPeriod) {
  return { gte: period.start, lte: period.end };
}

/**
 * Bộ lọc cho một cột kiểu `ownerId`. Trả `undefined` = không giới hạn (cả tenant), dùng cho scope
 * ALL và cho lúc xem trước chỉ tiêu. Tách riêng để các nguồn lọc qua quan hệ (`opportunity: {...}`)
 * dùng chung một luật với `byOwner`.
 */
function ownerIdFilter(context: KpiResolveContext): string | { in: string[] } | undefined {
  if (context.ownerUserId) return context.ownerUserId;
  if (context.ownerUserIds) return { in: [...context.ownerUserIds] };
  return undefined;
}

/** Điều kiện lọc theo người phụ trách; rỗng khi tính cho cả tenant. */
function byOwner(context: KpiResolveContext) {
  const ownerId = ownerIdFilter(context);
  return ownerId ? { ownerId } : {};
}

/**
 * Gom kết quả `groupBy` thành bảng tra theo người.
 *
 * Dòng không có người phụ trách (cột nullable) bị BỎ, không dồn vào ai: gán việc vô chủ cho một
 * người nào đó là bịa số vào KPI của họ.
 */
function ownerMap<T>(
  rows: readonly T[],
  ownerOf: (row: T) => string | null | undefined,
  valueOf: (row: T) => number,
): Map<string, number> {
  const result = new Map<string, number>();
  for (const row of rows) {
    const owner = ownerOf(row);
    if (!owner) continue;
    result.set(owner, (result.get(owner) ?? 0) + valueOf(row));
  }
  return result;
}

/** Số giờ giữa hai mốc thời gian. */
function hoursBetween(from: Date, to: Date): number {
  return (to.getTime() - from.getTime()) / (60 * 60 * 1000);
}

/** Số phút giữa hai mốc thời gian. */
function minutesBetween(from: Date, to: Date): number {
  return (to.getTime() - from.getTime()) / (60 * 1000);
}

/** Điều kiện lọc ticket cơ bản: chưa xoá, thuộc người phụ trách nếu có. */
function ticketBase(context: KpiResolveContext) {
  return { deletedAt: null, ...byOwner(context) };
}

/**
 * Mốc chốt sổ của kỳ KPI: cuối kỳ, nhưng không vượt quá hiện tại.
 *
 * Xem "tháng này" vào ngày 13 mà lấy mốc ngày 31 thì mọi khoản đến hạn ngày 14–31 đều bị đếm là quá
 * hạn — trang chủ từng hiển thị sai vì đúng lỗi này. Tương lai thì chưa có gì quá hạn được.
 */
function asOfEnd(period: KpiPeriod): Date {
  const now = new Date();
  return period.end < now ? period.end : now;
}

/**
 * Đơn hàng ĐÃ DUYỆT — chứng từ ghi nhận doanh thu DUY NHẤT của hệ thống.
 *
 * Trước đây doanh thu được ghép từ "cơ hội chuyển sang THẮNG" + "hợp đồng COMPLETED ký trong kỳ", và
