import { PrismaClient } from '@prisma/client';
import { computeDocumentTotals } from '@ics/shared';

/**
 * Sổ khách hàng 6 tháng cho môi trường demo.
 *
 * Vì sao cần: seed gốc chỉ tạo dữ liệu Ở HÔM NAY, nên trang chủ mở ra là một biểu đồ "doanh thu 6
 * tháng" phẳng lì với đúng một cột, phễu hai bậc, và mọi thẻ số ghi "chưa có dữ liệu kỳ trước để
 * so" — không nhìn ra được cái gì. Bộ này dựng một quyển sổ có bề dày thời gian: khách hàng, cơ hội
 * thắng/thua/đang mở, đơn hàng đã duyệt, hợp đồng, đợt thu tiền, hoạt động — rải đủ 6 tháng.
 *
 * Ba điều phải giữ:
 *
 *   1. CHIA CHO NHIỀU CHỦ SỞ HỮU. Bảng "Nhân viên dẫn đầu" và mọi thứ ở phạm vi OWN đều lọc theo
 *      `ownerId`. Dồn hết cho admin thì nhân viên đăng nhập vào thấy trang trống, đúng như bug đang
 *      gặp — và bảng xếp hạng chỉ có một dòng.
 *   2. MỐC THỜI GIAN TƯƠNG ĐỐI so với `now`. Chạy lại tháng sau thì sổ tự trượt theo, không phải
 *      sửa seed. Đổi lại: id cố định + `upsert` nên chạy nhiều lần không sinh thêm bản ghi.
 *   3. KHÔNG có ngày trong tương lai. Kỳ đang chạy được chốt ở hôm nay; một cơ hội thắng ngày 28
 *      trong khi hôm nay là mùng 10 sẽ biến mất khỏi thẻ số mà vẫn nằm trong biểu đồ tháng.
 *
 * Số liệu của "Nguyễn Thị Lan" (`lan.nguyen@demo.local`) được chọn có chủ ý để khớp với kế hoạch KPI
 * trong `seed-kpi.ts`: tháng này cô ấy vượt chỉ tiêu khách hàng mới, hụt doanh thu, và hụt xa số
 * hoạt động — ba vùng màu khác nhau trên đồng hồ chỉ tiêu ở trang chủ. Đổi bảng dưới đây thì phải
 * xem lại `INDIVIDUAL_ALLOCATION` bên `seed-kpi.ts`, nếu không phần trăm đạt mất ý nghĩa demo.
 */

/**
 * Số tháng dựng lùi lại, tính cả tháng hiện tại.
 *
 * 24 chứ không phải 6: biểu đồ trang chủ có mốc "cùng kỳ năm trước". Chỉ có 6 tháng thì đường so
 * sánh đó rỗng hoàn toàn — mà một đường rỗng nhìn giống hệt một đường bằng 0, tức là còn tệ hơn ẩn
 * nó đi. 24 tháng cho cả năm nay và năm ngoái đủ 12 điểm.
 */
const MONTHS = 24;

/** Số tháng được viết tay trong `SELLER_BOOKS` dưới đây; các tháng còn lại suy ra từ chúng. */
const AUTHORED_MONTHS = 6;

/**
 * Số tháng viết tay ĐỦ NGÀY (bỏ tháng cuối, tức tháng đang chạy).
 *
 * Tháng đang chạy cố ý thấp vì mới đi được vài ngày. Đem nó đi nhân bản cho các tháng đã qua thì
 * biểu đồ có những cái hố không giải thích được, và người xem sẽ đi tìm nguyên nhân kinh doanh cho
 * một tạo tác của seed.
 */
const FULL_MONTHS = AUTHORED_MONTHS - 1;

/**
 * Năm trước bằng 78% năm nay.
 *
 * Đủ thấp để đường "cùng kỳ năm trước" nằm tách ra, đủ cao để vẫn là cùng một doanh nghiệp đang lớn
 * dần chứ không phải hai công ty khác nhau.
 */
const PRIOR_YEAR_FACTOR = 0.78;

const MILLION = 1_000_000;

type Stage = 'MOI' | 'BAO_GIA' | 'THUONG_THAO';

/** Một tháng làm việc của một người. Đơn vị tiền: TRIỆU đồng, đổi sang VNĐ khi ghi. */
interface MonthlyBook {
  /** Cơ hội chuyển sang THẮNG trong tháng. Nuôi doanh thu đã chốt + thương vụ đã chốt. */
  won: number[];
  /**
   * Thương vụ chốt trong tháng, tính bằng TRIỆU đồng — mỗi số là một đơn hàng ĐÃ DUYỆT kèm một hợp
   * đồng cùng giá trị. Nuôi doanh thu đã chốt, công nợ, xếp hạng khách hàng và nhân viên.
   */
  contracts: number[];
  /** Cơ hội THUA tạo trong tháng — mẫu số của tỷ lệ chuyển đổi, và một bậc của phễu. */
  lost: number;
  /** Cơ hội còn đang mở, theo giai đoạn. Phễu chỉ có hình khi các bậc giữa có số. */
  open: { stage: Stage; amount: number }[];
  /** Khách hàng mới tạo trong tháng. */
  customers: number;
  /** Hoạt động CRM (gọi, gặp, email, ghi chú) trong tháng. */
  activities: number;
}

interface SellerBook {
  key: string;
  /** `null` = tài khoản admin (id truyền vào), khác `null` = tra theo email. */
  email: string | null;
  months: MonthlyBook[];
}

/**
 * Ba quyển sổ, xếp theo thứ tự tháng cũ → tháng này.
 *
 * Tháng cuối cùng cố ý THẤP hơn: kỳ đang chạy mới đi được vài ngày. Vẽ nó ngang bằng các tháng đủ
 * 30 ngày là dạy người xem đọc sai biểu đồ.
 */
const SELLER_BOOKS: SellerBook[] = [
  {
    key: 'lan',
    email: 'lan.nguyen@demo.local',
    months: [
      { won: [180, 140], contracts: [160], lost: 1, open: [], customers: 2, activities: 22 },
      { won: [220, 120], contracts: [200], lost: 2, open: [], customers: 2, activities: 26 },
      { won: [160], contracts: [180, 120], lost: 1, open: [], customers: 2, activities: 19 },
      { won: [260, 150], contracts: [240], lost: 2, open: [], customers: 3, activities: 28 },
      { won: [200, 180], contracts: [190], lost: 1, open: [], customers: 2, activities: 24 },
      {
        won: [110, 70],
        contracts: [120],
        lost: 1,
        // 2 thắng / 5 cơ hội tạo mới trong tháng = tỷ lệ chuyển đổi 40%.
        open: [
          { stage: 'BAO_GIA', amount: 95 },
          { stage: 'THUONG_THAO', amount: 210 },
        ],
        customers: 3,
        activities: 9,
      },
    ],
  },
  {
    key: 'anh',
    email: 'anh.tran@demo.local',
    months: [
      { won: [320], contracts: [280], lost: 1, open: [], customers: 1, activities: 14 },
      { won: [400, 200], contracts: [350], lost: 1, open: [], customers: 2, activities: 16 },
      { won: [280], contracts: [300], lost: 2, open: [], customers: 1, activities: 12 },
      { won: [520, 240], contracts: [480], lost: 1, open: [], customers: 2, activities: 18 },
      { won: [380], contracts: [420], lost: 1, open: [], customers: 1, activities: 15 },
      {
        won: [300],
        contracts: [260],
        lost: 1,
        open: [
          { stage: 'MOI', amount: 180 },
          { stage: 'THUONG_THAO', amount: 640 },
        ],
        customers: 2,
        activities: 6,
      },
    ],
  },
  {
    key: 'admin',
    email: null,
    months: [
      { won: [150], contracts: [], lost: 0, open: [], customers: 1, activities: 6 },
      { won: [], contracts: [180], lost: 1, open: [], customers: 1, activities: 4 },
      { won: [220], contracts: [], lost: 0, open: [], customers: 1, activities: 5 },
      { won: [], contracts: [260], lost: 1, open: [], customers: 1, activities: 7 },
      { won: [190], contracts: [], lost: 0, open: [], customers: 1, activities: 5 },
      {
        won: [],
        contracts: [],
        lost: 0,
        open: [{ stage: 'MOI', amount: 130 }],
        customers: 1,
        activities: 3,
      },
    ],
  },
];

/**
 * Tháng làm việc của một người tại mốc `monthsAgo`, suy ra từ 6 tháng viết tay.
 *
 * Ba vùng, và ranh giới giữa chúng là chỗ dễ sai nhất của bộ seed này:
 *
 *   - `< 6`: lấy đúng tháng đã viết tay. Đây là cửa sổ gần nhất, cũng là cửa sổ khớp với kế hoạch
 *     KPI trong `seed-kpi.ts`, nên không được suy diễn gì ở đây.
 *   - `6..11`: quay vòng 5 tháng ĐỦ NGÀY. Cùng năm nên không hạ tỷ lệ.
 *   - `>= 12`: soi lại tháng cùng kỳ của năm nay rồi nhân `PRIOR_YEAR_FACTOR`, để mỗi điểm năm ngoái
 *     có đúng một điểm năm nay đối chiếu. Riêng mốc 12 soi vào tháng đang chạy (chưa đủ ngày) nên
 *     lấy một tháng đủ thay thế.
 */
function monthFor(book: SellerBook, monthsAgo: number): MonthlyBook {
  if (monthsAgo < AUTHORED_MONTHS) return book.months[AUTHORED_MONTHS - 1 - monthsAgo];
  if (monthsAgo < 12) return book.months[(monthsAgo - AUTHORED_MONTHS) % FULL_MONTHS];

  const mirror = monthsAgo - 12;
  const base = mirror === 0 ? book.months[0] : monthFor(book, mirror);
