 *
 * Vì sao phải trả về: số lượng hàng là số nguyên nên tổng đơn lệch khỏi `targetValue` tối đa một
 * đơn vị hàng. Hợp đồng đi kèm ghi lại đúng con số trả về này — hai màn hình soi vào cùng một
 * thương vụ mà ra hai số tiền khác nhau là lỗi người dùng báo lên đầu tiên.
 */
async function writeApprovedOrder(
  prisma: PrismaClient,
  ctx: { tenantId: string; adminUserId: string; catalogue: CatalogueItem[] },
  spec: {
    id: string;
    code: string;
    customer: { id: string; name: string };
    ownerId: string;
    teamId: string | null;
    orderDate: Date;
    targetValue: number;
    /** Số tháng kể từ khi đặt hàng, để suy ra đã thu tới đâu. */
    monthsAgo: number;
    /** Vị trí trong danh mục để lấy giỏ hàng — quay vòng cho mỗi đơn một cặp mã khác nhau. */
    basketCursor: number;
  },
): Promise<number> {
  const { tenantId, adminUserId, catalogue } = ctx;
  const picks = BASKET_SHARES.map(
    (_, slot) => catalogue[(spec.basketCursor + slot) % catalogue.length],
  );

  /*
    Ngân sách TRƯỚC THUẾ, suy ngược từ giá trị đơn muốn có. Cộng thẳng `targetValue` vào các dòng sẽ
    ra đơn đắt hơn kế hoạch đúng bằng phần VAT — mà kế hoạch KPI bên `seed-kpi.ts` được đặt theo
