  */
  const vatWeight = BASKET_SHARES.reduce(
    (sum, share, slot) => sum + share * (1 + picks[slot].vatPercent / 100),
    0,
  );
  const budget = spec.targetValue / vatWeight;

  const lines = picks.map((product, slot) => ({
    product,
    // Tối thiểu 1: mã hàng đắt hơn phần ngân sách của nó vẫn phải ra một dòng có thật.
    quantity: Math.max(1, Math.round((budget * BASKET_SHARES[slot]) / product.unitPrice)),
  }));
  const totals = computeDocumentTotals(
    lines.map((line) => ({
      quantity: line.quantity,
      unitPrice: line.product.unitPrice,
      discountPercent: 0,
      discountAmount: 0,
      vatPercent: line.product.vatPercent,
    })),
    { discountPercent: 0, discountAmount: 0, vatPercent: 0, shippingFee: 0, installationFee: 0 },
  );

