    Đợt cuối lấy phần CÒN LẠI chứ không nhân phần trăm: 40% + 60% của một số lẻ làm tròn riêng từng
    đợt có thể lệch tổng đơn vài đồng, và vài đồng đó biến một đơn đã thu đủ thành đơn "còn nợ 1đ"
    nằm mãi trên thẻ công nợ.
  */
  const amounts = INSTALMENTS.map((part, index) =>
    index === INSTALMENTS.length - 1
      ? totals.grandTotal - Math.round((totals.grandTotal * INSTALMENTS[0].percent) / 100)
      : Math.round((totals.grandTotal * part.percent) / 100),
  );

  const collected = spec.monthsAgo >= FULLY_COLLECTED_AFTER_MONTHS;
  const advanced = spec.monthsAgo > 0;
  const isPaid = [advanced, collected];
  // Bất biến của `SalesOrderService.syncPaymentState`: đã thu = tổng các đợt đã đánh dấu thu. Lệch
  // ở đây là cột "Còn nợ" và thẻ "Công nợ phải thu" nói hai chuyện khác nhau trên cùng một đơn.
  const paidAmount = amounts.reduce((sum, amount, index) => sum + (isPaid[index] ? amount : 0), 0);

  const data = {
    code: spec.code,
    customerId: spec.customer.id,
    customerName: spec.customer.name,
    orderDate: spec.orderDate,
    status: 'APPROVED' as const,
    paymentStatus:
      paidAmount <= 0
        ? ('UNPAID' as const)
        : paidAmount >= totals.grandTotal
          ? ('PAID' as const)
          : ('PARTIAL' as const),
    subtotal: totals.subtotal,
    vatAmount: totals.vatAmount,
    grandTotal: totals.grandTotal,
    paidAmount,
    approvedBy: spec.ownerId,
    approvedAt: spec.orderDate,
    ownerId: spec.ownerId,
    teamId: spec.teamId,
    createdAt: spec.orderDate,
  };
  await prisma.salesOrder.upsert({
    where: { id: spec.id },
    update: { ...data, deletedAt: null, updatedBy: adminUserId },
    create: { id: spec.id, tenantId, ...data, createdBy: adminUserId, updatedBy: adminUserId },
  });

  for (const [slot, line] of lines.entries()) {
    const itemData = {
      productId: line.product.id,
      productCode: line.product.code,
      productName: line.product.name,
      unitName: line.product.unitName,
      quantity: line.quantity,
      unitPrice: line.product.unitPrice,
      vatPercent: line.product.vatPercent,
      lineTotal: totals.lines[slot].lineTotal,
      sortOrder: slot,
    };
    await prisma.salesOrderItem.upsert({
      where: { id: `${spec.id}-item-${slot + 1}` },
      update: { ...itemData, deletedAt: null },
      create: { id: `${spec.id}-item-${slot + 1}`, tenantId, orderId: spec.id, ...itemData },
    });
  }

  /*
    Xoá sạch lần thu của đơn rồi dựng lại: seed là chủ sở hữu duy nhất của những đơn này (id cố
    định), nên nó phải là nguồn duy nhất của sổ thu — cùng nguyên tắc `SalesOrderService` áp cho lịch
    thanh toán khi sửa đơn.

    Không có dòng này thì `upsert` theo id cố định vẫn cộng thêm vào những lần thu do migration
    `20260816090000` backfill (id `cuid()`, không trùng): tiền được tính hai lần, `paidAmount` và sổ
    thu lệch nhau, công nợ ra số ÂM. Đo trên DB đang chạy: 60/64 đơn lệch, tổng còn nợ -10,9 tỷ.
  */
  await prisma.salesOrderReceipt.deleteMany({ where: { orderId: spec.id } });

  for (const [index, part] of INSTALMENTS.entries()) {
    const paymentData = {
      name: part.name,
      percent: part.percent,
      amount: amounts[index],
      dueDate: new Date(spec.orderDate.getTime() + part.dueInDays * DAY),
      isPaid: isPaid[index],
      paidAt: isPaid[index]
        ? new Date(spec.orderDate.getTime() + part.dueInDays * DAY)
        : (null as Date | null),
      sortOrder: index,
    };
    await prisma.salesOrderPayment.upsert({
      where: { id: `${spec.id}-payment-${index + 1}` },
      update: { ...paymentData, deletedAt: null },
      create: {
        id: `${spec.id}-payment-${index + 1}`,
        tenantId,
        orderId: spec.id,
        ...paymentData,
      },
    });

    /*
      Lần thu tương ứng. Cờ `isPaid` ở trên chỉ nói TÌNH TRẠNG KỲ; SỐ TIỀN đã thu nằm ở
      `SalesOrderReceipt` và chỉ số công nợ đọc thẳng bảng đó (`orderOutstandingAsOf` trong
      `src/kpi/kpi-data-sources.ts`). Thiếu khối này thì DB mới seed có `paidAmount` khác 0 mà không
      có đồng nào trong sổ thu: thẻ "Công nợ phải thu" báo còn nợ trọn giá trị đơn, lệch đúng phần đã
      thu so với cột "Còn nợ" — chính là lỗi vừa sửa, tái sinh qua đường dữ liệu mẫu.
    */
    if (isPaid[index]) {
      await prisma.salesOrderReceipt.create({
        data: {
          id: `${spec.id}-receipt-${index + 1}`,
          tenantId,
          orderId: spec.id,
          amount: amounts[index],
          receivedAt: paymentData.dueDate,
          createdBy: adminUserId,
        },
      });
    }
  }

  return totals.grandTotal;
}

export async function seedDemoSales(
  prisma: PrismaClient,
  context: { tenantId: string; adminUserId: string; now?: Date },
): Promise<string> {
  const { tenantId, adminUserId } = context;
  const now = context.now ?? new Date();

  /**
   * Mốc thời gian của một sự kiện.
   *
   * Giờ cố định 03:00 UTC = 10:00 giờ Việt Nam: nằm giữa ngày ở cả hai múi giờ, nên sự kiện không
   * bao giờ nhảy sang ngày khác khi báo cáo quy về lịch Bangkok. Kẹp lại ở `now` để tháng đang chạy
   * không có mốc nào ở tương lai.
   */
  const at = (monthsAgo: number, sequence: number): Date => {
    const day = EVENT_DAYS[sequence % EVENT_DAYS.length];
    const stamp = new Date(
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - monthsAgo, day, 3, 0, 0),
    );
    return stamp.getTime() > now.getTime() ? new Date(now.getTime() - 60 * 60 * 1000) : stamp;
  };

  /*
    Danh mục hàng đọc từ DB chứ không chép lại vào đây: `seed.ts` dựng bốn mã hàng demo TRƯỚC khi gọi
    hàm này. Chép giá và thuế sang file này là dựng một bản sao thứ hai sẽ trôi khỏi bản gốc ngay lần
    ai đó sửa giá.
  */
  const catalogue = (
    await prisma.product.findMany({
      where: { tenantId, deletedAt: null },
      select: {
        id: true,
        code: true,
        name: true,
        retailPrice: true,
        vatPercent: true,
        unit: { select: { name: true } },
      },
      orderBy: { code: 'asc' },
    })
  )
    .map((product) => ({
      id: product.id,
      code: product.code,
      name: product.name,
      unitName: product.unit?.name ?? null,
      unitPrice: Number(product.retailPrice),
      vatPercent: Number(product.vatPercent),
    }))
    // Giá 0 thì không suy ra được số lượng: bỏ mã đó ra thay vì chia cho 0.

