 * trang chủ đều là tổng đơn trừ phần đã thu. Đơn một đợt thì chỉ có hai trạng thái nợ đủ hoặc hết
 * nợ, không bao giờ ra THU MỘT PHẦN — mà ngoài đời đó mới là trạng thái thường gặp nhất.
 */
const INSTALMENTS = [
  { name: 'Đợt 1 - Tạm ứng', percent: 40, dueInDays: 7 },
  { name: 'Đợt 2 - Thanh toán còn lại', percent: 60, dueInDays: 30 },
