async function writeApprovedOrder(
  prisma: PrismaClient,
  ctx: { tenantId: string; adminUserId: string; catalogue: CatalogueItem[] },
  spec: {
    id: string;
    code: string;
    customer: { id: string; name: string };
    ownerId: string;
    teamId: string | null;
    orderDate: Date;
    targetValue: number;
    /** Số tháng kể từ khi đặt hàng, để suy ra đã thu tới đâu. */
    monthsAgo: number;
    /** Vị trí trong danh mục để lấy giỏ hàng — quay vòng cho mỗi đơn một cặp mã khác nhau. */
    basketCursor: number;
  },
): Promise<number> {
  const { tenantId, adminUserId, catalogue } = ctx;
  const picks = BASKET_SHARES.map(
    (_, slot) => catalogue[(spec.basketCursor + slot) % catalogue.length],
  );

  /*
    Ngân sách TRƯỚC THUẾ, suy ngược từ giá trị đơn muốn có. Cộng thẳng `targetValue` vào các dòng sẽ
    ra đơn đắt hơn kế hoạch đúng bằng phần VAT — mà kế hoạch KPI bên `seed-kpi.ts` được đặt theo
    những con số trong `SELLER_BOOKS`, nên lệch ở đây là phần trăm đạt chỉ tiêu mất ý nghĩa demo.
  */
  const vatWeight = BASKET_SHARES.reduce(
    (sum, share, slot) => sum + share * (1 + picks[slot].vatPercent / 100),
    0,
  );
  const budget = spec.targetValue / vatWeight;

  const lines = picks.map((product, slot) => ({
    product,
    // Tối thiểu 1: mã hàng đắt hơn phần ngân sách của nó vẫn phải ra một dòng có thật.
    quantity: Math.max(1, Math.round((budget * BASKET_SHARES[slot]) / product.unitPrice)),
  }));
  const totals = computeDocumentTotals(
    lines.map((line) => ({
      quantity: line.quantity,
      unitPrice: line.product.unitPrice,
      discountPercent: 0,
      discountAmount: 0,
      vatPercent: line.product.vatPercent,
    })),
    { discountPercent: 0, discountAmount: 0, vatPercent: 0, shippingFee: 0, installationFee: 0 },
  );

  /*
    Đợt cuối lấy phần CÒN LẠI chứ không nhân phần trăm: 40% + 60% của một số lẻ làm tròn riêng từng
    đợt có thể lệch tổng đơn vài đồng, và vài đồng đó biến một đơn đã thu đủ thành đơn "còn nợ 1đ"
    nằm mãi trên thẻ công nợ.
  */
  const amounts = INSTALMENTS.map((part, index) =>
    index === INSTALMENTS.length - 1
      ? totals.grandTotal - Math.round((totals.grandTotal * INSTALMENTS[0].percent) / 100)
      : Math.round((totals.grandTotal * part.percent) / 100),
  );

  const collected = spec.monthsAgo >= FULLY_COLLECTED_AFTER_MONTHS;
  const advanced = spec.monthsAgo > 0;
  const isPaid = [advanced, collected];
