  // ở đây là cột "Còn nợ" và thẻ "Công nợ phải thu" nói hai chuyện khác nhau trên cùng một đơn.
  const paidAmount = amounts.reduce((sum, amount, index) => sum + (isPaid[index] ? amount : 0), 0);

  const data = {
    code: spec.code,
    customerId: spec.customer.id,
    customerName: spec.customer.name,
    orderDate: spec.orderDate,
    status: 'APPROVED' as const,
    paymentStatus:
      paidAmount <= 0
        ? ('UNPAID' as const)
        : paidAmount >= totals.grandTotal
          ? ('PAID' as const)
          : ('PARTIAL' as const),
    subtotal: totals.subtotal,
    vatAmount: totals.vatAmount,
    grandTotal: totals.grandTotal,
    paidAmount,
    approvedBy: spec.ownerId,
    approvedAt: spec.orderDate,
    ownerId: spec.ownerId,
    teamId: spec.teamId,
    createdAt: spec.orderDate,
  };
  await prisma.salesOrder.upsert({
    where: { id: spec.id },
    update: { ...data, deletedAt: null, updatedBy: adminUserId },
    create: { id: spec.id, tenantId, ...data, createdBy: adminUserId, updatedBy: adminUserId },
  });

  for (const [slot, line] of lines.entries()) {
    const itemData = {
      productId: line.product.id,
      productCode: line.product.code,
      productName: line.product.name,
      unitName: line.product.unitName,
      quantity: line.quantity,
      unitPrice: line.product.unitPrice,
      vatPercent: line.product.vatPercent,
      lineTotal: totals.lines[slot].lineTotal,
      sortOrder: slot,
    };
    await prisma.salesOrderItem.upsert({
      where: { id: `${spec.id}-item-${slot + 1}` },
      update: { ...itemData, deletedAt: null },
      create: { id: `${spec.id}-item-${slot + 1}`, tenantId, orderId: spec.id, ...itemData },
    });
  }

  /*
    Xoá sạch lần thu của đơn rồi dựng lại: seed là chủ sở hữu duy nhất của những đơn này (id cố
    định), nên nó phải là nguồn duy nhất của sổ thu — cùng nguyên tắc `SalesOrderService` áp cho lịch
    thanh toán khi sửa đơn.

    Không có dòng này thì `upsert` theo id cố định vẫn cộng thêm vào những lần thu do migration
