    thu lệch nhau, công nợ ra số ÂM. Đo trên DB đang chạy: 60/64 đơn lệch, tổng còn nợ -10,9 tỷ.
  */
  await prisma.salesOrderReceipt.deleteMany({ where: { orderId: spec.id } });

  for (const [index, part] of INSTALMENTS.entries()) {
    const paymentData = {
      name: part.name,
      percent: part.percent,
      amount: amounts[index],
      dueDate: new Date(spec.orderDate.getTime() + part.dueInDays * DAY),
      isPaid: isPaid[index],
      paidAt: isPaid[index]
        ? new Date(spec.orderDate.getTime() + part.dueInDays * DAY)
        : (null as Date | null),
      sortOrder: index,
    };
    await prisma.salesOrderPayment.upsert({
      where: { id: `${spec.id}-payment-${index + 1}` },
      update: { ...paymentData, deletedAt: null },
      create: {
        id: `${spec.id}-payment-${index + 1}`,
        tenantId,
        orderId: spec.id,
        ...paymentData,
      },
    });

    /*
      Lần thu tương ứng. Cờ `isPaid` ở trên chỉ nói TÌNH TRẠNG KỲ; SỐ TIỀN đã thu nằm ở
      `SalesOrderReceipt` và chỉ số công nợ đọc thẳng bảng đó (`orderOutstandingAsOf` trong
      `src/kpi/kpi-data-sources.ts`). Thiếu khối này thì DB mới seed có `paidAmount` khác 0 mà không
      có đồng nào trong sổ thu: thẻ "Công nợ phải thu" báo còn nợ trọn giá trị đơn, lệch đúng phần đã
      thu so với cột "Còn nợ" — chính là lỗi vừa sửa, tái sinh qua đường dữ liệu mẫu.
    */
    if (isPaid[index]) {
      await prisma.salesOrderReceipt.create({
        data: {
          id: `${spec.id}-receipt-${index + 1}`,
          tenantId,
          orderId: spec.id,
          amount: amounts[index],
          receivedAt: paymentData.dueDate,
          createdBy: adminUserId,
        },
      });
    }
  }

  return totals.grandTotal;
}

