    // Giá 0 thì không suy ra được số lượng: bỏ mã đó ra thay vì chia cho 0.
    .filter((product) => product.unitPrice > 0);

  let nameCursor = 0;
  let customerCount = 0;
  let opportunityCount = 0;
  let dealCount = 0;
  let orderCount = 0;
  let activityCount = 0;

  for (const book of SELLER_BOOKS) {
    const owner = await prisma.user.findUnique({
      where: book.email ? { email: book.email } : { id: adminUserId },
      select: { id: true, teamId: true },
    });
    // Không có tài khoản thì bỏ qua cả quyển sổ: gán dữ liệu cho một `ownerId` không tồn tại tạo ra
    // những bản ghi không ai xem được ở bất kỳ phạm vi nào.
    if (!owner) continue;
    const ownerId = owner.id;
    /*
      Nhóm lấy theo nhóm của CHÍNH người bán, không hardcode. Báo cáo phòng ban quy khách hàng về
      phòng qua `customer.teamId → team.departmentId`; bỏ trống là cả quyển sổ rơi vào "Chưa phân
      công". Admin không thuộc nhóm nào nên phần của admin ở lại đó — đúng thực tế, và cũng cho thấy
      dòng "Chưa phân công" hoạt động.
    */
    const teamId = owner.teamId;

    /** Khách hàng đã tạo của người này, để cơ hội/hợp đồng/hoạt động có chỗ gắn vào. */
    const customers: { id: string; name: string }[] = [];
    let sequence = 0;

    /*
      Đi từ tháng CŨ NHẤT tới tháng này, và `monthOffset` giữ đúng nghĩa cũ (0 = cũ nhất) để id các
      bản ghi đã seed trước đây bị `upsert` ghi đè thay vì bỏ lại thành rác không ai xoá.
    */
    for (let monthOffset = 0; monthOffset < MONTHS; monthOffset += 1) {
      const monthsAgo = MONTHS - 1 - monthOffset;
      const month = monthFor(book, monthsAgo);

      for (let index = 0; index < month.customers; index += 1) {
        const rawName = CUSTOMER_NAMES[nameCursor % CUSTOMER_NAMES.length];
        const suffix = nameCursor >= CUSTOMER_NAMES.length ? ` ${nameCursor}` : '';
        const name = `${rawName}${suffix}`;
        const isCompany = rawName.startsWith('Công ty');
        const id = `${tenantId}-demo-cust-${nameCursor}`;
        const createdAt = at(monthsAgo, sequence);
        const phone = `09${String(10_000_000 + nameCursor * 137).slice(0, 8)}`;

        const data = {
          code: `KHD${String(nameCursor + 1).padStart(3, '0')}`,
          type: isCompany ? ('COMPANY' as const) : ('INDIVIDUAL' as const),
          status: 'DANG_CHAM_SOC' as const,
          name,
          phone,
          phoneNormalized: phone,
          ownerId,
          teamId,
          createdAt,
        };
        await prisma.customer.upsert({
          where: { id },
          update: { ...data, deletedAt: null, updatedBy: adminUserId },
          create: { id, tenantId, ...data, createdBy: adminUserId, updatedBy: adminUserId },
        });

        customers.push({ id, name });
        nameCursor += 1;
        sequence += 1;
        customerCount += 1;
      }

      // Tháng đầu tiên của một người có thể chưa có khách nào — không có chỗ gắn thì bỏ qua tháng.
      if (customers.length === 0) continue;
      const customerAt = (index: number) => customers[index % customers.length];

      const deals: { stage: Stage | 'THANG' | 'THUA'; amount: number }[] = [
        ...month.won.map((amount) => ({ stage: 'THANG' as const, amount })),
        ...month.open,
        ...Array.from({ length: month.lost }, () => ({ stage: 'THUA' as const, amount: 60 })),
      ];

      for (const [index, deal] of deals.entries()) {
        const id = `${tenantId}-demo-opp-${book.key}-${monthOffset}-${index}`;
        const occurredAt = at(monthsAgo, sequence);
        const customer = customerAt(index);
        const data = {
          customerId: customer.id,
          name: `${DEAL_SUBJECTS[index % DEAL_SUBJECTS.length]} — ${customer.name}`,
          amount: deal.amount * MILLION,
          stage: deal.stage,
          expectedCloseDate: occurredAt,
          ownerId,
          teamId,
          createdAt: occurredAt,
        };
        await prisma.opportunity.upsert({
          where: { id },
          update: { ...data, deletedAt: null, updatedBy: adminUserId },
          create: { id, tenantId, ...data, createdBy: adminUserId, updatedBy: adminUserId },
        });
        opportunityCount += 1;
        sequence += 1;

        // Tỉ lệ chốt đọc `OpportunityStageHistory.changedAt`, KHÔNG đọc `stage` hiện tại: thiếu dòng
        // lịch sử này thì cơ hội THẮNG không được tính là đã chốt trong kỳ nào cả.
        if (deal.stage !== 'THANG') continue;
        await prisma.opportunityStageHistory.upsert({
          where: { id: `${id}-won` },
          update: { toStage: 'THANG', changedAt: occurredAt },
          create: {
            id: `${id}-won`,
            tenantId,
            opportunityId: id,
            fromStage: 'THUONG_THAO',
            toStage: 'THANG',
            changedAt: occurredAt,
            changedBy: ownerId,
          },
        });
      }

      for (const [index, value] of month.contracts.entries()) {
        // `monthOffset` chạy tới 23 nên phải đệm 2 chữ số, không thì tháng 1 đợt 12 và tháng 11 đợt
        // 2 cùng ra hậu tố `112`.
        const tag = `${book.key.toUpperCase()}-${String(monthOffset).padStart(2, '0')}${index}`;
        const signDate = at(monthsAgo, sequence);
        const customer = customerAt(index + 1);
        sequence += 1;

        /*
          ĐƠN HÀNG ĐÃ DUYỆT là mốc chốt doanh thu duy nhất của hệ thống (xem `sales.closed_revenue`).
          Sổ demo trước đây chỉ ghi hợp đồng, nên sau khi doanh thu chuyển sang đọc đơn hàng thì trang
          chủ, biểu đồ xu hướng và mọi bảng xếp hạng cùng về 0 — dữ liệu đầy DB mà màn hình trống.
        */
        let orderValue = value * MILLION;
        if (catalogue.length) {
          orderValue = await writeApprovedOrder(
            prisma,
            { tenantId, adminUserId, catalogue },
            {
              id: `${tenantId}-demo-order-${book.key}-${monthOffset}-${index}`,
              code: `DHD-${tag}`,
              customer,
              ownerId,
              teamId,
              orderDate: signDate,
              targetValue: value * MILLION,
              monthsAgo,
              basketCursor: dealCount,
            },
          );
          orderCount += 1;
        }
        dealCount += 1;

        /*
          Hợp đồng đi kèm, ghi lại đúng giá trị của đơn. Giữ lại vì module Hợp đồng có màn hình
          riêng, nhưng nó KHÔNG còn nuôi con số nào trên trang chủ nữa — chỗ nào cần tiền thì đọc
          đơn hàng.
        */
        const contractId = `${tenantId}-demo-contract-${book.key}-${monthOffset}-${index}`;
        const data = {
          code: `HDD-${tag}`,
          name: `Hợp đồng ${DEAL_SUBJECTS[index % DEAL_SUBJECTS.length].toLowerCase()}`,
          customerId: customer.id,
          customerName: customer.name,
          signDate,
          effectiveDate: signDate,
          expiryDate: new Date(signDate.getTime() + 365 * DAY),
          contractValue: orderValue,
          status: 'COMPLETED' as const,
          ownerId,
          teamId,
          createdAt: signDate,
        };
        await prisma.contract.upsert({
          where: { id: contractId },
          update: { ...data, deletedAt: null, updatedBy: adminUserId },
          create: {
            id: contractId,
            tenantId,
            ...data,
            createdBy: adminUserId,
            updatedBy: adminUserId,
          },
        });

        /*
          Lịch thu tiền của hợp đồng, soi đúng lịch của đơn (xem `FULLY_COLLECTED_AFTER_MONTHS`).
          Không có nó thì tab "Đợt thu tiền" ở màn hình hợp đồng trống trơn và trông như hỏng, dù
          công nợ thật đã nằm hết bên đơn hàng.
        */
        const contractPaid = monthsAgo >= FULLY_COLLECTED_AFTER_MONTHS;
        const dueDate = new Date(signDate.getTime() + 30 * DAY);
        const payment = {
          name: 'Đợt 1 - Thanh toán theo hợp đồng',
          amount: orderValue,
          dueDate,
          isPaid: contractPaid,
          paidAt: contractPaid ? dueDate : null,
        };
        await prisma.contractPayment.upsert({
          where: { id: `${contractId}-payment-1` },
          update: payment,
          create: { id: `${contractId}-payment-1`, tenantId, contractId, ...payment },
        });
      }

      for (let index = 0; index < month.activities; index += 1) {
        const id = `${tenantId}-demo-act-${book.key}-${monthOffset}-${index}`;
        const kind = ACTIVITY_KINDS[index % ACTIVITY_KINDS.length];
        const occurredAt = at(monthsAgo, sequence);
        const data = {
          customerId: customerAt(index).id,
          type: kind.type,
          subject: kind.subject,
          occurredAt,
          ownerId,
          createdAt: occurredAt,
        };
        await prisma.activity.upsert({
          where: { id },
          update: { ...data, deletedAt: null, updatedBy: adminUserId },
          create: { id, tenantId, ...data, createdBy: adminUserId, updatedBy: adminUserId },
        });
        activityCount += 1;
        sequence += 1;
      }
    }
  }

  return (
    `Sổ demo ${MONTHS} tháng: ${customerCount} khách hàng, ${opportunityCount} cơ hội, ` +
    `${dealCount} thương vụ (${orderCount} đơn hàng đã duyệt kèm lịch thu tiền), ` +
    `${activityCount} hoạt động — chia cho ${SELLER_BOOKS.length} chủ sở hữu` +
    (catalogue.length ? '' : ' — KHÔNG có mã hàng nào nên đơn hàng bị bỏ qua')
  );
}

