 * `KpiPlanSlot` dùng chung cho MỌI chỉ tiêu cùng nhịp trong kế hoạch — hai chỉ
 * tiêu cùng theo tháng thì dùng chung 12 dòng, không nhân đôi.
 */
private async ensurePlanSlot(
  tx: Prisma.TransactionClient,
  plan: { id: string; periodYear: number },
  cadence: KpiCadence,
  slotIndex: number,
): Promise<string> {
  const tenantId = this.tenantId();
  const key = slotKey(cadence, plan.periodYear, slotIndex);

  const existing = await tx.kpiPlanSlot.findFirst({
    where: { tenantId, planId: plan.id, slotKey: key },
    select: { id: true },
  });
  if (existing) return existing.id;

  const range = slotRange(cadence, plan.periodYear, slotIndex);
  const created = await tx.kpiPlanSlot.create({
    data: {
      tenantId,
      planId: plan.id,
      cadence,
      slotKey: key,
      slotIndex,
      slotStartAt: range.startAt,
      slotEndAt: range.endAt,
    },
    select: { id: true },
  });
  return created.id;
}

/**
 * Ghi lưới mốc của dòng PHÒNG BAN — thay nguyên khối.
 *
 * Lưu `targetPercent`, không lưu số tuyệt đối: đổi mục tiêu cả kỳ thì các mốc
 * tự giãn theo. Đây đúng là cách `allocationPercent` hoạt động khi giao cho cá
 * nhân, và cùng một lý do.
 */
private async writeSlotTargets(
  tx: Prisma.TransactionClient,
  plan: { id: string; periodYear: number },
  metricId: string,
  cadence: KpiCadence,
  slotTargets: readonly KpiSlotTargetInput[],
): Promise<void> {
  const tenantId = this.tenantId();

  await tx.kpiPlanMetricSlot.deleteMany({ where: { tenantId, planMetricId: metricId } });

  for (const target of slotTargets) {
    const planSlotId = await this.ensurePlanSlot(tx, plan, cadence, target.slotIndex);
    await tx.kpiPlanMetricSlot.create({
      data: {
        tenantId,
        planSlotId,
        planMetricId: metricId,
        targetPercent: new Prisma.Decimal(target.percent),
        targetValue: null,
        actualValue: null,
      },
    });
  }
}

/**
 * Dựng lại con số CẢ KỲ của một dòng từ các ô kỳ con của nó.
 *
 * Đây là mấu chốt khiến phần còn lại của module không phải biết gì về kỳ con:
 * sau khi gộp, `KpiPlanMetric.actualValue` vẫn là "kết quả cả kỳ" như cũ, nên
 * chấm điểm, gộp lên phòng ban và điểm tổng chạy nguyên vẹn.
 *
 * Cũng chính là nguyên tắc "gộp trước, chấm sau": chỉ có MỘT lần chấm, ở cấp kỳ.
 */
private async recomputeFromSlots(
  tx: Prisma.TransactionClient,
  metric: { id: string; kind: 'MEASURED' | 'PASS_FAIL'; measureType: KpiMeasureType },
): Promise<void> {
  const rows = await tx.kpiPlanMetricSlot.findMany({
    where: { tenantId: this.tenantId(), planMetricId: metric.id },
    select: { actualValue: true, planSlot: { select: { slotIndex: true } } },
  });
  const slots: SlotValue[] = rows.map((row) => ({
    slotIndex: row.planSlot.slotIndex,
    value: toNullableNumber(row.actualValue),
  }));

  if (metric.kind === 'PASS_FAIL') {
    /*
      Đạt/không đạt: `actualValue` = số lần đạt, `targetValue` = số LẦN KIỂM.
      Cả hai cùng thang nên `scorePassFail` không phải đổi gì — đúng ý đồ đặt
      `targetValue = 1` ("một lần kiểm") lúc thêm chỉ tiêu, giờ chỉ nâng lên N.

      Chưa ghi nhận lần nào ⇒ trả về trạng thái ban đầu (null / 1) thay vì 0/0,
      để chỉ tiêu bị coi là "chưa đánh giá được" chứ không phải "trượt".
    */
    const { passes, checks } = aggregatePassFailSlots(slots);
    await tx.kpiPlanMetric.update({
      where: { id: metric.id },
      data: {
        actualValue: checks === 0 ? null : new Prisma.Decimal(passes),
        targetValue: new Prisma.Decimal(checks === 0 ? 1 : checks),
      },
    });
    return;
  }

  const aggregated = aggregateSlotActual(slots, metric.measureType);
  await tx.kpiPlanMetric.update({
    where: { id: metric.id },
    data: { actualValue: aggregated === null ? null : new Prisma.Decimal(aggregated) },
  });
}

private assertEditable(status: KpiPlanStatus): void {
  if (!isEditable(status)) {
    throw new DomainError({ code: 'KPI_PLAN_NOT_EDITABLE' });
  }
}

/** Điều chỉnh trọng số / phân bổ — được cả khi đang áp dụng, chỉ khoá khi đã chốt. */

