import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import type {
  KpiAllocationCreateInput,
  KpiAllocationUpdateInput,
  KpiPlanStatus,
} from '@ics/shared';
import { AuditService } from '../common/audit/audit.service';
import { DomainError } from '../common/errors/domain-error';
import { PrismaService } from '../common/prisma.service';
import { TenantContextService } from '../common/tenant-context.service';
import type { RbacPrincipal } from '../rbac/rbac.service';
import { assertCanWriteDepartment } from './kpi-access';
import { KpiNotificationService } from './kpi-notification.service';
import { KpiPlanService, type PlanDetailView } from './kpi-plan.service';
import { roundTwo } from './kpi-scoring';
import { isAdjustable, isEditable } from './kpi-workflow';

/**
 * Luồng B — phân bổ chỉ tiêu phòng ban xuống cá nhân.
 *
 * Hai chế độ (§3 KPI_IMPLEMENT):
 *   DIVIDE  — chia target thành các phần, mỗi người một con số riêng.
 *   INHERIT — mỗi người nhận NGUYÊN target phòng ban (dùng cho chỉ tiêu tỷ lệ %
 *             hoặc mốc thời gian — không chia nhỏ được).
 *
 * Bất biến: dòng cá nhân luôn có `planTargetId` ≠ null VÀ `parentMetricId` ≠ null.
 * Việc giao vượt / chưa giao hết chỉ là CẢNH BÁO (tính ở `allocationSummary`),
 * không chặn lưu.
 */
@Injectable()
export class KpiAllocationService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly tenant: TenantContextService,
    private readonly audit: AuditService,
    private readonly plan: KpiPlanService,
    private readonly notifications: KpiNotificationService,
  ) {}

  async allocate(
    input: KpiAllocationCreateInput,
    principal: RbacPrincipal | undefined,
  ): Promise<PlanDetailView> {
    const deptMetric = await this.requireDeptMetric(input.deptMetricId);
    assertCanWriteDepartment(principal, deptMetric.plan.departmentId);
    this.assertAdjustable(deptMetric.plan.status);

    const mode = deptMetric.allocationMode ?? 'DIVIDE';
    if (mode === 'DIVIDE') {
      const missing = input.assignments.find((item) => item.percent === undefined);
      if (missing) {
        throw new ConflictException(
          'Chế độ chia phần cần nhập phần trăm cho từng nhân viên được giao',
        );
      }
    }

    const tenantId = this.tenantId();

    await this.prisma.$transaction(async (tx) => {
      for (const assignment of input.assignments) {
        const employee = await this.loadEmployee(tx, assignment.employeeId);
        const planTargetId = await this.ensurePlanTarget(tx, deptMetric.planId, employee);

        // Phần trăm là thứ được LƯU; số tuyệt đối chỉ là dẫn xuất từ mục tiêu
        // phòng ban hiện tại. INHERIT thì mỗi người nhận nguyên mục tiêu phòng.
        const deptTarget = Number(deptMetric.targetValue);
        const percent = mode === 'INHERIT' ? null : (assignment.percent as number);
        const targetValue = percent === null ? deptTarget : roundTwo((deptTarget * percent) / 100);

        // Giao LẠI cho người đã có phần thì cập nhật, không tạo thêm. Trước đây
        // luôn `create` nên giao lại là vỡ unique (P2002) — quản lý không sửa được
        // phần đã giao, phải xoá rồi giao lại từ đầu.
        const existing = await tx.kpiPlanMetric.findFirst({
          where: {
            tenantId,
            planId: deptMetric.planId,
            level: 'INDIVIDUAL',
            parentMetricId: deptMetric.id,
            planTargetId,
          },
          select: { id: true },
        });

        if (existing) {
          await tx.kpiPlanMetric.update({
            where: { id: existing.id },
            data: {
              targetValue: new Prisma.Decimal(targetValue),
              allocationPercent: percent === null ? null : new Prisma.Decimal(percent),
              allocationMode: mode,
            },
          });
          continue;
        }

        await tx.kpiPlanMetric.create({
          data: {
            tenantId,
            planId: deptMetric.planId,
            level: 'INDIVIDUAL',
            parentMetricId: deptMetric.id,
            planTargetId,
            criteriaId: deptMetric.criteriaId,
            sourceCriteriaId: deptMetric.sourceCriteriaId,
            objectiveId: deptMetric.objectiveId,
            aspect: deptMetric.aspect,
            csf: deptMetric.csf,
            name: deptMetric.name,
            description: deptMetric.description,
            targetValue: new Prisma.Decimal(targetValue),
            allocationPercent: percent === null ? null : new Prisma.Decimal(percent),
            // Chưa nhập kết quả ⇒ null, KHÔNG phải 0 (0 sẽ bị tính thành 0% và kéo điểm xuống).
            actualValue: null,
            unit: deptMetric.unit,
            weight: deptMetric.weight,
            direction: deptMetric.direction,
            allocationMode: mode,
            aggregation: deptMetric.aggregation,
            isBlocking: deptMetric.isBlocking,
            // Cá nhân chấm theo cùng mô hình với chỉ tiêu phòng — snapshot xuống.
            kind: deptMetric.kind,
            scoringShape: deptMetric.scoringShape,
            scoringMethod: deptMetric.scoringMethod,
            measureType: deptMetric.measureType,
            // Nhịp kỳ con phải giống dòng cha: mọi phép tính trên một dòng chỉ
            // đọc `cadence` của chính nó, hai nhịp lệch nhau là hỏng âm thầm.
            cadence: deptMetric.cadence,
            scoringConfig: deptMetric.scoringConfig ?? Prisma.JsonNull,
            thresholdValue: deptMetric.thresholdValue,
            stretchValue: deptMetric.stretchValue,
            /*
              Nguồn số liệu chép xuống dòng cá nhân — và ĐÂY mới là nơi nguồn tự
              động thực sự chạy: nguồn lọc theo `ownerId`, mà "của ai" chỉ có
              nghĩa ở dòng cá nhân. Dòng phòng ban sau khi đã giao thì lấy số
              bằng cách gộp các dòng con lại, không tự truy vấn nữa.
            */
            sourceType: deptMetric.sourceType,
            dataSourceId: deptMetric.dataSourceId,
            formula: deptMetric.formula,
            status: 'DRAFT',
          },
        });
      }
    });

    const after = await this.plan.getDetail(deptMetric.planId, principal);
    await this.audit.record({
      action: 'kpi.allocation.create',
      entity: 'KpiPlanMetric',
      entityId: deptMetric.id,
      after: {
        deptMetricId: deptMetric.id,
        mode,
        assignments: input.assignments,
      },
    });

    // Chỉ báo khi kế hoạch ĐÃ ban hành — `notifyAllocationChanged` tự lọc theo
    // trạng thái. Trên bản nháp thì phân bổ vẫn đang được soạn.
    await this.notifications.notifyAllocationChanged({
      plan: { id: deptMetric.planId, ...deptMetric.plan },
      metricName: deptMetric.name,
      employeeIds: input.assignments.map((assignment) => assignment.employeeId),
    });
    return after;
  }

  async updateAllocation(
    allocationId: string,
    input: KpiAllocationUpdateInput,
    principal: RbacPrincipal | undefined,
  ): Promise<PlanDetailView> {
    const allocation = await this.requireAllocation(allocationId);
    assertCanWriteDepartment(principal, allocation.plan.departmentId);
    this.assertAdjustable(allocation.plan.status);

    if (allocation.allocationMode === 'INHERIT') {
      throw new ConflictException(
        'Chỉ tiêu giao nguyên không sửa được mục tiêu riêng cho từng người — hãy sửa mục tiêu ở cấp phòng ban',
      );
    }

    // Sửa phần trăm ⇒ tính lại số tuyệt đối theo mục tiêu phòng ban hiện tại.
    const deptTarget = Number(allocation.parent?.targetValue ?? 0);
    await this.prisma.scoped.kpiPlanMetric.update({
      where: { id: allocationId },
      data: {
        allocationPercent: new Prisma.Decimal(input.percent),
        targetValue: new Prisma.Decimal(roundTwo((deptTarget * input.percent) / 100)),
      },
    });

    await this.notifications.notifyAllocationChanged({
      plan: { id: allocation.planId, ...allocation.plan },
      metricName: allocation.name,
      employeeIds: allocation.planTarget ? [allocation.planTarget.employeeId] : [],
    });

