import type { KpiPlanStatus } from '@ics/shared';

/**
 * Quy tắc vòng đời kế hoạch KPI — hàm thuần, không chạm DB.
 *
 *   NHÁP ── ban hành ──► ĐANG ÁP DỤNG ── chốt kỳ ──► ĐÃ CHỐT
 *     ▲                                                 │
 *     └──────── mở lại (chỉ KPI admin, kèm lý do) ◄──────┘
 *
 * KHÔNG có bước phê duyệt của người khác. Phòng ban là nơi xuất phát của mọi thứ
 * (mục tiêu, chỉ tiêu, target, trọng số), nên ban lãnh đạo không có căn cứ để
 * duyệt — duyệt mà không có căn cứ chỉ là con dấu. Kiểm soát nằm ở hai chỗ khác:
 *
 *   1. Kiểm tra TỰ ĐỘNG khi ban hành (`publishBlockers` ở service): phải có chỉ
 *      tiêu, tổng trọng số mỗi trụ = 100%, tỷ trọng 4 trụ = 100%.
 *   2. Minh bạch: KPI admin đọc được mọi phòng ban qua dashboard.
 *
