 * `isEditable` — nếu target sửa được sau khi kỳ đã chạy thì tháng 12 chỉ cần hạ
 * target xuống bằng số thực tế là "hoàn thành 100%", và KPI mất hết ý nghĩa.
 */

const TRANSITIONS: Record<KpiPlanStatus, KpiPlanStatus[]> = {
  DRAFT: ['APPROVED'],
  APPROVED: ['CLOSED'],
  CLOSED: ['DRAFT'],
};

export function isValidStatusTransition(from: KpiPlanStatus, to: KpiPlanStatus): boolean {
  return TRANSITIONS[from].includes(to);
}

/**
 * Mở lại kế hoạch đã chốt là ngoại lệ — chỉ KPI admin.
 *
 * Đây là cửa người DUY NHẤT còn lại trong vòng đời, và nó đáng giữ: kỳ đã chốt
 * là dữ liệu đã dùng để xếp hạng, mở lại nghĩa là sửa lại lịch sử.
 */
export function requiresAdmin(from: KpiPlanStatus, to: KpiPlanStatus): boolean {
  return from === 'CLOSED' && to === 'DRAFT';
}

/**
 * Sửa được CẤU TRÚC không: thêm/xoá chỉ tiêu, đổi mục tiêu, đổi nhịp chia, đổi
 * cách chấm. Chỉ khi còn nháp.
 *
 * Đây là thứ phải khoá lúc ban hành: nếu mục tiêu sửa được sau khi kỳ đã chạy
 * thì tháng 12 chỉ cần hạ mục tiêu xuống bằng số thực tế là "hoàn thành 100%".
 */
export function isEditable(status: KpiPlanStatus): boolean {
  return status === 'DRAFT';
}

/**
 * ĐIỀU CHỈNH được không: trọng số chỉ tiêu, phần trăm giao cho từng người, và
 * lưới mốc theo kỳ con. Được cả khi đang áp dụng, chỉ khoá khi đã chốt kỳ.
 *
 * Vì sao tách khỏi `isEditable`: điều chỉnh trọng số giữa kỳ là việc điều hành
 * BÌNH THƯỜNG, không phải sửa lén. Quý 1 hụt thì dồn trọng số sang các quý sau;
 * nhân viên A đuối hơn B thì hạ phần của A, nâng phần của B. Cấm việc này là
 * bắt kế hoạch đứng yên trong khi thực tế đã đổi.
 *
 * Ranh giới: điều chỉnh chỉ đụng tới "chia bao nhiêu, cho ai" — KHÔNG đụng tới
 * KẾT QUẢ ĐÃ GHI NHẬN và cũng không đụng tới mục tiêu của cả kỳ.
 */
export function isAdjustable(status: KpiPlanStatus): boolean {
  return status === 'DRAFT' || status === 'APPROVED';
}

/** Chỉ nhập kết quả thực tế khi kế hoạch đang áp dụng. */
export function acceptsActuals(status: KpiPlanStatus): boolean {
  return status === 'APPROVED';
}
  private buildPublishBlockers(aspects: PlanAspectView[], periodYear: number): string[] {
