    } else if (!isCompleteWeightSet(aspectWeights)) {
      blockers.push('Tỷ trọng 4 trụ cột của phòng ban phải bằng 100%');
    }

    for (const aspect of aspects) {
      if (aspect.metrics.length === 0) continue;
      if (!aspect.isWeightComplete) {
        blockers.push(
          `Tổng trọng số chỉ tiêu trong trụ ${aspect.aspect} là ${aspect.totalCriteriaWeight}%, phải bằng 100%`,
        );
      }
    }

