export function allowedCadences(input: { kind: 'MEASURED' | 'PASS_FAIL' }): readonly KpiCadence[] {
  return input.kind === 'PASS_FAIL' ? KPI_CADENCES : (['PERIOD', 'QUARTER', 'MONTH'] as const);
}

/**
 * Loại này có phải khai LƯỚI MỐC (% cho từng kỳ con) không?
 *
 * Chỉ ADDITIVE và SEMI_ADDITIVE mới chia được mục tiêu theo thời gian:
 *   · ADDITIVE      — chia phần, Σ các kỳ con = mục tiêu cả kỳ
 *   · SEMI_ADDITIVE — lộ trình, MỐC CUỐI = mục tiêu cả kỳ
 *
 * RATIO thì mục tiêu LẶP LẠI ở mọi kỳ con ("tỷ lệ hài lòng ≥ 90% mỗi tháng") nên
 * không có gì để chia; đạt/không đạt cũng vậy. Hai loại đó vẫn chọn nhịp — để
 * THU SỐ theo kỳ con — chỉ là không có lưới mốc.
 */
export function requiresSlotTargets(input: {
  kind: 'MEASURED' | 'PASS_FAIL';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  cadence: KpiCadence;
}): boolean {
  if (input.cadence === 'PERIOD') return false;
  if (input.kind === 'PASS_FAIL') return false;
  return input.measureType === 'ADDITIVE' || input.measureType === 'SEMI_ADDITIVE';
}

export type KpiSlotTarget = { slotIndex: number; percent: number };

/**
 * Kiểm lưới mốc hợp lệ. Trả thông báo tiếng Việt hoặc `null`.
 *
 * Một chân lý duy nhất cho contract (Zod), service và form — ba nơi lệch luật là
 * kiểu bug người dùng lưu được ở màn này nhưng bị 409 ở màn kia.
 */
export function validateSlotTargets(input: {
  kind: 'MEASURED' | 'PASS_FAIL';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  cadence: KpiCadence;
  periodYear: number;
  targets: readonly KpiSlotTarget[] | undefined;
}): string | null {
  if (!requiresSlotTargets(input)) return null;

  const targets = input.targets ?? [];
  if (!targets.length) return 'Cần chia mục tiêu cho từng kỳ con';

  const total = slotCount(input.cadence, input.periodYear);
  const seen = new Set<number>();
  for (const target of targets) {
    if (!Number.isInteger(target.slotIndex) || target.slotIndex < 0 || target.slotIndex >= total)
      return 'Có kỳ con không thuộc kỳ này';
    if (seen.has(target.slotIndex)) return 'Mỗi kỳ con chỉ được khai một lần';
    seen.add(target.slotIndex);
  }

  if (input.measureType === 'ADDITIVE') {
    // Dung sai 0.01 như tỷ trọng: 33.33+33.33+33.34 phải được coi là đủ 100%.
    const sum = targets.reduce((acc, target) => acc + target.percent, 0);
    if (Math.abs(sum - 100) >= 0.01)
      return `Tổng các kỳ con đang là ${Math.round(sum * 100) / 100}%, phải bằng 100%`;
    return null;
  }

  // SEMI_ADDITIVE — lộ trình: chỉ số CUỐI KỲ mới là thứ được chấm, nên mốc ở kỳ
  // con cuối cùng phải chính là mục tiêu cả kỳ. Các mốc giữa là chặng đường.
  const last = targets.find((target) => target.slotIndex === total - 1);
  if (!last) return 'Lộ trình phải có mốc ở kỳ con cuối cùng';
  if (Math.abs(last.percent - 100) >= 0.01) return 'Mốc của kỳ con cuối cùng phải bằng 100%';
  return null;
}

