    id: string,
    input: KpiPlanStatusInput,
    principal: RbacPrincipal | undefined,
    actorId: string,
  ): Promise<PlanDetailView> {
    // Cấp 'read': admin ĐƯỢC đổi trạng thái vì admin là người duy nhất mở lại được
    // kỳ đã chốt — khác với sửa nội dung. Quản lý vẫn chỉ trong phòng mình.
    const plan = await this.requirePlan(id, principal, 'read');

    const from = plan.status;
    const to = input.status;

    if (!isValidStatusTransition(from, to)) {
      throw new ConflictException(`Không thể chuyển trạng thái ${from} → ${to}`);
    }
    if (requiresAdmin(from, to) && !isKpiAdmin(principal)) {
      throw new ForbiddenException('Chỉ KPI admin được mở lại kế hoạch KPI đã chốt');
    }

    // Cửa chất lượng khi BAN HÀNH: kiểm tự động, không phải người duyệt.
    // Đây là thứ thay thế bước phê duyệt cũ — và là thứ thật sự chặn được
    // kế hoạch thiếu chỉ tiêu hoặc trọng số không đủ 100%.
    if (to === 'APPROVED') {
      const detail = await this.getDetail(id, principal);
      if (!detail.canPublish) {
        throw new ConflictException(detail.publishBlockers.join(' · '));
      }
    }

    const now = new Date();
    await this.prisma.scoped.kpiPlan.update({
      where: { id },
      data: {
        status: to,
        ...(to === 'APPROVED' ? { publishedAt: now } : {}),
        ...(to === 'CLOSED' ? { closedAt: now } : {}),
        ...(from === 'CLOSED' && to === 'DRAFT' ? { reopenedAt: now } : {}),
        updatedBy: actorId,
      },
    });

    const after = await this.getDetail(id, principal);
    await this.audit.record({
      action: 'kpi.plan.status',
      entity: 'KpiPlan',
      entityId: id,
      before: { status: from },
      after: { status: to, note: input.note ?? null },
    });

