const pad2 = (value: number) => String(value).padStart(2, '0');

/** Ngày thứ `dayOfYear` (1-based) của năm, tính theo UTC. */
function dateOfYear(year: number, dayOfYear: number): Date {
  return new Date(Date.UTC(year, 0, dayOfYear));
}

/** Ngày thứ mấy trong năm (1-based) của một mốc thời gian. */
function dayOfYearOf(date: Date): number {
  const startOfYear = Date.UTC(date.getUTCFullYear(), 0, 1);
  return (
    Math.floor(
      (Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) - startOfYear) /
        86_400_000,
    ) + 1
  );
}

export type SlotRange = { startAt: Date; endAt: Date };

/** Khoảng thời gian [đầu, cuối] của một kỳ con. `endAt` là mili-giây cuối cùng. */
export function slotRange(cadence: KpiCadence, year: number, slotIndex: number): SlotRange {
  const endOfDay = (date: Date) => new Date(date.getTime() + 86_400_000 - 1);

  switch (cadence) {
    case 'PERIOD':
      return {
        startAt: new Date(Date.UTC(year, 0, 1)),
        endAt: endOfDay(new Date(Date.UTC(year, 11, 31))),
      };
    case 'QUARTER':
      return {
        startAt: new Date(Date.UTC(year, slotIndex * 3, 1)),
        // Ngày 0 của tháng kế tiếp = ngày cuối tháng hiện tại.
        endAt: endOfDay(new Date(Date.UTC(year, slotIndex * 3 + 3, 0))),
      };
    case 'MONTH':
      return {
        startAt: new Date(Date.UTC(year, slotIndex, 1)),
        endAt: endOfDay(new Date(Date.UTC(year, slotIndex + 1, 0))),
      };
    case 'WEEK': {
      const startDay = slotIndex * 7 + 1;
      const endDay = slotIndex === WEEKS_PER_YEAR - 1 ? daysInYear(year) : startDay + 6;
      return { startAt: dateOfYear(year, startDay), endAt: endOfDay(dateOfYear(year, endDay)) };
    }
    case 'DAY': {
      const day = dateOfYear(year, slotIndex + 1);
      return { startAt: day, endAt: endOfDay(day) };
    }
  }
}

