/**
 * CÔNG THỨC KPI — ghép các nguồn số liệu thô thành một con số.
 *
 * Ranh giới với `sourceType = EXISTING`:
 *   · Nguồn   = MỘT phép đo. Được tính trong từng dòng dữ liệu (số ngày trễ, số
 *               giờ xử lý) nhưng KHÔNG ghép hai phép đo độc lập.
 *   · Công thức = ghép nhiều phép đo.
 *
 * Vì tham số của công thức là NGUỒN chứ không phải chỉ tiêu khác, ở đây không có
 * đồ thị phụ thuộc: không vòng lặp, không phải sắp thứ tự tính, không cần mã định
 * danh riêng cho chỉ tiêu. Đó là lý do chọn cách này thay vì cho tham chiếu chéo.
 *
 * TUYỆT ĐỐI KHÔNG dùng `eval`/`Function`: chuỗi này do người dùng nhập và được
 * chạy ở server, dùng eval là mở đường thực thi mã tuỳ ý.
 *
 * Hàm thuần, không phụ thuộc Zod — dùng chung backend (tính) ↔ frontend (kiểm khi
 * nhập). Hai bên kiểm khác nhau là kiểu bug lưu được ở form nhưng 409 ở server.
 */

/** Chặn công thức dài bất thường — vừa khó đọc vừa là bề mặt tấn công vô ích. */
export const KPI_FORMULA_MAX_LENGTH = 500;

/** Chặn lồng ngoặc quá sâu để parser đệ quy không thể làm tràn ngăn xếp. */
const MAX_DEPTH = 20;

/**
 * Cú pháp tham chiếu nguồn: `[sales.closed_revenue]`.
 *
 * Dùng ngoặc vuông chứ không để trần: id nguồn có dấu chấm (`sales.closed_deals`)
 * nên nếu để trần thì không phân biệt được đâu là hết tên, đâu là toán tử.
 */
const REFERENCE_PATTERN = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/;

type Node =
  | { type: 'number'; value: number }
  | { type: 'ref'; id: string }
  | { type: 'unary'; operator: '-'; operand: Node }
  | { type: 'binary'; operator: '+' | '-' | '*' | '/'; left: Node; right: Node };

type Token =
  | { type: 'number'; value: number; at: number }
  | { type: 'ref'; id: string; at: number }
  | { type: 'operator'; value: '+' | '-' | '*' | '/'; at: number }
  | { type: 'paren'; value: '(' | ')'; at: number };

/** Lỗi cú pháp mang thông điệp tiếng Việt — ném ra rồi bắt lại ở biên public. */
class FormulaError extends Error {}

// ─────────────────────────────────────────────────────────────
// Tách token
// ─────────────────────────────────────────────────────────────

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let index = 0;

  while (index < source.length) {
    const char = source[index];

    if (char === ' ' || char === '\t' || char === '\n' || char === '\r') {
 * Kiểm công thức hợp lệ VÀ mọi nguồn nó dùng đều có thật. Trả thông báo tiếng
 * Việt hoặc `null` — cùng khuôn với `validateSlotTargets`/`validateScoreBands`.
 */
export function validateKpiFormula(
  source: string,
  knownSourceIds: readonly string[],
): string | null {
  const parsed = parseKpiFormula(source);
  if (!parsed.ok) return parsed.error;

  const unknown = parsed.refs.filter((ref) => !knownSourceIds.includes(ref));
  if (unknown.length) return `Không có nguồn số liệu: ${unknown.join(', ')}`;
  return null;
}

/**
 * Tính công thức trên một bộ giá trị nguồn.
 *
 * Trả `null` khi CHƯA ĐÁNH GIÁ ĐƯỢC, và mọi phép có toán hạng `null` đều lan
 * `null` ra ngoài. Đây là điều kiện sống còn: ép về 0 nghĩa là một chỉ tiêu chưa
 * có số bị chấm 0 điểm, trong khi cả module đã thống nhất "thiếu số thì loại khỏi
 * phép tính điểm, không phải trượt".
 *
 * Chia cho 0 cũng trả `null` chứ không phải Infinity — "chưa có mẫu số" là chưa
 * đo được, ví dụ tỷ lệ chuyển đổi khi trong kỳ chưa có cơ hội nào.
 */

