import { PrismaClient } from '@prisma/client';
import * as argon2 from 'argon2';
import { DEPARTMENT_ROLE_SEEDS, SYSTEM_ROLE_SCOPES, SystemRole } from '@ics/shared';

/**
 * Cơ cấu tổ chức mở rộng cho môi trường dev: **3 CHI NHÁNH × 2 PHÒNG BAN**, mỗi phòng 1 trưởng
 * phòng + 2 nhân viên, tất cả đều có tài khoản đăng nhập.
 *
 * Vì sao phải nhiều chi nhánh chứ không phải nhiều phòng trong một chi nhánh:
 *
 *   1. Phân quyền KPI đi theo PHÒNG BAN, còn phạm vi dữ liệu của các module khác lại đi theo CHI
 *      NHÁNH (`User.branchId`, `Ticket.branchId`, `RequestTicket.branchId`). Một chi nhánh duy nhất
 *      thì mọi bộ lọc theo chi nhánh đều trả về đúng một nhóm — chạy hay không chạy nhìn giống nhau.
 *   2. Nguồn số liệu KPI tự động lọc theo `ownerId`. Muốn kiểm được "số của phòng A không lẫn sang
 *      phòng B" thì phải có dữ liệu THẬT nằm ở cả hai phòng, ở hai chi nhánh khác nhau.
 *
 * Vì sao MỌI người đều có tài khoản: chỉ tiêu KPI tự động tra số theo `ownerId`, mà `Employee` nối
 * sang `User` qua `Employee.userId`. Nhân viên không có tài khoản thì ô kết quả của họ vừa không tự
 * điền được, vừa bị khoá không cho nhập tay (`isAuto` ⇒ `canEnterActual = false`) — một ô chết mà
 * giao diện không giải thích được. Không để bộ dữ liệu mẫu tự tạo ra tình huống đó.
 *
 * Idempotent: id tiền định + upsert, và luôn reset `passwordHash` để đăng nhập ở máy dev không bị
 * lệch sau khi đổi biến môi trường.
 */

/** Mật khẩu dùng chung cho các tài khoản dev bên dưới. */
const DEV_PASSWORD = process.env.SEED_DEV_PASSWORD ?? 'Demo@12345';

/**
 * Nghiệp vụ chính của một phòng ban.
 *
 * Đây là thứ quyết định phòng đó SINH RA loại dữ liệu nào (đơn hàng / ticket / công việc tài chính)
 * và vì vậy chỉ tiêu KPI nào của phòng có thể lấy số tự động. Không suy ra từ TÊN phòng: tên là chuỗi
 * người dùng sửa được, còn đây là quyết định của bộ seed.
 */
export type SeedDepartmentProfile = 'SALES' | 'SUPPORT' | 'FINANCE' | 'HR';

interface DepartmentSeed {
  key: string;
  /** Ghi đè id khi phòng đã được `seed.ts` dựng sẵn — phải giữ nguyên để không tạo bản trùng. */
  fixedId?: string;
  name: string;
  description: string;
  profile: SeedDepartmentProfile;
  teamName: string;
  headTitle: string;
  staffTitle: string;
}

interface BranchSeed {
  key: string;
  fixedId?: string;
  name: string;
  departments: DepartmentSeed[];
}

/**
 * Ba chi nhánh. Chi nhánh đầu và hai phòng của nó dùng lại đúng id mà `seed.ts` đã tạo
 * (`<tenant>-branch`, `<tenant>-department`) — đổi id ở đây là bỏ lại một bản sao mồ côi kèm toàn bộ
 * nhân sự đang trỏ vào nó.
 */
function branchPlan(tenantId: string): BranchSeed[] {
  return [
    {
      key: 'hq',
      fixedId: `${tenantId}-branch`,
      name: 'Trụ sở chính',
      departments: [
        {
          key: 'hr',
          fixedId: `${tenantId}-department`,
          name: 'Phòng Hành chính - Nhân sự',
          description: 'Phòng ban phụ trách nhân sự, hành chính và đào tạo',
          profile: 'HR',
          teamName: 'Nhóm Hành chính - Nhân sự',
          headTitle: 'Trưởng phòng Hành chính - Nhân sự',
          staffTitle: 'Chuyên viên Hành chính - Nhân sự',
        },
        {
          key: 'sales',
          fixedId: `${tenantId}-dept-sales`,
          name: 'Phòng Kinh doanh',
          description: 'Phòng ban phụ trách bán hàng và phát triển khách hàng',
          profile: 'SALES',
          teamName: 'Nhóm Kinh doanh 1',
          headTitle: 'Trưởng phòng Kinh doanh',
          staffTitle: 'Nhân viên Kinh doanh',
        },
      ],
    },
    {
      key: 'dn',
      name: 'Chi nhánh Đà Nẵng',
      departments: [
        {
          key: 'sales-dn',
          name: 'Phòng Kinh doanh Đà Nẵng',
          description: 'Bán hàng khu vực miền Trung',
          profile: 'SALES',
          teamName: 'Nhóm Kinh doanh Đà Nẵng',
          headTitle: 'Trưởng phòng Kinh doanh Đà Nẵng',
          staffTitle: 'Nhân viên Kinh doanh Đà Nẵng',
        },
        {
          key: 'support-dn',
          name: 'Phòng Chăm sóc khách hàng',
          description: 'Tiếp nhận và xử lý yêu cầu, sự cố, khiếu nại của khách hàng',
          profile: 'SUPPORT',
          teamName: 'Nhóm Chăm sóc khách hàng',
          headTitle: 'Trưởng phòng Chăm sóc khách hàng',
          staffTitle: 'Chuyên viên Chăm sóc khách hàng',
        },
      ],
    },
    {
      key: 'hcm',
      name: 'Chi nhánh Hồ Chí Minh',
      departments: [
        {
          key: 'sales-hcm',
          name: 'Phòng Kinh doanh Hồ Chí Minh',
          description: 'Bán hàng khu vực miền Nam',
          profile: 'SALES',
          teamName: 'Nhóm Kinh doanh Hồ Chí Minh',
          headTitle: 'Trưởng phòng Kinh doanh Hồ Chí Minh',
          staffTitle: 'Nhân viên Kinh doanh Hồ Chí Minh',
        },
        {
          key: 'finance-hcm',
          name: 'Phòng Tài chính - Kế toán',
          description: 'Đối soát, chốt sổ, báo cáo thuế và kiểm soát tuân thủ',
          profile: 'FINANCE',
          teamName: 'Nhóm Tài chính - Kế toán',
          headTitle: 'Trưởng phòng Tài chính - Kế toán',
          staffTitle: 'Chuyên viên Kế toán',
        },
      ],
    },
  ];
}

type PersonRank = 'HEAD' | 'STAFF';

interface PersonSeed {
  key: string;
  code: string;
  familyName: string;
