  // ── Đà Nẵng / Kinh doanh ────────────────────────────────────
  { key: 'sales-dn-head', code: 'EPL/2026/00008', familyName: 'Đặng', givenName: 'Văn Hải', department: 'sales-dn', rank: 'HEAD', email: 'hai.dang@demo.local' },
