  { key: 'support-dn-staff-1', code: 'EPL/2026/00012', familyName: 'Cao', givenName: 'Bảo Long', department: 'support-dn', rank: 'STAFF', email: 'long.cao@demo.local' },
  { key: 'support-dn-staff-2', code: 'EPL/2026/00013', familyName: 'Đinh', givenName: 'Thuỳ Linh', department: 'support-dn', rank: 'STAFF', email: 'linh.dinh@demo.local' },
