  { key: 'sales-hcm-head', code: 'EPL/2026/00014', familyName: 'Võ', givenName: 'Thành Nam', department: 'sales-hcm', rank: 'HEAD', email: 'nam.vo@demo.local' },
  { key: 'sales-hcm-staff-1', code: 'EPL/2026/00015', familyName: 'Huỳnh', givenName: 'Gia Bảo', department: 'sales-hcm', rank: 'STAFF', email: 'bao.huynh@demo.local' },
  { key: 'sales-hcm-staff-2', code: 'EPL/2026/00016', familyName: 'Nguyễn', givenName: 'Ngọc Trâm', department: 'sales-hcm', rank: 'STAFF', email: 'tram.nguyen@demo.local' },
  // ── Hồ Chí Minh / Tài chính - Kế toán ───────────────────────
  { key: 'finance-hcm-head', code: 'EPL/2026/00017', familyName: 'Phan', givenName: 'Kim Ngân', department: 'finance-hcm', rank: 'HEAD', email: 'ngan.phan@demo.local' },
  { key: 'finance-hcm-staff-1', code: 'EPL/2026/00018', familyName: 'Lâm', givenName: 'Chí Cường', department: 'finance-hcm', rank: 'STAFF', email: 'cuong.lam@demo.local' },
