/** Mã nhân viên cuối cùng đã dùng ở trên — đẩy bộ đếm để app không sinh mã trùng. */
const LAST_EMPLOYEE_SEQUENCE = 19;

/** Một phòng ban đã ghi xong, kèm mọi id mà các bộ seed sau cần. */
export interface SeedDepartment {
  key: string;
  id: string;
  name: string;
  profile: SeedDepartmentProfile;
  teamId: string;
  branchKey: string;
  branchId: string;
  branchName: string;
}

/** Một nhân sự đã ghi xong, kèm tài khoản đăng nhập. */
export interface SeedPerson {
  key: string;
  employeeId: string;
  userId: string;
  employeeCode: string;
  fullName: string;
  email: string;
  rank: PersonRank;
  role: SystemRole;
  department: SeedDepartment;
}

export interface SeedOrgResult {
  branches: Array<{ key: string; id: string; name: string }>;
  departments: SeedDepartment[];
  people: SeedPerson[];
  summary: string;
}

export async function seedOrg(
  prisma: PrismaClient,
  context: { tenantId: string; organizationId: string },
): Promise<SeedOrgResult> {
  const { tenantId, organizationId } = context;

  /*
    Hai nhóm quyền gắn theo phòng ban, seed sẵn để làm LỰA CHỌN trong ô "Thiết lập quyền cho phòng ban".
    Migration 20260814090000_add_department_roles chỉ tạo chúng cho tenant đã có phòng ban bật cờ
    `isSales`/`isRecruitment` cũ — DB mới không có phòng nào bật cờ nên sẽ không có role nào để
    chọn. Cố ý CHỈ tạo role, KHÔNG nối vào phòng ban nào: nối là quyết định phân quyền, phải do
    người dùng bấm ở UI và đi qua audit + kiểm quyền `role.assign`.
  */
  for (const seed of DEPARTMENT_ROLE_SEEDS) {
    const role = await prisma.role.upsert({
      where: { tenantId_code: { tenantId, code: seed.code } },
      update: { name: seed.name, deletedAt: null },
      create: {
        tenantId,
        code: seed.code,
        name: seed.name,
        isSystem: false,
        dataScope: seed.dataScope ?? 'OWN',
      },
      select: { id: true },
    });
    const permissions = await prisma.permission.findMany({
      where: { code: { in: [...seed.permissions] } },
      select: { id: true },
    });
    await prisma.rolePermission.createMany({
      data: permissions.map(({ id }) => ({ roleId: role.id, permissionId: id })),
      skipDuplicates: true,
    });
  }

  const branches: Array<{ key: string; id: string; name: string }> = [];
  const departments: SeedDepartment[] = [];

  for (const branchSeed of branchPlan(tenantId)) {
    const branchId = branchSeed.fixedId ?? `${tenantId}-branch-${branchSeed.key}`;
    /*
      Nhánh `update` CỐ Ý không đặt lại `name` cho chi nhánh đã có sẵn: tên mặc định của trụ sở là
      chỗ giữ chỗ, tenant thật vào Cài đặt đổi thành tên của họ. Ghi đè mỗi lần seed chạy lại là đổi
      tên công ty người ta về "Trụ sở chính". Chi nhánh do bộ seed này tạo ra thì ngược lại — nó là
      dữ liệu mẫu nên được phép làm chủ tên của mình.
    */
    await prisma.branch.upsert({
      where: { id: branchId },
      update: branchSeed.fixedId
        ? { deletedAt: null }
        : { name: branchSeed.name, organizationId, deletedAt: null, updatedBy: 'SYSTEM' },
      create: {
        id: branchId,
        tenantId,
        organizationId,
        name: branchSeed.name,
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
    });
    branches.push({ key: branchSeed.key, id: branchId, name: branchSeed.name });

    for (const deptSeed of branchSeed.departments) {
      const departmentId = deptSeed.fixedId ?? `${tenantId}-dept-${deptSeed.key}`;
      await prisma.department.upsert({
        where: { id: departmentId },
        update: {
          name: deptSeed.name,
          description: deptSeed.description,
          branchId,
          deletedAt: null,
          updatedBy: 'SYSTEM',
        },
        create: {
          id: departmentId,
          tenantId,
          branchId,
          name: deptSeed.name,
          description: deptSeed.description,
          // `isSales`/`isRecruitment` cố ý để mặc định false: hai cờ đó nới phạm vi dữ liệu ở
          // RbacService, bật lên là đổi hành vi phân quyền — cần quyết định riêng, không seed ngầm.
          createdBy: 'SYSTEM',
          updatedBy: 'SYSTEM',
        },
      });

      /*
        Nhóm (Team) là ĐƯỜNG DUY NHẤT nối một khách hàng / cơ hội về phòng ban: bảng `customers` chỉ
        có `teamId`, không có `departmentId`. Không seed nhóm thì báo cáo "Phòng ban & Nhân viên" chỉ
        hiện đúng một dòng "Chưa phân công" cho toàn bộ dữ liệu — trông như báo cáo hỏng.
      */
      const teamId = `${tenantId}-team-${deptSeed.key}`;
      await prisma.team.upsert({
        where: { id: teamId },
        update: {
          name: deptSeed.teamName,
          branchId,
          departmentId,
          deletedAt: null,
          updatedBy: 'SYSTEM',
        },
        create: {
          id: teamId,
          tenantId,
          branchId,
          departmentId,
          name: deptSeed.teamName,
          createdBy: 'SYSTEM',
          updatedBy: 'SYSTEM',
        },
      });

      for (const [rank, name] of [
        ['head', deptSeed.headTitle],
        ['staff', deptSeed.staffTitle],
      ] as const) {
        const id = `${tenantId}-pos-${deptSeed.key}-${rank}`;
        await prisma.position.upsert({
          where: { id },
          update: { name, departmentId, deletedAt: null },
          create: { id, tenantId, departmentId, name, createdBy: 'SYSTEM', updatedBy: 'SYSTEM' },
        });
      }

      departments.push({
        key: deptSeed.key,
        id: departmentId,
        name: deptSeed.name,
        profile: deptSeed.profile,
        teamId,
        branchKey: branchSeed.key,
        branchId,
        branchName: branchSeed.name,
      });
    }
  }

  const departmentByKey = new Map(departments.map((dept) => [dept.key, dept]));

  const roles = await prisma.role.findMany({
    where: { tenantId },
    select: { id: true, code: true },
  });
  const roleIdByCode = new Map(roles.map((role) => [role.code, role.id]));
  const passwordHash = await argon2.hash(DEV_PASSWORD, { type: argon2.argon2id });

  const people: SeedPerson[] = [];

  for (const person of PEOPLE) {
    const department = departmentByKey.get(person.department);
    if (!department) throw new Error(`Seed org: không có phòng ban "${person.department}"`);

    const employeeId = `${tenantId}-emp-${person.key}`;
    const fullName = `${person.familyName} ${person.givenName}`;
    const jobTitle =
      person.rank === 'HEAD'
        ? `Trưởng phòng ${department.name.replace(/^Phòng\s+/, '')}`
        : department.name.replace(/^Phòng\s+/, 'Nhân viên ');
    const role = person.rank === 'HEAD' ? SystemRole.MANAGER : SystemRole.EMPLOYEE;

    const employeeData = {
      tenantId,
      employeeCode: person.code,
      fullName,
      familyName: person.familyName,
      givenName: person.givenName,
      branchId: department.branchId,
      departmentId: department.id,
      teamId: department.teamId,
      positionId: `${tenantId}-pos-${department.key}-${person.rank === 'HEAD' ? 'head' : 'staff'}`,
      jobTitle,
      startDate: new Date(Date.UTC(2026, 0, 1)),
      status: 'WORKING' as const,
      workEmail: person.email,
    };

    // Mã nhân viên là unique theo tenant, nhưng seed upsert theo `id`: một hồ sơ tạo tay trong DB
    // dev có thể đang giữ đúng mã này và làm seed vỡ P2002. Nhả mã ra trước rồi mới upsert.
    await prisma.employee.updateMany({
      where: { tenantId, employeeCode: person.code, id: { not: employeeId } },
      data: { employeeCode: `${person.code}-cu-${Date.now()}` },
    });

    await prisma.employee.upsert({
      where: { id: employeeId },
      update: { ...employeeData, deletedAt: null, updatedBy: 'SYSTEM' },
      create: { id: employeeId, ...employeeData, createdBy: 'SYSTEM', updatedBy: 'SYSTEM' },
    });

    // Tạo tài khoản ACTIVE kèm passwordHash để đăng nhập được ngay, bỏ qua luồng
    // gửi email mời (SMTP ở dev là placeholder).
    const user = await prisma.user.upsert({
      where: { email: person.email },
      update: {
        passwordHash,
        status: 'ACTIVE',
        deletedAt: null,
        fullName,
        branchId: department.branchId,
        teamId: department.teamId,
        updatedBy: 'SYSTEM',
      },
      create: {
        tenantId,
        email: person.email,
        passwordHash,
        fullName,
        status: 'ACTIVE',
        branchId: department.branchId,
        teamId: department.teamId,
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
      select: { id: true },
    });

    const roleId = roleIdByCode.get(role);
    if (!roleId) throw new Error(`Không tìm thấy role ${role}`);
    await prisma.userRole.upsert({
      where: { userId_roleId: { userId: user.id, roleId } },
      update: { dataScope: SYSTEM_ROLE_SCOPES[role], deletedAt: null },
      create: { tenantId, userId: user.id, roleId, dataScope: SYSTEM_ROLE_SCOPES[role] },
    });

    // Nối hồ sơ nhân sự ↔ tài khoản: RbacService lấy `departmentId` của principal
    // qua đường này, nên thiếu bước này là phân quyền theo phòng ban hỏng. Cũng chính là đường mà
    // chỉ tiêu KPI tự động dùng để biết "số này của ai" (`KpiPlanTarget.employee.userId`).
    await prisma.employee.update({
      where: { id: employeeId },
      data: { userId: user.id, updatedBy: 'SYSTEM' },
    });

    people.push({
      key: person.key,
      employeeId,
      userId: user.id,
      employeeCode: person.code,
      fullName,
      email: person.email,
      rank: person.rank,
      role,
      department,
    });
  }

  await prisma.employeeSequence.upsert({
    where: { tenantId_year: { tenantId, year: 2026 } },
    update: { lastValue: LAST_EMPLOYEE_SEQUENCE },
    create: { tenantId, year: 2026, lastValue: LAST_EMPLOYEE_SEQUENCE },
  });

  const summary =
    `Tổ chức dev: ${branches.length} chi nhánh × 2 phòng ban = ${departments.length} phòng, ` +
    `${departments.length} nhóm, ${departments.length * 2} vị trí, ${people.length} nhân sự — ` +
    `TẤT CẢ đều có tài khoản, mật khẩu chung "${DEV_PASSWORD}"\n` +
    departments
      .map((dept) => {
        const members = people
          .filter((person) => person.department.key === dept.key)
          .map((person) => `${person.email}${person.rank === 'HEAD' ? ' (MANAGER)' : ''}`)
          .join(', ');
        return `  · ${dept.branchName} / ${dept.name} [${dept.profile}]: ${members}`;
      })
      .join('\n');

  return { branches, departments, people, summary };
}
