            { from: 75, to: 90, score: 80 },
            { from: 90, to: null, score: 100 },
          ],
        },
      },
    ],
  },
];

const ASPECTS: Aspect[] = ['FINANCE', 'CUSTOMER', 'PROCESS', 'PEOPLE'];

function isPassFail(criteria: CriteriaBlueprint): criteria is PassFailBlueprint {
  return criteria.kind === 'PASS_FAIL';
}

/**
 * Thông tin mà `seed-kpi-plans.ts` cần để dựng chỉ tiêu của một kỳ mà KHÔNG chép
 * lại thư viện lần thứ hai — hai bản sao sẽ trôi khỏi nhau ngay lần sửa đầu tiên.
 */
export interface KpiCriteriaFacts {
  key: string;
  objectiveKey: string;
  aspect: Aspect;
  name: string;
  kind: 'MEASURED' | 'PASS_FAIL';
  unit: string | null;
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  allocationMode: 'DIVIDE' | 'INHERIT';
  scoringShape: 'UP' | 'DOWN' | 'RANGE';
  sourceType: 'MANUAL' | 'EXISTING' | 'FORMULA';
}

export const KPI_CRITERIA_FACTS: ReadonlyMap<string, KpiCriteriaFacts> = new Map(
  OBJECTIVE_LIBRARY.flatMap((objective) =>
    objective.criteria.map((criteria): [string, KpiCriteriaFacts] => [
      criteria.key,
      {
        key: criteria.key,
        objectiveKey: objective.key,
        aspect: objective.aspect,
        name: criteria.name,
        kind: isPassFail(criteria) ? 'PASS_FAIL' : 'MEASURED',
        unit: isPassFail(criteria) ? null : criteria.unit,
        measureType: isPassFail(criteria) ? 'RATIO' : criteria.measureType,
        allocationMode: isPassFail(criteria) ? 'INHERIT' : criteria.allocationMode,
        scoringShape: isPassFail(criteria) ? 'UP' : criteria.scoringShape,
        sourceType: criteria.source?.type ?? 'MANUAL',
      },
    ]),
  ),
);

/** Id của một chỉ tiêu trong thư viện của một phòng ban. */
export function kpiCriteriaId(departmentId: string, criteriaKey: string): string {
  return `${departmentId}-kpi-crit-${criteriaKey}`;
}

/** Id của một mục tiêu trong thư viện của một phòng ban. */
export function kpiObjectiveId(departmentId: string, objectiveKey: string): string {
  return `${departmentId}-kpi-obj-${objectiveKey}`;
}

/**
 * Dữ liệu ghi vào `kpi_template_criteria`.
 *
 * Chuẩn hoá PASS_FAIL đúng như `KpiObjectiveService.toCriteriaData`: không đơn
 * vị, gộp theo tỷ lệ, giao nguyên, không cấu hình chấm. Lệch khỏi bản đó là seed
 * tạo ra loại dữ liệu mà API không bao giờ tạo được.
 */
function toCriteriaRow(criteria: CriteriaBlueprint, sortOrder: number) {
  const source = criteria.source;
  const common = {
    name: criteria.name,
    description: criteria.description,
    csf: criteria.csf,
    sourceType: source?.type ?? ('MANUAL' as const),
    dataSourceId: source?.type === 'EXISTING' ? source.dataSourceId : null,
    formula: source?.type === 'FORMULA' ? source.formula : null,
    isCombined: false,
    isBlocking: criteria.isBlocking ?? false,
    sortOrder,
  };

  if (isPassFail(criteria)) {
    return {
      ...common,
      direction: 'INCREASE' as const,
      allocationMode: 'INHERIT' as const,
      aggregation: 'AVG' as const,
      kind: 'PASS_FAIL' as const,
      scoringShape: 'UP' as const,
      scoringMethod: 'CONTINUOUS' as const,
      measureType: 'RATIO' as const,
      scoringConfig: Prisma.JsonNull,
      unit: null,
    };
  }

  return {
    ...common,
    direction: DIRECTION_OF_SHAPE[criteria.scoringShape],
    allocationMode: criteria.allocationMode,
    aggregation: AGGREGATION_OF_MEASURE[criteria.measureType],
    kind: 'MEASURED' as const,
    scoringShape: criteria.scoringShape,
    scoringMethod: criteria.scoringMethod,
    measureType: criteria.measureType,
    scoringConfig: criteria.scoringConfig
      ? (criteria.scoringConfig as Prisma.InputJsonValue)
      : Prisma.JsonNull,
    unit: criteria.unit,
  };
}

/**
 * Bắt lỗi cấu hình NGAY LÚC SEED, bằng chính những hàm mà contract và UI dùng.
 *
 * Bảng khoảng hở một đoạn, `min > max`, công thức gõ sai tên nguồn — không thứ
 * nào nổ lúc ghi (cột là JSON / chuỗi tự do) mà nổ lúc chấm điểm, khi đó lỗi hiện
 * ra dưới dạng "điểm bằng null" ở một màn hình cách xa đây, gần như không lần
 * ngược được.
 */
function assertBlueprint(): void {
  const knownSourceIds = kpiSelectableDataSourceIds();
  const seenKeys = new Set<string>();

  for (const objective of OBJECTIVE_LIBRARY) {
    for (const criteria of objective.criteria) {
      if (seenKeys.has(criteria.key)) {
        // Khoá chỉ tiêu là ĐUÔI CỦA ID (`<dept>-kpi-crit-<key>`), nên trùng khoá
        // giữa hai mục tiêu là hai chỉ tiêu ghi lên cùng một hàng — bản sau ăn bản
        // trước và một mục tiêu bị rỗng, im lặng.
        throw new Error(`Seed KPI — khoá chỉ tiêu bị trùng: "${criteria.key}"`);
      }
      seenKeys.add(criteria.key);

      const sourceError = validateKpiSourceBinding({
        sourceType: criteria.source?.type ?? 'MANUAL',
        dataSourceId: criteria.source?.type === 'EXISTING' ? criteria.source.dataSourceId : null,
        formula: criteria.source?.type === 'FORMULA' ? criteria.source.formula : null,
        knownSourceIds,
      });
      if (sourceError) {
        throw new Error(`Seed KPI — nguồn của "${criteria.name}" không hợp lệ: ${sourceError}`);
      }

      if (isPassFail(criteria)) continue;
      const configError = validateScoringConfig({
        shape: criteria.scoringShape,
        method: criteria.scoringMethod,
        config: criteria.scoringConfig ?? null,
      });
      if (configError) {
        throw new Error(`Seed KPI — cấu hình chấm của "${criteria.name}" không hợp lệ: ${configError}`);
      }
    }
  }
}

/**
 * Ghi một bộ tỷ trọng trụ cột.
 *
 * Compound unique có `departmentId` nullable nên KHÔNG dùng được trong `where`
 * của upsert (giới hạn Prisma) ⇒ upsert theo id tiền định.
 */
async function upsertAspectWeights(
  prisma: PrismaClient,
  tenantId: string,
  scope: 'COMPANY' | 'DEPARTMENT',
  departmentId: string | null,
  periodYear: number,
  weights: AspectWeightSet,
): Promise<void> {
  for (const aspect of ASPECTS) {
    const id = `${tenantId}-kpi-aspect-${scope === 'COMPANY' ? 'company' : departmentId}-${aspect}-${periodYear}`;
    const weight = new Prisma.Decimal(weights[aspect]);
    await prisma.kpiAspectWeight.upsert({
      where: { id },
      update: { weight, updatedBy: 'SYSTEM' },
      create: {
        id,
        tenantId,
        scope,
        departmentId,
        aspect,
        periodYear,
        weight,
        createdBy: 'SYSTEM',
        updatedBy: 'SYSTEM',
      },
    });
  }
}

export async function seedKpi(prisma: PrismaClient, tenantId: string): Promise<string> {
  assertBlueprint();

  const departments = await prisma.department.findMany({
    where: { tenantId, deletedAt: null },
    orderBy: { name: 'asc' },
    select: { id: true, name: true },
  });
  if (departments.length === 0) return 'KPI: bỏ qua (chưa có phòng ban nào)';

  for (const year of [KPI_SEED_YEAR_CURRENT, KPI_SEED_YEAR_NEXT]) {
    await upsertAspectWeights(
      prisma,
      tenantId,
      'COMPANY',
      null,
      year,
      COMPANY_ASPECT_WEIGHTS[year],
    );
  }

  let objectiveCount = 0;
  let criteriaCount = 0;
  let retiredCriteria = 0;

  for (const [index, department] of departments.entries()) {
    const weightPair = DEPARTMENT_ASPECT_WEIGHTS[index % DEPARTMENT_ASPECT_WEIGHTS.length];
    await upsertAspectWeights(
      prisma,
      tenantId,
      'DEPARTMENT',
      department.id,
      KPI_SEED_YEAR_CURRENT,
      weightPair[0],
    );
    await upsertAspectWeights(
      prisma,
      tenantId,
      'DEPARTMENT',
      department.id,
      KPI_SEED_YEAR_NEXT,
      weightPair[1],
    );

    const objectiveIds: string[] = [];
    const criteriaIds: string[] = [];

    for (const blueprint of OBJECTIVE_LIBRARY) {
      const objectiveId = kpiObjectiveId(department.id, blueprint.key);
      objectiveIds.push(objectiveId);
      await prisma.kpiTemplate.upsert({
        where: { id: objectiveId },
        update: {
          aspect: blueprint.aspect,
          departmentId: department.id,
          title: blueprint.title,
          description: blueprint.description,
          updatedBy: 'SYSTEM',
          deletedAt: null,
        },
        create: {
          id: objectiveId,
          tenantId,
          aspect: blueprint.aspect,
          departmentId: department.id,
          title: blueprint.title,
          description: blueprint.description,
          createdBy: 'SYSTEM',
          updatedBy: 'SYSTEM',
        },
      });
      objectiveCount += 1;

      for (const [sortOrder, criteria] of blueprint.criteria.entries()) {
        const criteriaId = kpiCriteriaId(department.id, criteria.key);
        criteriaIds.push(criteriaId);
        const data = toCriteriaRow(criteria, sortOrder);
        await prisma.kpiTemplateCriteria.upsert({
          where: { id: criteriaId },
          update: { ...data, templateId: objectiveId, deletedAt: null },
          create: { id: criteriaId, tenantId, templateId: objectiveId, ...data },
        });
        criteriaCount += 1;
      }
    }

    /*
      Dọn phần thư viện do SEED tạo ra ở lần chạy trước mà nay không còn trong
      danh sách trên (đổi khoá, bỏ bớt chỉ tiêu).

      XOÁ MỀM chứ không xoá cứng: một chỉ tiêu có thể đã được đưa vào kế hoạch
      của người dùng, mà `KpiPlanMetric.criteria` là `onDelete: Restrict` —
      xoá cứng sẽ nổ FK và làm hỏng cả lượt seed. Lọc theo tiền tố id nên chỉ
      chạm vào hàng do seed sinh, không đụng chỉ tiêu người dùng tự tạo.
    */
    const retired = await prisma.kpiTemplateCriteria.updateMany({
      where: {
        tenantId,
        id: { startsWith: `${department.id}-kpi-crit-`, notIn: criteriaIds },
        deletedAt: null,
      },
      data: { deletedAt: new Date() },
    });
    retiredCriteria += retired.count;

    await prisma.kpiTemplate.updateMany({
      where: {
        tenantId,
        id: { startsWith: `${department.id}-kpi-obj-`, notIn: objectiveIds },
        deletedAt: null,
      },
      data: { deletedAt: new Date() },
    });
  }

  const criteriaPerDepartment = OBJECTIVE_LIBRARY.reduce(
    (sum, objective) => sum + objective.criteria.length,
    0,
  );
  const autoCriteria = OBJECTIVE_LIBRARY.flatMap((objective) => objective.criteria).filter(
    (criteria) => criteria.source,
  );

  return (
    `KPI thư viện: ${departments.length} phòng ban × (${OBJECTIVE_LIBRARY.length} mục tiêu, ` +
    `${criteriaPerDepartment} chỉ tiêu) = ${objectiveCount} + ${criteriaCount} bản ghi ` +
    `(${autoCriteria.filter((c) => c.source?.type === 'EXISTING').length} lấy tự động, ` +
    `${autoCriteria.filter((c) => c.source?.type === 'FORMULA').length} tính bằng công thức, ` +
    `${criteriaPerDepartment - autoCriteria.length} nhập tay mỗi phòng); ` +
    `tỷ trọng trụ cột kỳ ${KPI_SEED_YEAR_CURRENT} + ${KPI_SEED_YEAR_NEXT}` +
    (retiredCriteria ? `; ngừng dùng ${retiredCriteria} chỉ tiêu cũ` : '')
  );
}

