import { Prisma, PrismaClient } from '@prisma/client';
import {
  validateKpiSourceBinding,
  validateScoringConfig,
  type KpiScoringConfig,
} from '@ics/shared';
import { kpiSelectableDataSourceIds } from '../src/kpi/kpi-data-sources';

/**
 * Seed dữ liệu KPI theo khung BSC — **THƯ VIỆN ĐỊNH NGHĨA**.
 *
 * Nguyên tắc chia tầng, điểm dễ hiểu sai nhất của module:
 *
 *   - `KpiTemplate` + `KpiTemplateCriteria` = **ĐỊNH NGHĨA** ("Mục tiêu" và
 *     "Chỉ tiêu" trên giao diện), dùng lại qua nhiều kỳ. Chứa: đo cái gì, đơn vị,
 *     chấm thế nào, gộp thế nào, chia cho người thế nào, **lấy số ở đâu**.
 *     KHÔNG có trọng số, KHÔNG có mục tiêu số. Tên chỉ tiêu vì vậy là
 *     "Doanh thu", tuyệt đối không phải "Doanh thu đạt 500 triệu".
 *
 *   - `KpiPlan` + `KpiPlanMetric` = **CON SỐ CỦA MỘT KỲ**: mục tiêu + trọng số
 *     trong trụ + nhịp chia kỳ con. Nằm ở `seed-kpi-plans.ts`, chạy sau file này.
 *
 * Mục tiêu thuộc PHÒNG BAN, không dùng chung: theo phân quyền hiện tại chỉ quản
 * lý phòng mới tạo/sửa được mục tiêu của phòng mình, admin chỉ đọc.
 *
 * Tỷ trọng trụ cột cũng seed ở đây: nó là cấu hình của phòng ban (màn Tỷ trọng),
 * không phải kế hoạch. Thiếu nó thì kế hoạch vừa tạo không ban hành được và mọi
 * điểm tổng đều bằng `null`.
 *
