/**
 * Cột `direction` và `aggregation` là DI SẢN, suy ra từ mô hình chấm mới.
 *
 * Bản sao đúng nguyên của `DIRECTION_OF_SHAPE` / `AGGREGATION_OF_MEASURE` trong
 * `kpi-criteria-form.tsx`, để chỉ tiêu do seed tạo không phân biệt được với chỉ
 * tiêu người dùng tự nhập.
 */
const DIRECTION_OF_SHAPE = {
  UP: 'INCREASE',
  DOWN: 'DECREASE',
  // Khoảng tối ưu không "tăng" cũng không "giảm"; cột cũ buộc phải có một giá trị.
  RANGE: 'INCREASE',
} as const;

const AGGREGATION_OF_MEASURE = {
  ADDITIVE: 'SUM',
  SEMI_ADDITIVE: 'LAST',
  RATIO: 'AVG',
} as const;

const MILLION = 1_000_000;

/** Nguồn số liệu của một chỉ tiêu. Không khai = nhập tay. */
type SourceBinding =
  | { type: 'EXISTING'; dataSourceId: string }
  | { type: 'FORMULA'; formula: string };

type MeasuredBlueprint = {
  key: string;
  name: string;
  description: string;
  csf: string;
  kind?: 'MEASURED';
  unit: string;
  scoringShape: 'UP' | 'DOWN' | 'RANGE';
  scoringMethod: 'CONTINUOUS' | 'DISCRETE';
  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
  allocationMode: 'DIVIDE' | 'INHERIT';
  /**
   * Cấu hình dùng chung cho MỌI kỳ. Chỉ khai khi thang đo cố định qua các năm
   * (tỷ lệ %, số ngày tồn) — cận của bảng khoảng và min/max mang ĐƠN VỊ của phép
   * đo, nên nếu mỗi kỳ một thang thì phải để trống và khai ở từng kế hoạch.
   */
  scoringConfig?: KpiScoringConfig;
  isBlocking?: boolean;
  source?: SourceBinding;
};

type PassFailBlueprint = {
  key: string;
  name: string;
  description: string;
  csf: string;
  kind: 'PASS_FAIL';
  isBlocking?: boolean;
  source?: SourceBinding;
};

type CriteriaBlueprint = MeasuredBlueprint | PassFailBlueprint;

type ObjectiveBlueprint = {
  key: string;
  aspect: Aspect;
  title: string;
  description: string;
  criteria: CriteriaBlueprint[];
};

