/**
 * Số ngày trễ theo lịch giữa hạn chót và thời điểm hoàn thành (hoặc thời điểm hiện tại).
 *
 * Hàm ngày thuần, dùng chung cho dashboard (công nợ quá hạn) và module Tài chính. Trước đây nằm
 * trong `kpi-project-scoring.ts`; tách ra riêng để không phụ thuộc vào engine chấm điểm KPI.
 */
export function calendarLateDays(
  dueDate: Date | null | undefined,
  completedAt: Date | null | undefined,
  now: Date,
): number {
  if (!dueDate) return 0;
  const finishedAt = completedAt ?? now;
  const msPerDay = 24 * 60 * 60 * 1000;
  const diffDays = Math.floor((finishedAt.getTime() - dueDate.getTime()) / msPerDay);
  return Math.max(0, diffDays);
}
