/**
 * SỔ GHI SỐ THỰC TẾ MÀ BỘ SEED VỪA TẠO RA.
 *
 * Vì sao cần: kế hoạch KPI ở `seed-kpi-plans.ts` phải đặt MỤC TIÊU, mà mục tiêu chỉ có nghĩa nếu nó
 * đứng gần con số thực tế. Trước đây target được viết cứng và mỗi lần đổi bảng dữ liệu mẫu là phần
 * trăm đạt nhảy sang 8% hoặc 2 000% — người xem không học được gì từ một cái đồng hồ luôn kịch kim.
 *
 * Vì vậy các bộ seed dữ liệu (bán hàng, vận hành) vừa ghi DB vừa cộng dồn vào đây, rồi kế hoạch KPI
 * suy target ra từ chính con số đó. Hai bên không còn cách nào lệch nhau.
 *
 * Đây KHÔNG phải bản sao thứ hai của dữ liệu: nó chỉ là tổng theo (người, năm, phép đo) và chết
 * ngay khi tiến trình seed kết thúc. Nguồn sự thật vẫn là DB — `kpi-data-sources.ts` đọc lại từ đó.
 */

/**
 * Phép đo được theo dõi. Tên đặt theo Ý NGHĨA NGHIỆP VỤ, không theo tên nguồn KPI: một mục tiêu có
 * thể suy ra từ nhiều nguồn (tỷ lệ đúng hạn cần cả tử và mẫu).
 */
export type SeedFactMetric =
  // Bán hàng
  | 'revenue'
  | 'deals'
  | 'customers'
  | 'opportunities'
  | 'won'
  | 'activities'
  // Chăm sóc khách hàng
  | 'tickets_created'
  | 'tickets_resolved'
  | 'tickets_on_time'
  | 'resolution_hours'
  | 'first_response_minutes'
  | 'first_response_count'
  | 'csat_total'
  | 'csat_count'
  | 'incidents'
  | 'complaints'
  // Công việc & quy trình nội bộ
  | 'tasks_completed'
  | 'tasks_due'
  | 'requests_done'
  // Tài chính
  | 'reconciled'
  | 'finance_late_days'
  | 'finance_errors'
  | 'finance_compliance';

export class SeedFactBook {
  private readonly totals = new Map<string, number>();

  private static keyOf(userId: string, year: number, metric: SeedFactMetric): string {
    return `${userId}|${year}|${metric}`;
  }

  add(userId: string, year: number, metric: SeedFactMetric, value: number): void {
    const key = SeedFactBook.keyOf(userId, year, metric);
    this.totals.set(key, (this.totals.get(key) ?? 0) + value);
  }

  /** Tổng của một nhóm người trong một năm. Người chưa có số nào thì tính 0. */
  total(userIds: readonly string[], year: number, metric: SeedFactMetric): number {
    let sum = 0;
    for (const userId of userIds) {
      sum += this.totals.get(SeedFactBook.keyOf(userId, year, metric)) ?? 0;
    }
    return sum;
  }

  /** Có ghi được số nào cho nhóm này chưa — dùng để biết nên suy target hay dùng số mặc định. */
  has(userIds: readonly string[], year: number, metric: SeedFactMetric): boolean {
    return userIds.some((userId) => this.totals.has(SeedFactBook.keyOf(userId, year, metric)));
  }
}

