import { Prisma, PrismaClient } from '@prisma/client';
import type { SeedPerson } from './seed-org';
import type { SeedFactBook } from './seed-facts';

/**
 * DỮ LIỆU VẬN HÀNH cho môi trường demo: ticket CSKH, công việc, phiếu nội bộ, công việc và lỗi
 * tài chính — rải theo tháng, theo người, theo chi nhánh.
 *
 * Vì sao phải có riêng bộ này: trong 34 nguồn số liệu KPI thì hơn một nửa đọc các bảng
 * `tickets` / `tasks` / `request_tickets` / `finance_tasks` / `finance_issues`, mà KHÔNG bộ seed nào
 * từng ghi vào đó. Hệ quả là chỉ tiêu nào nối vào chúng cũng trả về 0 — và 0 trên một chỉ tiêu
 * "càng thấp càng tốt" lại là 100 điểm, nên bảng KPI trông như đã chạy đúng. Không thể kiểm được
 * phần lấy số tự động bằng một bộ dữ liệu như vậy.
 *
 * ── AI SINH RA DỮ LIỆU GÌ ────────────────────────────────────────────────────────────────────
 *
 *   Ticket CSKH        chỉ phòng có `profile = SUPPORT`
 *   Công việc tài chính chỉ phòng có `profile = FINANCE`
 *   Công việc (Task)    MỌI người — chỉ tiêu "hoàn thành đúng hạn" áp cho tất cả các phòng
 *   Phiếu nội bộ        MỌI người — cùng lý do
 *
 * Cố ý KHÔNG rải ticket cho phòng kinh doanh: nguồn `support.*` lọc theo `Ticket.ownerId`, nên nếu
 * ai cũng có ticket thì không còn kiểm được việc "chỉ tiêu của phòng A chỉ lấy số của phòng A".
 * Ranh giới giữa các phòng chính là thứ cần nhìn thấy được.
 *
 * ── GHI BẰNG deleteMany + createMany, KHÔNG PHẢI upsert ──────────────────────────────────────
 *
 * Bộ này sinh vài nghìn dòng. Upsert từng dòng là một vòng gọi mạng cho mỗi dòng, và DB dev nằm sau
 * pooler ở xa: đo được ~60ms mỗi lượt, tức là hơn năm phút chỉ để ghi bảng công việc. `createMany`
 * gửi cả lô trong một câu lệnh. Đổi lại phải xoá trước, và xoá được vì mọi id ở đây đều mang tiền tố
 * riêng của bộ seed nên không đụng dữ liệu người dùng tự tạo.
 */

/**
 * Số tháng dựng lùi lại, tính cả tháng hiện tại.
 *
 * 20 tháng phủ trọn năm KPI hiện tại + cả năm trước, đủ để so sánh kỳ trước trên trang chủ mà không
 * phải trả giá cho 24 tháng × 18 người ở những bảng có mật độ dòng cao nhất.
 */
const OPS_MONTHS = 20;

const HOUR_MS = 60 * 60 * 1000;
const DAY_MS = 24 * HOUR_MS;
const MILLION = 1_000_000;

export interface OpsSeedContext {
  tenantId: string;
  adminUserId: string;
  people: SeedPerson[];
  moduleWorkflowId: string;
  /** id cột Kanban của quy trình mặc định, tra theo `TaskStatus`. */
  moduleColumnIds: Map<string, string>;
  /** Quy trình đề nghị mà `seed.ts` đã dựng — phiếu nội bộ phải trỏ vào một quy trình có thật. */
  requestProcessId: string;
  requestProcessName: string;
  facts: SeedFactBook;
  now?: Date;
}

/**
 * Mốc thời gian của một sự kiện, kẹp lại ở hiện tại.
 *
 * Giờ cố định 03:00 UTC = 10:00 giờ Việt Nam: nằm giữa ngày ở cả hai múi giờ, nên sự kiện không bao
 * giờ nhảy sang ngày khác khi báo cáo quy về lịch Bangkok. Kẹp ở `now` vì tháng đang chạy không được
 * có mốc nào ở tương lai — một ticket "đã xử lý xong" vào ngày mai sẽ biến mất khỏi mọi thẻ số của
 * tháng này mà vẫn nằm trong biểu đồ.
 */
function eventAt(now: Date, monthsAgo: number, day: number, hourUtc = 3): Date {
  const stamp = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - monthsAgo, day, hourUtc, 0, 0),
  );
  return stamp.getTime() > now.getTime() ? new Date(now.getTime() - HOUR_MS) : stamp;
}

/** Ngày cuối của tháng cách `monthsAgo` tháng — để không sinh mốc ngày 31 của tháng 2. */
function daysInMonthAgo(now: Date, monthsAgo: number): number {
  return new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - monthsAgo + 1, 0),
  ).getUTCDate();
}

/** Nửa đêm UTC của một ngày lịch — đúng dạng mà cột `@db.Date` mong đợi. */
function dateOnly(source: Date): Date {
  return new Date(
    Date.UTC(source.getUTCFullYear(), source.getUTCMonth(), source.getUTCDate(), 0, 0, 0),
  );
}

/** Mốc đó có thuộc tương lai không — dùng để biết một hạn đã tới hay chưa. */
function inFuture(stamp: Date, now: Date): boolean {
  return stamp.getTime() > now.getTime();
}

/** Ngày trong tháng dùng cho các mốc, quay vòng. Tránh mùng 1 và cuối tháng cho khỏi lệch múi giờ. */
const EVENT_DAYS = [3, 6, 9, 12, 15, 18, 21, 24, 26, 28] as const;

const TICKET_SUBJECTS = [
  'Yêu cầu hướng dẫn cấu hình thiết bị',
  'Không truy cập được cổng dịch vụ',
  'Đề nghị đổi thông tin hợp đồng',
  'Phản ánh chất lượng lắp đặt',
  'Yêu cầu cấp lại tài liệu kỹ thuật',
  'Sự cố gián đoạn dịch vụ tại chi nhánh',
  'Khiếu nại thời gian phản hồi',
  'Yêu cầu bổ sung tài khoản người dùng',
] as const;

const FINANCE_TASK_TITLES = {
  RECONCILIATION: 'Đối soát công nợ khách hàng',
  CLOSING: 'Chốt sổ tháng',
  TAX_REPORT: 'Lập báo cáo thuế',
  PAYMENT: 'Thanh toán nhà cung cấp',
} as const;

const REQUEST_TITLES = [
  { category: 'LEAVE' as const, title: 'Đề nghị nghỉ phép', reason: 'Nghỉ phép theo chế độ' },
  {
    category: 'MISSED_ATTENDANCE' as const,
    title: 'Đề nghị bù công',
    reason: 'Quên chấm công khi đi công tác',
  },
  {
    category: 'EQUIPMENT' as const,
    title: 'Đề nghị cấp thiết bị',
    reason: 'Cần bổ sung thiết bị làm việc',
  },
] as const;

/**
 * Ghi một lô lớn theo từng khúc.
 *
 * Postgres giới hạn 65535 tham số cho một câu lệnh; một dòng công việc có ~20 cột nên khoảng 3000
 * dòng là chạm trần. Cắt khúc 500 vừa an toàn vừa vẫn gộp đủ để nhanh.
 */
async function writeChunks<T>(
  rows: T[],
  write: (chunk: T[]) => Promise<unknown>,
  size = 500,
): Promise<void> {
  for (let index = 0; index < rows.length; index += size) {
    await write(rows.slice(index, index + size));
  }
}

export async function seedDemoOps(
  prisma: PrismaClient,
  context: OpsSeedContext,
): Promise<string> {
  const { tenantId, adminUserId, people, facts } = context;
  const now = context.now ?? new Date();

  const taskRows: Prisma.TaskCreateManyInput[] = [];
  const ticketRows: Prisma.TicketCreateManyInput[] = [];
  const requestRows: Prisma.RequestTicketCreateManyInput[] = [];
  const financeTaskRows: Prisma.FinanceTaskCreateManyInput[] = [];
  const financeIssueRows: Prisma.FinanceIssueCreateManyInput[] = [];

  /** Khách hàng để gắn ticket vào — không bắt buộc, nhưng ticket không có khách trông rất giả. */
  const customers = await prisma.customer.findMany({
    where: { tenantId, deletedAt: null },
    select: { id: true },
    orderBy: { createdAt: 'asc' },
    take: 60,
  });

  for (const [personIndex, person] of people.entries()) {
    const profile = person.department.profile;
    /** Trưởng phòng gánh nhiều việc hơn nhân viên — để bảng xếp hạng không phẳng. */
    const load = person.rank === 'HEAD' ? 1.3 : 1;

    for (let monthOffset = 0; monthOffset < OPS_MONTHS; monthOffset += 1) {
      const monthsAgo = OPS_MONTHS - 1 - monthOffset;
      const lastDay = daysInMonthAgo(now, monthsAgo);
      const year = new Date(
        Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - monthsAgo, 1),
      ).getUTCFullYear();
      const dayAt = (slot: number) => Math.min(EVENT_DAYS[slot % EVENT_DAYS.length], lastDay);

      // ── Công việc (mọi người) ────────────────────────────────
      /*
        Mỗi tháng có ĐÚNG MỘT việc bỏ ngỏ. Đó là chỗ khiến "tỷ lệ hoàn thành đúng hạn" không bao giờ
        chạm 100%: mẫu số đếm theo HẠN, tử số đếm theo NGÀY HOÀN THÀNH, nên một việc treo là tỷ lệ
        tụt xuống ngay tháng đó — đúng hành vi cần nhìn thấy khi kiểm công thức.
      */
      const taskTotal = Math.round((4 + (personIndex % 3)) * load);
      for (let index = 0; index < taskTotal; index += 1) {
        const isOpen = index === taskTotal - 1;
        const due = dateOnly(eventAt(now, monthsAgo, dayAt(index)));
        const dueInFuture = inFuture(due, now);
        // Hạn còn ở tương lai thì việc chưa thể "hoàn thành trước hạn" — để nguyên đang làm.
        const completed = !isOpen && !dueInFuture;
        const completedAt = completed
          ? eventAt(now, monthsAgo, dayAt(index), index % 3 === 0 ? 9 : 4)
          : null;
        const status = completed ? 'COMPLETED' : dueInFuture ? 'NEW' : 'IN_PROGRESS';
        const order = new Prisma.Decimal((index + 1) * 1024);

        taskRows.push({
          id: `${tenantId}-ops-task-${person.key}-${monthOffset}-${index}`,
          tenantId,
          code: `TSK-${person.employeeCode.slice(-5)}-${String(monthOffset).padStart(2, '0')}${index}`,
          workflowId: context.moduleWorkflowId,
          workflowColumnId: context.moduleColumnIds.get(status) as string,
          branchId: person.department.branchId,
          departmentId: person.department.id,
          teamId: person.department.teamId,
          title: `${FINANCE_TASK_TITLES.CLOSING === 'x' ? '' : ''}${taskTitle(profile, index)}`,
          status,
          assigneeId: person.userId,
          createdById: person.userId,
          dueDate: due,
          completedAt,
          progress: completed ? 100 : dueInFuture ? 0 : 50,
          listOrder: order,
          kanbanOrder: order,
          createdAt: eventAt(now, monthsAgo, Math.max(1, dayAt(index) - 2)),
          updatedBy: adminUserId,
        });

        facts.add(person.userId, year, 'tasks_due', 1);
        if (completed) facts.add(person.userId, year, 'tasks_completed', 1);
      }

      // ── Phiếu đề nghị nội bộ (mọi người) ─────────────────────
      /*
        Một phiếu mỗi tháng, đã duyệt xong. `operation.completed_processes` lọc theo `resolvedAt` +
        `status = APPROVED`, nên phiếu còn PENDING không đếm — cố ý để tháng đang chạy có một phiếu
        chưa duyệt và con số của tháng này thấp hơn, thay vì mọi tháng giống nhau.
      */
      const requestSpec = REQUEST_TITLES[(personIndex + monthOffset) % REQUEST_TITLES.length];
      const requestCreatedAt = eventAt(now, monthsAgo, dayAt(1));
      const requestResolved = monthsAgo > 0 || dayAt(1) < now.getUTCDate() - 1;
      requestRows.push({
        id: `${tenantId}-ops-req-${person.key}-${monthOffset}`,
        tenantId,
        code: `PDN-${person.employeeCode.slice(-5)}-${String(monthOffset).padStart(2, '0')}`,
        processId: context.requestProcessId,
        processName: context.requestProcessName,
        category: requestSpec.category,
        title: requestSpec.title,
        reason: requestSpec.reason,
        formData: { note: requestSpec.reason },
        requesterUserId: person.userId,
        requesterEmployeeId: person.employeeId,
        branchId: person.department.branchId,
        departmentId: person.department.id,
        teamId: person.department.teamId,
        status: requestResolved ? 'APPROVED' : 'PENDING',
        resolvedAt: requestResolved ? eventAt(now, monthsAgo, Math.min(dayAt(1) + 2, lastDay)) : null,
        createdAt: requestCreatedAt,
        createdBy: person.userId,
        updatedBy: adminUserId,
      });
      if (requestResolved) facts.add(person.userId, year, 'requests_done', 1);

      // ── Ticket CSKH (chỉ phòng Chăm sóc khách hàng) ──────────
      if (profile === 'SUPPORT') {
        const ticketTotal = Math.round((8 + (personIndex % 3)) * load);
        for (let index = 0; index < ticketTotal; index += 1) {
          const createdAt = eventAt(now, monthsAgo, dayAt(index), 2);
          /*
            Ba loại theo tỷ lệ 6 : 2 : 2. `support.incident_count` và `support.complaint_count` đếm
            theo LOẠI, nên nếu mọi ticket cùng loại REQUEST thì hai chỉ tiêu đó vĩnh viễn bằng 0 và
            không phân biệt được với "chưa cắm nguồn".
          */
          const type = index % 5 === 3 ? 'INCIDENT' : index % 5 === 4 ? 'COMPLAINT' : 'REQUEST';

          // SLA 48 giờ; cứ 7 ticket có 1 cái xử lý trễ hạn để tỷ lệ đúng SLA không phẳng 100%.
          const slaDueAt = new Date(createdAt.getTime() + 2 * DAY_MS);
          const late = index % 7 === 6;
          const resolvedAt =
            index % 9 === 8
              ? null // Còn tồn đọng — không tính vào tử/mẫu của mọi chỉ tiêu theo `resolvedAt`.
              : new Date(createdAt.getTime() + (late ? 3.5 : 1 + (index % 3) * 0.4) * DAY_MS);
          const resolved = resolvedAt !== null && !inFuture(resolvedAt, now);
          const firstRespondedAt = new Date(createdAt.getTime() + (20 + (index % 5) * 25) * 60_000);
          // Ticket đã đánh giá: 2 trên 3. Số còn lại để `csat_response_count` nhỏ hơn số ticket —
          // đúng thực tế, và là điều kiện để thấy mẫu số của công thức CSAT hoạt động.
          const csatScore = index % 3 === 2 ? null : [5, 4, 5, 3, 4, 5][index % 6];

          ticketRows.push({
            id: `${tenantId}-ops-ticket-${person.key}-${monthOffset}-${index}`,
            tenantId,
            code: `TK-${person.employeeCode.slice(-5)}-${String(monthOffset).padStart(2, '0')}${index}`,
            type,
            status: resolved ? 'RESOLVED' : 'IN_PROGRESS',
            priority: type === 'INCIDENT' ? 'HIGH' : 'NORMAL',
            subject: TICKET_SUBJECTS[index % TICKET_SUBJECTS.length],
            customerId: customers.length ? customers[index % customers.length].id : null,
            slaDueAt,
            firstRespondedAt,
            resolvedAt: resolved ? resolvedAt : null,
            closedAt: resolved ? resolvedAt : null,
            csatScore: resolved ? csatScore : null,
            ownerId: person.userId,
            branchId: person.department.branchId,
            departmentId: person.department.id,
            teamId: person.department.teamId,
            createdAt,
            createdBy: person.userId,
            updatedBy: adminUserId,
          });

          facts.add(person.userId, year, 'tickets_created', 1);
          if (type === 'INCIDENT') facts.add(person.userId, year, 'incidents', 1);
          if (type === 'COMPLAINT') facts.add(person.userId, year, 'complaints', 1);
          facts.add(person.userId, year, 'first_response_count', 1);
          facts.add(
            person.userId,
            year,
            'first_response_minutes',
            (firstRespondedAt.getTime() - createdAt.getTime()) / 60_000,
          );
          if (resolved && resolvedAt) {
            facts.add(person.userId, year, 'tickets_resolved', 1);
            facts.add(
              person.userId,
              year,
              'resolution_hours',
              (resolvedAt.getTime() - createdAt.getTime()) / HOUR_MS,
            );
            if (resolvedAt <= slaDueAt) facts.add(person.userId, year, 'tickets_on_time', 1);
            if (csatScore !== null) {
              facts.add(person.userId, year, 'csat_total', csatScore);
              facts.add(person.userId, year, 'csat_count', 1);
            }
          }
        }
      }

      // ── Công việc + lỗi tài chính (chỉ phòng Tài chính) ──────
      if (profile === 'FINANCE') {
        const financeSpecs = [
          { type: 'RECONCILIATION' as const, amount: (180 + personIndex * 25) * MILLION },
          { type: 'RECONCILIATION' as const, amount: (120 + personIndex * 15) * MILLION },
          { type: 'CLOSING' as const, amount: null },
          { type: 'TAX_REPORT' as const, amount: null },
        ];

        for (const [index, spec] of financeSpecs.entries()) {
          const dueDate = dateOnly(eventAt(now, monthsAgo, dayAt(index + 2)));
          const dueInFuture = inFuture(dueDate, now);
          /*
            Cứ 5 việc có 1 việc xong trễ 3 ngày, và việc của tháng đang chạy chưa tới hạn thì để
            chưa xong. `finance.late_days` tính việc CHƯA XONG tới HIỆN TẠI, nên nếu tháng nào cũng
            xong đúng hạn thì chỉ tiêu trừ điểm luôn bằng 0 và không kiểm được gì.
          */
          const lateDays = (personIndex + index + monthOffset) % 5 === 0 ? 3 : 0;
          const completedAt = dueInFuture
            ? null
            : new Date(dueDate.getTime() + lateDays * DAY_MS + 8 * HOUR_MS);
          const done = completedAt !== null && !inFuture(completedAt, now);

          financeTaskRows.push({
            id: `${tenantId}-ops-fintask-${person.key}-${monthOffset}-${index}`,
            tenantId,
            code: `FIN-${person.employeeCode.slice(-5)}-${String(monthOffset).padStart(2, '0')}${index}`,
            type: spec.type,
            status: done ? 'COMPLETED' : 'IN_PROGRESS',
            title: `${FINANCE_TASK_TITLES[spec.type]} — ${person.department.branchName}`,
            dueDate,
            completedAt: done ? completedAt : null,
            targetAmount: spec.amount === null ? null : new Prisma.Decimal(spec.amount),
            // Đối soát xong mới có số đã đối soát; việc còn treo thì để trống, không ghi 0 —
            // 0 và "chưa làm" là hai chuyện khác nhau ở chỉ tiêu cộng dồn.
            reconciledAmount:
              spec.amount !== null && done ? new Prisma.Decimal(spec.amount) : null,
            ownerId: person.userId,
            branchId: person.department.branchId,
            departmentId: person.department.id,
            createdAt: eventAt(now, monthsAgo, 2),
            createdBy: person.userId,
            updatedBy: adminUserId,
          });

          if (spec.amount !== null && done) {
            facts.add(person.userId, year, 'reconciled', spec.amount);
          }
          if (done && lateDays > 0) facts.add(person.userId, year, 'finance_late_days', lateDays);
        }

        // Lỗi nghiệp vụ: 1 lỗi mỗi tháng, và cứ 4 tháng thêm 1 vi phạm tuân thủ.
        const issues: Array<{ type: 'ERROR' | 'COMPLIANCE'; title: string }> = [
          { type: 'ERROR', title: 'Hạch toán sai tài khoản đối ứng' },
        ];
        if ((monthOffset + personIndex) % 4 === 0) {
          issues.push({ type: 'COMPLIANCE', title: 'Chứng từ thiếu chữ ký duyệt' });
        }
        for (const [index, issue] of issues.entries()) {
          const detectedAt = eventAt(now, monthsAgo, dayAt(index + 5));
          financeIssueRows.push({
            id: `${tenantId}-ops-finissue-${person.key}-${monthOffset}-${index}`,
            tenantId,
            type: issue.type,
            severity: issue.type === 'COMPLIANCE' ? 'HIGH' : 'MEDIUM',
            title: issue.title,
            detectedAt,
            resolvedAt: monthsAgo > 0 ? new Date(detectedAt.getTime() + 4 * DAY_MS) : null,
            ownerId: person.userId,
            branchId: person.department.branchId,
            departmentId: person.department.id,
            createdAt: detectedAt,
            createdBy: person.userId,
            updatedBy: adminUserId,
          });
          facts.add(
            person.userId,
            year,
            issue.type === 'ERROR' ? 'finance_errors' : 'finance_compliance',
            1,
          );
        }
      }
    }
  }

  /*
    Xoá theo tiền tố rồi ghi lại cả lô. Tiền tố `<tenant>-ops-*` chỉ do bộ seed này sinh ra, nên
    không thể chạm vào công việc / ticket người dùng tự tạo — và cũng dọn luôn những dòng của lần
    chạy trước mà nay đã đổi khoá (thêm người, đổi số tháng).
  */
  await prisma.task.deleteMany({ where: { tenantId, id: { startsWith: `${tenantId}-ops-task-` } } });
  await writeChunks(taskRows, (chunk) => prisma.task.createMany({ data: chunk }));

  await prisma.requestTicket.deleteMany({
    where: { tenantId, id: { startsWith: `${tenantId}-ops-req-` } },
  });
  await writeChunks(requestRows, (chunk) => prisma.requestTicket.createMany({ data: chunk }));

  await prisma.ticket.deleteMany({
    where: { tenantId, id: { startsWith: `${tenantId}-ops-ticket-` } },
  });
  await writeChunks(ticketRows, (chunk) => prisma.ticket.createMany({ data: chunk }));

  // Lỗi trước công việc: `FinanceIssue.financeTaskId` có thể trỏ vào công việc, nên xoá theo thứ tự
  // ngược lại với thứ tự tạo để không vướng khoá ngoại.
  await prisma.financeIssue.deleteMany({
    where: { tenantId, id: { startsWith: `${tenantId}-ops-finissue-` } },
  });
  await prisma.financeTask.deleteMany({
    where: { tenantId, id: { startsWith: `${tenantId}-ops-fintask-` } },
  });
  await writeChunks(financeTaskRows, (chunk) => prisma.financeTask.createMany({ data: chunk }));
  await writeChunks(financeIssueRows, (chunk) => prisma.financeIssue.createMany({ data: chunk }));

  return (
    `Vận hành ${OPS_MONTHS} tháng: ${taskRows.length} công việc, ${requestRows.length} phiếu nội bộ, ` +
    `${ticketRows.length} ticket CSKH, ${financeTaskRows.length} công việc tài chính, ` +
    `${financeIssueRows.length} lỗi/vi phạm — chia cho ${people.length} người ở ` +
    `${new Set(people.map((person) => person.department.branchId)).size} chi nhánh`
  );
}

/** Tiêu đề công việc theo nghiệp vụ của phòng — để Kanban không phải 800 dòng giống nhau. */
function taskTitle(profile: SeedPerson['department']['profile'], index: number): string {
  const titles: Record<typeof profile, readonly string[]> = {
    SALES: [
      'Gọi lại khách hàng tiềm năng',
      'Chuẩn bị báo giá cho khách',
      'Theo dõi tiến độ đơn hàng',
      'Khảo sát công trình',
      'Chốt điều khoản thanh toán',
      'Cập nhật hồ sơ khách hàng',
    ],
    SUPPORT: [
      'Xử lý ticket tồn đọng',
      'Gọi xác nhận sau khi khắc phục sự cố',
      'Cập nhật kịch bản chăm sóc',
      'Tổng hợp phản ánh của khách',
      'Hướng dẫn khách sử dụng dịch vụ',
      'Rà soát ticket quá hạn SLA',
    ],
    FINANCE: [
      'Đối chiếu sao kê ngân hàng',
      'Kiểm tra hoá đơn đầu vào',
      'Lập bảng kê công nợ',
      'Chuẩn bị số liệu chốt sổ',
      'Rà soát chứng từ thanh toán',
      'Kiểm tra hồ sơ thuế',
    ],
    HR: [
      'Rà soát hồ sơ nhân sự',
      'Tổ chức buổi đào tạo nội bộ',
      'Tổng hợp bảng công tháng',
      'Phỏng vấn ứng viên',
      'Cập nhật quy định nội bộ',
      'Chuẩn bị hợp đồng lao động',
    ],
  };
  const pool = titles[profile];
  return pool[index % pool.length];
}

