/**
 * Quyển sổ của một người ở tháng `monthsAgo`, đã nhân hệ số chi nhánh.
 *
 * Hệ số áp vào TIỀN và SỐ LƯỢNG, KHÔNG áp vào số cơ hội thua: `lost` là mẫu số của tỷ lệ chuyển đổi,
 * nhân nó theo chi nhánh sẽ làm tỷ lệ chuyển đổi của ba chi nhánh khác nhau mà không có lý do nghiệp
 * vụ nào — người xem sẽ đi tìm nguyên nhân cho một tạo tác của seed.
 */
function scaledMonth(seller: Seller, monthsAgo: number): MonthlyBook {
  const base = monthFor(BOOK_TEMPLATES[seller.level], monthsAgo);
  if (seller.scale === 1) return base;
  const money = (value: number) => Math.max(10, Math.round(value * seller.scale));
  return {
    won: base.won.map(money),
    contracts: base.contracts.map(money),
    lost: base.lost,
    open: base.open.map((deal) => ({ stage: deal.stage, amount: money(deal.amount) })),
    customers: Math.max(1, Math.round(base.customers * seller.scale)),
    activities: Math.max(1, Math.round(base.activities * seller.scale)),
  };
}

