export async function seedDemoSales(
  prisma: PrismaClient,
  context: {
    tenantId: string;
    adminUserId: string;
    /** Toàn bộ nhân sự do `seedOrg` dựng — bộ này tự lọc ra người của phòng Kinh doanh. */
    people: SeedPerson[];
    facts: SeedFactBook;
    now?: Date;
  },
): Promise<string> {
  const { tenantId, adminUserId, facts } = context;
  const now = context.now ?? new Date();

  /*
    Danh sách người bán: admin + mọi nhân sự thuộc phòng có `profile = SALES`.

    Cấp bậc quyết định mức sổ, và HAI người của bộ seed cũ giữ nguyên khoá id (`lan`, `anh`) — mọi
    khách hàng / cơ hội / đơn hàng đã ghi ở lần chạy trước đều mang khoá đó, đổi là bỏ lại rác.
  */
  const legacyKeys: Record<string, string> = {
    'sales-head': 'anh',
    'sales-staff-1': 'lan',
  };
  const sellers: Seller[] = [
    // Admin không thuộc nhóm nào nên phần của admin nằm ở dòng "Chưa phân công" của báo cáo phòng
    // ban — đúng thực tế, và cũng cho thấy dòng đó hoạt động.
    { key: 'admin', ownerId: adminUserId, teamId: null, level: 'low', scale: 1 },
    ...context.people
      .filter((person) => person.department.profile === 'SALES')
      .map((person): Seller => {
        const level: BookLevel =
          person.rank === 'HEAD' ? 'high' : person.key.endsWith('staff-1') ? 'mid' : 'low';
        return {
          key: legacyKeys[person.key] ?? person.key,
          ownerId: person.userId,
          teamId: person.department.teamId,
          level,
          scale: BRANCH_SCALE[person.department.branchKey] ?? 1,
        };
      }),
  ];

