import { Prisma, PrismaClient } from '@prisma/client';
import { slotCount, slotKey, slotRange, type KpiCadence } from '@ics/shared';
import {
  KPI_CRITERIA_FACTS,
  KPI_SEED_YEAR_CURRENT,
  KPI_SEED_YEAR_NEXT,
  kpiCriteriaId,
  type KpiCriteriaFacts,
} from './seed-kpi';
import type { SeedDepartment, SeedDepartmentProfile, SeedPerson } from './seed-org';
import type { SeedFactBook, SeedFactMetric } from './seed-facts';

/**
 * KẾ HOẠCH KPI CỦA MỘT KỲ — phần mà bộ seed trước đây cố tình không làm, và vì vậy không ai kiểm
 * được đường lấy số tự động.
 *
 * Thư viện định nghĩa (`seed-kpi.ts`) chỉ nói "đo cái gì, lấy ở đâu". Con số chỉ xuất hiện khi một
 * chỉ tiêu được đưa vào kế hoạch của một kỳ và giao cho người cụ thể — vì nguồn số liệu lọc theo
 * `ownerId`, mà "của ai" chỉ có nghĩa ở DÒNG CÁ NHÂN. Không có kế hoạch thì toàn bộ phần EXISTING /
 * FORMULA nằm im, không cách nào biết nó đúng hay sai.
 *
 * ── DỰNG THẲNG BẢNG, KHÔNG GỌI SERVICE ───────────────────────────────────────────────────────
 *
 * Bộ seed là script Prisma thuần, không có DI container của Nest, nên không gọi được
 * `KpiPlanService.addDeptMetric` / `KpiAllocationService.allocate`. Thay vào đó nó ghi ĐÚNG hình
 * dạng mà hai service đó ghi:
 *
 *   · dòng phòng ban  `level = DEPARTMENT`, `planTargetId = null`, `parentMetricId = null`
 *   · dòng cá nhân    `level = INDIVIDUAL`, cả hai khác null — bất biến của luồng phân bổ
 *   · snapshot        kind / scoringShape / scoringMethod / measureType / cadence / scoringConfig /
 *                     sourceType / dataSourceId / formula đều CHÉP từ định nghĩa xuống, và chép
 *                     tiếp xuống dòng cá nhân
 *   · lưới mốc        `KpiPlanSlot` dùng chung cho mọi chỉ tiêu cùng nhịp trong một kế hoạch;
 *                     `KpiPlanMetricSlot.targetPercent` lưu PHẦN TRĂM, không lưu số tuyệt đối
 *   · trạng thái dòng `status = DRAFT` — `changeStatus` chỉ đổi trạng thái của KẾ HOẠCH, không bao
 *                     giờ đụng tới cột này, nên đặt khác đi là tạo ra dữ liệu API không tạo được
 *
 * Lệch khỏi hình dạng đó là seed sinh ra loại dữ liệu mà giao diện không bao giờ tạo được, và mọi
 * lỗi tìm thấy trên nó đều là lỗi giả.
 *
 * ── MỤC TIÊU SUY TỪ SỐ THỰC TẾ, KHÔNG VIẾT CỨNG ──────────────────────────────────────────────
 *
 * Bộ dữ liệu mẫu vừa ghi bao nhiêu doanh thu / ticket / công việc thì `SeedFactBook` biết. Mục tiêu
 * ở đây được suy ra từ đó: ngoại suy phần đã đi được của năm ra cả năm rồi hạ/nâng một chút. Nhờ vậy
 * phần trăm đạt luôn nằm quanh mức hợp lý — sửa bảng dữ liệu mẫu không còn làm đồng hồ chỉ tiêu kịch
 * kim (đúng lỗi của bản viết cứng trước đây, khi doanh thu chuyển sang đọc đơn hàng thì mọi target
 * lệch một triệu lần vì đơn vị "triệu VNĐ").
 */

const MILLION = 1_000_000;

/** Năm sau đặt cao hơn năm nay — và với chỉ tiêu trừ điểm thì SIẾT lại, không nới ra. */
const NEXT_YEAR_UP = 1.15;
const NEXT_YEAR_DOWN = 0.9;

/**
 * Cách suy mục tiêu của một chỉ tiêu trong kế hoạch.
 *
 *   FACT   ngoại suy một phép đo cộng dồn ra cả năm. `factor` dùng cho những chỉ tiêu tỉ lệ thuận
 *          với một phép đo khác nhưng không được theo dõi riêng (công nợ ≈ một phần doanh thu).
 *   RATE   tỷ lệ giữa hai phép đo — KHÔNG ngoại suy, vì tỷ lệ không lớn lên theo thời gian.
 *   FIXED  chỉ tiêu nhập tay: hệ thống không có nguồn nào, nên mục tiêu là một chính sách.
 */
type TargetRule =
  | { from: 'FACT'; metric: SeedFactMetric; factor?: number; margin?: number; fallback: number }
  | {
      from: 'RATE';
      over: SeedFactMetric;
      under: SeedFactMetric;
      scale?: number;
      margin?: number;
      fallback: number;
    }
  | { from: 'FIXED'; value: number };

interface PlanMetricSpec {
  criteriaKey: string;
  /** Trọng số trong TRỤ CỘT. Tổng của mỗi trụ phải đúng 100, nếu không kế hoạch không ban hành được. */
  weight: number;
  cadence: KpiCadence;
