/**
 * Lưới mốc theo nhịp và cách gộp.
 *
 *   ADDITIVE       chia phần — tổng các mốc = 100%.
 *   SEMI_ADDITIVE  lộ trình — MỐC CUỐI = 100%, các mốc giữa là chặng đường.
 *
 * Hai luật này do `validateSlotTargets` trong `@ics/shared` cầm; bảng dưới phải khớp, nếu không kế
 * hoạch ghi được nhưng không ban hành được và thông báo chặn sẽ trỏ vào một chỗ rất khó hiểu.
 *
 * Cố ý KHÔNG chia đều 12 tháng: nhịp kinh doanh thật nặng về cuối năm, và một lưới đều tăm tắp làm
 * người xem tưởng cột "so với tiến độ" bị hỏng.
 */
const SLOT_GRIDS: Record<'QUARTER' | 'MONTH', Record<'ADDITIVE' | 'SEMI_ADDITIVE', number[]>> = {
  QUARTER: {
    ADDITIVE: [22, 25, 25, 28],
    SEMI_ADDITIVE: [40, 65, 85, 100],
  },
  MONTH: {
    ADDITIVE: [7, 7, 8, 8, 9, 9, 9, 9, 8, 8, 9, 9],
    SEMI_ADDITIVE: [20, 30, 40, 50, 58, 66, 74, 80, 86, 92, 96, 100],
  },
};

/** Loại này có phải khai lưới mốc không — bản sao đúng luật của `requiresSlotTargets`. */
function needsSlotGrid(facts: KpiCriteriaFacts, cadence: KpiCadence): boolean {
  if (cadence === 'PERIOD') return false;
  if (facts.kind === 'PASS_FAIL') return false;
  return facts.measureType === 'ADDITIVE' || facts.measureType === 'SEMI_ADDITIVE';
}

/** Làm tròn mục tiêu theo đơn vị — target tiền lẻ tới từng đồng đọc rất khó. */
function roundTarget(value: number, unit: string | null): number {
  if (unit === 'VNĐ') return Math.max(MILLION, Math.round(value / MILLION) * MILLION);
  if (unit === '%' || unit === 'điểm' || unit === 'giờ' || unit === 'phút' || unit === 'ngày') {
    return Math.max(0.1, Math.round(value * 10) / 10);
  }
  return Math.max(1, Math.round(value));
}

interface TargetContext {
  userIds: string[];
  year: number;
  /** Số tháng của `year` đã đi qua (dùng để ngoại suy ra cả năm). */
  elapsedMonths: number;
  facts: SeedFactBook;
}

/**
 * Mục tiêu CẢ KỲ của một chỉ tiêu ở cấp phòng ban.
 *
 * Ngoại suy phần đã đi được của năm ra cả năm: dữ liệu mẫu chỉ có tới tháng hiện tại, nên lấy thẳng
 * tổng đã ghi làm mục tiêu cả năm sẽ ra một kế hoạch mà tháng 8 đã hoàn thành 100% và ba tháng cuối
 * không còn gì để làm.
 */
function deptTarget(spec: PlanMetricSpec, facts: KpiCriteriaFacts, ctx: TargetContext): number {
  const rule = spec.target;
  const defaultMargin = facts.scoringShape === 'DOWN' ? 1.05 : facts.scoringShape === 'UP' ? 0.95 : 1;

  if (rule.from === 'FIXED') return roundTarget(rule.value, facts.unit);

  if (rule.from === 'RATE') {
    const over = ctx.facts.total(ctx.userIds, ctx.year, rule.over);
    const under = ctx.facts.total(ctx.userIds, ctx.year, rule.under);
    if (under <= 0) return roundTarget(rule.fallback, facts.unit);
    const rate = (over / under) * (rule.scale ?? 1) * (rule.margin ?? defaultMargin);
    return roundTarget(rate, facts.unit);
  }

  const recorded = ctx.facts.total(ctx.userIds, ctx.year, rule.metric);
  if (recorded <= 0 || ctx.elapsedMonths <= 0) return roundTarget(rule.fallback, facts.unit);
  const fullYear = (recorded / ctx.elapsedMonths) * 12;
  return roundTarget(fullYear * (rule.factor ?? 1) * (rule.margin ?? defaultMargin), facts.unit);
}

/**
 * Chia phần trăm cho từng người THEO ĐÓNG GÓP THỰC TẾ của họ, không chia đều.
 *
 * Chia đều thì mọi người luôn đạt xấp xỉ như nhau và bảng xếp hạng cá nhân phẳng lì — mà bảng đó
 * chính là thứ cần nhìn thấy. Chia theo đóng góp thì người bán nhiều nhận phần lớn hơn, và phần trăm
 * đạt của từng người vẫn quanh 100% vì cả tử và mẫu đều đi từ cùng một con số.
 *
 * Mốc cuối nhận PHẦN CÒN LẠI chứ không nhân phần trăm: làm tròn từng người có thể ra tổng 99.9%, và
 * `buildPublishBlockers` chặn ban hành khi chia phần chưa đủ 100%.
 */
function splitPercents(weights: number[]): number[] {
  const total = weights.reduce((sum, value) => sum + value, 0);
  if (total <= 0) {
    // Chưa ai có số nào (chỉ tiêu nhập tay, hoặc phòng chưa phát sinh dữ liệu) ⇒ chia đều.
    const even = Math.floor((100 / weights.length) * 100) / 100;
    return weights.map((_, index) =>
      index === weights.length - 1
        ? Math.round((100 - even * (weights.length - 1)) * 100) / 100
        : even,
    );
  }
  const raw = weights.map((value) => Math.round((value / total) * 10_000) / 100);
  const head = raw.slice(0, -1);
  const used = head.reduce((sum, value) => sum + value, 0);
  return [...head, Math.round((100 - used) * 100) / 100];
}

export interface KpiPlanSeedContext {
  tenantId: string;
  departments: SeedDepartment[];
  people: SeedPerson[];
  facts: SeedFactBook;
  now?: Date;
}

export async function seedKpiPlans(
  prisma: PrismaClient,
  context: KpiPlanSeedContext,
): Promise<string> {
  const { tenantId, departments, people, facts } = context;
  const now = context.now ?? new Date();

  /*
    Số tháng của kỳ hiện tại đã đi qua. Dùng để ngoại suy mục tiêu. Kỳ đã qua hẳn thì 12; kỳ chưa
    tới thì 0 và mọi mục tiêu rơi về giá trị mặc định — nhưng kế hoạch của năm sau không đi đường này
    (nó nhân từ mục tiêu năm nay), nên trường hợp đó không xảy ra.
  */
  const elapsedMonths =
    now.getUTCFullYear() > KPI_SEED_YEAR_CURRENT
      ? 12
      : now.getUTCFullYear() < KPI_SEED_YEAR_CURRENT
        ? 0
        : now.getUTCMonth() + 1;

  let planCount = 0;
  let deptMetricCount = 0;
  let individualCount = 0;
  let slotCells = 0;
  const adopted: string[] = [];
  const skipped: string[] = [];

  for (const department of departments) {
    const members = people.filter((person) => person.department.key === department.key);
    if (!members.length) {
      skipped.push(`${department.name} (không có nhân sự)`);
      continue;
    }
    const specs = PLAN_BY_PROFILE[department.profile].filter((spec) => spec.weight > 0);
    const userIds = members.map((person) => person.userId);

    /*
      Mục tiêu của kỳ HIỆN TẠI tính một lần rồi dùng cho cả hai kỳ: kỳ sau nhân hệ số tăng trưởng.
      Không ngoại suy lại cho kỳ sau vì kỳ đó chưa có dữ liệu nào — mọi mục tiêu sẽ rơi về mặc định
      và hai kế hoạch của cùng một phòng trông không liên quan gì đến nhau.
    */
    const currentTargets = new Map<string, number>();
    for (const spec of specs) {
      const criteriaFacts = KPI_CRITERIA_FACTS.get(spec.criteriaKey);
      if (!criteriaFacts) throw new Error(`Seed KPI kế hoạch: không có chỉ tiêu "${spec.criteriaKey}"`);
      currentTargets.set(
        spec.criteriaKey,
        deptTarget(spec, criteriaFacts, { userIds, year: KPI_SEED_YEAR_CURRENT, elapsedMonths, facts }),
      );
    }

    for (const periodYear of [KPI_SEED_YEAR_CURRENT, KPI_SEED_YEAR_NEXT]) {
      /*
        Kỳ hiện tại ĐANG ÁP DỤNG để nhập được kết quả và để chỉ tiêu tự động chạy thật; kỳ sau còn
        NHÁP để thấy trạng thái đó (nhập kết quả bị khoá, cấu trúc còn sửa được).
      */
      const status = periodYear === KPI_SEED_YEAR_CURRENT ? 'APPROVED' : 'DRAFT';

      /*
        `KpiPlan` unique theo (tenant, phòng ban, kỳ) — nên KHÔNG upsert theo id của seed được: một
        kế hoạch do người dùng tự tạo cho cùng phòng cùng kỳ đang giữ chỗ đó và insert sẽ vỡ P2002.
        Tìm theo unique thật rồi DÙNG LẠI id đang có.
      */
      const existing = await prisma.kpiPlan.findFirst({
        where: { tenantId, departmentId: department.id, periodYear },
        select: { id: true },
      });
      const seedPlanId = `${department.id}-kpi-plan-${periodYear}`;
      const planId = existing?.id ?? seedPlanId;
      if (existing && existing.id !== seedPlanId) {
        adopted.push(`${department.name} kỳ ${periodYear}`);
      }

      const planData = {
        departmentId: department.id,
        periodYear,
        name: `Kế hoạch KPI ${periodYear} — ${department.name}`,
        description: `Kế hoạch KPI kỳ ${periodYear} của ${department.name}, ${department.branchName}.`,
        status: status as 'APPROVED' | 'DRAFT',
        publishedAt: status === 'APPROVED' ? new Date(Date.UTC(periodYear, 0, 5)) : null,
        closedAt: null,
        deletedAt: null,
        updatedBy: 'SYSTEM',
      };
      await prisma.kpiPlan.upsert({
        where: { id: planId },
        update: planData,
        create: { id: planId, tenantId, ...planData, createdBy: 'SYSTEM' },
      });
      planCount += 1;

      /*
        Dựng lại toàn bộ ruột của kế hoạch. Xoá chỉ tiêu TRƯỚC: `KpiPlanMetricSlot` và các bảng lịch
        sử đều `onDelete: Cascade` từ chỉ tiêu, còn `KpiPlanTarget` và `KpiPlanSlot` thì bị chỉ tiêu
        trỏ vào — xoá ngược thứ tự là vướng khoá ngoại.
      */
      await prisma.kpiPlanMetric.deleteMany({ where: { tenantId, planId } });
      await prisma.kpiPlanTarget.deleteMany({ where: { tenantId, planId } });
      await prisma.kpiPlanSlot.deleteMany({ where: { tenantId, planId } });

      // ── Người được giao ───────────────────────────────────────
      const targetRows: Prisma.KpiPlanTargetCreateManyInput[] = members.map((person) => ({
        id: `${planId}-t-${person.key}`,
        tenantId,
        planId,
        targetType: 'EMPLOYEE',
        employeeId: person.employeeId,
        employeeNameSnapshot: person.fullName,
        departmentIdSnapshot: department.id,
        departmentNameSnapshot: department.name,
        positionIdSnapshot: `${tenantId}-pos-${department.key}-${person.rank === 'HEAD' ? 'head' : 'staff'}`,
        positionNameSnapshot: person.rank === 'HEAD' ? `Trưởng phòng` : `Nhân viên`,
        status: 'DRAFT',
      }));
      await prisma.kpiPlanTarget.createMany({ data: targetRows });

      // ── Lưới kỳ con dùng chung cho cả kế hoạch ────────────────
      const cadences = new Set(
        specs
          .map((spec) => spec.cadence)
          .filter((cadence): cadence is 'QUARTER' | 'MONTH' => cadence !== 'PERIOD'),
      );
      const planSlotIdByKey = new Map<string, string>();
      const slotRows: Prisma.KpiPlanSlotCreateManyInput[] = [];
      for (const cadence of ['PERIOD' as const, ...cadences]) {
        for (let index = 0; index < slotCount(cadence, periodYear); index += 1) {
          const key = slotKey(cadence, periodYear, index);
          if (planSlotIdByKey.has(key)) continue;
          const id = `${planId}-s-${key}`;
          planSlotIdByKey.set(key, id);
          const range = slotRange(cadence, periodYear, index);
          slotRows.push({
            id,
            tenantId,
            planId,
            cadence,
            slotKey: key,
            slotIndex: index,
            slotStartAt: range.startAt,
            slotEndAt: range.endAt,
          });
        }
      }
      await prisma.kpiPlanSlot.createMany({ data: slotRows });

      // ── Chỉ tiêu phòng ban + phân bổ cá nhân ──────────────────
      const deptRows: Prisma.KpiPlanMetricCreateManyInput[] = [];
      const individualRows: Prisma.KpiPlanMetricCreateManyInput[] = [];
      const metricSlotRows: Prisma.KpiPlanMetricSlotCreateManyInput[] = [];

      const definitions = await prisma.kpiTemplateCriteria.findMany({
        where: {
          tenantId,
          id: { in: specs.map((spec) => kpiCriteriaId(department.id, spec.criteriaKey)) },
        },
        select: {
          id: true,
          templateId: true,
          name: true,
          description: true,
          csf: true,
          direction: true,
          allocationMode: true,
          aggregation: true,
          isBlocking: true,
          kind: true,
          scoringShape: true,
          scoringMethod: true,
          measureType: true,
          scoringConfig: true,
          unit: true,
          sourceType: true,
          dataSourceId: true,
          formula: true,
          template: { select: { aspect: true } },
        },
      });
      const definitionById = new Map(definitions.map((row) => [row.id, row]));

      for (const spec of specs) {
        const criteriaFacts = KPI_CRITERIA_FACTS.get(spec.criteriaKey) as KpiCriteriaFacts;
        const criteria = definitionById.get(kpiCriteriaId(department.id, spec.criteriaKey));
        if (!criteria) {
          throw new Error(
            `Seed KPI kế hoạch: thiếu định nghĩa "${spec.criteriaKey}" ở ${department.name} — chạy seedKpi trước`,
          );
        }

        const base = currentTargets.get(spec.criteriaKey) as number;
        /*
          Đạt/không đạt lưu `targetValue = 1` mang nghĩa "MỘT LẦN KIỂM", cùng thang với `actualValue`
          (số lần đạt) — đúng như `addDeptMetric` làm. Nhập kết quả theo kỳ con sẽ tự nâng lên N.
        */
        const target =
          criteria.kind === 'PASS_FAIL'
            ? 1
            : periodYear === KPI_SEED_YEAR_CURRENT
              ? base
              : roundTarget(
                  base * (criteriaFacts.scoringShape === 'DOWN' ? NEXT_YEAR_DOWN : NEXT_YEAR_UP),
                  criteria.unit,
                );

        const metricId = `${planId}-m-${spec.criteriaKey}`;
        const shared = {
          tenantId,
          planId,
          criteriaId: criteria.id,
          sourceCriteriaId: criteria.id,
          objectiveId: criteria.templateId,
          aspect: criteria.template.aspect,
          csf: criteria.csf,
          name: criteria.name,
          description: criteria.description,
          unit: criteria.unit,
          weight: new Prisma.Decimal(spec.weight),
          direction: criteria.direction,
          aggregation: criteria.aggregation,
          isBlocking: criteria.isBlocking,
          kind: criteria.kind,
          scoringShape: criteria.scoringShape,
          scoringMethod: criteria.scoringMethod,
          measureType: criteria.measureType,
          cadence: spec.cadence,
          // Nguồn số liệu snapshot xuống kế hoạch, rồi snapshot tiếp xuống dòng cá nhân — và ĐÂY
          // mới là nơi nguồn tự động thật sự chạy, vì nó lọc theo `ownerId`.
          sourceType: criteria.sourceType,
          dataSourceId: criteria.dataSourceId,
          formula: criteria.formula,
          scoringConfig: (criteria.scoringConfig ?? Prisma.JsonNull) as Prisma.InputJsonValue,
          status: 'DRAFT' as const,
        };

        deptRows.push({
          id: metricId,
          ...shared,
          level: 'DEPARTMENT',
          parentMetricId: null,
          planTargetId: null,
          targetValue: new Prisma.Decimal(target),
          allocationPercent: null,
          // Chưa có kết quả ⇒ null, KHÔNG phải 0: 0 bị chấm thành 0% và kéo điểm tổng xuống.
          actualValue: null,
          allocationMode: criteria.allocationMode,
        });
        deptMetricCount += 1;

        // Lưới mốc của dòng phòng ban — lưu PHẦN TRĂM để đổi mục tiêu cả kỳ là các mốc tự giãn theo.
        if (needsSlotGrid(criteriaFacts, spec.cadence)) {
          const grid =
            SLOT_GRIDS[spec.cadence as 'QUARTER' | 'MONTH'][
              criteriaFacts.measureType as 'ADDITIVE' | 'SEMI_ADDITIVE'
            ];
          for (const [index, percent] of grid.entries()) {
            const key = slotKey(spec.cadence, periodYear, index);
            metricSlotRows.push({
              id: `${planId}-ms-${spec.criteriaKey}-${key}`,
              tenantId,
              planSlotId: planSlotIdByKey.get(key) as string,
              planMetricId: metricId,
              targetPercent: new Prisma.Decimal(percent),
              targetValue: null,
              actualValue: null,
            });
            slotCells += 1;
          }
        }

        // Phân bổ cho từng người.
        const mode = criteria.allocationMode ?? 'DIVIDE';
        const contributions = members.map((person) => {
          const rule = spec.target;
          if (rule.from === 'FACT') return facts.total([person.userId], KPI_SEED_YEAR_CURRENT, rule.metric);
          if (rule.from === 'RATE') return facts.total([person.userId], KPI_SEED_YEAR_CURRENT, rule.under);
          return 0;
        });
        const percents = splitPercents(contributions);

        for (const [index, person] of members.entries()) {
          const percent = mode === 'INHERIT' ? null : percents[index];
          const personTarget =
            percent === null ? target : Math.round(((target * percent) / 100) * 100) / 100;
          individualRows.push({
            id: `${metricId}-${person.key}`,
            ...shared,
            level: 'INDIVIDUAL',
            parentMetricId: metricId,
            planTargetId: `${planId}-t-${person.key}`,
            targetValue: new Prisma.Decimal(personTarget),
            allocationPercent: percent === null ? null : new Prisma.Decimal(percent),
            actualValue: null,
            allocationMode: mode,
          });
          individualCount += 1;
        }
      }

      // Cha trước con: `parentMetricId` là khoá ngoại tự trỏ, hai lô riêng là chắc chắn đúng thứ tự.
      await prisma.kpiPlanMetric.createMany({ data: deptRows });
      await prisma.kpiPlanMetric.createMany({ data: individualRows });
      if (metricSlotRows.length) {
        await prisma.kpiPlanMetricSlot.createMany({ data: metricSlotRows });
      }
    }
  }

  return (
    `KPI kế hoạch: ${planCount} kế hoạch (${KPI_SEED_YEAR_CURRENT} ĐANG ÁP DỤNG + ` +
    `${KPI_SEED_YEAR_NEXT} NHÁP cho mỗi phòng), ${deptMetricCount} chỉ tiêu phòng ban, ` +
    `${individualCount} dòng giao cá nhân, ${slotCells} ô lưới mốc` +
    (adopted.length ? `\n  · DÙNG LẠI kế hoạch đã có và dựng lại ruột: ${adopted.join('; ')}` : '') +
    (skipped.length ? `\n  · bỏ qua: ${skipped.join('; ')}` : '')
  );
}

