function patch(p, pairs) {
  let s = fs.readFileSync(p, 'utf8');
  for (const [old, nw] of pairs) {
    const n = s.split(old).length - 1;
    if (n !== 1) throw new Error(`${p}: count=${n} for: ${old.slice(0, 90)}`);
    s = s.replace(old, nw);
  }
  fs.writeFileSync(p, s);
}

