// ─────────────────────────────────────────────────────────────
// 2. Gộp lô rồi truy vấn
// ─────────────────────────────────────────────────────────────

/**
 * Gộp mọi ô cần tính thành các lượt truy vấn theo (nguồn × khoảng thời gian).
 *
 * Đây là chỗ quyết định hiệu năng. Một kế hoạch 12 người × 3 chỉ tiêu tự động,
 * nếu hỏi từng người thì là 36 lượt × ~2 truy vấn cho MỘT lần mở trang. Gộp lại
 * còn đúng một truy vấn cho mỗi (nguồn, kỳ) nhờ `resolveByOwner` dùng `groupBy`.
 */
private planBatchJobs(targets: readonly ResolveTarget[]): Map<string, BatchJob> {
  const jobs = new Map<string, BatchJob>();

  for (const target of targets) {
    if (target.reuse !== undefined) continue; // Đã chốt, không phải hỏi lại.

    for (const sourceId of target.sources) {
      const key = `${sourceId}|${target.period.start.getTime()}|${target.period.end.getTime()}`;
      const job = jobs.get(key) ?? {
        sourceId,
        period: target.period,
        owners: new Set<string>(),
        needsTenantWide: false,
      };
      if (target.tenantWideOnly) job.needsTenantWide = true;
      else for (const owner of target.owners) job.owners.add(owner);
      jobs.set(key, job);
    }
  }

  return jobs;
}

/** Chạy các lượt gộp. Khoá kết quả trùng với khoá của `planBatchJobs`. */
private async runBatchJobs(jobs: Map<string, BatchJob>): Promise<Map<string, SourceReading>> {
  const entries = await Promise.all(
    [...jobs].map(async ([key, job]) => [key, await this.runBatchJob(job)] as const),
  );
  return new Map(entries);
}

private async runBatchJob(job: BatchJob): Promise<SourceReading> {
  const source = findKpiDataSource(job.sourceId);
  // Nguồn đã bị gỡ khỏi danh mục (đổi mã, bỏ tính năng) — để `null` là "chưa
  // đánh giá được" thay vì 0, vì 0 sẽ bị chấm thành trượt.
  if (!source) return { byOwner: new Map(), tenantWide: null, missing: true };

  const tenantWide = job.needsTenantWide
    ? await source.resolve(this.prisma.scoped, { period: job.period })
    : null;

  if (!job.owners.size) return { byOwner: new Map(), tenantWide, missing: false };

  const owners = [...job.owners];
  if (source.resolveByOwner) {
    const byOwner = await source.resolveByOwner(this.prisma.scoped, {
      period: job.period,
      ownerUserIds: owners,
    });
    return { byOwner, tenantWide, missing: false };
  }

  /*
    Nguồn chưa có bản gộp lô ⇒ hỏi từng người. Đúng nhưng tốn; chỉ nên rơi vào
    đây với nguồn ít dùng. Thêm `resolveByOwner` cho nguồn nào bị dùng nhiều.
  */
  const byOwner = new Map<string, number>();
  for (const owner of owners) {
    byOwner.set(
      owner,
      await source.resolve(this.prisma.scoped, { period: job.period, ownerUserId: owner }),
    );
  }
  return { byOwner, tenantWide, missing: false };
}

// ─────────────────────────────────────────────────────────────
// 3. Ghép thành con số của từng ô
// ─────────────────────────────────────────────────────────────

private composeValues(
  targets: readonly ResolveTarget[],
  readings: ReadonlyMap<string, SourceReading>,
): Map<string, AutoSlotValue[]> {
  const result = new Map<string, AutoSlotValue[]>();

  for (const target of targets) {
    const bucket = result.get(target.metric.id) ?? [];

    if (target.reuse !== undefined) {
      bucket.push({ slotIndex: target.slotIndex, value: target.reuse, frozen: true });
      result.set(target.metric.id, bucket);
      continue;
    }

    const value = this.valueOf(target, readings);
    bucket.push({ slotIndex: target.slotIndex, value, frozen: target.freeze && value !== null });
    result.set(target.metric.id, bucket);
  }

  return result;
}

private valueOf(
  target: ResolveTarget,
  readings: ReadonlyMap<string, SourceReading>,
): number | null {
  /** Số của MỘT nguồn cho đúng phạm vi người của dòng này. */
  const readOne = (sourceId: string): number | null => {
    const key = `${sourceId}|${target.period.start.getTime()}|${target.period.end.getTime()}`;
    const reading = readings.get(key);
    if (!reading || reading.missing) return null;
    if (target.tenantWideOnly) return reading.tenantWide;

    /*
      Cộng số của những người trong phạm vi. Dòng cá nhân chỉ có một người; dòng
      phòng ban chưa giao cho ai thì cộng cả phòng.

      Vắng mặt trong bảng = 0, KHÔNG phải `null`: nguồn RAW đều là đếm/cộng nên
      "không có dòng nào" đúng nghĩa là 0. Cần phân biệt "chưa có gì để đo" thì
      dùng công thức có mẫu số — 0/0 mới ra `null`.
    */
    let total = 0;
    for (const owner of target.owners) total += reading.byOwner.get(owner) ?? 0;
    return total;
  };

  const raw = this.rawValueOf(target, readOne);
  if (raw === null) return null;

  /*
    Đạt/không đạt: nguồn trả về một con số đếm, quy về 1 lần đạt / 0 lần đạt.
    Đây đúng là loại đáng tự động hoá nhất — "có nộp báo cáo hôm nay không" thì
    đếm được, và không ai muốn tick tay 20 ô mỗi tháng.
  */
  if (target.metric.kind === 'PASS_FAIL') return raw > 0 ? 1 : 0;

  return roundFour(raw);
}

private rawValueOf(
  target: ResolveTarget,
  readOne: (sourceId: string) => number | null,
): number | null {
  if (target.metric.sourceType === 'EXISTING') {
    return readOne(target.sources[0]);
  }

  /*
    Công thức được tính LẠI TỪ CÁC NGUỒN THÔ ở từng ô, không bao giờ gộp kết quả
    của các ô lại. Đây là luật sống còn của tỷ lệ: quý 1 thắng 10/40 = 25%, quý 2
    thắng 30/60 = 50%, cả năm là 40/100 = 40% chứ KHÔNG phải trung bình 37.5%.
    Vì mỗi ô đều tính từ tử số và mẫu số của chính khoảng thời gian đó nên kết
    quả đúng ở mọi mức gộp.
  */
  const parsed = parseKpiFormula(target.metric.formula ?? '');
  if (!parsed.ok) return null;

  const values: Record<string, number | null> = {};
  for (const ref of parsed.refs) values[ref] = readOne(ref);

