/** Ghi rõ số đến từ đâu — người đọc lịch sử không phải tra mã nguồn. */
private freezeNote(target: ResolveTarget): string {
  if (target.metric.sourceType === 'FORMULA') {
    return `Tự động chốt theo công thức: ${target.metric.formula ?? ''}`.trim();
  }
  const source = findKpiDataSource(target.sources[0]);
  return `Tự động chốt từ nguồn: ${source?.name ?? target.sources[0]}`;
}

/**
 * Dòng kỳ con dùng chung cho mọi chỉ tiêu cùng nhịp trong kế hoạch — giống hệt
 * `KpiPlanService.ensurePlanSlot`. Hai nơi cùng ghi vào một bảng nên phải cùng
 * một cách sinh `slotKey`, nếu không sẽ có hai dòng cho cùng một khoảng.
 */
private async ensurePlanSlot(
  tx: Prisma.TransactionClient,
  plan: { id: string; periodYear: number },
  cadence: KpiCadence,
  slotIndex: number,
): Promise<string> {
  const tenantId = this.tenantId();
  const key = slotKey(cadence, plan.periodYear, slotIndex);

  const existing = await tx.kpiPlanSlot.findFirst({
    where: { tenantId, planId: plan.id, slotKey: key },
    select: { id: true },
  });
  if (existing) return existing.id;

  const range = slotRange(cadence, plan.periodYear, slotIndex);
  const created = await tx.kpiPlanSlot.create({
    data: {
      tenantId,
      planId: plan.id,
      cadence,
      slotKey: key,
      slotIndex,
      slotStartAt: range.startAt,
      slotEndAt: range.endAt,
    },
    select: { id: true },
  });
  return created.id;
}

