      sau là chốt mất phần chưa kịp vào sổ.

      Lấy mốc 03/02 để chỉ có ĐÚNG hai kỳ con vào cuộc: tháng 1 vừa hết (chưa
      quá 5 ngày ân hạn) và tháng 2 đang chạy. Lấy mốc muộn hơn trong năm thì
      các tháng đầu năm đã quá hạn ân hạn từ lâu và sẽ bị chốt — đúng, nhưng
      không phải cái đang kiểm ở đây.
    */
    const groupBy = jest.fn().mockResolvedValue([{ assigneeId: 'user_a', _count: { _all: 1 } }]);
    const { service, prisma } = setup({ groupBy });

    await run(service, [{ ...BASE_METRIC, cadence: 'MONTH' }], new Date('2026-02-03T00:00:00Z'));

    expect(groupBy).toHaveBeenCalledTimes(2);
    expect(prisma.$transaction).not.toHaveBeenCalled();
  });

  it('kỳ đã qua hẳn hạn ân hạn thì chốt, kỳ đang chạy vẫn để sống', async () => {
    const groupBy = jest.fn().mockResolvedValue([{ assigneeId: 'user_a', _count: { _all: 2 } }]);
    const { service } = setup({ groupBy });

    const result = await run(
      service,
      [{ ...BASE_METRIC, cadence: 'MONTH' }],
      new Date('2026-02-09T00:00:00Z'),
    );

    const slots = result.get('m_1') ?? [];
    expect(slots.find((slot) => slot.slotIndex === 0)?.frozen).toBe(true);
    expect(slots.find((slot) => slot.slotIndex === 1)?.frozen).toBe(false);
  });

  it('ô đã chốt thì dùng lại số cũ, KHÔNG hỏi nguồn nữa', async () => {
    // Đây là điều kiện sống còn: hỏi lại nghĩa là điểm của kỳ đã duyệt lương
    // sẽ đổi mỗi khi ai đó sửa một bản ghi CRM cũ.
    const { service, groupBy } = setup();

    const result = await run(
      service,
      [{ ...BASE_METRIC, autoSyncedAt: new Date('2027-01-05T00:00:00Z'), actualValue: 42 }],
      new Date('2027-03-01T00:00:00Z'),
    );

    expect(groupBy).not.toHaveBeenCalled();
    expect(result.get('m_1')?.[0]).toMatchObject({ value: 42, frozen: true });
  });
});

