import { PrismaClient } from '@prisma/client';

const p = new PrismaClient();

async function main() {
  const tenant = await p.tenant.findFirstOrThrow({ where: { slug: 'demo' } });

  const counts = {
    kpiPlan: await p.kpiPlan.count({ where: { tenantId: tenant.id, deletedAt: null } }),
    kpiPlanMetric: await p.kpiPlanMetric.count({
      where: { tenantId: tenant.id, deletedAt: null },
    }),
    autoMetric: await p.kpiPlanMetric.count({
      where: { tenantId: tenant.id, deletedAt: null, sourceType: { not: 'MANUAL' } },
    }),
    frozenPeriod: await p.kpiPlanMetric.count({
      where: { tenantId: tenant.id, deletedAt: null, autoSyncedAt: { not: null } },
    }),
    metricSlot: await p.kpiPlanMetricSlot.count({ where: { tenantId: tenant.id } }),
