import { PrismaClient } from '@prisma/client';
import { PrismaService } from './src/common/prisma.service';
import { TenantContextService } from './src/common/tenant-context.service';
import { KpiMetricSourceService } from './src/kpi/kpi-metric-source.service';
import { KpiPlanService } from './src/kpi/kpi-plan.service';

const raw = new PrismaClient();

async function main() {
  const tenant = await raw.tenant.findFirstOrThrow({ where: { slug: 'demo' } });
  const admin = await raw.user.findFirstOrThrow({ where: { email: 'admin@demo.local' } });

  const ctx = {
    getTenantId: () => tenant.id,
    isSystem: () => false,
    getActorId: () => admin.id,
  } as unknown as TenantContextService;

  const prisma = new PrismaService(ctx);
  await prisma.onModuleInit?.();

  const audit = { record: async () => undefined } as never;
  const notifications = {
    notifyPlanPublished: async () => undefined,
    notifyAllocationChanged: async () => undefined,
    notifyActualsEntered: async () => undefined,
  } as never;
  const metricSource = new KpiMetricSourceService(prisma, ctx);
  const planService = new KpiPlanService(prisma, ctx, audit, metricSource, notifications);

  const plans = await raw.kpiPlan.findMany({
    where: { tenantId: tenant.id, deletedAt: null, periodYear: 2026 },
    orderBy: { name: 'asc' },
    select: { id: true, name: true, status: true },
  });

  for (const plan of plans) {
    const view = await planService.getDetail(plan.id, undefined);
    console.log(`\n===== ${view.name} [${view.status}] =====`);
    console.log(
      `  canPublish=${view.canPublish} blockers=${JSON.stringify(view.publishBlockers)}`,
    );
    for (const aspect of view.aspects) {
      for (const metric of aspect.metrics) {
        const src = (metric as Record<string, unknown>).sourceType;
        console.log(
          `  [${aspect.aspect}] "${metric.name}" src=${src} cadence=${metric.cadence} ` +
            `target=${metric.targetValue} actual=${metric.actualValue} pct=${metric.percent}`,
        );
        for (const item of metric.allocation.items) {
          const row = item as unknown as Record<string, unknown>;
          console.log(
            `        · ${row.employeeName}: target=${row.targetValue} actual=${row.actualValue} ` +
              `pct=${row.percent} isAuto=${row.isAuto} canEnter=${row.canEnterActual}`,
          );
        }
      }
    }
  }
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => raw.$disconnect());

