3	import { useEffect, useState, type RefObject } from 'react';
4	import {
5	  KPI_ALLOCATION_MODES,
6	  KPI_CRITERIA_KINDS,
7	  KPI_MEASURE_TYPES,
8	  KPI_SCORING_METHODS,
9	  KPI_SCORING_SHAPES,
10	  KPI_SOURCE_TYPES,
11	  type KpiAggregation,
12	  type KpiAllocationMode,
13	  type KpiCriteriaKind,
14	  type KpiDirection,
15	  type KpiMeasureType,
16	  type KpiScoringConfig,
17	  type KpiScoringMethod,
18	  type KpiScoringShape,
19	  type KpiSourceType,
20	} from '@ics/shared';
21	import { SlideOver } from '@/components/shared/slide-over';
22	import { AppSelect } from '@/components/shared/app-select';
23	import { Button } from '@/components/ui/button';
24	import { Input } from '@/components/ui/input';
25	import { errorMessage } from '../api/kpi-api';
26	import {
27	  KPI_ALLOCATION_MODE_LABELS,
28	  KPI_CRITERIA_KIND_HINTS,
29	  KPI_CRITERIA_KIND_LABELS,
30	  KPI_MEASURE_TYPE_LABELS,
31	  KPI_SCORING_METHOD_LABELS,
32	  KPI_SCORING_SHAPE_LABELS,
33	  KPI_SOURCE_TYPE_LABELS,
34	  type KpiCriteria,
35	} from '../model/kpi.types';
36	import {
37	  EMPTY_CONFIG_DRAFT,
38	  KpiScoringConfigFields,
39	  configToDraft,
40	  draftToConfig,
41	  validateDraft,
42	  type ConfigDraft,
43	} from './kpi-scoring-config-fields';
44	
45	/**
46	 * Đơn vị đo hay dùng — chọn nhanh thay vì gõ tay, để cùng một phép đo không bị
47	 * ghi thành "triệu VNĐ" / "Triệu VNĐ" / "trVNĐ" ở ba chỉ tiêu khác nhau.
48	 */
49	const UNIT_PRESETS = ['triệu VNĐ', '%', 'Đơn hàng', 'Khách hàng', 'Ngày'] as const;
50	
51	/** Giá trị sentinel cho lựa chọn "Khác" — không phải đơn vị thật. */
52	const UNIT_OTHER = '__other__';
53	
54	export type CriteriaFormValues = {
55	  name: string;
56	  description: string;
57	  csf: string;
58	  unit: string;
59	  sourceType: KpiSourceType;
60	  /** Cách đo — `PASS_FAIL` ẩn hết mục tiêu/đơn vị/cách chấm/cách gộp/phân bổ. */
61	  kind: KpiCriteriaKind;
62	  scoringShape: KpiScoringShape;
63	  scoringMethod: KpiScoringMethod;
64	  measureType: KpiMeasureType;
65	  allocationMode: KpiAllocationMode;
66	  isBlocking: boolean;
67	  /**
68	   * Cấu hình chấm khai NGAY Ở ĐÂY và dùng chung cho mọi kỳ.
69	   * Tắt ⇒ mỗi kế hoạch KPI tự thiết lập cấu hình của kỳ đó.
70	   */
71	  sharedConfig: boolean;
72	  config: ConfigDraft;
73	  /** Chỉ có khi form được mở kèm ô chọn mục tiêu. */
74	  objectiveId?: string;
75	};
76	
77	const EMPTY: CriteriaFormValues = {
78	  name: '',
79	  description: '',
80	  csf: '',
81	  unit: '',
82	  sourceType: 'MANUAL',
83	  kind: 'MEASURED',
84	  scoringShape: 'UP',
85	  scoringMethod: 'CONTINUOUS',
86	  measureType: 'ADDITIVE',
87	  allocationMode: 'DIVIDE',
88	  isBlocking: false,
89	  sharedConfig: false,
90	  config: EMPTY_CONFIG_DRAFT,
91	};
92	
93	function toValues(criteria: KpiCriteria | null): CriteriaFormValues {
94	  if (!criteria) return EMPTY;
95	  return {
96	    name: criteria.name,
97	    description: criteria.description ?? '',
98	    csf: criteria.csf ?? '',
99	    unit: criteria.unit ?? '',
100	    sourceType: criteria.sourceType,
101	    kind: criteria.kind,
102	    scoringShape: criteria.scoringShape,
103	    scoringMethod: criteria.scoringMethod,
104	    measureType: criteria.measureType,
105	    allocationMode: criteria.allocationMode,
106	    isBlocking: criteria.isBlocking,
107	    // Có cấu hình lưu ở định nghĩa ⇒ đó chính là "dùng chung".
108	    sharedConfig: Boolean(criteria.scoringConfig),
109	    config: configToDraft(criteria.scoringConfig),
110	  };
111	}
112	
113	/** Chiều & cách gộp cũ vẫn còn trong DB — suy ra từ mô hình mới để tương thích. */
114	const DIRECTION_OF_SHAPE: Record<KpiScoringShape, KpiDirection> = {
115	  UP: 'INCREASE',
116	  DOWN: 'DECREASE',
117	  RANGE: 'INCREASE',
118	};
119	const AGGREGATION_OF_MEASURE: Record<KpiMeasureType, KpiAggregation> = {
120	  ADDITIVE: 'SUM',
121	  SEMI_ADDITIVE: 'LAST',
122	  RATIO: 'AVG',
123	};
124	
125	/**
126	 * Cấu hình gửi kèm ĐỊNH NGHĨA — chỉ khi người dùng bật "dùng chung cho mọi kỳ".
127	 * Tắt ⇒ `undefined`, và mỗi kế hoạch KPI sẽ tự khai cấu hình của kỳ đó.
128	 */
129	function buildConfig(values: CriteriaFormValues): KpiScoringConfig | undefined {
130	  if (values.kind === 'PASS_FAIL' || !values.sharedConfig) return undefined;
131	  return draftToConfig(values.scoringShape, values.scoringMethod, values.config);
132	}
133	
134	/** Đổi giá trị form thành payload API — dùng chung cho mọi nơi tạo/sửa chỉ tiêu. */
135	export function toCriteriaPayload(values: CriteriaFormValues) {
136	  /*
137	    Đạt/không đạt có hình dạng cố định. Gửi thẳng giá trị đã chuẩn hoá thay vì
138	    bỏ trống: backend cũng chuẩn hoá y hệt, nên hai bên khớp nhau và payload chỉ
139	    có MỘT shape (union hai shape làm kiểu trả về không khớp contract).
140	
141	    Riêng `unit` phải BỎ TRỐNG — contract từ chối chỉ tiêu đạt/không đạt mà có
142	    đơn vị, vì đó là mâu thuẫn chứ không phải thiếu sót.
143	  */
144	  const isPassFail = values.kind === 'PASS_FAIL';
145	
146	  return {
147	    name: values.name,
148	    description: values.description || undefined,
149	    csf: values.csf || undefined,
150	    // Nguồn số liệu áp dụng cho CẢ HAI kiểu: check hằng ngày là ứng viên số một
151	    // cho tự động hoá, không ai muốn tick tay 20 checkbox mỗi tháng.
152	    sourceType: values.sourceType,
153	    isBlocking: values.isBlocking,
154	    isCombined: false,
155	    kind: values.kind,
156	    unit: isPassFail ? undefined : values.unit,
157	    // `direction`/`aggregation` là cột cũ, suy ra từ mô hình mới cho tương thích.
158	    direction: isPassFail ? ('INCREASE' as const) : DIRECTION_OF_SHAPE[values.scoringShape],
159	    aggregation: isPassFail ? ('AVG' as const) : AGGREGATION_OF_MEASURE[values.measureType],
160	    allocationMode: isPassFail ? ('INHERIT' as const) : values.allocationMode,
161	    scoringShape: isPassFail ? ('UP' as const) : values.scoringShape,
162	    scoringMethod: isPassFail ? ('CONTINUOUS' as const) : values.scoringMethod,
163	    measureType: isPassFail ? ('RATIO' as const) : values.measureType,
164	    scoringConfig: buildConfig(values),
165	  };
166	}
167	
168	/**
169	 * Form tạo/sửa ĐỊNH NGHĨA một chỉ tiêu (KPI).
170	 *
171	 * KHÔNG có trọng số và KHÔNG có target: hai con số đó thuộc về từng kỳ, nhập khi
172	 * đưa KPI vào kế hoạch KPI (`KpiDeptMetricForm`).
173	 *
174	 * Cách chấm khai theo hai trục trực giao: HÌNH DẠNG (càng cao/thấp/khoảng/nhị
175	 * phân) × CÁCH HIỆN (công thức liên tục / bảng khoảng).
176	 */
177	export function KpiCriteriaForm({
178	  open,
179	  criteria,
180	  triggerRef,
181	  objectives,
182	  stacked = false,
183	  onClose,
184	  onSubmit,
185	}: {
186	  open: boolean;
187	  criteria: KpiCriteria | null;
188	  triggerRef: RefObject<HTMLButtonElement>;
189	  objectives?: Array<{ id: string; label: string }>;
190	  stacked?: boolean;
191	  onClose: () => void;
192	  onSubmit: (values: CriteriaFormValues) => Promise<void>;
193	}) {
194	  const [values, setValues] = useState<CriteriaFormValues>(EMPTY);
195	  /**
196	   * Ô chọn đơn vị: giữ riêng khỏi `values.unit` vì "Khác" không phải một đơn vị.
197	   * `UNIT_OTHER` ⇒ hiện ô nhập tay bên cạnh, giá trị thật vẫn nằm ở `values.unit`.
198	   */
199	  const [unitChoice, setUnitChoice] = useState<string>('');
200	  const [objectiveId, setObjectiveId] = useState('');
201	  const [submitting, setSubmitting] = useState(false);
202	  const [error, setError] = useState<string | null>(null);
203	  const needObjective = objectives !== undefined;
204	
205	  useEffect(() => {
206	    if (!open) return;
207	    const next = toValues(criteria);
208	    setValues(next);
209	    // Đơn vị đã lưu nằm ngoài danh sách gợi ý ⇒ mở sẵn ô nhập tay.
210	    setUnitChoice(
211	      next.unit === ''
212	        ? ''
213	        : (UNIT_PRESETS as readonly string[]).includes(next.unit)
214	          ? next.unit
215	          : UNIT_OTHER,
216	    );
217	    setObjectiveId('');
218	    setError(null);
219	    setSubmitting(false);
220	  }, [open, criteria]);
221	
222	  const set = <K extends keyof CriteriaFormValues>(key: K, value: CriteriaFormValues[K]) =>
223	    setValues((current) => ({ ...current, [key]: value }));
224	
225	  const method = values.scoringMethod;
226	  /** Đạt/không đạt: không mục tiêu, không đơn vị, không cách chấm/gộp/phân bổ. */
227	  const isPassFail = values.kind === 'PASS_FAIL';
228	
229	  /** Chỉ kiểm khi người dùng chọn khai cấu hình dùng chung ở đây. */
230	  function validateConfig(): string | null {
231	    if (isPassFail || !values.sharedConfig) return null;
232	    return validateDraft(values.scoringShape, method, values.config);
233	  }
234	
235	  async function handleSubmit() {
236	    if (needObjective && !objectiveId) {
237	      setError('Vui lòng chọn mục tiêu chứa chỉ tiêu này.');
238	      return;
239	    }
240	    if (!values.name.trim()) {
241	      setError('Vui lòng nhập tên chỉ tiêu.');
242	      return;
243	    }
244	    if (!isPassFail && !values.unit.trim()) {
245	      setError('Vui lòng nhập đơn vị đo.');
246	      return;
247	    }
248	    const configError = validateConfig();
249	    if (configError) {
250	      setError(configError);
251	      return;
252	    }
253	
254	    setSubmitting(true);
255	    setError(null);
256	    try {
257	      await onSubmit({
258	        ...values,
259	        name: values.name.trim(),
260	        unit: values.unit.trim(),
261	        ...(needObjective ? { objectiveId } : {}),
262	      });
263	      onClose();
264	    } catch (submitError) {
265	      setError(errorMessage(submitError, 'Không lưu được chỉ tiêu'));
266	    } finally {
267	      setSubmitting(false);
268	    }
269	  }
270	
271	  return (
272	    <SlideOver
273	      open={open}
274	      onClose={onClose}
275	      triggerRef={triggerRef}
276	      stacked={stacked}
277	      title={criteria ? 'Sửa chỉ tiêu' : 'Tạo chỉ tiêu mới'}
278	      footer={
279	        <div className="flex justify-end gap-2 px-4 py-3 sm:px-5">
280	          <Button type="button" variant="outline" onClick={onClose}>
281	            Hủy
282	          </Button>
283	          <Button type="button" onClick={handleSubmit} disabled={submitting}>
284	            {submitting ? 'Đang lưu…' : 'Lưu'}
285	          </Button>
286	        </div>
287	      }
288	    >
289	      <div className="space-y-4 px-4 py-5 sm:px-5">
290	        {objectives && (
291	          <label className="flex flex-col gap-1 text-sm font-medium">
292	            <span>
293	              Thuộc mục tiêu <span className="text-destructive">*</span>
294	            </span>
295	            <AppSelect
296	              aria-label="Chọn mục tiêu chứa chỉ tiêu"
297	              value={objectiveId}
298	              onValueChange={setObjectiveId}
299	              placeholder={objectives.length ? 'Chọn mục tiêu' : 'Phòng ban chưa có mục tiêu nào'}
300	              disabled={!objectives.length}
301	              options={objectives.map((objective) => ({
302	                value: objective.id,
303	                label: objective.label,
304	              }))}
305	            />
306	            <span className="text-xs font-normal text-muted-foreground">
307	              Chỉ tiêu luôn thuộc một mục tiêu sẵn có. Muốn thêm mục tiêu mới thì vào tab “Mục tiêu
308	              và chỉ tiêu”.
309	            </span>
310	          </label>
311	        )}
312	
313	        <label className="flex flex-col gap-1 text-sm font-medium">
314	          <span>
315	            Tên chỉ tiêu <span className="text-destructive">*</span>
316	          </span>
317	          <Input
318	            value={values.name}
319	            onChange={(event) => set('name', event.target.value)}
320	            placeholder="Ví dụ: Doanh thu"
321	          />
322	          <span className="text-xs font-normal text-muted-foreground">
323	            Chỉ đặt tên phép đo, KHÔNG kèm con số — “Doanh thu”, không phải “Doanh thu đạt 50
324	            triệu”. Con số là của từng kỳ, nhập ở kế hoạch KPI.
325	          </span>
326	        </label>
327	
328	        {/*
329	          Trục CAO NHẤT — đặt ngay dưới tên vì nó quyết định phần còn lại của form
330	          hiện những gì. Đổi lựa chọn này là đổi hẳn tập thuộc tính của chỉ tiêu.
331	        */}
332	        <label className="flex flex-col gap-1 text-sm font-medium">
333	          <span>Cách đo chỉ tiêu</span>
334	          <AppSelect
335	            aria-label="Chọn cách đo chỉ tiêu"
