499	/** Kỳ KPI theo tháng/năm: từ 00:00:00 ngày 1 đến 23:59:59.999 ngày cuối tháng. */
500	export function monthPeriod(periodMonth: number, periodYear: number): KpiPeriod {
501	  return {
502	    start: new Date(periodYear, periodMonth - 1, 1, 0, 0, 0, 0),
503	    end: new Date(periodYear, periodMonth, 0, 23, 59, 59, 999),
504	  };
505	}
