import {
  KPI_ACHIEVEMENT_CAP,
  validateScoreBands,
  type KpiAllocationMode,
  type KpiAspect,
  type KpiMeasureType,
  type KpiScoreBand,
  type KpiScoringConfig,
  type KpiScoringMethod,
  type KpiScoringShape,
} from '@ics/shared';

// Chân lý validate band nằm ở `@ics/shared` (dùng chung với contract & UI).
// Re-export để các nơi trong backend (và test) vẫn lấy từ module scoring.
export { validateScoreBands };

/**
 * Nguồn chân lý DUY NHẤT cho mọi công thức chấm điểm KPI theo khung BSC.
 *
 * Toàn bộ hàm ở đây là hàm thuần (không inject gì, không chạm DB) — theo đúng
 * chuẩn `attendance-rules.ts` / `request-rules.ts` của repo.
 *
 * QUY TẮC BẮT BUỘC: backend tính, frontend chỉ hiển thị.
 * API phải trả sẵn `percent` / `score`; frontend KHÔNG được tính lại.
 * (Code KPI cũ có 4 bản công thức khác nhau ở 4 nơi → cùng một người ra 4 điểm khác nhau.)
 */

/** Làm tròn 2 chữ số thập phân. */
export function roundTwo(value: number): number {
  return Math.round(value * 100) / 100;
}

/** Trần % hoàn thành theo trụ cột: Tài chính 130%, các trụ khác 100%. */
export function achievementCap(aspect: KpiAspect): number {
  return KPI_ACHIEVEMENT_CAP[aspect];
}

// ─────────────────────────────────────────────────────────────
// ENGINE CHẤM ĐIỂM — phủ mọi loại KPI qua hai trục trực giao.
//
//   scoringShape  = quan hệ giá trị↔điểm  (UP / DOWN / RANGE)
//   scoringMethod = cách hiện thực đường  (CONTINUOUS / DISCRETE)
//
// CHỈ áp dụng cho chỉ tiêu `kind = MEASURED`. Chỉ tiêu đạt/không đạt đi đường
// riêng (tỷ lệ số lần đạt) và không dùng hàm này.
//
// `scoreMetric` là ĐIỂM VÀO DUY NHẤT để tính % hoàn thành.
//
// KHÔNG còn bậc-thang cứng 0/25/50/75/100 theo trụ cột như đường cũ (đó chỉ là
// placeholder). Muốn bậc thang thì khai method = DISCRETE với `bands` tuỳ ý.
// ─────────────────────────────────────────────────────────────

export type ScoreMetricInput = {
  actual: number | null;
  target: number;
  shape: KpiScoringShape;
  method: KpiScoringMethod;
  /** Túi tham số theo loại; null ⇒ dùng mặc định tuyến tính. */
  config?: KpiScoringConfig | null;
  /** Ngưỡng tuyệt đối override theo kỳ — sàn (UP) hoặc trần-xấu (DOWN). */
  threshold?: number | null;
  /** Mức "vượt" tuyệt đối override theo kỳ — nơi đạt điểm trần. */
  stretch?: number | null;
  /** Dùng để lấy trần % mặc định khi `config.cap` không khai. */
  aspect: KpiAspect;
};

/**
 * % hoàn thành của một KPI theo mô hình hai trục.
 *
 * Trả `null` khi chưa đánh giá được (chưa có số, hoặc cấu hình rời rạc có
 * "khoảng chết"). Không bao giờ ép về 0 khi thiếu số — KPI chưa có số phải bị
 * loại khỏi phép tính điểm chứ không bị chấm 0.
 */
export function scoreMetric(input: ScoreMetricInput): number | null {
  const { actual, target, shape, method, aspect } = input;
  if (actual === null || !Number.isFinite(actual)) return null;

  const config = input.config ?? undefined;
  const capPct = config?.cap ?? achievementCap(aspect);

  if (method === 'DISCRETE') {
    // Cận là giá trị thô cùng đơn vị với mục tiêu ⇒ không cần `target` ở đây.
    return scoreByBands(actual, config?.bands);
  }

  switch (shape) {
    case 'RANGE':
      return scoreRange(actual, config);

    case 'DOWN':
      return scoreDown(actual, target, capPct, input.threshold, input.stretch);

    case 'UP':
    default:
      return scoreUp(actual, target, capPct, config, input.threshold, input.stretch);
  }
}

/** UP — càng cao càng tốt, tuyến tính có sàn tuỳ chọn. */
function scoreUp(
  actual: number,
  target: number,
  capPct: number,
  config: KpiScoringConfig | undefined,
  threshold: number | null | undefined,
  stretch: number | null | undefined,
): number | null {
  // Sàn: ưu tiên ngưỡng tuyệt đối của kỳ, sau đó % của target trong định nghĩa.
  const floor =
    threshold ??
    (config?.floorPctOfTarget != null && Number.isFinite(target)
      ? (target * config.floorPctOfTarget) / 100
      : null);
  if (floor != null && actual < floor) return 0;

  if (!Number.isFinite(target) || target <= 0) return null;
  const raw = (actual / target) * 100;

  // Trần: config.cap > suy từ mức "vượt" > trần theo trụ.

