3	 *
4	 * Toàn bộ phép toán lịch nằm ở đây và dùng chung backend ↔ frontend: backend cần
5	 * để sinh slot và gộp số, frontend cần để vẽ selector và dải ô. Hai bên tự tính
6	 * lấy là kiểu bug lệch một ô mà không ai phát hiện.
7	 *
8	 * Hàm thuần, không phụ thuộc Zod. Mọi mốc thời gian tính bằng UTC — dùng giờ địa
9	 * phương thì cùng một `slotIndex` cho ra hai ngày khác nhau ở hai múi giờ.
10	 *
11	 * ── Ba khái niệm ────────────────────────────────────────────
12	 *   cadence   Nhịp chia của MỘT chỉ tiêu (mỗi chỉ tiêu tự chọn).
13	 *   slotIndex Thứ tự 0-based trong nhịp đó (quý 3 ⇒ 2, tháng 8 ⇒ 7).
14	 *   slotKey   Khoá tự mô tả, duy nhất trong kế hoạch: `2026-Q3`, `2026-08`.
15	 */
16	
17	export const KPI_CADENCES = ['PERIOD', 'QUARTER', 'MONTH', 'WEEK', 'DAY'] as const;
18	export type KpiCadence = (typeof KPI_CADENCES)[number];
19	
20	/**
21	 * Nhãn của nhịp khi CHỌN. "Cả kỳ (không chia)" chứ không phải "Năm": người dùng
22	 * chọn cách chia, và lựa chọn này nghĩa là *không* chia.
23	 */
24	export const KPI_CADENCE_LABELS: Record<KpiCadence, string> = {
25	  PERIOD: 'Cả kỳ (không chia)',
26	  QUARTER: 'Theo quý',
27	  MONTH: 'Theo tháng',
28	  WEEK: 'Theo tuần',
29	  DAY: 'Theo ngày',
30	};
31	
32	/**
33	 * Nhãn ngắn dùng cho selector "độ mịn đang xem".
34	 *
35	 * `PERIOD` ở đây là "Năm" chứ không phải "Cả kỳ": trong bộ chọn nó đứng cạnh
36	 * Quý/Tháng/Tuần nên phải cùng một loại đơn vị thời gian. Còn khi CHỌN CÁCH CHIA
37	 * (`KPI_CADENCE_LABELS`) thì nó mang nghĩa "không chia" — hai ngữ cảnh khác nhau.
38	 */
39	export const KPI_CADENCE_SHORT_LABELS: Record<KpiCadence, string> = {
40	  PERIOD: 'Năm',
41	  QUARTER: 'Quý',
42	  MONTH: 'Tháng',
43	  WEEK: 'Tuần',
44	  DAY: 'Ngày',
45	};
46	
47	/**
48	 * Các cửa sổ NGƯỜI XEM chọn được — hẹp hơn `KPI_CADENCES`.
49	 *
50	 * Khác với `cadence` của chỉ tiêu (nhịp GHI NHẬN), đây là nhịp ĐỌC. Không có
51	 * "Ngày": xem từng ngày thì quá mủn để đọc ra xu hướng và ô chọn kỳ thành danh
52	 * sách 365 mục — chỉ tiêu vẫn tick theo ngày, xem ở mức Tuần là thấy đủ.
53	 *
54	 * Nằm ở shared vì backend chấm SẴN điểm tổng hợp cho đúng những cửa sổ này; hai
55	 * bên lệch một mức là frontend chọn được một kỳ mà không có điểm nào khớp.
56	 */
57	export const KPI_VIEW_CADENCES = ['PERIOD', 'QUARTER', 'MONTH', 'WEEK'] as const;
58	
59	/** Độ mịn tăng dần — so hai nhịp xem cái nào chia nhỏ hơn. */
60	export const KPI_CADENCE_RANK: Record<KpiCadence, number> = {
61	  PERIOD: 0,
62	  QUARTER: 1,
63	  MONTH: 2,
64	  WEEK: 3,
65	  DAY: 4,
66	};
67	
68	/**
69	 * Tuần thứ 52 GỘP NỐT 1–2 ngày lẻ cuối năm.
70	 *
71	 * Cố ý không dùng tuần ISO: tuần ISO tràn sang năm trước/sau, mà một kỳ KPI là
72	 * một năm dương lịch — có ô nằm ngoài kỳ là vô nghĩa. Đổi lại, tuần cuối dài 8–9
73	 * ngày; đó là cái giá rẻ hơn nhiều so với một tuần "thuộc hai kỳ".
74	 */
75	const WEEKS_PER_YEAR = 52;
76	
77	export function isLeapYear(year: number): boolean {
78	  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
79	}
80	
81	export function daysInYear(year: number): number {
82	  return isLeapYear(year) ? 366 : 365;
83	}
84	
85	/** Số kỳ con của một nhịp trong một năm. */
86	export function slotCount(cadence: KpiCadence, year: number): number {
87	  switch (cadence) {
88	    case 'PERIOD':
89	      return 1;
90	    case 'QUARTER':
91	      return 4;
92	    case 'MONTH':
93	      return 12;
94	    case 'WEEK':
95	      return WEEKS_PER_YEAR;
96	    case 'DAY':
97	      return daysInYear(year);
98	  }
99	}
100	
101	const pad2 = (value: number) => String(value).padStart(2, '0');
102	
103	/** Ngày thứ `dayOfYear` (1-based) của năm, tính theo UTC. */
104	function dateOfYear(year: number, dayOfYear: number): Date {
105	  return new Date(Date.UTC(year, 0, dayOfYear));
106	}
107	
108	/** Ngày thứ mấy trong năm (1-based) của một mốc thời gian. */
109	function dayOfYearOf(date: Date): number {
110	  const startOfYear = Date.UTC(date.getUTCFullYear(), 0, 1);
111	  return (
112	    Math.floor(
113	      (Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) - startOfYear) /
114	        86_400_000,
115	    ) + 1
116	  );
117	}
118	
119	export type SlotRange = { startAt: Date; endAt: Date };
120	
121	/** Khoảng thời gian [đầu, cuối] của một kỳ con. `endAt` là mili-giây cuối cùng. */
122	export function slotRange(cadence: KpiCadence, year: number, slotIndex: number): SlotRange {
123	  const endOfDay = (date: Date) => new Date(date.getTime() + 86_400_000 - 1);
124	
125	  switch (cadence) {
126	    case 'PERIOD':
127	      return {
128	        startAt: new Date(Date.UTC(year, 0, 1)),
129	        endAt: endOfDay(new Date(Date.UTC(year, 11, 31))),
130	      };
131	    case 'QUARTER':
132	      return {
133	        startAt: new Date(Date.UTC(year, slotIndex * 3, 1)),
134	        // Ngày 0 của tháng kế tiếp = ngày cuối tháng hiện tại.
135	        endAt: endOfDay(new Date(Date.UTC(year, slotIndex * 3 + 3, 0))),
136	      };
137	    case 'MONTH':
138	      return {
139	        startAt: new Date(Date.UTC(year, slotIndex, 1)),
140	        endAt: endOfDay(new Date(Date.UTC(year, slotIndex + 1, 0))),
141	      };
142	    case 'WEEK': {
143	      const startDay = slotIndex * 7 + 1;
144	      const endDay = slotIndex === WEEKS_PER_YEAR - 1 ? daysInYear(year) : startDay + 6;
145	      return { startAt: dateOfYear(year, startDay), endAt: endOfDay(dateOfYear(year, endDay)) };
146	    }
147	    case 'DAY': {
148	      const day = dateOfYear(year, slotIndex + 1);
149	      return { startAt: day, endAt: endOfDay(day) };
150	    }
151	  }
152	}
153	
154	/** Khoá tự mô tả, duy nhất trong một kế hoạch (một kế hoạch = một năm). */
155	export function slotKey(cadence: KpiCadence, year: number, slotIndex: number): string {
156	  switch (cadence) {
157	    case 'PERIOD':
158	      return String(year);
159	    case 'QUARTER':
160	      return `${year}-Q${slotIndex + 1}`;
161	    case 'MONTH':
162	      return `${year}-${pad2(slotIndex + 1)}`;
163	    case 'WEEK':
164	      return `${year}-W${pad2(slotIndex + 1)}`;
165	    case 'DAY': {
166	      const { startAt } = slotRange('DAY', year, slotIndex);
167	      return `${year}-${pad2(startAt.getUTCMonth() + 1)}-${pad2(startAt.getUTCDate())}`;
168	    }
169	  }
170	}
171	
172	/** Nhãn đầy đủ, dùng ở selector và tiêu đề. */
173	export function slotLabel(cadence: KpiCadence, year: number, slotIndex: number): string {
174	  switch (cadence) {
175	    case 'PERIOD':
176	      return 'Cả kỳ';
177	    case 'QUARTER':
178	      return `Quý ${slotIndex + 1}`;
179	    case 'MONTH':
180	      return `Tháng ${slotIndex + 1}`;
181	    case 'WEEK':
182	      return `Tuần ${slotIndex + 1}`;
183	    case 'DAY': {
184	      const { startAt } = slotRange('DAY', year, slotIndex);
185	      return `${pad2(startAt.getUTCDate())}/${pad2(startAt.getUTCMonth() + 1)}`;
186	    }
187	  }
188	}
189	
190	/**
191	 * Nhãn ngắn cho tiêu đề cột của dải ô.
192	 *
193	 * Tháng dùng `T7`, tuần dùng `W31` — KHÔNG cùng chữ `T`, vì khi một chỉ tiêu theo
194	 * tháng và một chỉ tiêu theo tuần nằm cạnh nhau thì `T7` và `T7` là hai thứ khác
195	 * hẳn nhau.
196	 */
197	export function slotShortLabel(cadence: KpiCadence, year: number, slotIndex: number): string {
198	  switch (cadence) {
199	    case 'PERIOD':
200	      return 'Cả kỳ';
201	    case 'QUARTER':
202	      return `Q${slotIndex + 1}`;
203	    case 'MONTH':
204	      return `T${slotIndex + 1}`;
205	    case 'WEEK':
206	      return `W${slotIndex + 1}`;
207	    case 'DAY':
208	      return slotLabel('DAY', year, slotIndex);
209	  }
210	}
211	
212	/**
213	 * Nhãn của một DÃY kỳ con liền nhau: "Tuần 1–13", "Tháng 7–9".
214	 *
215	 * Dùng khi một cửa sổ ôm nhiều kỳ con. Liệt kê từng cái ("Tuần 1 · Tuần 2 · …")
216	 * vừa dài vừa phải cắt bằng dấu ba chấm, mà cắt xong thì người đọc mất luôn
217	 * thông tin quan trọng nhất là dãy đó KẾT THÚC ở đâu.
218	 *
219	 * `slotIndexesWithin` luôn trả về một dãy liền nhau nên chỉ cần hai đầu mút.
220	 */
221	export function slotSpanLabel(
222	  cadence: KpiCadence,
223	  year: number,
224	  fromIndex: number,
225	  toIndex: number,
226	): string {
227	  if (fromIndex === toIndex) return slotLabel(cadence, year, fromIndex);
228	  switch (cadence) {
229	    case 'PERIOD':
230	      return 'Cả kỳ';
231	    case 'QUARTER':
232	      return `Quý ${fromIndex + 1}–${toIndex + 1}`;
233	    case 'MONTH':
234	      return `Tháng ${fromIndex + 1}–${toIndex + 1}`;
235	    case 'WEEK':
236	      return `Tuần ${fromIndex + 1}–${toIndex + 1}`;
237	    case 'DAY':
238	      // Ngày đã có nhãn dd/MM nên ghép hai đầu là đọc được ngay.
239	      return `${slotLabel('DAY', year, fromIndex)}–${slotLabel('DAY', year, toIndex)}`;
240	  }
241	}
242	
243	/** Mô tả khoảng ("T7–T9", "01/08–31/08") — hiện kèm nhãn khi nhịp khác nhau. */
244	export function slotRangeLabel(cadence: KpiCadence, year: number, slotIndex: number): string {
245	  if (cadence === 'PERIOD') return `01/01–31/12/${year}`;
246	  const { startAt, endAt } = slotRange(cadence, year, slotIndex);
247	  if (cadence === 'MONTH') return `${pad2(startAt.getUTCMonth() + 1)}/${year}`;
248	  const fmt = (date: Date) => `${pad2(date.getUTCDate())}/${pad2(date.getUTCMonth() + 1)}`;
249	  return `${fmt(startAt)}–${fmt(endAt)}`;
250	}
251	
252	/**
253	 * Kỳ con chứa một mốc thời gian. `null` khi mốc đó nằm ngoài năm của kế hoạch.
254	 */
255	export function slotIndexAt(cadence: KpiCadence, year: number, at: Date): number | null {
256	  if (at.getUTCFullYear() !== year) return null;
257	  switch (cadence) {
258	    case 'PERIOD':
259	      return 0;
260	    case 'QUARTER':
261	      return Math.floor(at.getUTCMonth() / 3);
262	    case 'MONTH':
263	      return at.getUTCMonth();
264	    case 'WEEK':
265	      return Math.min(WEEKS_PER_YEAR - 1, Math.floor((dayOfYearOf(at) - 1) / 7));
266	    case 'DAY':
267	      return dayOfYearOf(at) - 1;
268	  }
269	}
270	
271	/**
272	 * Kỳ con mặc định khi mở màn hình.
273	 *
274	 * Kỳ đang chạy ⇒ kỳ con chứa hôm nay. Kỳ đã qua ⇒ kỳ con cuối (nơi có số liệu
275	 * gần nhất). Kỳ tương lai ⇒ kỳ con đầu.
276	 */
277	export function defaultSlotIndex(cadence: KpiCadence, year: number, now: Date): number {
278	  const current = slotIndexAt(cadence, year, now);
279	  if (current !== null) return current;
280	  return now.getUTCFullYear() > year ? slotCount(cadence, year) - 1 : 0;
281	}
282	
283	/**
284	 * Các kỳ con của `cadence` GIAO với một cửa sổ thời gian.
285	 *
286	 * Đây là phép duy nhất dùng để ghép hai nhịp khác nhau — không dùng phép chia
287	 * số học "quý = 3 tháng", vì tuần thì không lồng khít vào tháng. Giao khoảng
288	 * đúng cho mọi cặp nhịp, kể cả tuần nằm vắt qua hai tháng.
289	 */
290	export function slotIndexesWithin(cadence: KpiCadence, year: number, window: SlotRange): number[] {
291	  const result: number[] = [];
292	  const total = slotCount(cadence, year);
293	  for (let index = 0; index < total; index += 1) {
294	    const range = slotRange(cadence, year, index);
295	    if (
296	      range.startAt.getTime() <= window.endAt.getTime() &&
297	      range.endAt.getTime() >= window.startAt.getTime()
298	    ) {
299	      result.push(index);
300	    }
301	  }
302	  return result;
303	}
