305	// ─────────────────────────────────────────────────────────────
306	// Nhịp nào hợp lệ với loại chỉ tiêu nào
307	// ─────────────────────────────────────────────────────────────
308	
309	/**
310	 * Nhịp cho phép theo CÁCH ĐO.
311	 *
312	 * Đạt/không đạt mở tới tuần/ngày — đó chính là loại cần keep-check thường xuyên
313	 * ("nộp báo cáo đúng hạn mỗi ngày"), và điểm của nó là Σđạt/Σlần nên chia mịn
314	 * bao nhiêu cũng vẫn đúng.
315	 *
316	 * Chỉ tiêu đo bằng số dừng ở THÁNG: chia doanh thu xuống từng ngày là con số
317	 * không ai lập được kế hoạch, và một năm sẽ có 365 ô mục tiêu phải khai tay.
318	 */
319	export function allowedCadences(input: { kind: 'MEASURED' | 'PASS_FAIL' }): readonly KpiCadence[] {
320	  return input.kind === 'PASS_FAIL' ? KPI_CADENCES : (['PERIOD', 'QUARTER', 'MONTH'] as const);
321	}
322	
323	/**
324	 * Loại này có phải khai LƯỚI MỐC (% cho từng kỳ con) không?
325	 *
326	 * Chỉ ADDITIVE và SEMI_ADDITIVE mới chia được mục tiêu theo thời gian:
327	 *   · ADDITIVE      — chia phần, Σ các kỳ con = mục tiêu cả kỳ
328	 *   · SEMI_ADDITIVE — lộ trình, MỐC CUỐI = mục tiêu cả kỳ
329	 *
330	 * RATIO thì mục tiêu LẶP LẠI ở mọi kỳ con ("tỷ lệ hài lòng ≥ 90% mỗi tháng") nên
331	 * không có gì để chia; đạt/không đạt cũng vậy. Hai loại đó vẫn chọn nhịp — để
332	 * THU SỐ theo kỳ con — chỉ là không có lưới mốc.
333	 */
334	export function requiresSlotTargets(input: {
335	  kind: 'MEASURED' | 'PASS_FAIL';
336	  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
337	  cadence: KpiCadence;
338	}): boolean {
339	  if (input.cadence === 'PERIOD') return false;
340	  if (input.kind === 'PASS_FAIL') return false;
341	  return input.measureType === 'ADDITIVE' || input.measureType === 'SEMI_ADDITIVE';
342	}
343	
344	export type KpiSlotTarget = { slotIndex: number; percent: number };
345	
346	/**
347	 * Kiểm lưới mốc hợp lệ. Trả thông báo tiếng Việt hoặc `null`.
348	 *
349	 * Một chân lý duy nhất cho contract (Zod), service và form — ba nơi lệch luật là
350	 * kiểu bug người dùng lưu được ở màn này nhưng bị 409 ở màn kia.
351	 */
352	export function validateSlotTargets(input: {
353	  kind: 'MEASURED' | 'PASS_FAIL';
354	  measureType: 'ADDITIVE' | 'SEMI_ADDITIVE' | 'RATIO';
355	  cadence: KpiCadence;
356	  periodYear: number;
357	  targets: readonly KpiSlotTarget[] | undefined;
358	}): string | null {
359	  if (!requiresSlotTargets(input)) return null;
360	
361	  const targets = input.targets ?? [];
362	  if (!targets.length) return 'Cần chia mục tiêu cho từng kỳ con';
363	
364	  const total = slotCount(input.cadence, input.periodYear);
365	  const seen = new Set<number>();
366	  for (const target of targets) {
367	    if (!Number.isInteger(target.slotIndex) || target.slotIndex < 0 || target.slotIndex >= total)
368	      return 'Có kỳ con không thuộc kỳ này';
369	    if (seen.has(target.slotIndex)) return 'Mỗi kỳ con chỉ được khai một lần';
370	    seen.add(target.slotIndex);
371	  }
372	
373	  if (input.measureType === 'ADDITIVE') {
374	    // Dung sai 0.01 như tỷ trọng: 33.33+33.33+33.34 phải được coi là đủ 100%.
375	    const sum = targets.reduce((acc, target) => acc + target.percent, 0);
376	    if (Math.abs(sum - 100) >= 0.01)
377	      return `Tổng các kỳ con đang là ${Math.round(sum * 100) / 100}%, phải bằng 100%`;
378	    return null;
379	  }
380	
381	  // SEMI_ADDITIVE — lộ trình: chỉ số CUỐI KỲ mới là thứ được chấm, nên mốc ở kỳ
382	  // con cuối cùng phải chính là mục tiêu cả kỳ. Các mốc giữa là chặng đường.
383	  const last = targets.find((target) => target.slotIndex === total - 1);
384	  if (!last) return 'Lộ trình phải có mốc ở kỳ con cuối cùng';
385	  if (Math.abs(last.percent - 100) >= 0.01) return 'Mốc của kỳ con cuối cùng phải bằng 100%';
386	  return null;
387	}
