/** Dùng `bffJson` dùng chung — không dựng wrapper HTTP riêng cho feature. */

// ── Tỷ trọng trụ cột ────────────────────────────────────────

export function getAspectWeights(query: {
  scope: KpiWeightScope;
  departmentId?: string | null;
  periodYear: number;
}) {
  const params = new URLSearchParams({
    scope: query.scope,
    periodYear: String(query.periodYear),
  });
  if (query.departmentId) params.set('departmentId', query.departmentId);
  return bffJson<KpiAspectWeightSet>(`/kpi/aspect-weights?${params.toString()}`);
}

/** Dữ liệu dashboard: tỷ trọng công ty + phòng ban được xem + quyền sửa. */
export function getAspectWeightOverview(periodYear?: number) {
  const search = periodYear ? `?periodYear=${periodYear}` : '';
  return bffJson<KpiAspectWeightOverview>(`/kpi/aspect-weights/overview${search}`);
}

