451	  private assertCanManage(
452	    objectiveDepartmentId: string | null,
453	    principal: RbacPrincipal | undefined,
454	  ): string {
455	    const departmentId = this.requireOwnedDepartmentId(principal);
456	    if (objectiveDepartmentId !== departmentId) {
