463	    objectiveDepartmentId: string | null,
464	    principal: RbacPrincipal | undefined,
465	  ): void {
466	    if (this.isKpiAdmin(principal)) return;
467	    // departmentId = null là mục tiêu dùng chung, không thuộc phòng nào → ai cũng xem được.
468	    if (objectiveDepartmentId === null) return;
469	    if (objectiveDepartmentId !== (principal?.departmentId ?? null)) {
