  const error = validateKpiSourceBinding({
    sourceType: input.sourceType,
    dataSourceId: input.dataSourceId,
    formula: input.formula,
    knownSourceIds: kpiSelectableDataSourceIds(),
  });
  if (error) throw new ConflictException(error);
}

