44	    this.assertAdjustable(deptMetric.plan.status);
45	
46	    const mode = deptMetric.allocationMode ?? 'DIVIDE';
47	    if (mode === 'DIVIDE') {
48	      const missing = input.assignments.find((item) => item.percent === undefined);
49	      if (missing) {
50	        throw new ConflictException(
51	          'Chế độ chia phần cần nhập phần trăm cho từng nhân viên được giao',
52	        );
53	      }
54	    }
55	
56	    const tenantId = this.tenantId();
57	
58	    await this.prisma.$transaction(async (tx) => {
59	      for (const assignment of input.assignments) {
60	        const employee = await this.loadEmployee(tx, assignment.employeeId);
61	        const planTargetId = await this.ensurePlanTarget(tx, deptMetric.planId, employee);
62	
63	        // Phần trăm là thứ được LƯU; số tuyệt đối chỉ là dẫn xuất từ mục tiêu
64	        // phòng ban hiện tại. INHERIT thì mỗi người nhận nguyên mục tiêu phòng.
65	        const deptTarget = Number(deptMetric.targetValue);
66	        const percent = mode === 'INHERIT' ? null : (assignment.percent as number);
67	        const targetValue = percent === null ? deptTarget : roundTwo((deptTarget * percent) / 100);
68	
69	        // Giao LẠI cho người đã có phần thì cập nhật, không tạo thêm. Trước đây
70	        // luôn `create` nên giao lại là vỡ unique (P2002) — quản lý không sửa được
71	        // phần đã giao, phải xoá rồi giao lại từ đầu.
72	        const existing = await tx.kpiPlanMetric.findFirst({
73	          where: {
74	            tenantId,
75	            planId: deptMetric.planId,
76	            level: 'INDIVIDUAL',
77	            parentMetricId: deptMetric.id,
78	            planTargetId,
79	          },
80	          select: { id: true },
81	        });
82	
83	        if (existing) {
84	          await tx.kpiPlanMetric.update({
85	            where: { id: existing.id },
86	            data: {
87	              targetValue: new Prisma.Decimal(targetValue),
88	              allocationPercent: percent === null ? null : new Prisma.Decimal(percent),
89	              allocationMode: mode,
90	            },
91	          });
92	          continue;
93	        }
94	
95	        await tx.kpiPlanMetric.create({
96	          data: {
97	            tenantId,
98	            planId: deptMetric.planId,
99	            level: 'INDIVIDUAL',
100	            parentMetricId: deptMetric.id,
101	            planTargetId,
102	            criteriaId: deptMetric.criteriaId,
103	            sourceCriteriaId: deptMetric.sourceCriteriaId,
104	            objectiveId: deptMetric.objectiveId,
105	            aspect: deptMetric.aspect,
106	            csf: deptMetric.csf,
107	            name: deptMetric.name,
108	            description: deptMetric.description,
109	            targetValue: new Prisma.Decimal(targetValue),
110	            allocationPercent: percent === null ? null : new Prisma.Decimal(percent),
111	            // Chưa nhập kết quả ⇒ null, KHÔNG phải 0 (0 sẽ bị tính thành 0% và kéo điểm xuống).
112	            actualValue: null,
113	            unit: deptMetric.unit,
114	            weight: deptMetric.weight,
115	            direction: deptMetric.direction,
116	            allocationMode: mode,
117	            aggregation: deptMetric.aggregation,
118	            isBlocking: deptMetric.isBlocking,
119	            // Cá nhân chấm theo cùng mô hình với chỉ tiêu phòng — snapshot xuống.
120	            kind: deptMetric.kind,
121	            scoringShape: deptMetric.scoringShape,
122	            scoringMethod: deptMetric.scoringMethod,
123	            measureType: deptMetric.measureType,
124	            // Nhịp kỳ con phải giống dòng cha: mọi phép tính trên một dòng chỉ

124	            // Nhịp kỳ con phải giống dòng cha: mọi phép tính trên một dòng chỉ
125	            // đọc `cadence` của chính nó, hai nhịp lệch nhau là hỏng âm thầm.
126	            cadence: deptMetric.cadence,
127	            scoringConfig: deptMetric.scoringConfig ?? Prisma.JsonNull,
128	            thresholdValue: deptMetric.thresholdValue,
129	            stretchValue: deptMetric.stretchValue,
130	            status: 'DRAFT',
131	          },
132	        });
133	      }
134	    });
135	
136	    const after = await this.plan.getDetail(deptMetric.planId, principal);
137	    await this.audit.record({
138	      action: 'kpi.allocation.create',
139	      entity: 'KpiPlanMetric',
140	      entityId: deptMetric.id,
141	      after: {
142	        deptMetricId: deptMetric.id,
143	        mode,
144	        assignments: input.assignments,
145	      },
146	    });
147	    return after;
148	  }
