/** Bộ ba khai nguồn, snapshot trên từng dòng chỉ tiêu của kế hoạch. */
type MetricSource = {
  sourceType: KpiSourceType;
  dataSourceId: string | null;
  formula: string | null;
};

/**
 * Dòng này có lấy số tự động không.
 *
 * Kiểm cả phần khai kèm chứ không chỉ `sourceType`: dữ liệu cũ (từ trước khi nối
 * nguồn vào thật) có thể mang `EXISTING` mà `dataSourceId` rỗng. Coi những dòng đó
 * là tự động thì chúng vừa bị khoá ô nhập vừa không bao giờ có số.
 */
function isAutoSourced(metric: MetricSource): boolean {
  if (metric.sourceType === 'EXISTING') return Boolean(metric.dataSourceId);
  if (metric.sourceType === 'FORMULA') return Boolean(metric.formula);
  return false;
}

/** Tên nguồn để hiện cho người dùng thay vì mã máy. */
function sourceLabelOf(metric: MetricSource): string | null {
  if (!isAutoSourced(metric)) return null;
  if (metric.sourceType === 'FORMULA') return metric.formula;
  return findKpiDataSource(metric.dataSourceId as string)?.name ?? metric.dataSourceId;
}

