60	/**
61	 * ĐỊNH NGHĨA một chỉ tiêu, tái dùng qua nhiều kỳ.
62	 *
63	 * Cố ý không có trọng số và không có target: hai con số đó thuộc về từng kỳ và
64	 * nằm ở `KpiDeptMetric`. Tên chỉ tiêu vì vậy là "Doanh thu", không phải
65	 * "Doanh thu đạt 50 triệu".
66	 */
67	export interface KpiCriteria {
68	  id: string;
69	  name: string;
70	  description: string | null;
71	  csf: string | null;
72	  sourceType: KpiSourceType;
73	  dataSourceId: string | null;
74	  formula: string | null;
75	  direction: KpiDirection;
76	  allocationMode: KpiAllocationMode;
77	  aggregation: KpiAggregation;
78	  isCombined: boolean;
79	  isBlocking: boolean;
80	  /** Cách đo — `PASS_FAIL` làm mọi trường chấm điểm bên dưới mất ý nghĩa. */
81	  kind: KpiCriteriaKind;
82	  /** Mô hình chấm điểm — chỉ có nghĩa với `kind = MEASURED`. */
83	  scoringShape: KpiScoringShape;
84	  scoringMethod: KpiScoringMethod;
85	  measureType: KpiMeasureType;
86	  /** Túi tham số theo loại (floor/cap, min/max/tolerance, bands…). */
87	  scoringConfig: KpiScoringConfig | null;
88	  /** NULL với chỉ tiêu đạt/không đạt — loại đó không có đơn vị đo. */
89	  unit: string | null;
90	  sortOrder: number;
91	}
92	
93	export interface KpiObjective {
94	  id: string;
95	  aspect: KpiAspect;
96	  departmentId: string | null;
97	  departmentName: string | null;
98	  title: string;
99	  description: string | null;
100	  criteria: KpiCriteria[];
101	  /** Backend quyết định — FE không tự suy luận theo quyền. */
102	  canEdit: boolean;
103	}
104	
105	/**
106	 * Ngữ cảnh quyền trên thư viện mục tiêu.
107	 *
108	 * Mục tiêu & chỉ tiêu là việc nội bộ phòng ban: chỉ quản lý phòng đó tạo/sửa.
109	 * KPI admin chỉ đọc — quyền ghi duy nhất của admin là tỷ trọng trụ cột công ty.
110	 */
111	export interface KpiObjectiveContext {
112	  ownedDepartmentId: string | null;
113	  ownedDepartmentName: string | null;
114	  canCreate: boolean;
115	  isReadOnly: boolean;
116	}
117	
118	/** Nhãn hiển thị cho các enum — dùng chung giữa các màn KPI. */
119	export const KPI_DIRECTION_LABELS: Record<KpiDirection, string> = {
120	  INCREASE: 'Càng cao càng tốt',
121	  DECREASE: 'Càng thấp càng tốt',
122	};
123	
124	export const KPI_ALLOCATION_MODE_LABELS: Record<KpiAllocationMode, string> = {
125	  DIVIDE: 'Chia phần cho từng người',
126	  INHERIT: 'Giao nguyên cho mỗi người',
127	};
128	
129	export const KPI_AGGREGATION_LABELS: Record<KpiAggregation, string> = {
130	  SUM: 'Cộng dồn các tháng',
131	  AVG: 'Trung bình các tháng',
132	  LAST: 'Lấy giá trị cuối kỳ',
133	};
134	
135	export const KPI_SOURCE_TYPE_LABELS: Record<KpiSourceType, string> = {
136	  MANUAL: 'Nhập tay',
137	  EXISTING: 'Lấy tự động từ hệ thống',
138	  FORMULA: 'Tính bằng công thức',
139	};
140	
141	/** Cách đo chỉ tiêu — trục cao nhất, quyết định form hiện những gì. */
142	export const KPI_CRITERIA_KIND_LABELS: Record<KpiCriteriaKind, string> = {
143	  MEASURED: 'Đo bằng con số',
144	  PASS_FAIL: 'Đạt / không đạt',
145	};
146	
147	export const KPI_CRITERIA_KIND_HINTS: Record<KpiCriteriaKind, string> = {
148	  MEASURED: 'Có mục tiêu và đơn vị đo; chấm theo mức độ hoàn thành.',
149	  PASS_FAIL: 'Chỉ ghi nhận có đạt hay không, không có mục tiêu số.',
150	};
151	
152	/** Hình dạng quan hệ giá trị↔điểm — cách người dùng chọn "kiểu chấm". */
153	export const KPI_SCORING_SHAPE_LABELS: Record<KpiScoringShape, string> = {
154	  UP: 'Càng cao càng tốt',
155	  DOWN: 'Càng thấp càng tốt',
156	  RANGE: 'Có khoảng tối ưu',
157	};
158	
159	export const KPI_SCORING_METHOD_LABELS: Record<KpiScoringMethod, string> = {
160	  CONTINUOUS: 'Công thức liên tục',
161	  DISCRETE: 'Bảng bậc thang',
162	};
163	
164	export const KPI_MEASURE_TYPE_LABELS: Record<KpiMeasureType, string> = {
165	  ADDITIVE: 'Cộng dồn (doanh thu, số lượng)',
166	  SEMI_ADDITIVE: 'Trạng thái cuối kỳ (tồn kho, headcount)',
167	  RATIO: 'Tỷ lệ (chốt %, biên lợi nhuận)',
168	};
169	
170	// ── Kế hoạch KPI phòng ban (Luồng A) + phân bổ (Luồng B) ────────
171	
172	/**
173	 * Một ô của lưới kỳ con.
174	 *
175	 * Backend CHỈ trả ô có dữ liệu (có mốc mục tiêu hoặc có kết quả). Lưới đầy đủ do
176	 * màn hình tự dựng từ `cadence` + năm bằng `@ics/shared` — cùng module backend
177	 * dùng để sinh slot, nên không có chuyện hai bên lệch một ô.
178	 */
179	export interface KpiMetricSlot {
180	  slotIndex: number;
181	  /** % của mục tiêu cả kỳ — chỉ dòng phòng ban của loại có lưới mốc. */
182	  targetPercent: number | null;
183	  targetValue: number | null;
184	  actualValue: number | null;
185	  /** Backend chấm sẵn ở cấp kỳ con. */
186	  percent: number | null;
187	}
188	
189	/**
190	 * Kết quả ĐÃ GỘP của một cửa sổ thời gian thô hơn nhịp của chỉ tiêu.
191	 *
192	 * Backend tính sẵn cho mọi cửa sổ có thể chọn. Frontend KHÔNG tự cộng: gộp và
193	 * chấm điểm là nghiệp vụ (cộng dồn / lấy mốc cuối / trung bình), tự cộng ở đây
194	 * là mở đường cho hai nơi ra hai con số khác nhau.
195	 */
196	export interface KpiMetricRollup {
197	  cadence: KpiCadence;
198	  slotIndex: number;
199	  targetValue: number | null;
200	  actualValue: number | null;
201	  percent: number | null;
202	}
203	
204	export interface KpiAllocationItem {

204	export interface KpiAllocationItem {
205	  id: string;
206	  employeeId: string;
207	  employeeName: string;
208	  positionName: string;
209	  targetValue: number;
210	  /** Phần trăm của mục tiêu phòng ban — nguồn sự thật của phân bổ. */
211	  allocationPercent: number | null;
212	  actualValue: number | null;
213	  /** Backend tính sẵn. */
214	  percent: number | null;
215	  /** Phần giao cho chính người đang xem — backend đã đẩy lên đầu danh sách. */
216	  isMine: boolean;
217	  canEnterActual: boolean;
218	  /** Chỉ những kỳ con ĐÃ có kết quả của riêng người này. */
219	  slots: KpiMetricSlot[];
220	  /** Kết quả đã gộp theo từng cửa sổ thô hơn — xem `KpiMetricRollup`. */
221	  rollups: KpiMetricRollup[];
222	}
223	
224	export interface KpiAllocationSummary {
225	  allocated: number;
226	  /** Âm nghĩa là đã giao vượt target phòng ban. */
227	  remaining: number;
228	  isOverAllocated: boolean;
229	  isUnderAllocated: boolean;
230	  /** Tổng % đã giao — chưa đủ 100% chỉ là thông báo, không chặn thao tác nào. */
231	  allocatedPercent: number;
232	  items: KpiAllocationItem[];
233	}
234	
235	export interface KpiDeptMetric {
236	  id: string;
237	  criteriaId: string | null;
238	  objectiveId: string | null;
239	  /** Tên mục tiêu chứa chỉ tiêu này — hiện thành badge. */
240	  objectiveTitle: string | null;
241	  csf: string | null;
242	  name: string;
243	  /** NULL với chỉ tiêu đạt/không đạt — loại đó không có đơn vị đo. */
244	  unit: string | null;
245	  targetValue: number;
246	  actualValue: number | null;
247	  weight: number;
248	  direction: KpiDirection;
249	  allocationMode: KpiAllocationMode;
250	  aggregation: KpiAggregation;
251	  isBlocking: boolean;
252	  /** Cách đo (snapshot của kỳ). */
253	  kind: KpiCriteriaKind;
254	  /** Mô hình chấm điểm (snapshot của kỳ) — chỉ có nghĩa với `MEASURED`. */
255	  scoringShape: KpiScoringShape;
256	  scoringMethod: KpiScoringMethod;
257	  measureType: KpiMeasureType;
258	  /** Nhịp chia kỳ con — `PERIOD` là không chia. */
259	  cadence: KpiCadence;
260	  /** Cấu hình chấm của kỳ (đã gộp bảng dùng chung + bảng riêng của kỳ). */
261	  scoringConfig: KpiScoringConfig | null;
262	  percent: number | null;
263	  allocation: KpiAllocationSummary;
264	  /** Mốc mục tiêu + kết quả đã gộp của phòng ban theo từng kỳ con. */
