'use client';

import { useMemo } from 'react';
import { AlertTriangle, Plus } from 'lucide-react';
import { parseKpiFormula, type KpiSourceType } from '@ics/shared';
import { AppSelect } from '@/components/shared/app-select';
import { fieldClass } from '@/components/shared/field-class';
import type { KpiDataSource } from '../model/kpi.types';

/**
 * Phần khai NGUỒN SỐ LIỆU của một chỉ tiêu.
 *
 * Ba lựa chọn nguồn trước đây trông giống hệt nhau vì không lựa chọn nào có ô đi
 * kèm — chọn "lấy tự động" xong không thấy gì để chọn, nên cả ba đều rơi về nhập
 * tay. Đây là phần bù vào.
 *
 * Ranh giới giữa hai lựa chọn tự động:
 *   EXISTING  lấy thẳng MỘT phép đo có sẵn
 *   FORMULA   ghép nhiều phép đo lại bằng bốn phép tính
 *
 * Vì tham số của công thức là NGUỒN chứ không phải chỉ tiêu khác nên không có
 * tham chiếu vòng, và người dùng chỉ cần biết đúng một danh mục.
 */
export function KpiSourceFields({
  sourceType,
  dataSourceId,
  formula,
  sources,
  loading,
  onChangeDataSourceId,
  onChangeFormula,
}: {
  sourceType: KpiSourceType;
  dataSourceId: string;
  formula: string;
  sources: KpiDataSource[];
  loading: boolean;
  onChangeDataSourceId: (value: string) => void;
  onChangeFormula: (value: string) => void;
}) {
  const selected = sources.find((source) => source.id === dataSourceId) ?? null;

  /** Lỗi cú pháp hiện NGAY khi gõ — chờ tới lúc bấm Lưu mới báo là quá muộn. */
  const formulaError = useMemo(() => {
    if (sourceType !== 'FORMULA' || !formula.trim()) return null;
    const parsed = parseKpiFormula(formula);
    if (!parsed.ok) return parsed.error;
    const unknown = parsed.refs.filter((ref) => !sources.some((source) => source.id === ref));
    return unknown.length ? `Không có nguồn số liệu: ${unknown.join(', ')}` : null;
  }, [sourceType, formula, sources]);

  if (sourceType === 'MANUAL') {
    return (
      <p className="rounded-md border bg-muted/40 px-3 py-2 text-xs text-muted-foreground">
        Quản lý phòng nhập kết quả cho từng người ở màn kế hoạch KPI.
      </p>
    );
  }

  if (loading) {
    return (
      <p className="rounded-md border bg-muted/40 px-3 py-2 text-xs text-muted-foreground">
        Đang tải danh mục nguồn dữ liệu…
      </p>
    );
  }

  if (!sources.length) {
    return (
      <p className="rounded-md border border-destructive/30 bg-destructive-subtle px-3 py-2 text-xs text-destructive">
        Không tải được danh mục nguồn dữ liệu. Hãy đóng và mở lại form.
      </p>
    );
  }

  if (sourceType === 'EXISTING') {
    return (
      <div className="space-y-2">
        <AppSelect
          aria-label="Chọn nguồn dữ liệu của hệ thống"
          value={dataSourceId}
          onValueChange={onChangeDataSourceId}
          placeholder="Chọn nguồn dữ liệu"
          options={sources.map((source) => ({ value: source.id, label: source.name }))}
        />

        {/*
          Mô tả nguồn KHÔNG phải trang trí: "tổng số việc trong tháng 8" có ít
          nhất ba nghĩa (giao trong tháng / đến hạn trong tháng / hoàn thành trong
          tháng) và ba con số đó khác hẳn nhau. Hiện rõ mốc thời gian và cách xác
          định "của ai" ngay lúc chọn, thay vì để tranh cãi lúc chốt lương.
        */}
        {selected && (
          <div className="space-y-1 rounded-md border bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
            <p>{selected.description}</p>
            <p>
              <span className="font-medium text-foreground">Tính theo kỳ:</span>{' '}
              {selected.periodBasis}
            </p>
            <p>
              <span className="font-medium text-foreground">Tính theo người:</span>{' '}
              {selected.ownerBasis}
            </p>
            <p>
              <span className="font-medium text-foreground">Đơn vị của nguồn:</span> {selected.unit}
            </p>
          </div>
        )}

        {selected?.ownerScope === 'TENANT_ONLY' && (
          <p className="flex items-start gap-2 rounded-md border border-warning/30 bg-warning-subtle px-3 py-2 text-xs text-warning-foreground">
            <AlertTriangle className="mt-0.5 size-4 shrink-0" aria-hidden />
            <span>
              Nguồn này không tách được theo từng người, nên chỉ dùng cho chỉ tiêu giữ ở cấp phòng
              ban. Nếu đem giao cho cá nhân thì phần đã giao sẽ không có số.
            </span>
          </p>
        )}

        {selected && (
          <p className="text-xs font-normal text-muted-foreground">
            Đơn vị đo của chỉ tiêu nên trùng với đơn vị của nguồn ({selected.unit}) — lệch đơn vị là
            lệch cả thang điểm.
          </p>
        )}
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <textarea
        aria-label="Nhập công thức"
        className={`${fieldClass} min-h-20 py-2 font-mono`}
        value={formula}
        onChange={(event) => onChangeFormula(event.target.value)}
        placeholder="[sales.opportunities_won] / [sales.opportunities_created] * 100"
      />

      <p className="text-xs font-normal text-muted-foreground">
        Dùng bốn phép tính <code>+ - * /</code>, ngoặc đơn và tham chiếu nguồn trong ngoặc vuông.
        Thiếu số liệu hoặc chia cho 0 sẽ cho ra “chưa đánh giá được”, không phải 0 điểm.
      </p>

      {formulaError && (
        <p
          className="rounded-md border border-destructive/30 bg-destructive-subtle px-3 py-2 text-xs text-destructive"
          role="alert"
        >
          {formulaError}
        </p>
      )}

      {/*
        Bấm để chèn thay vì bắt gõ tay mã nguồn: mã có dấu chấm và gạch dưới, gõ
        sai một ký tự là công thức hỏng mà nhìn không ra.
      */}
      <div className="space-y-1 rounded-md border bg-muted/30 p-2">
        <p className="text-xs font-medium">Chèn nguồn số liệu</p>
        <div className="flex flex-wrap gap-1">
          {sources.map((source) => (
            <button
              key={source.id}
              type="button"
              title={`${source.description} · Tính theo kỳ: ${source.periodBasis}`}
              onClick={() => onChangeFormula(`${formula}[${source.id}]`)}
              className="inline-flex items-center gap-1 rounded border bg-background px-2 py-1 text-xs hover:bg-muted"
            >
              <Plus className="size-3" aria-hidden />
              {source.name}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

