import { KpiMetricSourceService, type AutoMetricInput } from './kpi-metric-source.service';

/**
 * Spec cho phần lấy số tự động.
 *
 * Cố ý chạy trên DANH MỤC NGUỒN THẬT (`tasks.completed`) thay vì nguồn giả: thứ
 * dễ sai nhất ở đây không phải luồng điều khiển mà là ĐIỀU KIỆN TRUY VẤN — lọc
 * đúng người, đúng khoảng thời gian của kỳ con. Nguồn giả sẽ không bắt được lỗi đó.
 */

function setup(over: { groupBy?: jest.Mock } = {}) {
  const groupBy = over.groupBy ?? jest.fn().mockResolvedValue([]);

  const tx = {
    kpiPlanMetric: { update: jest.fn().mockResolvedValue({}) },
    kpiMetricActualHistory: { create: jest.fn().mockResolvedValue({}) },
    kpiPlanSlot: {
      findFirst: jest.fn().mockResolvedValue(null),
      create: jest.fn().mockResolvedValue({ id: 'slot_1' }),
    },
    kpiPlanMetricSlot: {
      findFirst: jest.fn().mockResolvedValue(null),
      create: jest.fn().mockResolvedValue({ id: 'ms_1' }),
      update: jest.fn().mockResolvedValue({}),
    },
    kpiPlanMetricSlotActualHistory: { create: jest.fn().mockResolvedValue({}) },
  };

  const prisma = {
    scoped: { task: { groupBy } },
    $transaction: jest.fn((fn: (client: unknown) => unknown) => fn(tx)),
  };
  const tenant = { getTenantId: jest.fn().mockReturnValue('t1') };

  const service = new KpiMetricSourceService(prisma as never, tenant as never);
  return { service, prisma, tx, groupBy };
}

const BASE_METRIC: AutoMetricInput = {
  id: 'm_1',
  level: 'INDIVIDUAL',
  kind: 'MEASURED',
  cadence: 'PERIOD',
  sourceType: 'EXISTING',
  dataSourceId: 'tasks.completed',
  formula: null,
  autoSyncedAt: null,
  actualValue: null,
  ownerUserId: 'user_a',
  hasChildren: false,
};

const PLAN = { id: 'plan_1', periodYear: 2026 };

function run(
  service: KpiMetricSourceService,
  metrics: AutoMetricInput[],
  now: Date,
  existingSlots = new Map(),
) {
  return service.resolveForPlan({
    plan: PLAN,
    metrics,
    existingSlots,
    departmentUserIds: ['user_a', 'user_b'],
    now,
  });
}

describe('KpiMetricSourceService', () => {
  describe('lọc theo người', () => {
    it('hỏi đúng tài khoản của người được giao', async () => {
      const groupBy = jest.fn().mockResolvedValue([{ assigneeId: 'user_a', _count: { _all: 7 } }]);
      const { service } = setup({ groupBy });

      const result = await run(service, [BASE_METRIC], new Date('2027-03-01T00:00:00Z'));

      expect(groupBy).toHaveBeenCalledTimes(1);
      expect(groupBy.mock.calls[0][0].where.assigneeId).toEqual({ in: ['user_a'] });
      expect(result.get('m_1')?.[0].value).toBe(7);
    });

    it('nhân viên chưa có tài khoản thì KHÔNG truy vấn và không có số', async () => {
      // Điền 0 vào đây là bịa: người đó không phải làm được 0 việc, mà là hệ thống
      // không có cách nào biết việc nào của họ.
      const { service, groupBy } = setup();

      const result = await run(
        service,
        [{ ...BASE_METRIC, ownerUserId: null }],
        new Date('2027-03-01T00:00:00Z'),
      );

      expect(groupBy).not.toHaveBeenCalled();
      expect(result.has('m_1')).toBe(false);
    });

    it('dòng phòng ban ĐÃ giao cho cá nhân thì không tự lấy số', async () => {
      // Số của phòng được gộp từ các dòng con; tự lấy thêm là hai nguồn sự thật.
      const { service, groupBy } = setup();

      const result = await run(
        service,
        [{ ...BASE_METRIC, level: 'DEPARTMENT', ownerUserId: null, hasChildren: true }],
        new Date('2027-03-01T00:00:00Z'),
      );

      expect(groupBy).not.toHaveBeenCalled();
      expect(result.size).toBe(0);
    });

    it('dòng phòng ban CHƯA giao thì cộng số của cả phòng', async () => {
      const groupBy = jest.fn().mockResolvedValue([
        { assigneeId: 'user_a', _count: { _all: 4 } },
        { assigneeId: 'user_b', _count: { _all: 6 } },
      ]);
      const { service } = setup({ groupBy });

      const result = await run(
        service,
        [{ ...BASE_METRIC, level: 'DEPARTMENT', ownerUserId: null }],
        new Date('2027-03-01T00:00:00Z'),
      );

      expect(groupBy.mock.calls[0][0].where.assigneeId).toEqual({ in: ['user_a', 'user_b'] });
      expect(result.get('m_1')?.[0].value).toBe(10);
    });
  });

  describe('lọc theo thời gian', () => {
    it('kỳ cả năm hỏi đúng khoảng 01/01–31/12', async () => {
      const { service, groupBy } = setup();

      await run(service, [BASE_METRIC], new Date('2027-03-01T00:00:00Z'));

      const where = groupBy.mock.calls[0][0].where;
      expect(where.completedAt.gte.toISOString()).toBe('2026-01-01T00:00:00.000Z');
      expect(where.completedAt.lte.toISOString()).toBe('2026-12-31T23:59:59.999Z');
    });

    it('chia theo tháng thì mỗi kỳ con là một khoảng riêng', async () => {
      const { service, groupBy } = setup();

      // 10/08/2026: tháng 1..7 đã xong, tháng 8 đang chạy, tháng 9..12 chưa tới.
      await run(
        service,
        [{ ...BASE_METRIC, cadence: 'MONTH' }],
        new Date('2026-08-10T00:00:00Z'),
      );

      expect(groupBy).toHaveBeenCalledTimes(8);
      const ranges = groupBy.mock.calls.map((call) => [
        call[0].where.completedAt.gte.toISOString(),
        call[0].where.completedAt.lte.toISOString(),
      ]);
      expect(ranges[0]).toEqual(['2026-01-01T00:00:00.000Z', '2026-01-31T23:59:59.999Z']);
      expect(ranges[7]).toEqual(['2026-08-01T00:00:00.000Z', '2026-08-31T23:59:59.999Z']);
    });

    it('KHÔNG hỏi các kỳ con chưa bắt đầu', async () => {
      // Điền 0 vào kỳ chưa tới sẽ biến "chưa đến hạn" thành "làm được 0" ⇒ chấm trượt.
      const { service, groupBy } = setup();

      await run(
        service,
        [{ ...BASE_METRIC, cadence: 'MONTH' }],
        new Date('2026-02-15T00:00:00Z'),
      );

      expect(groupBy).toHaveBeenCalledTimes(2);
    });
  });

  describe('đóng băng', () => {
    it('kỳ đang chạy thì KHÔNG ghi DB', async () => {
      const groupBy = jest.fn().mockResolvedValue([{ assigneeId: 'user_a', _count: { _all: 3 } }]);
      const { service, prisma } = setup({ groupBy });

      const result = await run(service, [BASE_METRIC], new Date('2026-08-10T00:00:00Z'));

      expect(prisma.$transaction).not.toHaveBeenCalled();
      expect(result.get('m_1')?.[0].frozen).toBe(false);
    });

    it('kỳ đã xong và qua hạn ân hạn thì ghi xuống kèm vết SYSTEM', async () => {
      const groupBy = jest.fn().mockResolvedValue([{ assigneeId: 'user_a', _count: { _all: 9 } }]);
      const { service, tx } = setup({ groupBy });

      const result = await run(service, [BASE_METRIC], new Date('2027-03-01T00:00:00Z'));

      expect(tx.kpiPlanMetric.update).toHaveBeenCalledTimes(1);
      const written = tx.kpiPlanMetric.update.mock.calls[0][0].data;
