1	import { calendarLateDays } from '@ics/shared';
2	import type { PrismaService } from '../common/prisma.service';
3	
4	/**
5	 * Danh mục nguồn dữ liệu KPI — nơi duy nhất định nghĩa "số thực tế của chỉ tiêu lấy từ đâu".
6	 *
7	 * Mỗi nguồn tự chịu trách nhiệm LỌC THEO KỲ KPI. Trước đây các nguồn cộng dồn toàn bộ lịch sử
8	 * (dù mô tả ghi "trong kỳ KPI"), nên điểm KPI tháng nào cũng giống nhau và tăng vô hạn theo
9	 * thời gian — sai về nghiệp vụ. Giờ mọi nguồn đều nhận `period` và chỉ tính trong khoảng đó.
10	 *
11	 * Thêm nguồn mới: khai một phần tử vào KPI_DATA_SOURCES là xong — không phải sửa chỗ chấm điểm.
12	 *
13	 * ── HAI LOẠI NGUỒN ──────────────────────────────────────────────────────────────────────
14	 *
15	 *   RAW      MỘT phép đo. Được phép tính toán trong TỪNG DÒNG dữ liệu (số ngày trễ của một
16	 *            công việc, số giờ xử lý một ticket) và được phép gom từ nhiều bảng cùng nói về
17	 *            một thứ (doanh thu = cơ hội thắng + hợp đồng ký). Dùng làm chỉ tiêu KPI.
18	 *
19	 *   DERIVED  Đã GHÉP HAI phép đo độc lập thành tỷ lệ/trung bình. CHỈ dùng cho trang chủ.
20	 *
21	 * Vì sao DERIVED bị cấm làm chỉ tiêu KPI: KPI gộp nhiều kỳ con lên cả năm, mà tỷ lệ thì không
22	 * gộp được. Quý 1 thắng 10/40, quý 2 thắng 30/60 ⇒ cả năm là 40/100 = 40%, KHÔNG phải trung
23	 * bình của 25% và 50% = 37.5%. Muốn đúng thì tử số và mẫu số phải là hai nguồn RAW riêng, rồi
24	 * `sourceType = FORMULA` chia lại ở TỪNG cấp gộp. Trang chủ chỉ hiển thị một kỳ, không gộp,
25	 * nên nhận sẵn tỷ lệ là hoàn toàn đúng — đó là lý do hai bên có luật khác nhau.
26	 */
27	
28	export interface KpiPeriod {
29	  /** Đầu kỳ, tính cả mốc này. */
30	  start: Date;
31	  /** Cuối kỳ, tính cả mốc này. */
32	  end: Date;
33	}
34	
35	/**
36	 * Bối cảnh khi lấy số thực tế.
37	 *
38	 * `ownerUserId` rất quan trọng: KPI là của TỪNG NGƯỜI, nên chỉ tiêu "doanh thu" của nhân viên A
39	 * phải là doanh thu do A phụ trách, không phải doanh thu toàn công ty. Khi không truyền
40	 * (vd xem trước lúc soạn chỉ tiêu) thì lấy số của cả tenant.
41	 */
42	export interface KpiResolveContext {
43	  period: KpiPeriod;
44	  ownerUserId?: string | null;
45	  /**
46	   * Giới hạn theo MỘT NHÓM người phụ trách — dùng khi trang chủ hiển thị số của nhóm / phòng ban /
47	   * chi nhánh mà người xem được phép đọc. Có `ownerUserId` thì `ownerUserId` thắng (KPI cá nhân).
48	   *
49	   * Mảng RỖNG có nghĩa "không ai trong phạm vi" và phải cho ra 0. Đây là lý do tồn tại của
50	   * `ownerIdFilter` bên dưới: nếu để mảng rỗng rơi vào nhánh "không lọc gì" thì một trưởng nhóm
51	   * chưa có thành viên sẽ nhìn thấy số của TOÀN BỘ công ty — lộ dữ liệu, không phải hiển thị sai.
52	   */
53	  ownerUserIds?: readonly string[] | null;
54	}
55	
56	/**
57	 * Bối cảnh lấy số theo LÔ: một kỳ, nhiều người, tách riêng số của từng người.
