/**
 * Số LẦN KIỂM của một dòng đạt/không đạt lấy tự động — mẫu số của tỷ lệ.
 *
 * Đường nhập tay có `recomputeFromSlots` ghi `targetValue = số lần kiểm` mỗi
 * lần nhập. Đường tự động không ghi gì khi kỳ còn chạy, nên phải suy ra ở đây.
 */
const autoChecks = new Map<string, number>();

/*
  Gộp các ô kỳ con thành CON SỐ CẢ KỲ cho chỉ tiêu tự động có chia nhịp.

  Thiếu bước này thì dải ô theo tháng hiện đúng số nhưng cột "kết quả cả kỳ"
  lại trống — vì cột `actualValue` trong DB chỉ được `recomputeFromSlots` cập
  nhật, mà hàm đó nằm trên đường NHẬP TAY. Dùng đúng hai hàm gộp của đường
  nhập tay để hai đường không bao giờ ra hai con số khác nhau.
*/
for (const [metricId, filled] of autoValues) {
  const metric = metrics.find((row) => row.id === metricId);
  if (!metric || metric.cadence === 'PERIOD') continue;

  const slotValues: SlotValue[] = filled.map((slot) => ({
    slotIndex: slot.slotIndex,
    value: slot.value,
  }));

  if (metric.kind === 'PASS_FAIL') {
    const { passes, checks } = aggregatePassFailSlots(slotValues);
    autoPeriodValue.set(metricId, checks === 0 ? null : passes);
    autoChecks.set(metricId, checks === 0 ? 1 : checks);
    continue;
  }
  autoPeriodValue.set(metricId, aggregateSlotActual(slotValues, metric.measureType));
}

