  autoPeriodValue.has(metric.id)
    ? (autoPeriodValue.get(metric.id) ?? null)
    : toNullableNumber(metric.actualValue);

/** Mục tiêu cả kỳ — đạt/không đạt lấy tự động thì mẫu số là số lần kiểm suy ra ở trên. */
const targetValueOf = (metric: { id: string; targetValue: Prisma.Decimal }) =>
  autoChecks.get(metric.id) ?? toNumber(metric.targetValue);

