import { fireEvent, screen } from '@testing-library/react';

/**
 * Chọn một mục trong `AppSelect`. Component này là combobox dựng bằng Radix Popover, không phải
 * `<select>` gốc, nên test không dùng `fireEvent.change` được.
 */
export function selectAppOption(comboboxName: string | RegExp, optionName: string | RegExp) {
  fireEvent.click(screen.getByRole('combobox', { name: comboboxName }));
  fireEvent.click(screen.getByRole('option', { name: optionName }));
}

