import { createRef } from 'react';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { selectAppOption } from '@/components/shared/app-select.test-utils';
import { KpiCriteriaForm } from './kpi-criteria-form';
import { listKpiDataSources } from '../api/kpi-api';

vi.mock('../api/kpi-api', async () => {
  const actual = await vi.importActual<typeof import('../api/kpi-api')>('../api/kpi-api');
  return { ...actual, listKpiDataSources: vi.fn() };
});

const mockListSources = vi.mocked(listKpiDataSources);

const SOURCES = [
  {
    id: 'tasks.assigned_total',
    name: 'Số công việc được giao',
    description: 'Tổng số công việc được tạo và giao cho người đó trong kỳ.',
    unit: 'Việc',
    periodBasis: 'Ngày tạo công việc',
    ownerBasis: 'Người được giao việc',
    ownerScope: 'PER_OWNER' as const,
  },
  {
    id: 'marketing.qualified_leads',
    name: 'Lead đủ điều kiện',
    description: 'Số lead đủ điều kiện được ghi nhận trong kỳ KPI.',
    unit: 'Lead',
    periodBasis: 'Ngày lead hoàn tất chiến dịch',
    ownerBasis: 'Không có — số của toàn công ty',
    ownerScope: 'TENANT_ONLY' as const,
  },
];

const SOURCE_TYPE = 'Chọn nguồn số liệu';
const SOURCE_PICKER = 'Chọn nguồn dữ liệu của hệ thống';

function renderForm() {
  render(
    <KpiCriteriaForm
      open
      criteria={null}
      triggerRef={createRef<HTMLButtonElement>()}
      onClose={() => {}}
      onSubmit={async () => {}}
    />,
  );
}

/** Chọn "Lấy tự động" rồi đợi danh mục nguồn về. */
async function pickAutoSource(optionName: string) {
  selectAppOption(SOURCE_TYPE, 'Lấy tự động từ hệ thống');
  await waitFor(() => {
    expect(screen.getByRole('combobox', { name: SOURCE_PICKER })).toBeInTheDocument();
  });
  selectAppOption(SOURCE_PICKER, optionName);
}

describe('KpiCriteriaForm — nguồn số liệu', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockListSources.mockResolvedValue(SOURCES);
  });

  /*
    Hồi quy: trước đây `sourcesLoading` vừa được set trong effect vừa nằm trong
    deps của chính effect đó, nên effect tự huỷ mình ngay sau khi bật cờ loading.
    Request vẫn đi (thấy trong tab Network) nhưng response về thì không còn ai
    nhận, và màn hình kẹt ở "Đang tải…" vĩnh viễn.
  */
  it('hiện ô chọn nguồn sau khi API trả về, không kẹt ở trạng thái đang tải', async () => {
    renderForm();

    selectAppOption(SOURCE_TYPE, 'Lấy tự động từ hệ thống');

    await waitFor(() => {
      expect(screen.getByRole('combobox', { name: SOURCE_PICKER })).toBeInTheDocument();
    });
    expect(screen.queryByText(/Đang tải danh mục nguồn dữ liệu/)).not.toBeInTheDocument();
  });

  it('chỉ gọi API danh mục MỘT lần dù đổi qua lại giữa các loại nguồn', async () => {
    renderForm();

    await waitFor(() => expect(mockListSources).toHaveBeenCalled());
    selectAppOption(SOURCE_TYPE, 'Lấy tự động từ hệ thống');
    selectAppOption(SOURCE_TYPE, 'Tính bằng công thức');
    selectAppOption(SOURCE_TYPE, 'Lấy tự động từ hệ thống');

    expect(mockListSources).toHaveBeenCalledTimes(1);
  });

  it('chọn nguồn xong thì hiện rõ mốc thời gian và cách xác định người', async () => {
    // Hai thông tin này là thứ ngăn tranh cãi lúc chốt lương: "tổng số việc
    // tháng 8" có thể là giao / đến hạn / hoàn thành trong tháng 8.
    renderForm();

    await pickAutoSource('Số công việc được giao');

    expect(screen.getByText('Ngày tạo công việc')).toBeInTheDocument();
    expect(screen.getByText('Người được giao việc')).toBeInTheDocument();
  });

  it('cảnh báo khi nguồn không tách được theo từng người', async () => {
    renderForm();

    await pickAutoSource('Lead đủ điều kiện');

    expect(screen.getByText(/không tách được theo từng người/)).toBeInTheDocument();
  });

  it('chọn công thức thì hiện ô nhập và báo lỗi cú pháp ngay khi gõ', async () => {
    renderForm();

    selectAppOption(SOURCE_TYPE, 'Tính bằng công thức');
    await waitFor(() => expect(screen.getByLabelText('Nhập công thức')).toBeInTheDocument());

    fireEvent.change(screen.getByLabelText('Nhập công thức'), {
      target: { value: '[tasks.assigned_total] /' },
    });

    expect(await screen.findByRole('alert')).toHaveTextContent(/kết thúc giữa chừng/i);
  });

  it('công thức tham chiếu nguồn không có thật thì báo tên nguồn đó', async () => {
    renderForm();

    selectAppOption(SOURCE_TYPE, 'Tính bằng công thức');
    await waitFor(() => expect(screen.getByLabelText('Nhập công thức')).toBeInTheDocument());

    fireEvent.change(screen.getByLabelText('Nhập công thức'), {
      target: { value: '[sales.khong_co_that] * 2' },
    });

    expect(await screen.findByRole('alert')).toHaveTextContent('sales.khong_co_that');
  });
});

