  if (!open || dataSources.length || sourcesLoading) return;
  sourcesRequested.current = true;
  setSourcesLoading(true);
  listKpiDataSources()
    .then(setDataSources)
    // Nuốt lỗi là cố ý: form vẫn dùng được cho chỉ tiêu nhập tay, và
