/** Một ô cụ thể cần tính (hoặc đã có sẵn vì đã chốt). */
private collectTargets(input: ResolvePlanInput): ResolveTarget[] {
  const targets: ResolveTarget[] = [];
  let budget = MAX_RESOLVES_PER_READ;

  for (const metric of input.metrics) {
    const sources = this.sourcesOf(metric);
    if (!sources) continue;

    /*
      Dòng phòng ban ĐÃ GIAO cho cá nhân thì không tự lấy số: kết quả của phòng
      được gộp từ phần đã giao (`rollUpAllocatedActual`). Tự lấy thêm ở đây là
      có hai nguồn sự thật trên cùng một dòng, và chúng sẽ lệch nhau.
    */
    if (metric.level === 'DEPARTMENT' && metric.hasChildren) continue;

    const owners =
      metric.level === 'INDIVIDUAL'
        ? metric.ownerUserId
          ? [metric.ownerUserId]
          : null // Nhân viên chưa có tài khoản ⇒ không tra được, để trống.
        : [...input.departmentUserIds];
    if (owners === null) continue;

    /*
      Nguồn không tách được theo người (vd lead từ chiến dịch) chỉ dùng được ở
      cấp phòng ban. Gán cho cá nhân thì cả 12 người cùng nhận số toàn công ty —
      sai mà nhìn vào không thấy sai, nên thà để trống.
    */
    const tenantWideOnly = sources.some(
      (source) => findKpiDataSource(source)?.ownerScope === 'TENANT_ONLY',
    );
    if (tenantWideOnly && metric.level === 'INDIVIDUAL') continue;

    for (const slot of this.slotsToResolve(metric, input)) {
      if (slot.reuse !== undefined) {
        targets.push({ metric, sources, owners, tenantWideOnly, ...slot });
        continue;
      }
      if (budget <= 0) break;
      budget -= 1;
      targets.push({ metric, sources, owners, tenantWideOnly, ...slot });
    }
  }

  return targets;
}

/** Mã các nguồn một chỉ tiêu cần. `null` = chỉ tiêu này không lấy tự động. */
private sourcesOf(metric: AutoMetricInput): string[] | null {
  if (metric.sourceType === 'EXISTING') {
    return metric.dataSourceId ? [metric.dataSourceId] : null;
  }
  if (metric.sourceType === 'FORMULA') {
    if (!metric.formula) return null;
    const parsed = parseKpiFormula(metric.formula);
    return parsed.ok ? parsed.refs : null;
  }
  return null;
}

